const CET6_WORDS = [{"w":"abandon","t":"vt. 离弃，丢弃；遗弃；抛弃；放弃","p":"ə'bændən","e":["How could she abandon her own child?","她怎么能抛弃自己的孩子呢？"]},{"w":"abandonment","t":"n. 放弃","p":"əˈbændənmənt","c":1,"e":["...memories of her father's complete abandonment of her.","…她父亲对她的彻底抛弃的那些记忆。"]},{"w":"abbreviation","t":"n. 节略，缩写，缩短","p":"əbriːvɪ'eɪʃ(ə)n","e":["‘Dr’ is the written abbreviation of ‘Doctor’.","Dr是Doctor的书面缩写形式。"]},{"w":"abide","t":"v. 忍受；遵守","p":"ə'baɪd","e":["You'll have to abide by the rules of the club.","你必须遵守俱乐部的规定。"]},{"w":"abnormal","t":"adj. 反常的，异常的","p":"æb'nɔːml","e":["My parents thought it was abnormal for a boy to be interested in ballet.","我父母认为一个男孩子对芭蕾舞感兴趣并不正常。"]},{"w":"abnormally","t":"adv. 不正常地","p":"æb'nɔ:məlɪ","c":1,"e":["abnormally high blood pressure","异常高的血压"]},{"w":"abolish","t":"vt. 彻底废除，废止","p":"ə'bɒlɪʃ","e":["Slavery was abolished in the US in the 19th century.","美国于19世纪废除了奴隶制。"]},{"w":"abolition","t":"n. 废除","p":"ˌæbəˈlɪʃn","c":1,"e":["The abolition of slavery in Brazil and the Caribbean closely followed the pattern of the United States.","巴西和加勒比海地区对奴隶制的废除很大程度上遵循了美国的模式。"]},{"w":"abortion","t":"n. 流产，堕胎","p":"ə'bɔːʃn","e":["She decided to have an abortion .","她决定做人工流产。"]},{"w":"abrupt","t":"adj. 突然的，意外的；唐突的，鲁莽的","p":"ə'brʌpt","e":["an abrupt change of plan","计划的突然改变"]},{"w":"absence","t":"n. 缺席，不在；缺席的时间，外出期；缺乏，不存在","p":"'æbsəns","e":["In the absence of any evidence, the police had to let Myers go.","警察没有证据，只好把迈尔斯放了。"]},{"w":"absent","t":"adj. 不在的","p":"'æbs(ə)nt","e":["students who are regularly absent from school","经常缺课的学生"]},{"w":"absolutely","t":"adv. 当然","p":"ˈæbsəlu:tli","c":1,"e":["‘They could have told us, couldn't they? ’ ‘Absolutely! ’","“他们本来可以告诉我们的，不是吗？”“当然！”"]},{"w":"absorb","t":"vt. 吸收；吸引…的注意，使全神贯注；把…并入，同化","p":"əb'sɔːb","e":["Plants absorb nutrients from the soil.","植物从土壤中吸收养分。"]},{"w":"absorption","t":"n. 吸收；专注","p":"əb'zɔːpʃ(ə)n; -'sɔːp-","e":["I don’t understand James’ absorption with military history.","我不明白詹姆斯为何对军事史那么着迷。"]},{"w":"abstract","t":"adj. 抽象的","p":"'æbstrækt","c":1,"e":["Human beings are the only creatures capable of abstract thought (=  thinking about ideas  ) .","人类是唯一具有抽象思维能力的动物。"]},{"w":"absurd","t":"adj. 荒谬的，荒唐的","p":"əb'sɜːd","e":["It seems an absurd idea.","这似乎是个荒唐的想法。"]},{"w":"abundance","t":"n. 大量，丰富，充足","p":"ə'bʌndəns","e":["This area of Mexico has an abundance of safe beaches and a pleasing climate.","墨西哥的这个地区有大量的安全沙滩与宜人的气候。"]},{"w":"abundant","t":"adj. 丰富的，富裕的；大量的，充足的","p":"ə'bʌndənt","e":["abundant opportunities for well qualified staff","提供给高素质的员工的大量机会"]},{"w":"abuse","t":"n. 虐待；v. 滥用","p":"ə'bju:s","c":1,"e":["An independent committee will look into alleged human rights abuses.","一个独立委员会将对涉嫌践踏人权的行为进行调查。"]},{"w":"academic","t":"adj. 学院的；学术的；纯理论的，不切实际的；n. 大学教师","p":"ˌækə'demɪk","e":["He possessed no academic qualifications.","他没有学历。"]},{"w":"accelerate","t":"v. 加速","p":"ək'seləreɪt","c":1,"e":["measures to accelerate the rate of economic growth","加快经济增长速度的措施"]},{"w":"acceptance","t":"n. 接受，承认；容忍","p":"ək'septəns","e":["He wrote a letter of acceptance (=  a letter in which you agree to accept a job, university place etc  ) to the university.","他给那所大学写了一封接受函。"]},{"w":"access","t":"v. 取得，获取","p":"ˈækses","c":1,"e":["Users can access their voice mail remotely.","用户可以远程获取语音邮件。"]},{"w":"accessory","t":"n. 附件，零件，配件；装饰品；同谋，帮凶，包庇犯","p":"ək'sesəri","e":["bathroom accessories such as mirrors and towel-rails","镜子和毛巾架等浴室配件"]},{"w":"accident","t":"n. 意外，事故","p":"'æksɪdənt","e":["The pilot, whether by accident or design (=  whether it was planned or not planned  ) , made the plane do a sharp turn.","不知是有意还是无意，那名飞行员让飞机来了个急转弯。"]},{"w":"accidentally","t":"adv. 偶然地，意外地","p":"ˌæksɪˈdentəli","c":1,"e":["She accidentally erased the tape.","她意外地抹去了录了音的磁带。"]},{"w":"accommodate","t":"v. 容纳；适应","p":"əˈkɒmədeɪt","c":1,"e":["Her eyes took a while to accommodate to the darkness.","她的眼睛过了一会儿才适应黑暗。"]},{"w":"accommodation","t":"n. 住处，膳宿","p":"əˌkɒmə'deɪʃn","e":["Universities have to provide student accommodation for first-year students.","大学必须为一年级生提供学生宿舍。"]},{"w":"accompany","t":"v. 陪同，伴随；为…伴奏","p":"ə'kʌmpəni","e":["Wherever her husband went, she would accompany him.","不论丈夫去哪里，她都陪伴左右。"]},{"w":"accomplish","t":"v. 实现","p":"ə'kʌmplɪʃ","c":1,"e":["Mission accomplished (=  we have done what we intended to do  ) .","大功告成。"]},{"w":"accord","t":"v. 相符合，相一致，相和谐；授予，赠与，给予；n. 一致，符合；谅解，协议","p":"ə'kɔːd","e":["You will not be accorded any special treatment.","你不会得到任何特殊待遇。"]},{"w":"accordance","t":"n. 一致，和谐，符合","p":"ə'kɔːdns","e":["If your pursuit of personal career and ideal are in accordance with ours, if you are seeking for the pleasure from sharing the same ambitions, please join us!","如果您想谋求个人事业、理想与公司的事业和理想高度一致，如果您追求的是志同道合的工作愉悦，请加入我们！"]},{"w":"account","t":"vi. 说明…的原因；占…；n. 记述；解释；账目","p":"ə'kaunt","e":["My husband and I have a joint account (=  one that is shared between two people  ) .","我和丈夫有个联名账户。"]},{"w":"accountable","t":"adj. 应负责的，有责任的","p":"ə'kauntəbl","c":1,"e":["The hospital should be held accountable for the quality of care it gives.","医院应当对医护质量负责。"]},{"w":"accountant","t":"n. 会计","p":"əˈkaʊntənt","c":1,"e":["The accountant checked this unnecessary spending in good time.","会计及时卡住了这笔不必要的开支。"]},{"w":"accrue","t":"v. 积累","p":"ə'kru:","c":1,"e":["Interest will accrue until payment is made.","利息将会累计增加，直至付清款项。"]},{"w":"accumulate","t":"v. 积累","p":"əˈkju:mjəleɪt","c":1,"e":["It is unjust that a privileged few should continue to accumulate wealth.","少数特权阶级继续积聚财富，这是不公平的。"]},{"w":"accurate","t":"adj. 精确的","p":"ˈækjərət","c":1,"e":["It is difficult to get accurate figures on population numbers.","很难取得精确的人口统计数字。"]},{"w":"accuse","t":"v. 指控","p":"ə'kju:z","c":1,"e":["The professor stands accused of (=  has been accused of  ) stealing his student’s ideas and publishing them.","那位教授被指控剽窃学生的观点拿去发表。"]},{"w":"accustom","t":"v. 使习惯","p":"ə'kʌstəm","c":1,"e":["She tried to accustom herself to the tight bandages.","她尝试着使自己习惯那些紧绷的绷带。"]},{"w":"accustomed","t":"adj. 惯常的，习惯的","p":"ə'kʌstəmd","e":["The pans were in their accustomed places.","那些锅在老地方。"]},{"w":"achieve","t":"v. 达到，实现","p":"ə'tʃi:v","c":1,"e":["She eventually achieved her goal of becoming a professor.","她终于实现目标，当上了教授。"]},{"w":"achievement","t":"n. 完成；成就，成绩","p":"ə'tʃiːvmənt","e":["His great achievement is to make all the players into a united team.","他的伟大成就在于把所有选手组织成一支团结的队伍。"]},{"w":"acid","t":"adj. 酸的，酸性的；尖刻的，刻薄的；n. 酸","p":"'æsɪd","e":["a juicy apple with a slightly acid flavour","一个多汁、略带酸味的苹果"]},{"w":"acknowledge","t":"vt. 承认，承认…的权威；告知收到，确认；对…表示谢意，报偿","p":"ək'nɒlɪdʒ","e":["The government must acknowledge what is happening and do something about it.","对于目前的情况，政府必须承认其存在并对此采取措施。"]},{"w":"acquaint","t":"vt. 使认识，使了解；使熟悉","p":"ə'kweɪnt","e":["I need to acquaint myself with the new regulations.","我得熟悉一下新的规章制度。"]},{"w":"acquaintance","t":"n. 熟人","p":"ə'kweɪntəns","c":1,"e":["He heard about the job through a mutual acquaintance (=  someone you and another person both know  ) .","他是通过一个双方都认识的人知道有这份工作的。"]},{"w":"acquire","t":"vt. 取得，获得；学到","p":"ə'kwaɪə","e":["Manning hoped to acquire valuable works of art as cheaply as possible.","曼宁希望以尽可能低的价格买到有价值的艺术品。"]},{"w":"action","t":"n. 行动","p":"'ækʃ(ə)n","e":["The government must take action (=do something) now to stop the rise in violent crime.","政府现在必须采取行动遏止暴力犯罪的上升。"]},{"w":"activate","t":"v. 激活","p":"'æktɪveɪt","c":1,"e":["The yeast’s growth is activated by sugar and warmth.","糖分和温暖的环境会激发酵母菌的生长。"]},{"w":"acute","t":"adj. 严重的；急性的；灵敏的，敏锐的；精明的","p":"ə'kjuːt","e":["The housing shortage is more acute than first thought.","住房短缺情况比一开始想的要严重。"]},{"w":"acutely","t":"adv. 强烈地","p":"əˈkju:tli","c":1,"e":["Students are becoming acutely aware that they need more than just paper qualifications.","学生越来越强烈地意识到他们需要的不仅是一纸文凭。"]},{"w":"adapt","t":"vt. 使适应；改编","p":"ə'dæpt","e":["The ability to adapt is a definite asset in this job.","适应能力是做这份工作的绝对有利条件。"]},{"w":"adaptation","t":"n. 改编版；适应","p":"ædəp'teɪʃ(ə)n","c":1,"e":["Branagh won two awards for his screen adaptation of Shakespeare's Henry the Fifth.","布拉纳因他对莎士比亚的《亨利五世》的荧幕改编而获了两次奖。"]},{"w":"addict","t":"n. 吸毒上瘾者；对…着迷的人","p":"'ædɪkt","c":1,"e":["My nephew is a complete video game addict.","我侄子绝对是个电子游戏迷。"]},{"w":"addition","t":"n. 加，加法；附加物","p":"ə'dɪʃn","e":["This is a fine book; a worthy addition to the series.","这是一本好书——是对这套丛书有价值的增补。"]},{"w":"additional","t":"adj. 附加的，追加的","p":"ə'dɪʃənl","e":["Additional information can be obtained from the centre.","可以从中心获取更多信息。"]},{"w":"address","t":"v. 解决","p":"ə'dres","c":1,"e":["Our products address the needs of real users.","我们的产品满足真正用户的需要。"]},{"w":"adequate","t":"adj. 足够的；可以胜任的","p":"'ædɪkwət","e":["Some creams we tested failed to give adequate protection against UV light.","我们检测的有些防晒霜不能提供足够的防紫外线保护。"]},{"w":"adhere","t":"vi. 黏附，附着；遵守；坚持；追随，支持","p":"əd'hɪə","e":["All members of the association adhere to a strict code of practice.","所有该协会的成员都遵守严格的业务守则。"]},{"w":"adjacent","t":"adj. 邻近的，毗连的","p":"ə'dʒeɪsnt","e":["We stayed in adjacent rooms.","我们住在毗连的房间里。"]},{"w":"adjoin","t":"vt. 贴近；与…毗连","p":"ə'dʒɔɪn","e":["A vacant plot of land adjoins his house.","有一块空地紧挨着他家。"]},{"w":"adjust","t":"vi. 适应；vt. 调整，调节；校正","p":"ə'dʒʌst","e":["They’ll soon settle in – kids are very good at adjusting.","他们很快就会习惯的——小孩子适应能力很强。"]},{"w":"adjustable","t":"adj. 可调整的，可校准的","p":"ə'dʒʌstəbl","e":["an adjustable spanner","一把活动扳手"]},{"w":"administration","t":"n. 管理；政府","p":"ədˌmɪnɪˈstreɪʃn","c":1,"e":["We’re looking for someone with experience in administration.","我们正在寻找一个有管理经验的人。"]},{"w":"admiration","t":"n. 钦佩；赞美，羡慕","p":"ædmə'reɪʃ(ə)n","e":["Daniel gazed at her in admiration .","丹尼尔用爱慕的眼神注视着她。"]},{"w":"admit","t":"vi. 承认；vt. 承认，供认；准许…进入","p":"əd'mɪt","e":["‘Okay, so maybe I was a little bit scared,’ Jenny admitted.","“行了，也许我是有点害怕。”珍妮承认道。"]},{"w":"adolescent","t":"adj. 青春期的；青少年的；n. 青少年","p":"ˌædə'lesnt","e":["It is important that an adolescent boy should have an adult in whom he can confide.","一个青春期男孩应该有一个他能倾吐心声的成年人，这是很重要的。"]},{"w":"adopt","t":"v. 采纳","p":"ə'dɒpt","c":1,"e":["The courts were asked to adopt a more flexible approach to young offenders.","法庭被要求对少年犯采取更为灵活的处理方法。"]},{"w":"adoption","t":"n. 收养；采纳，采取","p":"ə'dɒpʃ(ə)n","e":["She decided to put the baby up for adoption.","她决定让人收养那个婴儿。"]},{"w":"adore","t":"vt. 崇拜，敬慕；爱慕，热爱；非常喜欢","p":"ə'dɔː","e":["Betty adores her grandchildren.","贝蒂非常宠爱孙辈。"]},{"w":"advantage","t":"n. 优点，优势；好处","p":"əd'vɑːntɪdʒ","e":["Younger workers tend to be at an advantage (=  have an advantage  ) when applying for jobs.","年轻点的工人申请工作时往往处于优势地位。"]},{"w":"advantageous","t":"adj. 有利的，有助的","p":"ædvən'teɪdʒəs","e":["He was now in a more advantageous position.","他现在的位置更有利。"]},{"w":"adventure","t":"n. 冒险","p":"əd'ventʃə(r)","c":1,"e":["Ahab’s adventures at sea","亚哈的海上历险"]},{"w":"adventurer","t":"n. 冒险者","p":"ədˈventʃərə(r)","c":1,"e":["an adventurer travelling the world","周游世界的冒险家"]},{"w":"adverse","t":"adj. 不利的","p":"ˈædvɜ:s","c":1,"e":["They fear it could have an adverse effect on global financial markets.","他们担心这会对全球金融市场产生不利影响。"]},{"w":"adversely","t":"adv. 不利地","p":"əd'vɜ:slɪ","c":1,"e":["Her health was adversely affected by the climate.","那种气候损害了她的健康。"]},{"w":"adversity","t":"n. 逆境","p":"ədˈvɜːsəti","c":1,"e":["his courage in the face of adversity","他面对逆境的勇气"]},{"w":"advertise","t":"v. 登广告","p":"'ædvətaɪz","e":["They no longer advertise alcohol or cigarettes at sporting events.","他们不再在体育赛事上做烟酒广告了。"]},{"w":"advisable","t":"adj. 可取的；适当的","p":"əd'vaɪzəbl","e":["It is advisable to write a career objective at the start of your resume.","简历开头最好写上职业目标。"]},{"w":"advocate","t":"vt. 拥护，提倡，主张；n. 拥护者，提倡者；辩护者，律师","p":"'ædvəkeɪt；-ət","e":["Extremists were openly advocating violence.","极端主义者公开鼓吹使用暴力。"]},{"w":"aerial","t":"adj. 飞机的，航空的；空中的，架空的；n. 天线","p":"'eərɪəl","e":["an aerial view of the Three Gorges Dam project","一张三峡大坝工程鸟瞰图"]},{"w":"aerospace","t":"n. 航空航天工业","p":"'eərəspeɪs","e":["employment in the aerospace industry","航空航天工业的工作"]},{"w":"aesthetic","t":"adj. 美学的，审美的；悦目的，雅致的","p":"iːs'θetɪk","e":["From an esthetic point of view, it’s a nice design.","从美学角度看，这是个不错的设计。"]},{"w":"affection","t":"n. 喜爱","p":"əˈfekʃn","c":1,"e":["The church was held in great affection (=  loved and cared about a lot  ) by the local residents.","教会深受当地民众爱戴。"]},{"w":"affiliate","t":"v. 使隶属于","p":"əˈfɪlieɪt","c":1,"e":["The Society is not affiliated with any political party.","该社团不隶属任何政党。"]},{"w":"affiliation","t":"n. 隶属关系，单位团体","p":"ə,fɪlɪ'eʃən","c":1,"e":["the newspaper’s political affiliations","该报纸所属的政治派系"]},{"w":"affirm","t":"vt. 断言，坚持声称；证实，确认","p":"ə'fɜːm","e":["The general affirmed rumors of an attack.","将军证实了袭击的传闻。"]},{"w":"afflict","t":"vt. 使苦恼，折磨","p":"ə'flɪkt"},{"w":"afford","t":"vt. 担负得起；提供","p":"ə'fɔːd","e":["The room affords a beautiful view over the city.","这房间可以俯瞰城市美景。"]},{"w":"agenda","t":"n. 议程","p":"ə'dʒendə","c":1,"e":["The Republicans have stuck to their conservative agenda.","共和党人坚持自己的保守议题。"]},{"w":"agent","t":"n. 代理人，代理商；政府代表；动因，原因；剂","p":"'eɪdʒənt","e":["Our agent in Rio deals with all our Brazilian business.","我们在里约热内卢的业务代表处理我们在巴西的全部业务。"]},{"w":"aggravate","t":"v. 加重，加剧","p":"'æɡrəveɪt","c":1,"e":["Their money problems were further aggravated by a rise in interest rates.","由于利率上调，他们的财务问题更加严重。"]},{"w":"aggregate","t":"adj. 总计的，合计的；n. 总数，合计；vt. 总计达，合计；使聚集，使积聚","p":"'ægrɪgət; (for v.) ˈægrɪgeɪt","e":["an increase in the aggregate production","总产量的增长"]},{"w":"aggressive","t":"adj. 挑衅的","p":"əˈgresɪv","c":1,"e":["Teachers apparently expect a certain amount of aggressive behaviour from boys.","老师显然料到男孩子多少会有些好勇斗狠的行为。"]},{"w":"agitation","t":"n. 鼓动，煸动；搅动","p":"ædʒɪ'teɪʃ(ə)n","e":["mass agitation for political reform","要求政治改革的大骚动"]},{"w":"agonize","t":"v. 使痛苦","p":"'æɡənaɪz","c":1,"e":["All the way home she agonized about what she should do.","回家一路上，她都在发愁该怎么办。"]},{"w":"agony","t":"n. 痛苦","p":"'ægənɪ","c":1,"e":["the agony of arthritis","关节炎的剧烈疼痛"]},{"w":"agreeable","t":"adj. 令人愉快的，惬意的；同意的，乐意的","p":"ə'griːəbl","e":["We spent a most agreeable couple of hours.","我们非常愉快地度过了几个小时。"]},{"w":"aid","t":"v. 援助，有助于","p":"eɪd","c":1,"e":["an index to aid the reader","方便读者的索引"]},{"w":"air-conditioning","t":"n. 空调设备，空调系统","p":"'eəkənˌdɪʃənɪŋ","e":["The two chief function of any air-conditioning system are the regulation of air temperature and humidity.","任何空气调节系统的两大主要功能，就是调节空气的温度和湿度。"]},{"w":"aisle","t":"n. 过道，通道","p":"aɪl","e":["Would you like a window seat or an aisle seat (=  seat next to the aisle  ) ?","您想要靠窗的座位还是靠过道的座位？"]},{"w":"alarm","t":"n. 惊恐，忧虑，警报；vt. 使惊恐，使担心","p":"ə'lɑːm","e":["Car alarms are always going off in the street.","街上总有汽车警报器在响。"]},{"w":"alas","t":"int. 唉，哎呀","p":"ə'læs; ə'lɑːs","e":["For many people, alas, hunger is part of everyday life.","唉，对很多人来说，挨饿是家常便饭。"]},{"w":"album","t":"n. 粘贴簿，集邮簿，相册","p":"'ælbəm","e":["a photograph album","相册"]},{"w":"alcohol","t":"n. 酒精，乙醇","p":"'ælkəhɒl","e":["{\"GLOSS\":[\"when someone drinks too much\"],\"COLLOINEXA\":[\"alcohol abuse\"]}","酗酒"]},{"w":"alert","t":"adj. 机警的；v. 提醒","p":"ə'lɜ:t","c":1,"e":["campaigns to alert the public to the dangers of HIV","让公众意识到艾滋病病毒危险的宣传活动"]},{"w":"algebra","t":"n. 代数学","p":"'ældʒɪbrə","e":["He was not good at algebra in middle school.","他中学时不擅长代数。"]},{"w":"alien","t":"adj. 陌生的","p":"'eɪlɪən","c":1,"e":["the alien environment of the city","城里陌生的环境"]},{"w":"alienate","t":"vt. 使疏远，使不友好，离间；转让，让渡","p":"'eɪlɪəneɪt","e":["The latest tax proposals will alienate many voters.","最新的纳税提案将失去远许多选民的支持。"]},{"w":"alignment","t":"n. 排成直线；结盟，联合","p":"ə'laɪnm(ə)nt","e":["the geometrical alignment of the Sun, Moon, and Earth at the eclipse","日蚀或月蚀发生时太阳、月亮和地球成几何直线的排列"]},{"w":"allege","t":"vt. 断言，宣称，硬说","p":"ə'ledʒ","e":["She alleged that there was rampant drug use among the male members of the group.","她指称该组织中有大量的男性成员吸毒。"]},{"w":"allegedly","t":"adv. 据说","p":"ə'ledʒɪdlɪ","c":1,"e":["a sports car, allegedly stolen in Manchester","据说是在曼彻斯特被偷的一辆跑车"]},{"w":"allergic","t":"adj. 过敏的","p":"əˈlɜ:dʒɪk","c":1,"e":["an allergic reaction to nuts","对坚果的过敏性反应"]},{"w":"alleviate","t":"v. 减轻，缓解","p":"əˈliːvieɪt","c":1,"e":["measures to alleviate poverty","扶贫措施"]},{"w":"alliance","t":"n. 结盟；联盟","p":"ə'laɪəns","e":["independent organizations and alliances","独立组织和联盟"]},{"w":"allied","t":"adj. 联合的；联姻的","p":"'ælaɪd; ə'laɪd"},{"w":"allocate","t":"vt. 分配；分派，把…拨给","p":"'æləkeɪt","e":["Tickets are limited and will be allocated to those who apply first.","票数有限，将分配给那些先申请的人。"]},{"w":"allowance","t":"n. 津贴，补贴；零用钱","p":"ə'lauəns","e":["If you are entitled to sickness allowance, you must claim it from your employer.","你如果有资格领取疾病津贴，必须向雇主申请索要。"]},{"w":"alloy","t":"n. 合金；vt. 将…铸成合金","p":"'ælɒɪ","e":["Brass is an alloy of copper and zinc.","黄铜是铜和锌的合金。"]},{"w":"ally","t":"n. 盟国；同盟者，伙伴","p":"'ælaɪ","e":["Ridley was one of the Queen’s closest allies.","里德利是女王最亲密的盟友之一。"]},{"w":"alongside","t":"prep. 在…旁边","p":"əlɒŋ'saɪd","e":["He crossed the street and walked alongside Central Park.","他过了马路，然后在中央公园旁边走着。"]},{"w":"alphabetical","t":"adj. 按字母表顺序的","p":"ˌælfəˈbetɪkl","c":1,"e":["The files are arranged in alphabetical order .","这些文件按字母顺序排列。"]},{"w":"alter","t":"vt. 改变，变更，变动","p":"'ɔːltə","e":["The city centre has altered beyond recognition (=  changed very much  ) .","市中心变得都认不出来了。"]},{"w":"alteration","t":"n. 变更，改变","p":"ɔːltə'reɪʃ(ə)n; 'ɒl-","e":["If you make alterations to the Windows setup, save the new settings before closing.","如果更改了视窗操作系统的设置，关闭前要保存新的设置。"]},{"w":"alternate","t":"adj. 交替的，轮流的；间隔的；v. 轮流，交替","p":"ˈɔ:ltəneɪt;(for adj.)ɔ:lˈtɜ:nət","e":["alternate blue and red stripes","蓝红相间的条纹"]},{"w":"alternative","t":"n. 代替品","p":"ɔ:lˈtɜ:nətɪv","c":1,"e":["New ways to treat arthritis may provide an alternative to painkillers.","治疗关节炎的新方法可能会提供一种止痛药的替代品。"]},{"w":"alternatively","t":"adv. 二选一地；非此即彼","p":"ɔːl'tɜːnətɪvlɪ","c":1,"e":["Hotels are generally of a good standard and not too expensive. Alternatively you could stay in an apartment.","旅馆一般标准高并且不太贵。或者你可以住公寓。"]},{"w":"amateur","t":"adj. 业余的；n. 业余爱好者","p":"'æmətə; -tʃə; -tjʊə; ,æmə'tɜː","e":["...professional athletes and amateur runners.","…专业运动员和业余赛跑运动员。"]},{"w":"ambassador","t":"n. 大使，使节","p":"æm'bæsədə","e":["the US ambassador to Spain","美国驻西班牙大使"]},{"w":"ambient","t":"adj. 周围的，包围着的","p":"'æmbɪənt","e":["...ambient sounds of children in the background.","...背景处环绕着孩子们的声音。"]},{"w":"ambiguous","t":"adj. 引起歧义的，模棱两可的，含糊不清的","p":"æm'bɪgjuəs","e":["The language in the Minister’s statement is highly ambiguous.","部长的声明措辞很含糊。"]},{"w":"ambition","t":"n. 野心，报复","p":"æmˈbɪʃn","c":1,"e":["He was young and full of ambition.","他年轻，而且雄心勃勃。"]},{"w":"ambitious","t":"adj. 有抱负的，雄心勃勃的；有野心的","p":"æm'bɪʃəs","e":["Alfred was intensely ambitious, obsessed with the idea of becoming rich.","艾尔弗雷德雄心勃勃，一心想着发财。"]},{"w":"amend","t":"v. 修订","p":"əˈmend","c":1,"e":["‘Steve stole it – or rather borrowed it,’ he amended.","“史蒂夫偷的——应该说是借的。”他改口道。"]},{"w":"ammunition","t":"n. 弹药，军火","p":"ˌæmju'nɪʃn","e":["He had only seven rounds of ammunition for the revolver.","他只有7发左轮手枪的弹药。"]},{"w":"ample","t":"adj. 足够的；宽敞的","p":"'æmp(ə)l","e":["There'll be ample opportunity to relax, swim and soak up some sun.","将会有充足的机会来放松、游泳和接受一些阳光。"]},{"w":"amplify","t":"vt. 放大，增强；扩大；详述，进一步阐述","p":"'æmplɪfaɪ","e":["an amplified guitar","带有扩音设备的电吉他"]},{"w":"amplitude","t":"n. 振幅；广大；充足","p":"'æmplɪtjuːd","e":["As we fall asleep the amplitude of brain waves slowly becomes greater.","进入睡眠状态时，我们的脑电波振幅慢慢变大。"]},{"w":"amusement","t":"n. 乐趣；娱乐，消遣","p":"ə'mjuːzm(ə)nt","e":["Steve couldn’t hide his amusement.","史蒂夫忍俊不禁。"]},{"w":"analogous","t":"adj. 类似的，相似的；可比拟的","p":"ə'næləgəs","e":["Marine construction technology like this is very complex, somewhat analogous to trying to build a bridge under water.","像这样的海洋建筑技术非常复杂，有些类似于尝试在水下建筑一座桥。"]},{"w":"analogue","t":"n. 类似物","p":"'ænəlɒg","e":["Scientists are attempting to compare features of extinct animals with living analogues.","科学家正试图把已灭绝动物的特征与现存类似动物相比较。"]},{"w":"analogy","t":"n. 比拟；类比，类推","p":"ə'nælədʒi","e":["The analogy between music and fragrance has stuck.","音乐与香味的类比已经深入人心了。"]},{"w":"analyse","t":"vt. 分析；分解，解析","p":"'ænəlaɪz","e":["You need to sit down and analyse why you feel so upset.","你得坐下来想一想自己为什么会那么生气。"]},{"w":"analysis","t":"n. 分析，分析报告；分解，解析","p":"ə'næləsɪs","e":["She’s been in analysis for three years.","她接受精神分析治疗已经三年了。"]},{"w":"analytical","t":"adj. 分析的","p":"ˌænəˈlɪtɪkl","c":1,"e":["analytical chemistry","分析化学"]},{"w":"ancestor","t":"n. 祖宗，祖先；原型；先驱","p":"'ænsestə","e":["My ancestors were French.","我的祖先是法国人。"]},{"w":"ancient","t":"adj. 古代的","p":"'eɪnʃənt","c":1,"e":["the ancient civilizations of Asia","亚洲的古代文明"]},{"w":"ankle","t":"n. 脚踝","p":"ˈæŋkl","c":1,"e":["slender ankles","纤细的脚踝"]},{"w":"anniversary","t":"n. 周年","p":"ˌænɪ'vɜːsəri","e":["Jack and Kim celebrated their twentieth wedding anniversary in January.","1月，杰克和金庆祝了他们的结婚20周年纪念日。"]},{"w":"announce","t":"v. 报告…的来到","p":"ə'naʊns","e":["After announcing himself at the reception desk, James was led upstairs.","在接待处通报姓名后，詹姆斯被领上楼去。"]},{"w":"annoy","t":"vt. 使恼怒；打搅","p":"ə'nɔɪ","e":["What annoyed him most was that he had received no apology.","最令他生气的是没人向他道歉。"]},{"w":"annual","t":"adj. 每年的，一年一次的；n. 年报，年鉴；一年生的植物","p":"'ænjuəl","e":["The school trip has become an annual event.","学校组织的旅行成了一年一度的活动。"]},{"w":"annually","t":"adv. 年年，每年","p":"'ænjʊəlɪ; 'ænjʊlɪ","e":["The exhibition is held annually.","这个展览每年举行一次。"]},{"w":"anode","t":"n. 阳极，正极，板极","p":"'ænəʊd","e":["The kit comes with an anode, a cathode, and an LED light.","这种套装电池包括一根阳极、一根阴极和一颗LED灯。"]},{"w":"anonymous","t":"adj. 匿名的","p":"ə'nɒnɪməs","c":1,"e":["According to one employee, who wishes to remain anonymous , the company engaged in illegal activities.","根据一位不愿透露姓名的员工所述，这家公司曾从事非法活动。"]},{"w":"answer","t":"v. 符合，适合","p":"'ɑːnsə","e":["Does this answer your requirements?","这个符合你的要求吗？"]},{"w":"antenna","t":"n. 触角；天线","p":"æn'tenə","e":["The minister was praised for his acute political antennae (= ability to understand complicated political situations) .","这位部长以政治触觉敏锐而为人称道。"]},{"w":"anticipate","t":"v. 期望，预期","p":"æn'tɪsɪpeɪt","c":1,"e":["A good speaker is able to anticipate an audience’s needs and concerns.","好的演讲者能够预先考虑到听众需要什么、关注什么。"]},{"w":"antique","t":"adj. 古时的，古老的；n. 古物，古玩，古董","p":"æn'tiːk","e":["an antique rosewood desk","古董红木书桌"]},{"w":"anxiety","t":"n. 焦虑","p":"æŋ'zaɪətɪ","c":1,"e":["A high level of anxiety was created by the introduction of cameras into the factory.","工厂安装了摄像头，这引起了工人的高度不安。"]},{"w":"anybody","t":"n. 重要人物","e":["She wasn't anybody before she got that job.","她在获得那个职位之前不过是个无名之辈。"]},{"w":"apartment","t":"n. 公寓","p":"əˈpɑ:tmənt","c":1,"e":["She lives in a small apartment.","她住在一套小公寓里。"]},{"w":"apathy","t":"n. 冷漠","p":"ˈæpəθi","c":1,"e":["The campaign failed because of public apathy.","由于公众反应冷淡，这次运动失败了。"]},{"w":"apologize","t":"v. 道歉","p":"ə'pɒlədʒaɪz","c":1,"e":["I’m so sorry, I do apologize.","非常对不起，我真心道歉。"]},{"w":"apology","t":"n. 道歉，认错，谢罪","p":"ə'pɒlədʒi","e":["Edward can’t be here today, but he sends his apologies .","爱德华今天来不了，他向大家表示歉意。"]},{"w":"apparatus","t":"n. 器械，器具，仪器；机构，组织","p":"ˌæpə'reɪtəs","e":["Astronauts have special breathing apparatus.","航天员有专门的呼吸装装备。"]},{"w":"apparent","t":"adj. 显然的","p":"ə'pær(ə)nt","e":["The difference in quality was immediately apparent .","质量的差异显而易见。"]},{"w":"appeal","t":"n. 请求，呼吁,；上诉","p":"əˈpiːl","c":1,"e":["The girl’s family have made a public appeal for help to try and catch her killer.","那名遇害女孩的家人吁请公众协助捉拿凶手。"]},{"w":"appearance","t":"n. 出现，来到；外观","p":"ə'pɪərəns","e":["They work hard at school without giving the appearance of being particularly hard-working.","他们在学校里学习很用功，只是表面上并不显得特别如此。"]},{"w":"appease","t":"vt. 平息，抚慰；姑息","p":"ə'piːz","e":["They attempted to appease international opposition by promising to hold talks.","他们答应举行会谈，试图以此平息国际上的反对声音。"]},{"w":"appendix","t":"n. 阑尾；附录","p":"ə'pendɪks","e":["Christine had to go into hospital to have her appendix out (=  have it removed  ) .","克里丝蒂娜不得不去医院切除阑尾。"]},{"w":"applaud","t":"vi. 鼓掌，喝彩；vt. 向…鼓掌，向…喝彩；称赞，赞许","p":"ə'plɔːd","e":["A crowd of 300 supporters warmly applauded her speech.","300名支持者为她的演讲热烈鼓掌。"]},{"w":"applause","t":"n. 喝彩；夸奖，称赞","p":"ə'plɔːz","e":["She got a round of applause (= a short period of applause) when she finished.","她结束的时候获得一阵掌声。"]},{"w":"appliance","t":"n. 用具，器具，器械","p":"ə'plaɪəns","e":["He could also learn to use the vacuum cleaner, the washing machine and other household appliances.","他还能学习使用吸尘器、洗衣机和其他家用电器。"]},{"w":"applicable","t":"adj. 可应用的","p":"əˈplɪkəbl","c":1,"e":["What is a reasonable standard for one family is not applicable for another.","对一个家庭合理的标准对于另一个家庭并不适用。"]},{"w":"applicant","t":"n. 申请者","p":"ˈæplɪkənt","c":1,"e":["We have had lots of applicants for these positions.","对这些职位我们已有了很多申请人。"]},{"w":"application","t":"n. 申请，申请书；施用，涂抹；应用，实施；实用性","p":"ˌæplɪ'keɪʃn","e":["The Council is currently reviewing the way it deals with planning applications .","市政会目前正在审查其处理规划申请的方式。"]},{"w":"apply","t":"vi. 应用，实施，使用；适用；申请，请求；vt. 涂，敷，施","p":"ə'plaɪ","e":["We need to apply for planning permission to build a garage.","我们建车库需要申请规划许可。"]},{"w":"appoint","t":"v. 任命","p":"ə'pɔɪnt","c":1,"e":["officials appointed by the government","政府任命的官员"]},{"w":"appraisal","t":"n. 估计，估量；评价","p":"ə'preɪzl","e":["What is needed in such cases is a calm appraisal of the situation.","在此类情况下需要的是对形势的冷静估计。"]},{"w":"appreciable","t":"adj. 可察觉的","p":"ə'priːʃəb(ə)l; -ʃɪə-","e":["There’s no appreciable change in the patient’s condition.","病人的状况没有明显改变。"]},{"w":"appreciation","t":"n. 欣赏；感激","p":"əpriːʃɪ'eɪʃ(ə)n; -sɪ-","e":["It helps children to develop an appreciation of poetry and literature.","这有助于培养小孩子对诗歌和文学作品的欣赏力。"]},{"w":"appreciative","t":"adj. 表示赞赏的，感谢的","p":"əˈpri:ʃətɪv","c":1,"e":["There is a murmur of appreciative laughter.","有一阵低低的赞赏的笑声。"]},{"w":"approach","t":"n. 方法","p":"ə'prəʊtʃ","c":1,"e":["He decided to adopt a different approach and teach the Bible through story-telling.","他决定采用一种不同的方法，通过讲故事来教授《圣经》。"]},{"w":"appropriate","t":"adj. 适当的","p":"ə'prəʊprɪət","c":1,"e":["The timing of the announcement was particularly appropriate .","通告发布的时机很合适。"]},{"w":"appropriation","t":"n. 挪用","p":"ə,prəʊprɪ'eɪʃ(ə)n","c":1,"e":["Other charges include fraud and illegal appropriation of land.","其他指控包括诈骗和非法占用土地。"]},{"w":"approval","t":"n. 赞成，同意；认可，批准","p":"ə'pruːvl","e":["It is just three months since we received official approval to go ahead with the project.","三个月前我们刚刚得到正式批准进行这个项目。"]},{"w":"approve","t":"v. 赞同","p":"ə'pru:v","c":1,"e":["Catherine’s parents now approve of her marriage.","凯瑟琳的父母现在认可她的婚姻了。"]},{"w":"approximately","t":"adv. 大约","p":"əˈprɒksɪmətli","c":1,"e":["The yolk contains all the fat and approximately half of the protein of the egg.","蛋黄含有鸡蛋中全部的脂肪和大约一半的蛋白质。"]},{"w":"apt","t":"adj. 易于…的，有…倾向的；恰当的，适宜的；聪明的，反应敏捷的","p":"æpt","e":["‘Love at first sight’ is a very apt description of how he felt when he saw her.","用“一见钟情”来形容他见到她时的感觉再恰当不过。"]},{"w":"aptly","t":"adv. 适当地","p":"ˈæptlɪ","c":1,"e":["The aptly named Skyline Restaurant provides spectacular views of the city below.","天际餐厅名副其实，可以俯瞰城市美景。"]},{"w":"arbitrary","t":"adj. 随心所欲的；专断的","p":"'ɑːbɪtrəri","e":["the arbitrary arrests of political opponents","对政敌的任意逮捕"]},{"w":"arc","t":"n. 弧形；弧；电弧，弧光","p":"ɑːk","e":["the arc of a rainbow","彩虹的弧状"]},{"w":"arch","t":"n. 拱门；v. （使）拱起","p":"ɑːtʃ","e":["Two rows of trees arched over the driveway.","车道两旁树木交错，形成一个拱顶。"]},{"w":"architect","t":"n. 建筑师；创造者","p":"'ɑːkɪtekt","e":["Tinoco was one of the architects of the government’s economic reforms.","蒂诺科是政府经济改革的设计师之一。"]},{"w":"arctic","t":"adj. 北极的；n. 北极","p":"'ɑːktɪk","e":["the Arctic island of Novaya Zemlya","北极的新地岛"]},{"w":"arena","t":"n. 表演场地，竞技场；活动场所","p":"ə'riːnə","e":["an indoor arena","室内剧场"]},{"w":"argue","t":"vi. 争论，争辩，辩论；vt. 主张；说服","p":"'ɑːgjuː","e":["We could hear the neighbours arguing.","我们听到邻居在争吵。"]},{"w":"arise","t":"v. 出现","p":"ə'raɪz","c":1,"e":["More problems like those at the nuclear power plant are certain to arise.","核电厂肯定还会出现那样的问题。"]},{"w":"arm","t":"v. 装备，武装","p":"ɑ:m","c":1,"e":["The local farmers have armed themselves with rifles and pistols.","当地的农场主用步枪和手枪武装自己。"]},{"w":"armor","t":"n. 盔甲，装甲；保护物","p":"'ɑːmə"},{"w":"arouse","t":"v. 唤起","p":"ə'raʊz","c":1,"e":["Matt’s behavior was arousing the interest of the neighbors.","马特的行为渐渐引起了邻居的兴趣。"]},{"w":"arrange","t":"v. 安排，准备；整理","p":"ə'reɪndʒ","e":["Contact your local branch to arrange an appointment.","请联络当地分部安排预约。"]},{"w":"arrangement","t":"n. 整理，排列；安排；准备工作","p":"ə'reɪndʒmənt","e":["Have you made all your travel arrangements?","你的旅行都安排好了吗？"]},{"w":"array","t":"n. 展示；陈列，一系列；排列，队形；衣服，盛装；","p":"ə'reɪ","e":["a bewildering array of options","一大堆眼花缭乱的选择"]},{"w":"arrest","t":"vt. 逮捕，拘留；停止，阻止；吸引；n. 逮捕，拘留，扣留","p":"ə'rest","e":["He was arrested and charged with murder.","他遭到逮捕并被指控谋杀。"]},{"w":"arrogant","t":"adj. 傲慢无礼的","p":"ˈærəgənt","c":1,"e":["He was unbearably arrogant.","他的傲慢让人无法忍受。"]},{"w":"artery","t":"n. 动脉；干线，要道","p":"'ɑːtəri","e":["...Connecticut Ave., one of the main arteries of Washington.","…康涅狄格大道，华盛顿的主干道之一。"]},{"w":"articulate","t":"adj. 善于表达的，发音清晰的；表达得清楚有力的；vt. 明确有力地表达；清楚地吐，清晰地发","p":"ɑ:'tɪkjʊleɪt","e":["bright, articulate 17-year-olds","聪明伶俐的17岁少年"]},{"w":"artificial","t":"adj. 人造的；虚伪的","p":"ˌɑ:tɪ'fɪʃl","c":1,"e":["an artificial smile","假笑"]},{"w":"artillery","t":"n. 火炮，大炮；炮兵","p":"ɑː'tɪləri","e":["Using tanks and heavy artillery, they seized the town.","他们使用坦克和重炮攻下了这座城市。"]},{"w":"ascend","t":"v. 上升","p":"ə'send","c":1,"e":["The plane ascended rapidly.","飞机迅速爬升。"]},{"w":"ascertain","t":"vt. 弄清，查明；确定","p":"ˌæsə'teɪn","e":["A postmortem was ordered to try to ascertain the cause of death.","下令验尸以查明死因。"]},{"w":"ascribe","t":"vt. 把…归因于，把…归属于","p":"ə'skraɪb","e":["An autopsy eventually ascribed the baby's death to sudden infant death syndrome.","一次尸检最终把这名婴儿的死亡归因于婴儿猝死综合症。"]},{"w":"ashore","t":"adv. 在岸上，上岸","p":"ə'ʃɔː","e":["Several dead birds had been washed ashore.","几只死鸟被冲上了岸。"]},{"w":"aspect","t":"n. 方面","p":"'æspekt","c":1,"e":["Dealing with people is the most important aspect of my work.","与人打交道是我工作中最重要的一方面。"]},{"w":"aspiration","t":"n. 强烈的愿望；志向，抱负","p":"ˌæspə'reɪʃn","e":["a high level of political aspiration","崇高的政治抱负"]},{"w":"aspirational","t":"adj. 渴望成功的的","p":"ˌæspəˈreɪʃənl","c":1,"e":["aspirational young women","有抱负的年轻女性"]},{"w":"ass","t":"n. 傻瓜，蠢笨的人；驴","p":"æs","e":["He’s a pompous ass.","他是头自负的蠢驴。"]},{"w":"assassinate","t":"v. 刺杀，暗杀","p":"ə'sæsɪneɪt","c":1,"e":["a plot to assassinate the President","刺杀总统的阴谋"]},{"w":"assassination","t":"n. 刺杀，暗杀","p":"əˌsæsɪ'neɪʃn","e":["He narrowly escaped an assassination attempt (=  when someone tries but fails to kill someone else  ) .","他在一次暗杀行动中死里逃生。"]},{"w":"assault","t":"n. 攻击","p":"əˈsɔ:lt","c":1,"e":["The refugee camp came under assault again last night.","昨晚难民营再次遭袭。"]},{"w":"assemble","t":"v. 收集，组装","p":"ə'sembl","c":1,"e":["The aircraft will continue to be assembled in France.","飞机将继续在法国组装。"]},{"w":"assert","t":"v. 主张，断言","p":"əˈsɜːt","c":1,"e":["French cooking, she asserted, is the best in the world.","她坚称法国菜是世界上最好的。"]},{"w":"assertive","t":"adj. 断定的；过分自信的","p":"ə'sɜːtɪv","e":["Women have become more assertive in the past decade.","妇女在过去十年已变得更坚定自信。"]},{"w":"assess","t":"vt. 对估价；评价，评论","p":"ə'ses","e":["The test was to assess aptitude rather than academic achievement.","该测试将评估能力而不是学业成绩。"]},{"w":"assessment","t":"n. 评估，评价","p":"əˈsesmənt","c":1,"e":["a reading assessment test","阅读评估测试"]},{"w":"asset","t":"n. 资产，财产；有价值的特性或技能，优点","p":"'æset","e":["the value of a company’s assets","公司的资产价值"]},{"w":"assign","t":"vt. 指派，分配；布置；指定","p":"ə'saɪn","e":["How much time have you assigned for the meeting?","你给这个会议定了多长时间？"]},{"w":"assignment","t":"n. 任务；指定的作业；分配，指派","p":"ə'saɪnmənt","e":["a history assignment","历史作业"]},{"w":"assimilate","t":"v. 同化","p":"əˈsɪməleɪt","c":1,"e":["Refugees find it difficult to become assimilated into the community.","难民觉得难以融入社区。"]},{"w":"assimilation","t":"n. 同化，同化作用；消化","p":"əˌsɪmə'leɪʃn","e":["Ethnic amalgamation ethnic assimilation and ethnic fusion of culture are three kinds of different phenomena in ethnic relation.","民族融合、民族同化和民族文化融合是民族关系中存在的三种不同的现象。"]},{"w":"assistance","t":"n. 协助，援助","p":"ə'sɪstəns","e":["Can I be of any assistance (=  can I help you  ) ?","我能帮什么忙吗？"]},{"w":"associate","t":"v. 把…联系在一起；使联合，结合；交往 [ə'səuʃiət]；adj. 副的；n. 伙伴，同事","p":"ə'səuʃieɪt","e":["Through science we've got the idea of associating progress with the future.","通过科学我们已有了将进步与未来联系起来的观念。"]},{"w":"association","t":"n. 联系","p":"əˌsəʊʃɪ'eɪʃn","c":1,"e":["his close association with the Green Party","他与绿党的密切关系"]},{"w":"assume","t":"v. 假定，认为","p":"əˈsju:m","c":1,"e":["I think we can safely assume (=  it is almost certain  ) that interest rates will go up again soon.","我想我们几乎可以肯定，利率很快会再次上调。"]},{"w":"assumption","t":"n. 假设","p":"əˈsʌmpʃn","c":1,"e":["A lot of people make the assumption that poverty only exists in the Third World.","许多人以为贫困仅仅存在于第三世界。"]},{"w":"assurance","t":"n. 把握，信心；保证，表示保证的话；保险","p":"ə'ʃuərəns","e":["Despite my repeated assurances, Rob still looked very nervous.","尽管我再三保证，罗布看起来还是很紧张。"]},{"w":"assure","t":"vt. 使确信；确保，向…保证","p":"ə'ʃuə","e":["The document is genuine, I can assure you .","我能向你保证，这文件是真的。"]},{"w":"astonishment","t":"n. 惊奇，惊讶","p":"ə'stɒnɪʃmənt","e":["She stared at him in astonishment.","她吃惊地看着他。"]},{"w":"astronomical","t":"adj. 天文数字的","p":",æstrə'nɑmɪkl","c":1,"e":["Houses in the subdivision are going for astronomical prices.","该小区里的房子在以天价出售。"]},{"w":"astronomy","t":"n. 天文学","p":"ə'strɒnəmɪ","e":["Do you know anything about astronomy?","你懂天文学吗?"]},{"w":"athlete","t":"n. 运动员，体育家","p":"'æθliːt","e":["a professional athlete","一位专业运动员"]},{"w":"athletic","t":"adj. 强壮的；擅长运动的；运动的，运动员的","p":"æθˈletɪk","c":1,"e":["They have been given college scholarships purely on athletic ability.","他们完全凭他们的运动才能获得了大学奖学金。"]},{"w":"athletics","t":"n. 体育运动","p":"æθˈletɪks","c":1,"e":["...students who play intercollegiate athletics.","…参加大学校际体育运动的学生们。"]},{"w":"atlas","t":"n. 地图集","p":"'ætləs","e":["The atlas should help the eradication fight by letting health officials know just where the problem areas are.","而这些地图集刚好能帮助卫生局高清楚问题地区所在，然后将虫虫们斩草除根。"]},{"w":"atmosphere","t":"n. 气氛；大气（层）","p":"'ætməsfɪə(r)","c":1,"e":["The shuttle Columbia will re-enter Earth's atmosphere tomorrow morning.","哥伦比亚号航天飞机将在明天上午重进地球大气层。"]},{"w":"atom","t":"n. 原子","p":"'ætəm","e":["carbon atoms","碳原子"]},{"w":"attach","t":"vt. 缚，系，贴，附加；使依恋，使喜爱；使附属；认为有","p":"ə'tætʃ","e":["When approving a merger, the commission can attach conditions.","委员会在批准公司合并时可能附加条件。"]},{"w":"attachment","t":"n. 爱慕；附件；连接物","p":"ə'tætʃm(ə)nt","e":["the attachments that secure your boots firmly to the skis","把靴子牢牢固定在滑雪板上的扣件"]},{"w":"attack","t":"n&vt. 攻击，进攻；突然发作","p":"ə'tæk","e":["victims of racial attacks","种族袭击的受害者"]},{"w":"attain","t":"vt. 达到，获得；完成","p":"ə'teɪn","e":["More women are attaining positions of power.","越来越多的女性获得要职。"]},{"w":"attempt","t":"vt. 尝试，试图，努力","p":"ə'tempt","e":["Weather conditions prevented them from attempting the jump.","天气状况使他们无法尝试跳伞。"]},{"w":"attendance","t":"n. 到场；出席人数","p":"ə'tend(ə)ns","e":["Last year’s fair saw attendance figures of 32,000.","去年的交易会有3.2万人参加。"]},{"w":"attendant","t":"n. 服务人员","p":"əˈtendənt","c":1,"e":["a car park attendant","停车场的服务员"]},{"w":"attitude","t":"n. 态度，看法；姿势","p":"'ætɪtjuːd","e":["As soon as they found out I was a doctor, their whole attitude changed.","他们一听说我是医生，态度就完全改变了。"]},{"w":"attorney","t":"n. 代理人；辩护律师","p":"ə'tɜːnɪ","e":["...a prosecuting attorney.","…一位公诉律师。"]},{"w":"attract","t":"vt. 吸引，引起…注意","p":"ə'trækt","e":["I’m not usually attracted to blondes.","我一般不喜欢金发女子。"]},{"w":"attractive","t":"adj. 有吸引力的，引起注意的","p":"ə'træktɪv","e":["Women seem to find him attractive .","女性似乎觉得他很有吸引力。"]},{"w":"attribute","t":"v. 归因于","p":"əˈtrɪbjuːt","c":1,"e":["Women tend to attribute their success to external causes such as luck.","女性往往把她们的成功归因于外因，如运气。"]},{"w":"auction","t":"n&vt. 拍卖","p":"'ɔːkʃn","e":["The painting is expected to fetch up to $400,000 at auction.","这幅画预计在拍卖会上能卖到40万美元。"]},{"w":"audience","t":"n. 听众，观众；读者","p":"'ɔːdiəns","e":["One member of the audience described the opera as ‘boring’.","有一名观众说这出歌剧“乏味”。"]},{"w":"authentic","t":"adj. 真的，真正的；可靠的，可信的","p":"ɔː'θentɪk","e":["an authentic account","真实可信的说法"]},{"w":"author","t":"n. 著作家，作者","p":"'ɔːθə","e":["It’s clear that the author is a woman.","显然，这位作者是女性。"]},{"w":"authoritative","t":"adj. 有权威性的，可信的；专断的，命令式的","p":"ɔː'θɒrətətɪv","e":["the most authoritative work on English surnames","有关英语姓氏的最权威著作"]},{"w":"authorities","t":"n. 当局","p":"ɔ:'θɒrɪtɪs","c":1,"e":["This provided a pretext for the authorities to cancel the elections.","这给当局提供了一个取消选举的借口。"]},{"w":"authority","t":"n. 权威；当局","p":"ɔ:ˈθɒrəti","c":1,"e":["an agreement between the US and Colombian authorities","美国和哥伦比亚当局的一份协议"]},{"w":"authorization","t":"n. 授权","p":"ˈɔ:θəraɪzeɪʃən","c":1,"e":["Children may not leave the building without the authorization of the principal.","没有校长的许可，孩子们不能离开这幢楼。"]},{"w":"authorize","t":"vt. 授权，批准","p":"'ɔːθəraɪz","e":["an authorized biography","授权传记"]},{"w":"automate","t":"v. 使自动化","p":"'ɔːtəmeɪt","e":["Cash machines automate two basic functions of a bank – deposits and withdrawals.","柜员机使银行的两个基本功能——存款和取款自动化了。"]},{"w":"automatic","t":"adj. 自动的","p":"ˌɔ:tə'mætɪk","c":1,"e":["My camera is fully automatic .","我的照相机是全自动的。"]},{"w":"Automatically","t":"adv. 自动地；不经思考地","p":"ɔːtə'mætɪklɪ","c":1,"e":["The doors opened automatically as we approached.","我们走近时，门自动开了。"]},{"w":"autonomous","t":"adj. 自治的；独立自主的","p":"ɔː'tɒnəməs","e":["They proudly declared themselves part of a new autonomous province.","他们自豪地宣布自己是新自治省的一部分。"]},{"w":"autonomy","t":"n. 自治，自治权；人身自由，自主权","p":"ɔː'tɒnəmi","e":["campaigners who want greater autonomy for Corsica","希望科西嘉有更多自治权的活动家"]},{"w":"auxiliary","t":"adj. 辅助的","p":"ɔ:gˈzɪliəri","c":1,"e":["an auxiliary nurse","助理护士"]},{"w":"avail","t":"v. 有帮助；有益；有用；n. 效用，利益，帮助","p":"ə'veɪl","e":["Guests should feel at liberty to avail themselves of your facilities.","客人们应可以随意使用你们的设施。"]},{"w":"availability","t":"n. 有效（性）；可得性","p":"ə,veɪlə'bɪlətɪ","e":["the availability of cheap flights","有廉价机票出售"]},{"w":"available","t":"adj. 可获得的，可利用的","p":"əˈveɪləbl","c":1,"e":["Meetings were held to update employees as soon as new information became available .","一有新的信息就开会告诉员工。"]},{"w":"avert","t":"vt. 防止，避免；转移","p":"ə'vɜːt","e":["The tragedy could have been averted if the crew had followed safety procedures.","如果乘务人员按照安全规则操作，这场悲剧是可以避免的。"]},{"w":"aviation","t":"n. 航空，航空学；飞机制造业","p":"ˌeɪvi'eɪʃn","e":["...the aviation industry.","…航空工业。"]},{"w":"avoid","t":"vt. 避免，躲开；撤销","p":"ə'vɔɪd","e":["Road safety is taught to young children to avoid road accidents.","小孩子受到道路安全知识的教育，以避免交通事故。"]},{"w":"awake","t":"v. 认识到","p":"ə'weɪk","e":["Artists finally awoke to the aesthetic possibilities of photography.","艺术家终于意识到了摄影的美学潜质。"]},{"w":"award","t":"n. 奖，奖品；判定；vt. 授予，给予；判给，裁定","p":"ə'wɔːd","e":["The movie has won a number of awards.","该片获得了多个奖项。"]},{"w":"aware","t":"adj. 知道的，意识到的","p":"ə'weə","e":["Mr Braley has been made aware of the need for absolute secrecy.","布雷利先生被告知需要绝对保密。"]},{"w":"awareness","t":"n. 意识","p":"əˈweənəs","c":1,"e":["Health officials have tried to raise awareness (=  improve people’s knowledge  ) about AIDS.","卫生部官员努力提高人们对艾滋病的认识。"]},{"w":"awesome","t":"adj. 令人敬畏的,令人赞叹的；极好的","p":"'ɔ:səm","c":1,"e":["Their last concert was really awesome.","他们上一场音乐会真棒。"]},{"w":"awful","t":"adj. 威严的；令人崇敬的","p":"'ɔːfʊl"},{"w":"awkward","t":"adj. 尴尬的；棘手的；笨拙的","p":"'ɔːkwəd","c":1,"e":["A laugh can help people over an awkward situation.","笑可以助人化解尴尬。"]},{"w":"axial","t":"adj. 轴的；轴向的","p":"'æksɪəl","e":["Angular momentum is an axial vector quantity.","角动量是一种轴矢量。"]},{"w":"axis","t":"n. 轴，轴线，中心线；坐标轴，基准线","p":"'æksɪs","e":["The Earth rotates on an axis between the north and south poles.","地球绕着南北两极之间的地轴自转。"]},{"w":"axle","t":"n. （轮）轴，车轴，心棒","p":"'æks(ə)l","e":["the front/rear axle","前 / 后车轴"]},{"w":"baby","t":"n. 一家中年龄最小的人","p":"'beɪbɪ","e":["Clare is the baby of the family.","克莱尔是家里最小的孩子。"]},{"w":"bachelor","t":"n. 未婚男子；学士","p":"'bætʃələ","e":["Gerald was 38, and a confirmed bachelor (=  a man who has decided that he will never marry  ) .","杰拉德38岁，抱定主意独身。"]},{"w":"background","t":"n. 出身背景，经历；背景资料；背景，底子","p":"'bækgraund","e":["It’s important to understand other people, people from different backgrounds .","要理解别人，理解那些来自不同背景的人，这是很重要的。"]},{"w":"backup","t":"n. 后补，援助","p":"ˈbækʌp","c":1,"e":["We can use him as a backup if one of the other players drops out.","如果有参赛者退出，我们可以用他作为替补。"]},{"w":"bacon","t":"n. 咸猪肉，熏猪肉","p":"'beɪk(ə)n","e":["bacon and eggs","咸猪肉煎蛋"]},{"w":"bacteria","t":"n. 细菌","p":"bæk'tɪərɪə","c":1,"e":["When you eat off the plate, all of those bacteria go into your stomach.","当你吃掉了盘子里的食物时，这些细菌就会进入你的肚子。"]},{"w":"bacterium","t":"n. 细菌","p":"bæk'tɪərɪəm","e":["The bacterium Streptococcus pneumoniae causes about a third of some 3,000 annual meningitis cases.","在每年约3000起脑膜炎病例中，1/3左右是由一种叫“肺炎链球菌”的细菌引起的。"]},{"w":"badge","t":"n. 标记, 徽章","p":"bædʒ","c":1,"e":["We were each handed a badge with our name on it.","我们每个人都拿到一个徽章，上面有我们的名字。"]},{"w":"baffle","t":"v. 使迷惑，困惑","p":"ˈbæfl","c":1,"e":["The question baffled me completely.","这个问题把我彻底难倒了。"]},{"w":"bait","t":"n. 饵；引诱物","p":"beɪt","e":["The fish wouldn’t take the bait.","鱼儿不上钩。"]},{"w":"balcony","t":"n. 阳台；楼厅，楼座","p":"'bælkənɪ","e":["Has your flat got a balcony?","你的公寓有阳台吗？"]},{"w":"bald","t":"adj. 秃头的；无毛的","p":"bɔːld","e":["He combed his hair and tried to hide his bald patch (=  part of someone’s head where there is no hair  ).","他梳了梳头，试图把头顶的秃块遮掩起来。"]},{"w":"ballet","t":"n. 芭蕾","p":"'bæleɪ","c":1,"e":["We’re going to the ballet tomorrow evening.","我们明天晚上要去看芭蕾舞演出。"]},{"w":"bamboo","t":"n. 竹，竹子","p":"ˌbæm'buː","e":["...huts with walls of bamboo.","…竹墙小屋。"]},{"w":"band","t":"n. 乐队；群，伙；带；条纹；波段；vt. 用带绑扎","p":"bænd","e":["They formed a band when they were still at school.","他们还在读书的时候就组建了一个乐队。"]},{"w":"bandage","t":"n. 绷带；vt. 用绷带绑扎","p":"'bændɪdʒ","e":["We put some ointment and a bandage on his knee.","我们在他的膝盖上涂了些药膏，还缠了一条绷带。"]},{"w":"bandit","t":"n. 土匪，盗匪，歹徒","p":"'bændɪt","e":["They travelled 30 miles through bandit country.","他们走了30英里，穿过强盗横行的乡间。"]},{"w":"bang","t":"v. 猛击，猛撞；发出砰的一声，砰砰地响；砰地敲；n. 巨响；枪声；猛击","p":"bæŋ","e":["The baby kept banging the table with his spoon.","宝宝不停地拿调羹敲桌子。"]},{"w":"bank","t":"v. 把钱存入银行","p":"bæŋk","e":["Did you bank that check?","你把那张支票存入银行了吗？"]},{"w":"banker","t":"n. 银行家","p":"'bæŋkə","e":["...an investment banker.","…一位投资银行家。"]},{"w":"bankrupt","t":"adj. 破产的；v. 使破产","p":"'bæŋkrʌpt","e":["Johns had been nearly bankrupted through a failed business venture.","约翰斯因为商业投资失败几近破产。"]},{"w":"banquet","t":"n. 宴会，盛宴","p":"'bæŋkwɪt","e":["a state banquet (=  one attended by heads of government and other important people  )","国宴"]},{"w":"barely","t":"adv. 几乎不，仅仅","p":"ˈbɛəli","c":1,"e":["Joe and his brother are barely on speaking terms.","乔和他哥哥几乎不说话。"]},{"w":"bargain","t":"vi. 讨价还价；n. 特价商品；协议，交易","p":"'bɑːgən","e":["They prefer to bargain with individual clients, for cash.","他们更愿意同个人客户洽谈，做现金交易。"]},{"w":"barge","t":"n. 驳船；大型游船","p":"bɑːdʒ","e":["Carrying goods by train costs nearly three times more than carrying them by barge.","通过铁路运货的成本比驳船运货成本高出近3倍。"]},{"w":"barley","t":"n. 大麦","p":"'bɑːlɪ","e":["...fields of ripening wheat and barley.","…快要成熟的小麦和大麦田。"]},{"w":"barometer","t":"n. 气压计，睛雨表","p":"bə'rɒmɪtə","e":["The barometer is falling (= showing that it will probably rain).","气压在下降（表示可能要下雨）。"]},{"w":"baron","t":"n. 男爵；贵族；巨商","p":"'bær(ə)n","e":["...their stepfather, Baron Michael Distemple.","…他们的继父迈克尔• 迪斯坦普尔男爵"]},{"w":"barren","t":"adj. 贫瘠的，荒芜的；不结果实的，不育的；无益的，没有结果的","p":"'bærən","e":["Thousands of years ago the surface was barren desert.","很久很久以前，地面还是一片荒漠。"]},{"w":"barricade","t":"n. 路障，栅栏，障碍；vt. 设路障于，挡住","p":"ˌbærɪ'keɪd","e":["The fans were kept back behind barricades.","歌迷们被拦在路障后面。"]},{"w":"barrier","t":"n. 障碍，阻碍","p":"'bærɪə(r)","c":1,"e":["He advocated the removal of trade barriers.","他提倡消除贸易壁垒。"]},{"w":"baseball","t":"n. 棒球运动；棒球","e":["a baseball bat/team/stadium","棒球球棒 / 球队 / 球场"]},{"w":"basement","t":"n. 地下室；地窖；底层","p":"'beɪsm(ə)nt","e":["They bought an old schoolhouse to live in and built a workshop in the basement.","他们买了座旧校舍居住，还在地下室建了个作坊。"]},{"w":"basin","t":"n. 内海；盆地；流域","p":"'beɪs(ə)n","e":["the Pacific Basin","太平洋海盆"]},{"w":"basis","t":"n. 基础，根据；原则","p":"'beɪsɪs","e":["Their claim had no basis in fact (=  it was not true  ) .","他们的说法没有事实根据。"]},{"w":"batch","t":"n. 一批，一组，一群；一批生产量","p":"bætʃ","e":["an overnight batch file","夜间批处理文件"]},{"w":"batter","t":"v. 连续猛击；n. 面糊","p":"'bætə","e":["As a child, she was battered by her father.","她小时候遭受过父亲的殴打。"]},{"w":"battery","t":"n. 电池","p":"ˈbætri","c":1,"e":["When the red light comes on, you should recharge the battery .","红灯亮起的时候你就应该给电池充电了。"]},{"w":"battle","t":"n. 激战，战役","p":"'bætl","c":1,"e":["a pitched battle (=  a long and serious battle  ) between police and drug gangs","警方和贩毒团伙之间的一场激战"]},{"w":"bazaar","t":"n. 集市，廉价商店","p":"bə'zɑː","e":["Kamal was a vendor in Cairo's open-air bazaar.","卡莫尔曾是开罗露天集市的摊贩。"]},{"w":"bead","t":"n. 有孔小珠；水珠；露珠","p":"biːd","e":["She wore a string of green glass beads around her neck.","她脖子上戴着一串绿色的玻璃珠子。"]},{"w":"beam","t":"v. 面露喜色；定向发出，播送；n. 梁，横梁；束，柱；笑容，喜色","p":"biːm","e":["the first sports broadcast to be beamed across the Atlantic","首次向大西洋彼岸播送的体育节目"]},{"w":"bearing","t":"n. 方位；（机器的）承座；轴承；忍受","p":"'beərɪŋ","e":["An oil seal was replaced, along with both front wheel bearings.","换了一个油封和两个前轮轴承"]},{"w":"bed","t":"n. 河床，（湖）底","p":"bed","e":["the sea bed","海底"]},{"w":"beetle","t":"n. 甲虫","p":"'biːt(ə)l","e":["a black beetle","黑甲虫"]},{"w":"beforehand","t":"adv. 预先，事先","p":"bɪ'fɔːhænd","e":["The police need to be briefed beforehand on how to deal with this sort of situation.","需要事先告诉警察这种情况怎样处理。"]},{"w":"behave","t":"vi. 表现，举止；运转，做出反应；vt. 检点自己的行为","p":"bɪ'heɪv","e":["I couldn't believe these people were behaving in this way.","我无法相信这些人竟这样行事。"]},{"w":"behavior","t":"n. 行为，举止，表现","p":"bɪ'heɪvjə"},{"w":"belly","t":"n. 肚子，腹部","p":"'beli","e":["She laid her hands on her swollen belly.","她把手放在隆起的肚子上。"]},{"w":"bemoan","t":"v. 抱怨；惋惜","p":"bɪˈməʊn","c":1,"e":["He was bemoaning the fact that lawyers charge so much.","他抱怨律师收费太高。"]},{"w":"bend","t":"v. 使屈从，屈从","p":"bend"},{"w":"beneficial","t":"adj. 有利的，有益的","p":"ˌbenɪ'fɪʃl","e":["a drug that has a beneficial effect on the immune system","有益于免疫系统的一种药物"]},{"w":"benefit","t":"vi. 得益；n. 利益，恩惠；救济金，保险金，津贴；vt. 有益于","p":"'benɪfɪt","e":["They are working together to benefit the whole community.","他们在为整个社区的利益共同努力。"]},{"w":"bestow","t":"v. 把…赠与","p":"bɪ'stəʊ","e":["honours bestowed on him by the Queen","女王授予他的荣誉"]},{"w":"betray","t":"vt. 背叛，出卖；失信于，辜负；泄露；暴露，显露","p":"bɪ'treɪ","e":["I would never betray a confidence (=  tell a secret that someone has trusted me with  ) .","我永远不会泄露秘密。"]},{"w":"between","t":"adv. 当中，中间","p":"bɪ'twiːn","e":["The house was near a park but there was a road in between.","房子在一处公园附近，但两者之间隔着一条马路。"]},{"w":"beverage","t":"n. 饮料","p":"'bevərɪdʒ","e":["the Food and Beverage Manager","餐饮部经理"]},{"w":"beware","t":"v. 谨防，当心","p":"bɪ'weə","e":["Police warned drivers to beware.","警方提醒司机小心行驶。"]},{"w":"bewilder","t":"vt. 使迷惑；使难住","p":"bɪ'wɪldə","e":["He was bewildered by his daughter’s reaction.","他被女儿的反应弄糊涂了。"]},{"w":"beyond","t":"adv. 在更远处，再往后；prep. 在…的那边，远于；迟于；越出","p":"bɪ'jɒnd","e":["The financing of home ownership will continue through the 1990s and beyond.","房屋产权的融资将持续到20世纪90年代及以后。"]},{"w":"bias","t":"n. 偏见","p":"'baɪəs","c":1,"e":["Students were evaluated without bias.","对学生的评估都是公正的。"]},{"w":"bibliography","t":"n. 参考书目；书目","p":"ˌbɪbli'ɒgrəfi","e":["At the end of this chapter there is a select bibliography of useful books.","本章末尾附着有用书籍的精选书目。"]},{"w":"bid","t":"v. 报价；命令","p":"bɪd","e":["She bid £100 for a Victorian chair.","她出价100英镑买一把维多利亚时代的椅子。"]},{"w":"biochemistry","t":"n. 生物化学","p":"baɪə(ʊ)'kemɪstrɪ","c":1,"e":["...the effects of air pollutants on the biochemistry of plants or animals.","…大气污染物对植物或动物生化过程的影响。"]},{"w":"biodiversity","t":"n. 生物多样性","p":"ˌbaɪəʊdaɪˈvɜːsəti","c":1,"e":["the biodiversity of the rainforest","热带雨林中的生物多样性"]},{"w":"biography","t":"n. 传记","p":"baɪˈɒgrəfi","c":1,"e":["...recent biographies of Stalin.","…近年的斯大林传记。"]},{"w":"bipartisan","t":"adj. 两党的","p":"ˌbaɪpɑ:tɪˈzæn","c":1,"e":["a bipartisan committee","一个由两党代表组成的委员会"]},{"w":"bishop","t":"n. （基督教的）主教","p":"'bɪʃəp","e":["the Bishop of Durham","达勒姆郡的主教"]},{"w":"bitter","t":"adj. 痛苦的","p":"'bɪtə(r)","c":1,"e":["His photo stirred up bitter memories.","他的照片勾起了痛苦的回忆。"]},{"w":"bitterness","t":"n. 苦味，辛酸，苦难","p":"bɪtənəs","e":["The flowers of the hop plant add bitterness to the beer.","忽布花可增加啤酒的苦味。"]},{"w":"bizarre","t":"adj. 古怪的；奇怪的","p":"bɪˈzɑ:(r)","c":1,"e":["dancers in rather bizarre costumes","身着奇装异服的舞者"]},{"w":"blacksmith","t":"n. 铁匠，锻工","p":"'blæksmɪθ","e":["A hammer, pliers and an anvil - the main tools of a blacksmith.","铁匠使用的重要工具：一把大锤、一把铁钳和一个大铁墩"]},{"w":"blame","t":"v. 谴责","p":"bleɪm","c":1,"e":["I blame his mother. She does everything for him.","怪他母亲不好，她什么事都要为他做。"]},{"w":"blank","t":"adj. 空白的；茫然的，无表情的；n. 空白；空白表格","p":"blæŋk","e":["Leave the last page blank .","最后一页留空。"]},{"w":"blast","t":"n. 管乐器的声音","p":"blɑːst","e":["The station master gave a blast on his whistle and we were off.","站长一声哨响，我们出发了。"]},{"w":"blaze","t":"vi. 熊熊燃烧，着火；发光，放光彩；迸发，爆发；n. 火焰，烈火；光辉，强烈的光；迸发，爆发；灿烂，炫耀","p":"bleɪz","e":["The room was warm, with a fire blazing in the hearth.","房间里暖融融的，壁炉里的火熊熊燃烧。"]},{"w":"bleach","t":"v. 漂白，变白","p":"bliːtʃ","e":["The wood had been bleached by the sun .","木头已被太阳晒得褪了色。"]},{"w":"bleak","t":"adj. 荒凉的","p":"bli:k","c":1,"e":["a bleak January afternoon","一月里一个阴冷的下午"]},{"w":"bleed","t":"vi. 出血，流血；泌脂；vt. 勒索…的钱","p":"bliːd","e":["Tragically, she bled to death .","非常不幸，她失血过多死了。"]},{"w":"blind","t":"n. 百叶窗；窗帘；遮帘","p":"blaɪnd","e":["The blinds were drawn (=  pulled down  ) to protect the new furniture from the sun.","窗帘都放了下来，避免太阳光照在新的家具上。"]},{"w":"blink","t":"vi. 眨眼睛；闪亮，闪烁；n. 眨眼睛；一瞬间","p":"blɪŋk","e":["I blinked as I came out into the sunlight.","我走出来，在太阳光下直眨眼睛。"]},{"w":"block","t":"n. 阻塞；障碍物","p":"blɒk","e":["a major block to progress","进步的重大阻碍"]},{"w":"blond","t":"n. 白肤金发碧眼的人","p":"blɒnd"},{"w":"bloom","t":"v. 开花，茂盛","p":"blu:m","c":1,"e":["Most roses will begin to bloom from late May.","大多数玫瑰从五月末开始开花。"]},{"w":"blossom","t":"vi. 开花；发展，长成；n. 花","p":"'blɒsəm","e":["The apple trees are just beginning to blossom.","苹果树正开始开花。"]},{"w":"blouse","t":"n. 女衬衫","p":"blaʊz","c":1,"e":["a silk blouse","丝质女衬衫"]},{"w":"blue","t":"adj. 伤心的；下流的","p":"bluː","e":["I’ve been feeling kind of blue.","我心情不大好。"]},{"w":"blueprint","t":"n. 蓝图，设计图","p":"'blu:prɪnt","c":1,"e":["a blueprint for health-care reform","医疗保健改革蓝图"]},{"w":"blunder","t":"vi. 跌跌撞撞地走，慌乱地走；犯错误；n. 错误","p":"'blʌndə","e":["They blundered badly when they gave him the job.","他们犯了大错，让他做这份工作。"]},{"w":"blunt","t":"adj. 钝的；率直的，直言不讳的；vt. 使迟钝；使减弱；使钝","p":"blʌnt","e":["Sharpen all your blunt knives.","把你所有的钝刀子都磨一磨。"]},{"w":"blur","t":"v. 变模糊；n. 模糊，模糊的东西","p":"blɜː","e":["Many of the details in the picture are blurred.","照片中的许多细节部分都模糊了。"]},{"w":"blush","t":"n&vi. 脸红","p":"blʌʃ","e":["Wilson saw she was watching him and blushed.","威尔逊看到她在注视着自己，不由得脸红了。"]},{"w":"board","t":"n. 董事会","p":"bɔ:d","c":1,"e":["a board meeting","董事会会议"]},{"w":"boast","t":"v. 自夸","p":"bəʊst","c":1,"e":["‘I wouldn’t be afraid,’ she boasted.","“我才不怕呢。”她吹嘘道。"]},{"w":"body","t":"n. 物体","p":"'bɒdɪ","e":["an operation to remove a foreign body (= sth that would not usually be there) from a wound","从伤口摘除异物的手术"]},{"w":"boiler","t":"n. 锅炉","p":"'bɒɪlə"},{"w":"bonus","t":"n. 奖金，红利；额外给予的东西","p":"'bəunəs","e":["Further additions to your pay may take the form of bonus payments.","工资以外的钱可能以奖金的形式发放。"]},{"w":"booklet","t":"n. 小册子","p":"'buklət","e":["a free booklet on drug abuse","关于嗜毒问题的免费小册子"]},{"w":"boom","t":"n. 繁荣","p":"bu:m","c":1,"e":["The economy went from boom to bust (=  from increasing to decreasing  ) very quickly.","经济很快就从繁荣走向了萧条。"]},{"w":"boost","t":"v. 提高","p":"bu:st","c":1,"e":["to boost exports/profits","增加出口；提高利润"]},{"w":"booth","t":"n. 小房间，公用电话亭，岗亭；售货棚，货摊","p":"buːð","e":["a voting booth","投票间"]},{"w":"border","t":"vi. 近似，与…接壤；n. 边，边缘，边界；vt. 给…加上边，围；邻接","p":"'bɔːdə","e":["...the European and Arab countries bordering the Mediterranean.","…地中海沿岸的欧洲国家和阿拉伯国家。"]},{"w":"bore","t":"n. 讨厌的人；麻烦事","p":"bɔː","e":["He turned out to be a crashing bore (= used to emphasize that someone is very boring ).","他这人原来无聊透顶。"]},{"w":"boring","t":"adj. 令人厌烦的，乏味的，无聊的","p":"'bɔːrɪŋ","e":["Her husband is about the most boring person I’ve ever met.","她丈夫可以说是我见过的最无聊的人。"]},{"w":"botanical","t":"adj. 植物学的","p":"bəˈtænɪkl","c":1,"e":["The area is of great botanical interest.","该地区很有植物学研究价值。"]},{"w":"bother","t":"v. 困扰","p":"'bɒðə(r)","c":1,"e":["Danny, don’t bother Ellen while she’s reading.","丹尼，埃伦看书的时候不要去打扰她 。"]},{"w":"bounce","t":"v. 弹起，反弹，颠跳；n. 弹，反弹","p":"bauns","e":["Stop bouncing up and down on the sofa.","别在沙发上蹦来蹦去了。"]},{"w":"bound","t":"adj. 一定的；有义务的；v. 跳跃；弹回，反跃；成为…的界限，给…划界；n. 跳跃；界限，限制","p":"baund"},{"w":"bourgeois","t":"adj. 中产阶级的；庸俗的；资产阶级的","p":"'bʊəʒwɑː","e":["the backlash against bourgeois materialism","对世俗的物质主义的鞭挞"]},{"w":"bowel","t":"n. 肠；内部，深处","p":"'bauəl","e":["cancer of the bowel","肠癌"]},{"w":"box","t":"n. （法庭的）专席","p":"bɒks","e":["the jury box","陪审团席"]},{"w":"boycott","t":"n&vt. 抵制，拒绝参与","p":"'bɔɪkɒt","e":["We boycott all products tested on animals.","我们抵制所有拿动物做试验的产品。"]},{"w":"brace","t":"vi. 做好准备；振作精神；vt. 使防备，使受锻炼；支住，撑牢，使绷紧；n. 支架，托架","p":"breɪs","e":["He braced himself for the icy plunge into the black water.","他准备跳入冰冷的黑水。"]},{"w":"bracket","t":"n. 括号；等级段，档次；壁架，托架；vt. 把…置于括号内；把…归入同一类","p":"'brækɪt","e":["The Magi, Brahmins, and Druids were bracketed together as men of wisdom.","三贤人、婆罗门、德鲁伊特教僧侣一起被归为智者。"]},{"w":"branch","t":"n. 分支，分公司","p":"brɑ:ntʃ","c":1,"e":["They’re planning to open a branch in St. Louis next year.","他们计划明年在圣路易斯开一家分店。"]},{"w":"brand","t":"n. 商标，牌子；vt. 铭刻，打烙印于；加污名于，谴责","p":"brænd","e":["The owner couldn't be bothered to brand the cattle.","主人懒得给这牛打上烙印。"]},{"w":"breach","t":"n. 破坏，违反；破裂，不和；缺口，裂口；vt. 攻破，在…造成缺口；破坏，违反","p":"briːtʃ","e":["She wanted to help heal the breach between them.","她想帮助他们修复破裂的关系。"]},{"w":"breakdown","t":"n. 垮台，破裂；衰竭，衰弱；损坏，故障；明细，清单","p":"'breɪkdaun","e":["Always carry a phone with you in case you have a breakdown on the motorway.","一定要随身带电话，以防汽车在高速公路上抛锚。"]},{"w":"breakfast","t":"v. 吃早餐","p":"'brekfəst","e":["All the ladies breakfasted in their rooms.","所有女士在她们房间里用了早餐。"]},{"w":"breakthrough","t":"n. 突破性进展","p":"'breɪkθru:","c":1,"e":["Scientists have made a major breakthrough in the treatment of cancer.","科学家在癌症治疗方面取得了重大突破。"]},{"w":"breed","t":"v. 繁殖；导致","p":"bri:d","c":1,"e":["Eagles breed during the cooler months of the year.","鹰在一年中较凉爽的季节交配繁殖。"]},{"w":"breezy","t":"adj. 轻松愉快的","p":"'bri:zɪ","c":1,"e":["a breezy and relaxed air of confidence","轻松自信的神态"]},{"w":"brew","t":"vi. 冲泡；酝酿，行将发生；vt. 酿造；冲泡；n. 冲泡的饮料","p":"bruː","e":["Every beer on the menu was brewed locally.","酒单上的所有啤酒都是本地酿造的。"]},{"w":"bribe","t":"v. 贿赂","p":"braɪb","c":1,"e":["The only way we could get into the country was by bribing the border officials.","我们要进入这个国家，唯一的办法是贿赂边境官员。"]},{"w":"bride","t":"n. 新娘","p":"braɪd","c":1,"e":["Guests toasted the bride and groom with champagne.","客人们以香槟为新娘新郎敬酒。"]},{"w":"bridegroom","t":"n. 新郎","p":"'braɪdgruːm","e":["The bridegroom asked the guests to stand and then toasted the bridesmaids.","新郎请客人起立为女傧相干杯."]},{"w":"bridge","t":"v. 架桥于…之上；缩小","p":"brɪdʒ","c":1,"e":["Alvin managed to bridge the gap between ballet and modern dance.","阿尔文设法弥合了芭蕾舞和现代舞蹈之间的差异。"]},{"w":"bridle","t":"n. 马笼头；马勒；v. 束缚；抑制","p":"'braɪd(ə)l"},{"w":"brief","t":"adj. 简短的，短暂的；vt. 向…介绍基本情况，做…的提要；n. 概要，摘要","p":"briːf","e":["Let’s keep this conversation brief; I have a plane to catch.","我们长话短说吧，我还要赶飞机。"]},{"w":"briefcase","t":"n. 公文包，公事包","p":"'briːfkeɪs","e":["If you ask about my impression on him, I feel he looks like a typical businessman, you know, dark suit and briefcase.","如果你问我对他的印象如何，我感觉他看起来像是个典型的商人，你知道，黑西装和公文包的那种。"]},{"w":"brightness","t":"n. 明亮，辉煌，聪明","p":"'braɪtnɪs"},{"w":"brilliant","t":"adj. 才华横溢的；极好的","p":"ˈbrɪliənt","c":1,"e":["The film was absolutely brilliant .","这部电影极为出色"]},{"w":"brink","t":"n. 边缘，边沿","p":"brɪŋk","e":["Their economy is teetering on the brink of collapse.","他们的经济正摇摆于崩溃的边缘。"]},{"w":"brisk","t":"adj. 轻快的，生气勃勃的；兴隆的，繁忙活跃的；寒冷而清新的","p":"brɪsk","e":["They set off at a brisk pace .","他们踏着轻快的步伐上路了。"]},{"w":"broaden","t":"v. 放宽，变阔","p":"'brɔːd(ə)n","e":["The council decided to broaden the pavement.","地方议会决定拓宽人行道。"]},{"w":"brochure","t":"n. 小册子","p":"'brəuʃə(r)","e":["a holiday brochure","度假手册"]},{"w":"bronze","t":"n. 青铜，青铜色，古铜色；青铜制品，铜牌","p":"brɒnz","e":["a bell cast in bronze","青铜浇铸的一口钟"]},{"w":"brood","t":"vi. 沉思，考虑；孵蛋；n. 一窝；全体孩子","p":"bruːd","e":["Don’t sit at home brooding all day.","别整天坐在家里闷闷不乐的。"]},{"w":"bruise","t":"v. 使碰伤，擦伤","p":"bru:z","c":1,"e":["She fell off her bike and bruised her knee.","她从自行车上摔下来，擦伤了膝盖。"]},{"w":"brutal","t":"adj. 残酷的","p":"'bru:tl","c":1,"e":["a brutal man","一个凶残的男人"]},{"w":"bubble","t":"vi. 冒泡，起泡，沸腾；n. 泡，泡沫，水泡，气泡；幻想的计划","p":"'bʌbl","e":["Heat the cheese until it bubbles.","把奶酪加热到冒泡。"]},{"w":"buck","t":"v. 反对；n. 美元","p":"bʌk","c":1,"e":["He was a rebel who bucked the system (=  opposed rules or authority  ) .","他是一个反抗体制的叛逆者。"]},{"w":"bud","t":"vi. 发芽，萌芽；n. 花蕾，叶芽","p":"bʌd","e":["Without love, the best in the bud before killing!","得不到的爱情，最好在萌芽之前扼杀！"]},{"w":"Buddhism","t":"n. 佛教，释教","p":"'bʊdɪz(ə)m","e":["The custom derives its origin from Buddhism.","这种习惯起源于佛教。"]},{"w":"budget","t":"v. 规划，安排；编预算；adj. 低廉的，收费公道的；n. 预算，预算拨款","p":"'bʌdʒɪt","e":["This scheme enables you to budget the cost through fixed monthly payments.","这个计划可以让你把费用分摊在每个月里等额偿还。"]},{"w":"buffalo","t":"n. 水牛；水陆坦克","p":"'bʌfələʊ"},{"w":"bug","t":"n. 虫子；小病；故障，缺陷；窃听器；vt. 烦扰，纠缠；在…装窃听器","p":"bʌg","e":["There’s a nasty bug going round (=  that a lot of people have caught  ) .","现在流行着一种很烦人的传染病。"]},{"w":"bugle","t":"n. 军号，喇叭","p":"'bjuːg(ə)l","e":["The bugle sounded as the troops advanced.","军号吹响前进的号令。"]},{"w":"bulk","t":"v. 变得越来越大；使更大；n. 物体，体积；大批","p":"bʌlk","e":["The bulk of consumers are based in towns.","大多数消费者都是城镇居民。"]},{"w":"bull","t":"n. 公牛；雄兽；买进证券投机图利者，看涨的人","p":"bul","e":["a herd of cows with one bull","一群母牛加一头公牛"]},{"w":"bulletin","t":"n. 简明新闻，最新消息；公告，布告，公报；学报，期刊","p":"'bulətɪn","e":["...the early morning news bulletin.","…早间新闻快报。"]},{"w":"bully","t":"n. 恃强欺弱者；vt. 威吓，欺负","p":"'buli","e":["Bullies are often cowards.","恃强凌弱者往往是懦夫。"]},{"w":"bump","t":"v. 颠簸","p":"bʌmp","c":1,"e":["A police car bumped down the track.","一辆警车颠簸着行驶在小路上。"]},{"w":"burden","t":"n. 负担","p":"'bɜ:dn","c":1,"e":["His family responsibilities had started to become a burden.","家庭责任已开始成为他的负担。"]},{"w":"bureaucracy","t":"n. 官僚主义","p":"bjʊə'rɒkrəsɪ","c":1,"e":["the reduction of unnecessary bureaucracy","消除不必要的官僚体制"]},{"w":"burglar","t":"n. 夜盗，窃贼","p":"'bɜːglə","e":["Burglars broke into their home.","窃贼闯进了他们家。"]},{"w":"burial","t":"n. 埋葬","p":"'berɪəl","c":1,"e":["The priest prepared the body for burial.","牧师为尸体做好了下葬的准备。"]},{"w":"burner","t":"n. 煤气头","p":"'bɜːnə"},{"w":"bushel","t":"n. 蒲式耳（容量单位）","p":"'bʊʃ(ə)l","e":["Wheat averages 56 pounds to a bushel.","小麦平均 56 磅为一蒲式耳。"]},{"w":"bust","t":"vi. 爆裂，坏掉；vt. 打破，打碎；n. 胸像，半身像；胸部，胸围","p":"bʌst","e":["I bust my watch this morning.","今天早上我把手表摔坏了。"]},{"w":"butt","t":"n. 大酒桶，桶","p":"bʌt","e":["a rainwater butt","接雨水的大桶"]},{"w":"buzz","t":"vi. 发出嗡嗡声；忙乱，急行；发出嘈杂的谈话声；n. 嗡嗡声；嘈杂的谈话声","p":"bʌz","e":["a loud buzzing noise","很大的嗡嗡声"]},{"w":"bypass","t":"n. 旁道，迂回道；vt. 绕过，绕…走；越过，置…于不顾","p":"'baɪpɑːs","e":["a triple heart bypass operation","心脏三重旁通管手术"]},{"w":"cabin","t":"n. 小屋；船舱，机舱","p":"'kæbɪn","e":["a log cabin","原木小屋"]},{"w":"cabinet","t":"n. 橱，柜；内阁","p":"'kæbɪnət","e":["a member of the Cabinet","内阁成员"]},{"w":"cable","t":"n. 缆，索，电缆，电报；vt. 给… 发电报，用电报传送","p":"'keɪbl","e":["cables and switches for computers","电脑的缆线和开关"]},{"w":"cafeteria","t":"n. 自助餐厅","p":"ˌkæfəˈtɪəriə","c":1,"e":["the school cafeteria","学校餐厅"]},{"w":"calcium","t":"n. 钙","p":"'kælsiəm","e":["Like fibre, calcium binds with fat molecules and helps flush them out through the intestine.","像纤维、钙可以和脂肪分子结合，帮助他们彻底的通过肠道。"]},{"w":"calculate","t":"v. 计算，推算；计划，打算","p":"'kælkjuleɪt","e":["These instruments calculate distances precisely.","这些仪器计算距离非常精确。"]},{"w":"calculation","t":"n. 计算","p":"ˌkælkjuˈleɪʃn","c":1,"e":["By my calculation(s), we made a profit of £20 000 last year.","我算了一下，我们去年赢利2万英镑。"]},{"w":"calculus","t":"n. 微积分；结石","p":"'kælkjʊləs","e":["I think I've finally unzipped this calculus problem.","我认为我最终解出了这道微积分题。"]},{"w":"calibration","t":"n. 校准；标定，刻度","p":"kælɪ'breɪʃ(ə)n","e":["a calibration error","校准误差"]},{"w":"calorie","t":"n. 卡路里","p":"'kælərɪ","c":1,"e":["I need to burn off a few calories (= lose some weight by exercising ) .","我要消耗掉一些卡路里。"]},{"w":"campaign","t":"n. 活动","p":"kæm'peɪn","c":1,"e":["Police have launched a campaign to crack down on drug dealers.","警方发起了一场严厉打击毒贩的运动。"]},{"w":"can","t":"v. 装罐头","p":"kæn","e":["...fruits and vegetables that will be canned, skinned, diced, or otherwise processed.","…将要经过装罐、去皮、切块或其他加工程序的水果和蔬菜。"]},{"w":"cancel","t":"v. 取消","p":"'kænsl","c":1,"e":["I’m afraid I’ll have to cancel our meeting tomorrow.","恐怕我得取消我们明天的会议。"]},{"w":"cancer","t":"n. 癌，癌症，肿瘤","p":"'kænsə","e":["a new treatment which effectively kills cancer cells","一种能有效杀死癌细胞的新疗法"]},{"w":"candidate","t":"n. 候选人，投考者，申请求职者","p":"'kændɪdət","e":["a presidential candidate","总统候选人"]},{"w":"cane","t":"n. 手杖；茎","p":"keɪn","e":["...cane furniture.","…藤制家具。"]},{"w":"cannon","t":"n. 加农炮，大炮，火炮","p":"'kænən","e":["The cannons boom, the band plays.","炮声隆隆，鼓乐齐鸣。"]},{"w":"canvas","t":"n. 帆布；帆布画布，油画","p":"'kænvəs","e":["a canvas bag","帆布包"]},{"w":"capability","t":"n. 能力，才能","p":"ˌkeɪpəˈbɪləti","e":["I can speak French, but simultaneous translation is beyond my capabilities (= too difficult ).","我能讲法语，但是同声传译我做不了。"]},{"w":"capable","t":"adj. 有能力的","p":"'keɪpəbl","c":1,"e":["The company isn’t capable of handling an order that large.","那家公司没有能力应付那么大的订单。"]},{"w":"capacitance","t":"n. 电容，电容量","p":"kə'pæsɪt(ə)ns"},{"w":"capacitor","t":"n. 电容器","p":"kə'pæsɪtə","e":["The second resistor has been replaced by a capacitor.","第二个电阻已由一个电容所代替。"]},{"w":"capacity","t":"n. 能力；容量","p":"kə'pæsətɪ","c":1,"e":["The room had seating capacity for about 80.","这房间能坐80个人左右。"]},{"w":"cape","t":"n. 斗篷，披肩；海角，岬","p":"keɪp","e":["Cape Cod","科德角"]},{"w":"capital","t":"adj. 资金的，资本的","p":"'kæpɪtl","c":1,"e":["capital investments","资本投资"]},{"w":"capsule","t":"n. 胶囊；航天舱，密封舱","p":"'kæpsjuːl","e":["a space capsule orbiting the Earth","沿地球轨道飞行的太空舱"]},{"w":"caption","t":"n. 说明文字，字幕","p":"'kæpʃn","e":["The local paper featured me standing on a stepladder with a caption, \"Wendy climbs the ladder to success.\"","当地的报纸刊登了一幅我站在活梯上的特写，下面写着：“温迪登上了成功之梯。”"]},{"w":"captive","t":"adj. 被俘虏的，被捕获的；n. 俘虏","p":"'kæptɪv","e":["Her heart had begun to pound inside her chest like a captive animal.","她心如鹿撞，怦怦跳个不停。"]},{"w":"capture","t":"v. 逮捕；捕捉","p":"'kæptʃə(r)","c":1,"e":["These photographs capture the essence of working-class life at the turn of the century.","这些相片捕捉到了世纪之交工人阶级生活的神韵。"]},{"w":"cardinal","t":"adj. 最重要的；基本的；n. 红衣主教；【数】基数","p":"'kɑːdɪnl","e":["Having clean hands is one of the cardinal rules when preparing food.","双手洁净是准备食物时的一项最基本要求。"]},{"w":"carpenter","t":"n. 木匠","p":"ˈkɑːpəntə(r)","c":1,"e":["That carpenter wanted to become a lawyer， but he was advised to stick to his last.","那个木匠想当律师， 但别人劝他安分守己地干他自己的老本行。"]},{"w":"carpentry","t":"n. 木工活","p":"ˈkɑ:pəntri","c":1,"e":["I don't think he's really learning carpentry; he's only playing at it.","我看他并不真正在学木工, 他只是在玩玩罢了。"]},{"w":"carry","t":"v. 刊登","p":"'kærɪ","e":["The morning paper carried a story about demonstrations in New York and Washington D.C.","晨报登载了纽约和华盛顿特区举行示威游行的报道。"]},{"w":"cartoon","t":"n. 动画片；漫画","p":"kɑː'tuːn","e":["...one of Britain's best-loved cartoon characters, Rupert the Bear.","英国最受欢迎的漫画形象之一——鲁珀特熊"]},{"w":"cartridge","t":"n. 弹药筒","p":"'kɑːtrɪdʒ","e":["Only four of the five spent cartridges were recovered by police.","5个子弹壳中只有4个被警方收回。"]},{"w":"carve","t":"vt. 切，把…切碎；雕刻，刻","p":"kɑːv","e":["carved wooden chairs","木雕椅子"]},{"w":"cast","t":"v. 投掷，扔","p":"kɑ:st","c":1,"e":["Sparks leapt as he cast more wood on the fire.","他往火里投进更多的木块，火星四处飞溅。"]},{"w":"casual","t":"adj. 偶然的；非正式的；临时的，不定期的；漠不关心的，冷淡的","p":"'kæʒuəl","e":["Jean felt more comfortable in casual clothes .","琼穿上便服感到更舒服。"]},{"w":"casualty","t":"n. 伤亡人数","p":"ˈkæʒuəlti","c":1,"e":["The rebels have inflicted heavy casualties .","叛乱者造成了大量的伤亡。"]},{"w":"catalogue","t":"v. 为…编目录","p":"'kæt(ə)lɒg","e":["The manuscripts have never been systematically catalogued.","一直没有系统地为这些手稿编过目录。"]},{"w":"catalyst","t":"n. 催化剂；刺激因素","p":"'kæt(ə)lɪst","e":["They hope his election will act as a catalyst for reform.","他们希望他的当选会成为改革的催化剂。"]},{"w":"catastrophe","t":"n. 大灾难，灾祸","p":"kə'tæstrəfi","e":["From all points of view, war would be a catastrophe.","从各个方面来看，战争都会是一场灾难。"]},{"w":"category","t":"n. 种类","p":"ˈkætəgəri","c":1,"e":["Williams’ style does not fit easily into the category of jazz.","威廉斯的风格不能轻易归入爵士乐的范畴。"]},{"w":"cater","t":"v. 迎合","p":"'keɪtə","c":1,"e":["We cater to an exclusive clientele.","我们满足一个特殊客户群的需求。"]},{"w":"cathedral","t":"n. 大教堂","p":"kə'θiːdrəl","e":["St Paul’s Cathedral","圣保罗大教堂"]},{"w":"catholic","t":"adj. [C-]天主教的；普遍的，广泛的；n. [C-]天主教徒","p":"'kæθlɪk","e":["She has catholic tastes (= likes a lot of different things ) .","她的兴趣非常广泛。"]},{"w":"caution","t":"n. 小心，谨慎；注意，警告；vt. 警告，劝…小心","p":"'kɔːʃn","e":["The physician must exercise caution when prescribing antidepressants.","医师在开抗抑郁药处方时必须谨慎。"]},{"w":"cautious","t":"adj. 谨慎的","p":"ˈkɔ:ʃəs","c":1,"e":["The air-pollution board has reacted with cautious optimism to the announcement.","空气污染委员会对这项通告表示谨慎乐观。"]},{"w":"cavity","t":"n. 洞，穴，凹处；龋洞","p":"'kævəti","e":["...a cavity in the roof.","…屋顶的一个洞。"]},{"w":"cellar","t":"n. 地窖，地下室；酒窖","p":"'selə","e":["a coal cellar","煤窖"]},{"w":"cement","t":"v. 粘结","p":"sɪ'ment","e":["Most artificial joints are cemented into place.","绝大部分人造关节是被黏结复位的。"]},{"w":"cemetery","t":"n. 墓地，公墓","p":"'semətri","e":["We got arrested once, for singing bawdy songs in a cemetery.","我们曾经因为在公墓唱下流歌曲而被拘留过一次。"]},{"w":"censor","t":"v. 审查，检查","p":"'sensə","e":["The information given to the press was carefully censored by the Ministry of Defence.","发布给报界的信息经过了国防部的仔细审查。"]},{"w":"census","t":"n. 人口普查，统计","p":"'sensəs","e":["a traffic census","交通状况调查"]},{"w":"ceramic","t":"adj. 陶器的；n. 陶瓷器","p":"sə'ræmɪk","e":["I make ceramic cups there. Do you remember the gift I gave you for your last birthday? Those two cups?","在那里，我可以自己制作陶瓷茶杯。还记得你上次生日时我送你的礼物吗？那两个茶杯？"]},{"w":"cereal","t":"n. 加工而成的谷类食物；谷类植物，谷物","p":"'sɪəriəl","e":["a bowl of breakfast cereal","一碗早餐麦片"]},{"w":"certainty","t":"n. 必然的事，确定的事实；确信，确实","p":"'sɜːtnti","e":["The result is impossible to predict with any degree of certainty .","这一结果完全无法确切预测。"]},{"w":"certification","t":"n. 证书","p":",sɜːtɪfɪ'keɪʃən","c":1,"e":["We successfully completed the certification for open water diving.","我们成功地拿到了开放水域潜水证书。"]},{"w":"certify","t":"v. 保证，证明","p":"'sɜːtɪfaɪ","c":1,"e":["The accounts were certified by an auditor.","这些账目经审计员核实过。"]},{"w":"chain","t":"n. 连锁店","p":"tʃeɪn","c":1,"e":["...a large supermarket chain.","…一家大型连锁超市。"]},{"w":"challenge","t":"n. 挑战，邀请比赛；艰巨的任务；怀疑，质问；vt. 反对，公然反抗；向…挑战；对…质疑","p":"'tʃælɪndʒ","e":["They threw down the challenge that he couldn’t wash 40 cars in one hour (= invited him to try to do it ) .","他们激将他，说他不可能在1小时内擦洗40辆汽车。"]},{"w":"champagne","t":"n. 香槟酒","p":"ʃæm'peɪn","e":["Waiter: Sir, what would you like to drink, wine or champagne?","服务员：先生，您想喝点什么？葡萄酒还是香槟酒？"]},{"w":"champion","t":"v. 支持，拥护","p":"ˈtʃæmpiən","c":1,"e":["He passionately championed the poor.","他曾热情地捍卫穷人。"]},{"w":"chant","t":"vt. 反复有节奏地喊叫；吟诵，咏唱；n. 反复有节奏的喊叫；赞美诗，圣歌","p":"tʃɑːnt","e":["protesters chanting anti-government slogans","反复呼喊反政府口号的抗议者"]},{"w":"chaos","t":"n. 混乱","p":"'keɪɒs","c":1,"e":["The country was plunged into economic chaos.","这个国家陷入了经济大混乱。"]},{"w":"chapel","t":"n. 小教堂，祈祷室","p":"'tʃæpl","e":["Bethan goes to chapel every Sunday.","贝唐每个星期天都去教堂做礼拜。"]},{"w":"character","t":"n. 角色；某物的特色","p":"'kærəktə(r)","c":1,"e":["A soulless shopping centre stands across from one of the few buildings with character, the town hall.","一座毫无生气的购物中心对面就是少有的几个别具特色的建筑物之一：市政厅。"]},{"w":"characteristic","t":"adj. 特有的，典型的；n. 特性","p":"ˌkærəktə'rɪstɪk","e":["the highly characteristic (= very typical ) flint walls of the local houses","当地房子非常有特色的燧石墙"]},{"w":"characterize","t":"vt. 成为…的特征，以…为特征；描绘的特性，描述","p":"'kærəktəraɪz","e":["Bright colours characterize his paintings.","明亮的色彩是他绘画作品的特点。"]},{"w":"charcoal","t":"n. 炭，木炭；生物炭","p":"'tʃɑːkəʊl","e":["cooking over a charcoal fire","在炭火上做饭"]},{"w":"charge","t":"v. 索价；控告；使充电，使充满；向前冲；n. 费用；管理；控告，指责；电荷，充电","p":"tʃɑːdʒ","e":["They have the evidence to charge him.","他们有证据来指控他。"]},{"w":"charm","t":"n. 魅力；妩媚；v. 迷人","e":["She turned on the charm (= used her charm ) to all the men.","她对所有那些男人都施展魅力。"]},{"w":"charter","t":"v. 包租（飞机、船等）","p":"'tʃɑːtə","e":["We chartered a boat to take us to some of the smaller islands.","我们包了一条船带我们到一些较小的岛上去。"]},{"w":"chase","t":"n&vt. 追逐，追赶，追求","p":"tʃeɪs","e":["The dogs saw him running and chased him.","那些狗看到他在跑就追他。"]},{"w":"chatter","t":"v. 喋喋不休；n. 喋喋不休","p":"'tʃætə","e":["She chattered away happily until she noticed I wasn’t listening.","她开心地说个不停，直到发觉我没在听才停下来。"]},{"w":"cheat","t":"n. 欺诈；骗取","p":"tʃiːt","e":["It's really a cheat, but you can use ready-made pastry if you want.","这东西真是骗人，但如果你愿意的话，可以用现成的油酥面团。"]},{"w":"check","t":"v. 检查；阻止","p":"tʃek","c":1,"e":["He grinned, and then checked himself, not wanting to upset Jack.","他咧嘴一笑，然后克制住自己，因为他不想让杰克不开心。"]},{"w":"cherish","t":"vt. 珍爱，珍视；爱护，抚育；抱有，怀有","p":"'tʃerɪʃ","e":["I cherish the memory of that day.","我珍惜那一天的回忆。"]},{"w":"chestnut","t":"n. 栗子；栗树；栗色","p":"'tʃesnʌt","e":["forests full of oak and chestnut","长满橡树和栗子树的森林"]},{"w":"chew","t":"v. 咀嚼；深思","p":"tʃuː","c":1,"e":["This meat’s so tough I can hardly chew it!","这肉太老了，我几乎嚼不动！"]},{"w":"chief","t":"adj. 主要的，为首的；总的；n. 首领，长官；酋长，族长","p":"tʃiːf","e":["She had many reasons for taking the money, but chief among them was revenge.","她拿这笔钱的原因有很多，但最主要的是为了报复。"]},{"w":"chill","t":"v. 感到寒冷；冷藏","p":"tʃɪl","e":["The wind blew across her body, chilling her wet skin.","风吹在她身上，她湿漉漉的皮肤感到非常寒冷。"]},{"w":"chip","t":"n. 屑片，碎片；炸土豆条；集成电路片，集成块；缺口，瑕疵","p":"tʃɪp","e":["the age of the silicon chip","芯片时代"]},{"w":"choice","t":"n. 入选者；adj. 优等的","p":"tʃɒɪs","e":["I think London was a good choice as a venue.","我觉得伦敦是个很好的选址。"]},{"w":"cholesterol","t":"n. 胆固醇","p":"kə'lestərɒl","e":["If it does, you should discuss with your physician other approaches to cholesterol control.","若确实如此，您应该与您的医生讨论其他控制胆固醇方法。"]},{"w":"chop","t":"n. 一块排骨，肉块","p":"tʃɒp","e":["a grilled pork/lamb chop","烤猪排/羊排"]},{"w":"chord","t":"n. 和弦，和音；弦，心弦","p":"kɔːd","e":["Many of the things she says will strike a chord with other young women.","她说的许多话都能引起其他年轻女子的共鸣。"]},{"w":"chorus","t":"n. 合唱队；合唱，合唱曲；副歌，叠句；齐声，齐声说的话；vt. 齐声说，随声附和","p":"'kɔːrəs","e":["Everyone joined in the chorus.","唱到副歌时，每个人都跟着齐唱起来。"]},{"w":"Christ","t":"n. 救世主（耶稣基督）","p":"kraɪst","e":["a follower of Christ","耶稣的门徒"]},{"w":"Christian","t":"adj. 基督教的","p":"'krɪstɪən; -tʃ(ə)n","e":["the Christian religion","基督教"]},{"w":"chronic","t":"adj. 长期的；慢性的","p":"ˈkrɒnɪk","c":1,"e":["chronic heart disease","慢性心脏病"]},{"w":"chronically","t":"adv. 慢性地；持久地","p":"'krɑnɪkli","c":1,"e":["a hospital for the chronically ill","慢性病医院"]},{"w":"chronicle","t":"v. 记录","p":"'krɒnɪkl","c":1,"e":["His life is chronicled in a new biography published last week.","他的生平被写成一本新传记，于上周出版。"]},{"w":"chunk","t":"n. 厚片，大块；相当大的部分","p":"tʃʌŋk","e":["ice chunks","大冰块"]},{"w":"cigar","t":"n. 雪茄烟，叶卷烟","p":"sɪ'gɑː","e":["He was smoking a big cigar.","他在抽一只大雪茄。"]},{"w":"circular","t":"n. 传单，通报，通函","p":"'sɜːkjʊlə","e":["The proposal has been widely publicized in press information circulars sent to 1,800 newspapers.","通过向1800份报纸发送新闻通告，这项提议得到了广泛地宣传。"]},{"w":"circulation","t":"n. 发行量","p":"sɜːkjʊ'leɪʃ(ə)n","c":1,"e":["The Daily News once had the highest circulation of any daily in the country.","《每日新闻报》一度在该国所有日报中拥有最高发行量。"]},{"w":"circumstance","t":"n. 情况，环境","p":"'sɜ:kəmstəns","c":1,"e":["The Soviet Union had been forced by circumstances to sign a pact with Nazi Germany.","苏联为形势所迫同纳粹德国签订了一项条约。"]},{"w":"circus","t":"n. 马戏，马戏团；喧闹的场面；环形广场","p":"'sɜːkəs","e":["The first day of school is always such a circus.","开学第一天总是这样闹哄哄的。"]},{"w":"citation","t":"n. 引文","p":"saɪ'teɪʃn","c":1,"e":["The essay begins with a citation from ‘Hamlet’.","这篇文章开头引用了《哈姆雷特》中的一句话。"]},{"w":"cite","t":"vt. 引用，引证；传唤，传讯；表彰，嘉奖","p":"saɪt","e":["The judge cited a 1956 Supreme Court ruling in her decision.","法官在她的判决中引用了1956年最高法院的一项裁决。"]},{"w":"citizenship","t":"n. 公民的身份, 公民的职责和权力","p":"'sɪtɪzənʃɪp","e":["McGuirk holds dual citizenship (= the legal right of being a citizen in two countries ) in Ireland and the US.","麦吉尔克拥有爱尔兰和美国的双重国籍。"]},{"w":"civilian","t":"n. 平民；adj. 平民的","p":"sɪ'vɪlj(ə)n","e":["It was difficult to return to civilian life after ten years in the military.","从军十年后重新过平民生活不容易。"]},{"w":"claim","t":"v. 声称；索取","p":"kleɪm","c":1,"e":["I don’t claim to be a feminist, but I’d like to see more women in top jobs.","我不会自称是女权主义者，但我希望看到更多的女性担任高职。"]},{"w":"clamp","t":"vt. 夹紧，夹住，固定；n. 夹头，夹具，夹钳","p":"klæmp","e":["Creed opened his mouth to speak, then clamped it shut .","克里德张口欲言，忽又闭口不说了。"]},{"w":"clan","t":"n. 宗族，家族","p":"klæn","e":["the Campbell clan","坎贝尔家族"]},{"w":"clap","t":"n. 拍手喝采声；霹雳声","p":"klæp","e":["Come on everyone, let’s give Tommy a clap.","来吧各位，我们为汤米鼓鼓掌吧。"]},{"w":"clarify","t":"v. 澄清，明确","p":"'klærəfaɪ","c":1,"e":["Reporters asked him to clarify his position (= say exactly what his beliefs are ) on welfare reform.","记者们要求他阐明他在福利改革问题上的立场。"]},{"w":"clarity","t":"n. 清晰，清楚","p":"ˈklærəti","c":1,"e":["a lack of clarity in the law on property rights","产权法律含糊不清"]},{"w":"clash","t":"vi. 发生冲突；不协调；砰地相撞，发出刺耳的撞击声；n. 冲突；不协调；刺耳的撞击声","p":"klæʃ","e":["Troops clashed near the border.","军队在边境附近发生了冲突。"]},{"w":"clasp","t":"n. 扣子，钩子；紧抱，紧握；vt. 抱紧，握紧；扣住，扣紧","p":"klɑːsp","e":["the firm clasp of her hand","她有力的握手"]},{"w":"classic","t":"adj. 最优秀的，典型的，标准的；传统式样的，典雅的；n. 文学名著，经典作品，杰作；优秀的典范；","p":"'klæsɪk","e":["The Coca-Cola bottle is one of the classic designs of the last century.","可口可乐瓶是上个世纪的经典设计之一。"]},{"w":"classical","t":"adj. 古典的，经典的","p":"'klæsɪkl","e":["the classical theory of relativity","经典相对论"]},{"w":"classification","t":"n. 分类，分级，分类法；类别，级别","p":"ˌklæsɪfɪ'keɪʃn","e":["the classification of wines according to quality","葡萄酒按品质的分类"]},{"w":"classify","t":"v. 分类","p":"'klæsɪfaɪ","c":1,"e":["Families are classified according to the father’s occupation.","各个家庭按父亲的职业分类。"]},{"w":"clatter","t":"n. 得得声，卡嗒声","p":"'klætə","e":["the clatter of horses' hoofs","嗒嗒的马蹄声"]},{"w":"clause","t":"n. 条款","p":"klɔ:z","c":1,"e":["A confidentiality clause was added to the contract.","合同中加上了一项保密条款。"]},{"w":"cleanliness","t":"n. 清洁","p":"'klenlɪnəs","e":["a high standard of cleanliness","很高的卫生标准"]},{"w":"clearance","t":"n. 净空，余隙；许可，批准；票据交换，清算；清除，清理，出空","p":"'klɪərəns","e":["She’ll race if she gets medical clearance from her doctor.","如果取得了医生的许可，她就会参加比赛。"]},{"w":"clearing","t":"n. （森林中的）空旷地","p":"'klɪərɪŋ","e":["A helicopter landed in a clearing in the dense jungle.","一架直升机在茂密丛林中的一片空地着陆了。"]},{"w":"clerk","t":"n. 店员；办事员，职员","p":"klɑːk","e":["a clerk in a commercial firm","一家商行的文员"]},{"w":"client","t":"n. 委托人，当事人；顾客","p":"'klaɪənt","e":["a meeting with an important client","与一位重要客户的会面"]},{"w":"cliff","t":"n. 悬崖，峭壁","p":"klɪf","e":["The car rolled over the edge of a cliff.","汽车翻下了悬崖边。"]},{"w":"climate","t":"n. 气候；风土，地带；风气，气氛","p":"'klaɪmət","e":["Los Angeles’ warm dry climate","洛杉矶温暖干燥的气候"]},{"w":"climax","t":"n. 高潮，最令人兴奋的部分","p":"'klaɪmæks","e":["The festival reaches its climax with the traditional boat-burning ceremony.","传统的烧船仪式将节庆活动推向了高潮。"]},{"w":"cling","t":"vi. 紧紧抓住；黏着，挨近；依附，依恋；坚持，墨守，忠实于","p":"klɪŋ","e":["Some children tend to cling on their first day at school.","有些小孩在上学第一天往往会有恋家的情绪。"]},{"w":"clinic","t":"n. 诊所，医务室；会诊；会诊时间；门诊时间","p":"'klɪnɪk","e":["The baby clinic is held on Monday afternoons.","婴儿门诊时间为每周一下午。"]},{"w":"clip","t":"n. 夹子，回形针，别针；弹夹，弹仓；剪，修剪；剪报，电影片断；vt. 夹住，扣住；剪，修剪","p":"klɪp","e":["The wire is held on with a metal clip.","电线用金属夹子固定。"]},{"w":"cloak","t":"v. 掩盖，掩饰；覆盖，笼罩","p":"kləʊk","e":["The talks have been cloaked in secrecy.","会谈是秘密进行的。"]},{"w":"clockwise","t":"adv. 顺时针方向地","p":"'klɒkwaɪz","e":["Screw the lid on clockwise.","按顺时针方向拧紧盖子。"]},{"w":"clone","t":"v. 无性繁殖，克隆；n. 无性繁殖系，克隆；复制品，翻版","p":"kləun","e":["The idea of cloning extinct life forms still belongs to science fiction.","对绝种的生命形式进行克隆的想法仍然属于科学幻想。"]},{"w":"closet","t":"adj. 私下的；隐蔽的；n. 橱，壁橱；vt. 把…引进密室会谈","p":"'klɒzɪt","e":["a closet full of beautiful clothes","满是漂亮衣服的壁橱"]},{"w":"cloudy","t":"adj. 混浊的；模糊不清的","p":"'klaʊdɪ","e":["...an absurdly cloudy political debate...","极为含糊不清的政治辩论"]},{"w":"clown","t":"n. （马戏的）小丑，丑角","p":"klaʊn","e":["The performance of the clown kept the public rolling about.","小丑的表演使观众笑得前仰后合。"]},{"w":"clue","t":"n. 线索","p":"klu:","c":1,"e":["Archaeological evidence will provide clues about what the building was used for.","考古证据将为这幢建筑的用途提供线索。"]},{"w":"cluster","t":"vi. 群集，丛生；n. 串，簇；群，组；vt. 使群集，集中","p":"'klʌstə","e":["However, there are some problems in the cluster environment.","然而，在集群环境中却存在一些问题。"]},{"w":"clutch","t":"vi. 企图抓住；vt. 抓紧，紧握；n. 离合器；掌握，控制；把握，抓紧","p":"klʌtʃ","e":["Tom fell to the ground clutching his stomach.","汤姆捂着肚子倒在地上。"]},{"w":"coach","t":"n. 教练","p":"kəʊtʃ","c":1,"e":["the Norwegian national coach","挪威国家队教练"]},{"w":"coalition","t":"n. 结合体，同盟；结合，联合","p":"ˌkəuə'lɪʃn","e":["an emergency meeting of the three coalition parties","三个联盟政党召开的一次紧急会议"]},{"w":"coarse","t":"adj. 粗的，粗糙的；粗劣的；粗俗的","p":"kɔːs","e":["a jacket of coarse wool","粗羊毛夹克衫"]},{"w":"coastal","t":"adj. 海滨的","p":"'kəʊstl","c":1,"e":["the coastal waters of Britain","英国的近海水域"]},{"w":"cocaine","t":"n. 可卡因，古柯碱","p":"kəu'keɪn","e":["To investigate, his team injected cocaine, capsaicin or both at once into the abdomens of several groups of about 30 mice.","他的团队将辣椒素或可卡因中的一种，或同时将两种注射进几组老鼠的腹部，每组约30只。"]},{"w":"cock","t":"n. 公鸡","p":"kɒk","e":["A cock crowed in the distance.","远处有只公鸡在打鸣。"]},{"w":"cocktail","t":"n. 鸡尾酒；餐前开胃小吃；混合物","p":"'kɒkteɪl","e":["On arrival, guests are offered wine or a champagne cocktail.","到达时，客人们可以享用葡萄酒或一份香槟鸡尾酒。"]},{"w":"code","t":"n. 代号，密码","p":"kəʊd","c":1,"e":["The hacker came smack up against the company's policy of keeping its records in code.","这个计算机黑客突然碰壁了，因这家公司实行了用密码保存公司纪录的政策。"]},{"w":"coefficient","t":"n. 协同因素；系数，率","p":",kəʊɪ'fɪʃ(ə)nt","e":["In 8pq, the coefficient of pq is 8.","在8pq中pq的系数为8。"]},{"w":"coffin","t":"n. 棺材，灵柩","p":"'kɒfɪn"},{"w":"cognitive","t":"adj. 认知的","p":"ˈkɒgnətɪv","c":1,"e":["cognitive psychology","认知心理学"]},{"w":"coherent","t":"adj. 条理清楚的，连贯的；一致的，协调的","p":"kəu'hɪərənt","e":["The three years of the course are planned as a coherent whole.","这三年的课程是作为连贯的整体来安排的。"]},{"w":"coin","t":"v. 铸造（硬币）","p":"kɒɪn"},{"w":"coincide","t":"vi. 同时发生；相符，相一致；位置重合，重叠","p":"ˌkəuɪn'saɪd","e":["When our vacations coincided, we often holidayed together.","我们的假期要是凑巧赶在一起，我们常常会一同去度假。"]},{"w":"coincidence","t":"n. 巧合，巧事；一致，符合","p":"kəu'ɪnsɪdəns","e":["‘I’m going to Appleby tomorrow.’ ‘ What a coincidence ! I’m going there too.’","“明天我要去阿普尔比。”“太巧了！我也要去那里。”"]},{"w":"coke","t":"n. 焦炭","p":"kəʊk","e":["...a coke-burning stove.","…一个烧焦炭的炉子。"]},{"w":"collaborate","t":"v. 合作","p":"kəˈlæbəreɪt","c":1,"e":["During the late seventies, he collaborated with the legendary Muddy Waters.","70年代后期，他和大名鼎鼎的马迪•沃特斯合作过。"]},{"w":"collaboration","t":"n. 合作，协作；勾结","p":"kəˌlæbə'reɪʃn","e":["The company is building the centre in collaboration with the Institute of Offshore Engineering.","该公司正与海洋工程学院合建这座中心。"]},{"w":"collaborative","t":"adj. 合作的","p":"kəˈlæbərətɪv","c":1,"e":["...a collaborative research project.","…一个合作研究项目。"]},{"w":"collapse","t":"v. 坍塌，崩塌","p":"kə'læps","c":1,"e":["Uncle Ted’s chair collapsed under his weight.","椅子承受不了特德叔叔的重量，塌架了。"]},{"w":"colleague","t":"n. 同事，同僚","p":"'kɒliːg","e":["She discussed the idea with some of her colleagues.","她和几位同事讨论了这个想法。"]},{"w":"collective","t":"adj. 共同的","p":"kəˈlektɪv","c":1,"e":["our collective responsibility for the environment","我们对环境的共同责任"]},{"w":"collide","t":"v. 撞击，碰撞","p":"kə'laɪd","c":1,"e":["Two trains collided head-on (= when they were moving directly towards each other ) .","两辆火车迎头相撞。"]},{"w":"collision","t":"n. 碰撞；冲突，抵触","p":"kə'lɪʒn","e":["Two people were killed in a head-on collision (= between two vehicles that are moving directly towards each other ) on highway 218.","218号公路上有两辆汽车迎面相撞，两人死亡。"]},{"w":"colonial","t":"adj. 殖民地的","p":"kə'ləuniəl","e":["Britain was the largest colonial power .","英国曾是最大的殖民强国。"]},{"w":"colonist","t":"n. 移民；殖民地居民","p":"'kɒlənɪst","e":["The colonists struggled through their first winter.","这些殖民地居民艰难地度过了第一个冬天。"]},{"w":"column","t":"n. 专栏","p":"ˈkɒləm","c":1,"e":["He writes a weekly column for ‘The Times’.","他每周为《泰晤士报》写一篇专栏文章。"]},{"w":"combat","t":"n. 战争，斗争，格斗；vt. 与…斗争，与…战斗","p":"'kɒmbæt","e":["We flew over 200 combat missions in the war.","我们在战争中执行过两百多次战斗飞行任务。"]},{"w":"combination","t":"n. 组合，结合","p":"kɒmbɪ'neɪʃ(ə)n","c":1,"e":["A combination of factors may be responsible for the increase in cancer.","各种因素的综合作用可能导致了癌症发病率的上升。"]},{"w":"combine","t":"v. 结合，联合；化合；n. 联合企业；联合收割机","p":"kəm'baɪn","e":["Ruth hesitated, uncertain of how to combine honesty and diplomacy in her answer.","露丝犹豫了，她不知道怎样回答才能既诚实又婉转。"]},{"w":"combustion","t":"n. 燃烧","p":"kəm'bʌstʃ(ə)n","e":["The energy is released by combustion on the application of a match.","能量通过点火柴燃烧释放出来。"]},{"w":"comedy","t":"n. 喜剧；喜剧场面","p":"'kɒmɪdɪ","e":["a career in stand-up comedy","单口喜剧表演职业"]},{"w":"comet","t":"n. 彗星","p":"'kɒmɪt","e":["Halley’s comet","哈雷彗星"]},{"w":"comic","t":"adj. 喜剧的，滑稽的；n. 连环漫画；喜剧演员","p":"'kɒmɪk","e":["a comic novel","滑稽小说"]},{"w":"command","t":"n&vt. 命令，指挥；控制","p":"kə'mɑːnd","e":["By 1944, Fletcher had command of a B-17 bomber and a ten-man crew.","到1944年，弗莱彻已负责指挥一架B-17轰炸机和十名机组人员。"]},{"w":"commemorate","t":"vt. 纪念，庆祝","p":"kə'meməreɪt","e":["a parade to commemorate the town’s bicentenary","庆祝该镇建立200周年的游行"]},{"w":"commence","t":"v. 开始","p":"kə'mens","e":["Your first evaluation will be six months after you commence employment.","工作六个月后，你将接受第一次绩效评估。"]},{"w":"commend","t":"vt. 称赞，表扬；推荐","p":"kə'mend","e":["The paper was highly commended in the UK Press Awards.","该报获得了“英国新闻奖”的高度褒奖。"]},{"w":"commentary","t":"n. 实况报道，解说词；评论，评论文章","p":"'kɒməntri","e":["Commentary is by Tom Ferris.","由汤姆•费里斯现场解说。"]},{"w":"commentator","t":"n. 评论员","p":"ˈkɒmənteɪtə(r)","c":1,"e":["political commentators","政治评论员"]},{"w":"commerce","t":"n. 商业","p":"'kɒmɜ:s","c":1,"e":["measures promoting local commerce and industry","促进地方工商业发展的措施"]},{"w":"commercial","t":"adj. 商业的，商务的；商品化的，商业性的","p":"kə'mɜːʃl","e":["Our top priorities must be profit and commercial growth.","我们必须把利润和贸易增长作为我们的第一要务。"]},{"w":"commission","t":"n. 委任状；委员会；佣金，回扣；授权，委托；vt. 委任，委托","p":"kə'mɪʃn","e":["The Government set up a commission to investigate allegations of police violence.","政府成立了一个委员会调查对警察施暴行为的指控。"]},{"w":"commit","t":"vt. 犯，干；使承诺；把…托付给；调拨…供使用，拨出","p":"kə'mɪt","e":["Women commit fewer crimes than men.","女性犯罪比男性少。"]},{"w":"commitment","t":"n. 承诺","p":"kə'mɪtmənt","c":1,"e":["Are you ready to make a long-term commitment ?","你是否准备好作出长久的承诺？"]},{"w":"committee","t":"n. 委员会，全体委员","p":"kə'mɪti","e":["a committee meeting","委员会会议"]},{"w":"commodity","t":"n. 商品","p":"kə'mɒdətɪ","c":1,"e":["Commodity prices fell sharply.","商品价格急剧下跌。"]},{"w":"commonplace","t":"adj. 普通的，平庸的；n. 寻常的事物，平庸的东西","p":"'kɒmənpleɪs","e":["Car thefts are commonplace in this part of town.","镇上的这个地段盗车案屡见不鲜。"]},{"w":"commonsense","t":"adj. 有常识的","p":"'kɔmən'sens","e":["The judge's ruling was based on the simple commonsense tenet that no man is above the law.","法官的判决基于一个常识性原则，即谁也不能凌驾于法律之上。"]},{"w":"commonwealth","t":"n. [C-]英联邦；联邦，联合体","p":"'kɒmənwelθ","e":["...the Asian, Caribbean and African members of the commonwealth.","…英联邦在亚洲、加勒比海和非洲的成员国。"]},{"w":"communicate","t":"v. 通讯，交际，交流；连接，相通；传达，传播；传染","p":"kə'mjuːnɪkeɪt","e":["A baby communicates its needs by crying.","婴儿用哭来表达需要。"]},{"w":"communication","t":"n. 通讯，交流，交际；通信工具，交通联系","p":"kəˌmjuːnɪ'keɪʃn","e":["Good communication is vital in a large organization.","在大机构里良好的沟通是极为重要的。"]},{"w":"community","t":"n. 社区，社会，公社；团体，界；群落","p":"kə'mjuːnəti","e":["The new arts centre will serve the whole community.","这座新的艺术中心将为整个社区服务。"]},{"w":"commute","t":"vi. 乘公交车上下班，经常乘车往返于两地；vt. 减；折合，折偿；上下班交通","p":"kə'mjuːt","e":["Baldry’s 20-year prison sentence was commuted to three years.","鲍德里二十年的刑期被减至三年。"]},{"w":"compact","t":"adj. 紧密的，紧凑的","p":"kəm'pækt","c":1,"e":["The bushes grew in a compact mass.","灌木长成茂密的一片。"]},{"w":"companion","t":"n. 同伴，共事者；伴侣","p":"kəm'pæniən","e":["For ten years he had been her constant companion .","十年来他一直陪伴她左右。"]},{"w":"comparable","t":"adj. 可比较的；类似的；比得上的","p":"'kɔmpərəbl","e":["A car of comparable size would cost far more abroad.","同样大小的汽车在国外要贵得多。"]},{"w":"compare","t":"vt. 比较，对照；把…比作","p":"kəm'peə","e":["The report compares the different types of home computer available.","这份报告比较了市场上不同类型的家用计算机。"]},{"w":"comparison","t":"n. 比较，对照；比拟，比喻","p":"kəm'pærɪsn","e":["Her paintings invite comparison with those of the early Impressionists (= they remind you of them ) .","她的画作让人想起早期的印象派作品。"]},{"w":"compartment","t":"n. 车厢, 隔间","p":"kəm'pɑ:tmənt","c":1,"e":["She kept the money hidden in a secret compartment in her briefcase.","她把钱藏在公文包的暗层里。"]},{"w":"compatible","t":"adj. 兼容的；能和睦相处的，合得来的","p":"kəm'pætəbl","e":["The new software is IBM compatible (= can be used with IBM computers ) .","这个新软件与IBM的计算机兼容。"]},{"w":"compel","t":"v. 强迫","p":"kəm'pel","c":1,"e":["...the introduction of legislation to compel cyclists to wear a helmet.","…强制骑车人戴头盔的法律的引入。"]},{"w":"compelling","t":"adj. 引人注目的","p":"kəmˈpelɪŋ","c":1,"e":["His life makes a compelling story .","他的一生是个引人入胜的故事。"]},{"w":"compensate","t":"v. 弥补","p":"'kɒmpenseɪt","c":1,"e":["Because my left eye is so weak, my right eye has to work harder to compensate.","因为我左眼视力差，右眼就要辛苦点来弥补一下。"]},{"w":"compensation","t":"n. 补偿，赔偿，赔偿费","p":"kɒmpen'seɪʃ(ə)n","e":["People who are wrongly arrested may be paid compensation .","被误抓的人有可能得到补偿费。"]},{"w":"compete","t":"vi. 比赛，竞争，对抗","p":"kəm'piːt","e":["The banks have long competed with American Express's charge cards and various shop cards.","这些银行长期以来一直与美国运通公司的记账卡和各种商店卡竞争。"]},{"w":"competence","t":"n. 能力","p":"ˈkɒmpɪtəns","c":1,"e":["Typing is considered by most employers to be a basic competence.","大多数雇主认为打字是一项基本技能。"]},{"w":"competent","t":"adj. 能胜任的，有能力的","p":"ˈkɒmpɪtənt","c":1,"e":["A competent mechanic should be able to fix the problem.","一名合格的机修工应该能够解决这个问题。"]},{"w":"competition","t":"n. 比赛；竞争","p":"ˌkɒmpə'tɪʃn","e":["Going to trade fairs is an ideal opportunity to size up the competition .","参加商品交易会是估量竞争规模的理想机会。"]},{"w":"competitive","t":"adj. 竞争的，比赛的；好竞争的，求胜心切的；有竞争力的","p":"kəm'petətɪv","e":["The team seems to have lost its competitive edge recently (= its ability to compete well ) .","这支球队近来好像丧失了竞争优势。"]},{"w":"competitor","t":"n. 竞争者，敌手","p":"kəm'petɪtə","e":["Last year they sold twice as many computers as their competitors.","去年他们的计算机销量是竞争对手的两倍。"]},{"w":"compile","t":"vt. 汇编；编制，编纂","p":"kəm'paɪl","e":["The document was compiled by the Department of Health.","这份文件是由卫生部汇编的。"]},{"w":"complain","t":"vi. 抱怨，诉苦；控告，投诉","p":"kəm'pleɪn","e":["Miners have complained bitterly that the government did not fulfil their promises.","矿工们已愤愤地抱怨政府没有兑现他们的承诺。"]},{"w":"complaint","t":"n. 抱怨，投诉","p":"kəmˈpleɪnt","c":1,"e":["The sales assistants are trained to deal with customer complaints in a friendly manner.","售货员都受过培训，要以友好的态度处理顾客的投诉。"]},{"w":"complement","t":"n. 补充","p":"ˈkɒmplɪment","c":1,"e":["This wine would be a nice complement to grilled dishes.","这种葡萄酒配烧烤食物会很不错。"]},{"w":"completion","t":"n. 完成，结束，完满","p":"kəm'pliːʃn","e":["The house is nearing completion (= almost finished ) .","房子即将完工。"]},{"w":"complex","t":"adj. 由许多部分组成的，复合的；复杂的，难懂的；n. 综合体，集合体；情结，夸大的情绪反应","p":"'kɒmpleks","e":["Peter seemed to have an instant understanding of the most complex issues.","再复杂的问题彼得似乎也是一看就明白。"]},{"w":"complexion","t":"n. 肤色，面色；局面；性质","p":"kəm'plekʃn","e":["Drinking water is good for the complexion.","喝水让气色变好。"]},{"w":"complexity","t":"n. 复杂（性）","p":"kəm'pleksətɪ","e":["a design of great complexity","一项非常复杂的设计"]},{"w":"complicated","t":"adj. 复杂的","p":"'kɒmplɪkeɪtɪd","c":1,"e":["For young children, getting dressed is a complicated business.","对幼童来说，穿衣服是件复杂的事。"]},{"w":"complication","t":"n. 困难，难题；并发症","p":"ˌkɒmplɪ'keɪʃn","e":["Pneumonia is one of the common complications faced by bed-ridden patients.","肺炎是卧床病人所面临的常见并发症之一。"]},{"w":"compliment","t":"n. 赞美，恭维；致意，问候；vt. 赞美，恭维","p":"'kɒmplɪmənt","e":["All the guests paid her extravagant compliments.","所有客人都对她赞不绝口。"]},{"w":"comply","t":"vi. 遵从，依从，服从","p":"kəm'plaɪ","e":["The newspaper was asked by federal agents for assistance and agreed to comply.","联邦探员要求这家报社给予协助，报社同意配合。"]},{"w":"component","t":"adj. 组成的，构成的；n. 组成部分，部件，组件","p":"kəm'pəunənt","e":["Gorbachev failed to keep the component parts of the Soviet Union together.","戈尔巴乔夫没能使苏联各组成部分保持在一起。"]},{"w":"compose","t":"vt. 组成，构成；创作，为…谱曲；使平静，使镇静","p":"kəm'pəuz","e":["Barrington has composed the music for a new production of ‘A Midsummer Night’s Dream’.","巴林顿为新版的《仲夏夜之梦》谱了曲。"]},{"w":"composer","t":"n. 作曲家","p":"kəm'pəʊzə","e":["...music by Strauss, Mozart, Beethoven, and other great composers.","…施特劳斯、莫扎特、贝多芬及其他伟大作曲家创作的音乐。"]},{"w":"composite","t":"adj. 混合成的，综合成的；n. 合成物；复合材料","p":"'kɒmpəzɪt","e":["The author builds up a useful compo-site picture of contemporary consumer culture.","作者勾勒出了一幅实用的当代消费文化全景图。"]},{"w":"composition","t":"n. 作文","p":"ˌkɒmpəˈzɪʃn","c":1,"e":["I had to write a composition about the Royal visit.","我得写一篇关于皇室出访的作文。"]},{"w":"compound","t":"adj. 复合的，化合的；n. 化合物，复合物；复合词；vt. 使恶化，加重；使化合，使合成","p":"'kɒmpaund","e":["...the big compound eyes of dragonflies.","…蜻蜓的大复眼。"]},{"w":"comprehend","t":"v. 了解，理解，领会","p":"kɒmprɪ'hend","e":["She cannot comprehend the extent of the disaster.","她无法理解这场灾难的严重程度。"]},{"w":"comprehension","t":"n. 理解，理解力，领悟；理解力测验","p":"ˌkɒmprɪ'henʃn","e":["Why you let her talk you into doing such a foolish thing is beyond my comprehension (= impossible for me to understand ) .","你怎么会被她说服去做这种蠢事，我实在是无法理解。"]},{"w":"comprehensive","t":"adj. 综合的，全面的","p":"ˌkɒmprɪˈhensɪv","c":1,"e":["We offer our customers a comprehensive range of financial products.","我们为客户提供全面的金融产品。"]},{"w":"compression","t":"n. 压缩，压紧，浓缩","p":"kəm'preʃ(ə)n","e":["the compression of air","空气的压缩"]},{"w":"compromise","t":"v. 妥协","p":"ˈkɒmprəmaɪz","c":1,"e":["She admitted that she was unable to compromise.","她承认自己无法作出妥协。"]},{"w":"compulsory","t":"adj. 必须做的，强制性的；必修的","p":"kəm'pʌlsəri","e":["He believes that the study of history should be compulsory in school.","他认为在学校里学习历史应该是强制性的。"]},{"w":"compute","t":"v. 计算，估算","p":"kəm'pjuːt","e":["Final results had not yet been computed.","最终的结果还未计算出来。"]},{"w":"concede","t":"vi. 让步，认输；vt. 承认，承认…为真；承认失败；允许，让予","p":"kən'siːd","e":["‘That’s the only possible solution.’ ‘Yes, I suppose so,’ Charles conceded.","“那是唯一可行的解决办法。”“对，我想是。”查尔斯承认道。"]},{"w":"conceit","t":"n. 自负，自高自大","p":"kən'siːt","e":["The conceit of the woman!","这个自负的女人！"]},{"w":"conceive","t":"vi. 构想出，设想；怀孕；vt. 想出，认为；怀","p":"kən'siːv","e":["Scientists first conceived the idea of the atomic bomb in the 1930’s.","在20世纪30年代，科学家第一次有了原子弹的设想。"]},{"w":"concentrate","t":"v. 全神贯注，全力以赴；集中，聚集；浓缩；n. 浓缩物，浓缩液","p":"'kɒnsntreɪt","e":["Construction of the aircraft is being concentrated at Prestwick.","飞机制造正在向普雷斯特威克集中。"]},{"w":"concentration","t":"n. 集中；专注，专心；浓缩；浓度","p":"ˌkɒnsn'treɪʃn","e":["She needed all her powers of concentration to stop herself from slipping on the icy road.","她需要集中全部注意力才能不让自己在结冰的路上滑倒。"]},{"w":"concept","t":"n. 概念，观念；设想","p":"'kɒnsept","e":["It’s very simple, once you grasp the concept .","你一旦掌握了这个概念之后就很简单了。"]},{"w":"conception","t":"n. 思想，观念，概念；构想，设想；怀孕","p":"kən'sepʃn","e":["the original conception of the book","此书最初的构想"]},{"w":"concern","t":"n. 关切的事，有关的事；关心，挂念；关系，关联；公司，企业；vt. 涉及，有关；使关心，使担心","p":"kən'sɜːn","e":["He was moved by her obvious concern.","她明显的关心使他感动。"]},{"w":"concert","t":"n. 一齐，一致，协作","p":"'kɒnsət","e":["It appeared that both the accused were acting in concert in the attack upon the deceased.","两名被告看来是合力袭击死者的。"]},{"w":"concession","t":"n. 妥协","p":"kən'seʃn","c":1,"e":["The British were not prepared to make any concessions.","英国人没有打算作出让步。"]},{"w":"concise","t":"adj. 简明的，简要的","p":"kən'saɪs","e":["Your summary should be as clear and concise as possible.","你的总结应该尽可能地明白简洁。"]},{"w":"conclude","t":"vi. 结束，终了；vt. 推断出，推论出；缔结，议定","p":"kən'kluːd","e":["When the investigation is concluded, the results will be sent to the US Attorney’s office.","等到调查结束后，结果会被送到联邦检察官办公室。"]},{"w":"conclusive","t":"adj. 得出结论的","p":"kənˈklu:sɪv","c":1,"e":["The investigation failed to provide any conclusive evidence.","调查未能提供任何结论性的证据。"]},{"w":"concrete","t":"adj. 具体的","p":"'kɒŋkri:t","c":1,"e":["a dialogue about concrete issues and problems","有关具体事情和问题的对话"]},{"w":"condemn","t":"vt. 谴责，指责；判…刑，宣告…有罪","p":"kən'dem","e":["Politicians were quick to condemn the bombing.","政治家们立即对爆炸事件进行了谴责。"]},{"w":"condense","t":"vt. 使冷凝，使凝结；浓缩，压缩，简缩","p":"kən'dens","e":["the mist which condensed on every cold surface","每个冰冷的表面上凝结的水汽"]},{"w":"conduct","t":"v. 进行，实行","p":"kən'dʌkt","c":1,"e":["The memorial service was conducted by the Rev. David Prior.","这次追悼仪式由戴维·普赖尔牧师主持。"]},{"w":"confer","t":"v. 授予","p":"kənˈfɜ:(r)","c":1,"e":["The constitution also confers large powers on Brazil's 25 constituent states.","宪法还授予巴西25个成员州极大的权力。"]},{"w":"conference","t":"n. 会议，讨论会；讨论，商谈","p":"'kɒnfərəns","e":["Representatives from over 100 countries attended the International Peace Conference in Geneva.","来自一百多个国家的代表出席了在日内瓦举行的国际和平大会。"]},{"w":"confess","t":"v. 承认","p":"kənˈfes","c":1,"e":["Marsha confessed that she didn’t really know how to work the computer.","玛莎承认自己其实并不会使用计算机。"]},{"w":"confidence","t":"n. 信任，信赖；信心，自信","p":"'kɒnfɪdəns","e":["I felt I was doing well and my confidence began to grow.","我觉得自己干得不错，自信心就开始增加了。"]},{"w":"confident","t":"adj. 确信的，肯定的；自信的","p":"'kɒnfɪdənt","e":["Despite her disability, Philippa is very confident.","菲莉帕虽然有残疾，却很自信。"]},{"w":"confidential","t":"adj. 机密的","p":"ˌkɒnfɪˈdenʃl","c":1,"e":["The information will be regarded as strictly confidential (= completely confidential ) .","这一信息将被视为绝对机密。"]},{"w":"configuration","t":"n. 配置，布局，构造","p":"kənˌfɪgə'reɪʃn","e":["...Stonehenge, in southwestern England, an ancient configuration of giant stones.","…史前巨石柱群，位于英国西南部，是一座古代巨石阵列。"]},{"w":"confine","t":"v. 限制","p":"kənˈfaɪn","c":1,"e":["Vaughan is confined to a wheelchair .","沃恩离不开轮椅。"]},{"w":"confirm","t":"vt. 证实，肯定；确认；批准","p":"kən'fɜːm","e":["New evidence has confirmed the first witness’s story.","新的证据证实了第一个证人的说法。"]},{"w":"confirmation","t":"n. 证实，确定；确认","p":"kɒnfə'meɪʃ(ə)n","e":["There has still been no official confirmation of the report.","这则报道仍未得到官方证实。"]},{"w":"conflict","t":"n. 冲突","p":"'kɒnflɪkt","c":1,"e":["Doctors exercise considerable power and often come into conflict with politicians.","医生行使很大的权力，常常和政客们发生冲突。"]},{"w":"conform","t":"vi. 遵守，适应；顺从；相似，一致，符合","p":"kən'fɔːm","e":["the pressure on schoolchildren to conform","小学生要顺应社会的压力"]},{"w":"conformity","t":"n. 一致","p":"kən'fɔ:mɪtɪ","c":1,"e":["We must act in conformity with local regulations.","我们必须按当地的法规行事。"]},{"w":"confront","t":"vt. 迎面遇到，遭遇；勇敢地面对，正视；使对质，使当面对证","p":"kən'frʌnt","e":["The problems confronting the new government were enormous.","新政府面临的难题是巨大的。"]},{"w":"confrontational","t":"adj. 对抗的，有敌意的","p":"ˌkɒnfrʌnˈteɪʃnl","c":1,"e":["The committee's confrontational style of campaigning has made it unpopular.","该委员会挑衅的宣传方式使之不得人心。"]},{"w":"confusion","t":"n. 困惑，糊涂；混淆；骚乱","p":"kən'fjuːʒn","e":["To avoid confusion, the teams wore different colours.","为了避免混淆，各队穿着不同颜色的服装。"]},{"w":"congress","t":"n. 代表大会；国会，议会","p":"'kɒŋgres","e":["a congress of the ruling Labor Party","执政党工党的代表大会"]},{"w":"connection","t":"n. 连接；联系；连接物，连接点；亲戚","p":"kə'nekʃn","e":["Students often see little connection between school and the rest of their lives.","学生往往看不到上学和今后生活的联系。"]},{"w":"conquer","t":"v. 征服","p":"ˈkɒŋkə(r)","c":1,"e":["Egypt was conquered by the Persian king Kambyses.","埃及被波斯国王冈比西斯征服。"]},{"w":"conqueror","t":"n. 征服者，胜利者","p":"'kɒŋk(ə)rə(r)","e":["The people of an oppressed country obey their conquerors because they want to go on living.","一个被压迫国家的人民顺从他们的征服者，是因为他们想活下去。"]},{"w":"conscientious","t":"adj. 有良心的，认真负责的","p":",kɒnʃɪ'enʃəs","c":1,"e":["A conscientious teacher may feel inclined to take work home.","一个认真负责的教师可能会想着把工作带回家去做。"]},{"w":"conscious","t":"adj. 意识到的，自觉的；神志清醒的；有意的，存心的","p":"'kɒnʃəs","e":["The driver was still conscious when the ambulance arrived.","救护车赶到时，司机仍然神志清醒。"]},{"w":"consciousness","t":"n. 意识；知觉","p":"'kɒnʃəsnɪs","e":["She could faintly hear voices as she began to regain consciousness (= wake up ) .","她开始恢复知觉时，隐约听到有人在说话。"]},{"w":"consecutive","t":"adj. 连续的，连贯的","p":"kən'sekjətɪv","e":["Can they win the title for the third consecutive season?","他们能连续第三个赛季赢得冠军称号吗？"]},{"w":"consensus","t":"n. 共识，一致","p":"kənˈsensəs","c":1,"e":["The EU Council of Finance Ministers failed to reach a consensus on the pace of integration.","欧盟财政部长会议未能就一体化的进度达成共识。"]},{"w":"consent","t":"n. 同意","p":"kənˈsent","c":1,"e":["The chairman was elected by common consent (= with most people agreeing ) .","主席是大家一致推选出来的。"]},{"w":"consequence","t":"n. 结果，后果；重要，重大","p":"'kɒnsɪkwəns","e":["I don’t suppose it is of any consequence now.","现在我觉得这事一点都无所谓了。"]},{"w":"consequent","t":"adj. 作为结果的，随之发生的","p":"'kɒnsɪkwənt","e":["the rise in inflation and consequent fall in demand","通货膨胀的加剧和随之而来的需求下降"]},{"w":"consequently","t":"adv. 因此，因而，所以","p":"'kɒnsɪkwəntli","e":["The molecules are absorbed into the bloodstream and consequently affect the organs.","这些分子被吸收到血液里，从而影响到器官。"]},{"w":"conservation","t":"n. 保护","p":"ˌkɒnsəˈveɪʃn","c":1,"e":["a local conservation group","当地的一个环境保护团体"]},{"w":"conservative","t":"adj. 保守的","p":"kənˈsɜ:vətɪv","c":1,"e":["a very conservative attitude to education","对待教育非常守旧的态度"]},{"w":"conserve","t":"v. 保留，保护","p":"kənˈsɜːv","c":1,"e":["We must conserve our woodlands for future generations.","我们必须为子孙后代保护林地。"]},{"w":"considerable","t":"adj. 相当多的","p":"kənˈsɪdərəbl","c":1,"e":["Michael has already spent considerable time in Barcelona.","迈克尔在巴塞罗那已经待了相当长的时间了。"]},{"w":"considerate","t":"adj. 考虑周到的，体贴的，体谅的","p":"kən'sɪdərət","e":["I think he's the most charming, most considerate man I've ever known.","我觉得他是我所认识的最有魅力、最体贴的男士。"]},{"w":"consist","t":"vi. 由…组成；在于；一致","p":"kən'sɪst","e":["My diet consisted almost exclusively of chocolate-covered cookies and glasses of milk.","我的饮食几乎只包含裹上巧克力的曲奇饼和一杯杯牛奶。"]},{"w":"consistent","t":"adj. 一致的","p":"kənˈsɪstənt","c":1,"e":["She’s the team’s most consistent player.","她是该队中表现最为稳定的选手。"]},{"w":"console","t":"v. 安慰","p":"kən'səʊl","c":1,"e":["No one could console her when Peter died.","彼得去世时没人能够安慰她。"]},{"w":"consolidate","t":"v. 巩固，加强；联为一体，合并","p":"kən'sɒlɪdeɪt","e":["The company has consolidated its position as the country’s leading gas supplier.","这家公司巩固了作为该国主要煤气供应商的地位。"]},{"w":"conspicuous","t":"adj. 显著的","p":"kənˈspɪkjuəs","c":1,"e":["The notice must be displayed in a conspicuous place.","通告一定要贴在显眼的地方。"]},{"w":"constant","t":"adj. 不断的","p":"'kɒnstənt","c":1,"e":["He kept in constant contact with his family while he was in Australia.","他在澳大利亚时一直和家人保持着联系。"]},{"w":"constituent","t":"adj. 组成的，构成的；n. 选民，选区居民；成分，组成；配料","p":"kən'stɪtjuənt","e":["the EU and its constituent members","欧盟及其成员国"]},{"w":"constitute","t":"vt. 组成，形成；设立；任命","p":"'kɒnstɪtjuːt","e":["We must redefine what constitutes a family.","我们必须对家庭的构成重新定义。"]},{"w":"constitution","t":"n. 宪法，章程；组成；设立","p":"ˌkɒnstɪ'tjuːʃn","e":["The right to speak freely is written into the Constitution of the United States.","言论自由的权利被写入美国宪法。"]},{"w":"constrain","t":"v. 限制","p":"kən'streɪn","c":1,"e":["Women’s employment opportunities are often severely constrained by family commitments.","女性的就业机会常常受到家庭责任的严重限制。"]},{"w":"constraint","t":"n. 限制，束缚，约束","p":"kən'streɪnt","e":["Constraints on spending have forced the company to rethink its plans.","由于开支受到限制，这家公司不得不重新考虑其计划。"]},{"w":"construct","t":"vt. 建造；构思；n. 建筑物；构想；观念","p":"kən'strʌkt","e":["There are plans to construct a new road bridge across the river.","有计划要建造一条新的跨河公路桥。"]},{"w":"construction","t":"n. 建筑","p":"kən'strʌkʃn","c":1,"e":["a road construction project","道路修建计划"]},{"w":"consul","t":"n. 领事","p":"'kɒns(ə)l","e":["the British Consul in Paris","英国驻巴黎领事"]},{"w":"consult","t":"v. 咨询","p":"kən'sʌlt","c":1,"e":["If symptoms persist, consult a doctor without delay.","如果症状持续的话，马上咨询医生。"]},{"w":"consultancy","t":"n. 咨询公司","p":"kən'sʌltənsɪ","c":1,"e":["a management consultancy","管理咨询公司"]},{"w":"consultant","t":"n. 顾问；会诊医师，专科医生","p":"kən'sʌltənt","e":["a management consultant","管理顾问"]},{"w":"consultation","t":"n. 商议","p":"ˌkɒnslˈteɪʃn","c":1,"e":["This is a critical question that we must answer together through consultation and coordination.","这是一个我们必须通过磋商和协调共同回答的关键问题。"]},{"w":"consume","t":"vi. 消灭，毁灭；vt. 消费；吃完，喝光","p":"kən'sjuːm","e":["Some of the most efficient refrigerators consume 70 percent less electricity than traditional models.","一些能效最高的冰箱比传统型号少消耗70%的电。"]},{"w":"consumer","t":"n. 消费者，用户，消耗者","p":"kən'sjuːmə","e":["It will offer a wider choice of goods for the consumer (= consumers in general ) .","它将为消费者提供更多的商品选择。"]},{"w":"consumption","t":"n. 消耗；消费","p":"kənˈsʌmpʃn","c":1,"e":["Vigorous exercise increases oxygen consumption.","剧烈运动增加氧的消耗。"]},{"w":"contact","t":"n. 接触，联系，交往；vt. 与…接触，与…取得联系","p":"'kɒntækt","e":["The town is cut off from contact with the outside world.","小镇与外界的联系被切断了。"]},{"w":"contaminate","t":"v. 污染，弄脏","p":"kən'tæmɪneɪt","c":1,"e":["Drinking water supplies are believed to have been contaminated.","据信饮用水已受到污染。"]},{"w":"contamination","t":"n. 污染","p":"kənˌtæmɪ'neɪʃən","c":1,"e":["radioactive contamination","放射性污染"]},{"w":"contemplate","t":"vt. 盘算，计议；思量，对…周密考虑；注视，凝视","p":"'kɒntempleɪt","e":["He had even contemplated suicide.","他甚至想过自杀。"]},{"w":"contemporary","t":"adj. 现代的，当代的；同时代的","p":"kən'temprəri","e":["She writes a lot of contemporary music for people like Whitney Houston.","她为惠特尼·休斯敦等人创作大量当代音乐作品。"]},{"w":"contempt","t":"n. 轻视，蔑视","p":"kən'tempt","e":["How could she have loved a man who so clearly held her in contempt ?","她怎么会爱上一个明显看不起她的男人呢？"]},{"w":"contend","t":"vi. 争夺，竞争；搏斗，争斗；vt. 声称，主张","p":"kən'tend","e":["Inevitably, fights break out between the members of contending groups.","争权夺利的几个团体之间不可避免地发生了打斗。"]},{"w":"content","t":"adj. 满意的","p":"'kɒntent","c":1,"e":["Andy was a good husband, and Nicky was clearly very content.","安迪是个好丈夫，尼基显然非常满足。"]},{"w":"contention","t":"n. 争论","p":"kənˈtenʃn","c":1,"e":["The issue of hunting is a source of contention.","狩猎问题是争论的焦点。"]},{"w":"contest","t":"n. 竞赛，争夺；vt. 争夺，与…竞争；对…提出质疑，辩驳","p":"'kɒntest","e":["Stone decided to hold a contest to see who could write the best song.","斯通决定举行一场比赛，看谁能够写出最佳歌曲。"]},{"w":"contestant","t":"n. 参赛者","p":"kənˈtestənt","c":1,"e":["Later he applied to be a contestant on the television show.","之后他报了名做该电视秀的参赛者。"]},{"w":"context","t":"n. 上下文；来龙去脉","p":"'kɒntekst","e":["The meaning of ‘mad’ depends on its context.","mad一词的意义要视上下文而定。"]},{"w":"continental","t":"adj. 大陆的，大陆性的","p":"kɒntɪ'nent(ə)l","e":["the warming-up of continental interiors","内陆地区的变暖"]},{"w":"continual","t":"adj. 连续的；频频的","p":"kən'tɪnjuəl","e":["the Japanese business philosophy of continual improvement","日本人精益求精的经营哲学"]},{"w":"continuity","t":"n. 连续，持续","p":"ˌkɒntɪ'njuːəti","e":["We should ensure continuity of care between hospital and home.","我们应当保证医院护理和家庭护理的连续性。"]},{"w":"contract","t":"v. 缩小；订合同；感染，染上；n. 契约，合同","p":"'kɒntrækt","e":["Metal contracts as it cools.","金属遇冷收缩。"]},{"w":"contradict","t":"vt. 反驳，否认…的真实性；与…发生矛盾，与…抵触","p":"ˌkɒntrə'dɪkt","e":["Deborah opened her mouth to contradict, but closed it again.","黛博拉张口想要反驳，但又把嘴闭上了。"]},{"w":"contradiction","t":"n. 矛盾，不一致；否认，反驳","p":"ˌkɒntrə'dɪkʃn","e":["apparent contradictions in the defendant’s testimony","被告证词中的明显矛盾"]},{"w":"contrary","t":"adj. 相反的","p":"'kɒntrərɪ","c":1,"e":["The men shouted contrary orders.","这些人大声喊叫的命令互相矛盾。"]},{"w":"contrast","t":"vi. 形成对比，对比之下显出区别；n. 对比，对照；反差[kən'trɑːst]；vt. 对比，对照","p":"'kɒntrɑːst","e":["an essay comparing and contrasting (= showing how two things are similar and different ) Verdi and Wagner and their operas","把威尔第和瓦格纳以及他们的歌剧进行比较和对照的一篇文章"]},{"w":"contribute","t":"v. 有助于，促成；捐赠","p":"kən'trɪbju:t","c":1,"e":["Enya’s success has contributed substantially to the current interest in Celtic music.","时下人们对凯尔特音乐感兴趣，这很大程度上要归功于恩雅的成功。"]},{"w":"contribution","t":"n. 贡献","p":"ˌkɒntrɪˈbju:ʃn","c":1,"e":["The school sees its job as preparing students to make a contribution to society.","这所学校以培养学生为社会作贡献为己任。"]},{"w":"contrive","t":"vt. 谋划，策划；设法做到；设计，想出","p":"kən'traɪv","e":["The lawsuit says oil companies contrived the oil shortage in the 1970s.","诉讼中说，是石油公司策划了20世纪70年代的油荒。"]},{"w":"controversial","t":"adj. 受到争议的","p":"kɒntrə'vɜːʃ(ə)l","c":1,"e":["He is a controversial figure (= person who does controversial things ) in the art world.","他是艺术界极具争议的人物。"]},{"w":"controversy","t":"n. 争议","p":"'kɒntrəvɜ:sɪ","c":1,"e":["(= began ) over the use of the chemicals on crops.","对庄稼施用化学品的做法引起了争论。"]},{"w":"convene","t":"vi. 开会，集合；vt. 召集","p":"kən'viːn","e":["a report by experts convened by the National Institutes of Health","由全国健康协会召集的专家提出的一份报告"]},{"w":"convenience","t":"n. 方便；便利设施","p":"kən'viːniəns","e":["Ready meals sell well because of their convenience.","即食餐因为方便销路好。"]},{"w":"convention","t":"n. 习俗，惯例；公约；会议","p":"kən'venʃn","e":["a teachers’ convention","教师大会"]},{"w":"conventional","t":"adj. 传统的","p":"kən'venʃənl","c":1,"e":["Internet connections through conventional phone lines are fairly slow.","通过传统的电话线来连接因特网速度很慢。"]},{"w":"converge","t":"vi. 会合，互相靠拢；聚集，集中；趋近","p":"kən'vɜːdʒ","e":["The two rivers converge into one near Pittsburgh.","这两条河在匹兹堡附近汇合。"]},{"w":"conversion","t":"n. 转变","p":"kən'vɜːʃ(ə)n","c":1,"e":["...the conversion of disused rail lines into cycle routes.","…把废弃的铁路改变成自行车道。"]},{"w":"convert","t":"v. 转换，改变","p":"kən'vɜ:t","c":1,"e":["a 19th-century converted barn","由19世纪谷仓改建的房子"]},{"w":"convey","t":"vt. 表达；传递；运送，输送","p":"kən'veɪ","e":["He was sent to convey a message to the UN Secretary General.","他被派去向联合国秘书长传达一条信息。"]},{"w":"convict","t":"v. 证明……有罪","p":"kən'vɪkt","c":1,"e":["a convicted murderer","已定罪的谋杀犯"]},{"w":"conviction","t":"n. 确信，信服，深信","p":"kən'vɪkʃ(ə)n","e":["It was a reasonable explanation, but his voice lacked conviction .","这解释合情合理，只是他的语气不坚定。"]},{"w":"convince","t":"v. 使……相信","p":"kən'vɪns","c":1,"e":["Although I soon convinced him of my innocence, I think he still has serious doubts about my sanity.","尽管我很快就使他相信我是清白的，但是他还是非常怀疑我精神是否正常。"]},{"w":"convincing","t":"adj. 令人信服的","p":"kən'vɪnsɪŋ","c":1,"e":["convincing evidence of his guilt","证明他有罪的有力证据"]},{"w":"cooperative","t":"adj. 有合作意向的，乐意合作的；合作的，协作的；n. 合作社，合作商店","p":"kəu'ɒpərətɪv","e":["He was doing his best to be cooperative.","他在尽全力配合。"]},{"w":"coordinate","t":"adj. 同等的","p":"kəʊ'ɔ:dɪneɪt","e":["coordinate clauses joined by ‘and’","用 and 连接的并列分句"]},{"w":"coordination","t":"n. 协调；（肌肉的）协调","p":"kəʊˌɔ:dnˈeɪʃən","c":1,"e":["Too much alcohol affects your coordination.","喝酒太多会影响你动作的协调。"]},{"w":"cope","t":"vi. 应付，处理","p":"kəup","e":["He coped quite well as manager while still captaining the team.","他是球队的主教练，同时兼任队长，干得相当好。"]},{"w":"cord","t":"n. 细绳，粗线，索；灯芯绒裤","p":"kɔːd","e":["He pulled explosives and some tangled cord from his bag.","他从他的包里掏出炸药和一些乱糟糟的绳子。"]},{"w":"cordial","t":"adj. 热情友好的，热诚的","p":"'kɔːdiəl","e":["The talks were conducted in a cordial atmosphere.","会谈在友好的气氛中进行。"]},{"w":"cork","t":"n. 软木，软木塞；vt. 用瓶塞塞住","p":"kɔːk","e":["a cork bulletin board","软木公告板"]},{"w":"cornerstone","t":"n. 基石","p":"'kɔrnɚston","c":1,"e":["Research is the cornerstone of the profession.","研究是该职业的基石。"]},{"w":"corporate","t":"adj. 法人团体的，公司的；全体的，共同的","p":"'kɔːpərɪət","e":["The company is moving its corporate headquarters (= main offices ) from New York to Houston.","这家公司要把总部从纽约迁到休斯敦。"]},{"w":"corps","t":"n. 队，部队；一组","p":"kɔː","e":["the medical corps","医疗部队"]},{"w":"corpse","t":"n. 死尸，尸体","p":"kɔːps","e":["The corpse was found by children playing in the woods.","这具尸体是在林子里玩耍的孩子发现的。"]},{"w":"correctly","t":"adv. 正确地，恰当地","p":"kə'rek(t)lɪ","e":["If you can use a word correctly and effectively, you comprehend it.","你如果能正确和有效地使用一个字，你就了解它了。"]},{"w":"correlate","t":"vi. 相关，关联；vt. 使相互关联","p":"'kɒrəleɪt","e":["Obesity correlates with increased risk for hypertension and stroke.","过度肥胖与高血压和中风的发病风险增加密切相关。"]},{"w":"correlation","t":"n. 相关，关联","p":",kɔrə'leʃən","c":1,"e":["...the correlation between smoking and disease.","…吸烟和疾病之间的关联。"]},{"w":"correspondence","t":"n. 信件，函件；通信，通信联系；符合，一致，相似","p":"ˌkɒrə'spɒndəns","e":["A secretary came in twice a week to deal with his correspondence.","一个秘书每个星期来两次处理他的信件。"]},{"w":"corresponding","t":"adj. 相应的，符合的","p":"ˌkɒrə'spɒndɪŋ","e":["The war and the corresponding fall in trade have had a devastating effect on the country.","战争以及由此所导致的贸易量下降对这个国家产生了致命的影响。"]},{"w":"corrode","t":"v. 腐蚀，侵蚀","p":"kə'rəud","e":["Acidic water will corrode the pipes.","酸性水会腐蚀管子。"]},{"w":"corrosion","t":"n. 腐蚀，侵蚀；锈","p":"kə'rəʊʒ(ə)n","e":["They are sprayed with oil to prevent corrosion.","它们被喷了油以防腐蚀。"]},{"w":"corrupt","t":"adj. 堕落的，腐败的，贪赃舞弊的；vt. 腐蚀，使堕落","p":"kə'rʌpt","e":["Corrupt judges have taken millions of dollars in bribes.","腐败的法官接受了几百万美元的贿赂。"]},{"w":"corruption","t":"n. 腐败","p":"kəˈrʌpʃn","c":1,"e":["The investigation uncovered widespread corruption within the police force.","这项调查揭发出了警察机关内部普遍的腐败。"]},{"w":"cosmic","t":"adj. 宇宙的；广大无边的，极大的","p":"'kɒzmɪk","e":["the cosmic laws governing our world","主宰我们世界的宇宙法则"]},{"w":"cosmos","t":"n. 宇宙","p":"'kɒzmɒs","e":["...the natural laws of the cosmos.","…宇宙的自然法则。"]},{"w":"costume","t":"n. 服装","p":"'kɒstjuːm","c":1,"e":["the film’s lavish costumes and spectacular sets","影片中奢华的戏装和壮观的场景"]},{"w":"couch","t":"n. 睡椅，长沙发椅","p":"kaʊtʃ","e":["Tom offered to sleep on the couch.","汤姆说他来睡沙发。"]},{"w":"council","t":"n. 理事会，委员会","p":"'kaunsl","e":["the council for civil liberties","公民自由委员会"]},{"w":"counsel","t":"v. 建议，忠告","p":"'kaʊnsl","c":1,"e":["My advisers counselled me to do nothing.","我的顾问建议我不要做任何事情。"]},{"w":"counselor","t":"n. 咨询顾问","p":"'kaʊnsələ","c":1,"e":["For some people, a paid career counselor or coach is the best approach.","对有些人来说，付钱请职业顾问或教练是最好的方法。"]},{"w":"count","t":"n. 起拆理由，罪状","p":"kaʊnt","e":["Davis was found not guilty on all counts .","戴维斯受到指控的各项罪名均不成立。"]},{"w":"counter","t":"n. 柜台；计数器；筹码","p":"'kauntə","e":["He wondered if the girl behind the counter recognised him.","他在想柜台后面的那个女孩是否认出了他。"]},{"w":"countermeasure","t":"n. 对策","p":"ˈkaʊntəmeʒə(r)","c":1,"e":["new countermeasures against terrorism","对抗恐怖主义的新措施"]},{"w":"counterpart","t":"n. 对等物","p":"ˈkaʊntəpɑːt","c":1,"e":["As soon as he heard what was afoot, he telephoned his German and Italian counterparts to protest.","他一听到在进行中的事，马上就给德国和意大利相应人员打电话抗议。"]},{"w":"coupon","t":"n. 礼券，优惠券；配给券，票证","p":"'kuːpɒn","e":["The coupon entitles you to ten cents off your next purchase.","这张优惠券可以让你在下次购物时节省10分钱。"]},{"w":"courageous","t":"adj. 勇敢的，无畏的","p":"kə'reɪdʒəs","e":["He was wrong, and courageous enough to admit it.","他是错了，而且有勇气承认自己错了。"]},{"w":"court","t":"n. 法院，法庭；庭院；宫廷；球场","p":"kɔːt","e":["It could not be proved in a court of law.","这无法在法庭上证实。"]},{"w":"courteous","t":"adj. 有礼貌的，谦恭的","p":"'kɜːtjəs","e":["The staff are always courteous and helpful.","员工们总是彬彬有礼、乐于帮助。"]},{"w":"courtesy","t":"n. 谦恭有礼；有礼貌的举止","p":"'kɜːtəsi","e":["It’s a matter of common courtesy to acknowledge letters.","确认收到来信是起码的礼貌。"]},{"w":"cover","t":"v. 遮盖，遮蔽","p":"'kʌvə(r)","c":1,"e":["Cover the pot and bake for an hour.","把锅盖上，烘烤一小时。"]},{"w":"coverage","t":"n. 报道","p":"ˈkʌvərɪdʒ","c":1,"e":["live coverage of the match (= the match is broadcast at the same time that it is happening )","这场比赛的现场直播"]},{"w":"coward","t":"n. 胆小鬼，懦夫","p":"'kauəd","e":["Try it. Don’t be such a coward.","试一下，别那么胆小。"]},{"w":"cozy","t":"adj. 舒适的","p":"ˈkəʊzi","c":1,"e":["The living room was warm and cozy.","客厅暖和又舒适。"]},{"w":"crab","t":"n. 蟹；蟹肉；v. 捕蟹","p":"kræb","e":["crab meat","蟹肉"]},{"w":"crack","t":"v. 发出爆裂声","p":"kræk","e":["Dennis rubbed his hands together and cracked his knuckles.","丹尼斯搓着双手，把指关节弄得咯咯响。"]},{"w":"cradle","t":"n. 摇篮；策源地，发源地；vt. 轻轻地抱，捧","p":"'kreɪdl","e":["She rocked the cradle to quieten the child.","她摇动摇篮，让宝宝安静下来。"]},{"w":"craft","t":"n. 手艺；v. 精巧地制作","p":"krɑ:ft","c":1,"e":["Each doll is crafted individually by specialists.","每个布娃娃都由专业人员手工制作"]},{"w":"crank","t":"n. 曲柄；v. 用曲柄转动","p":"kræŋk","e":["He was idly turning a crank on a strange mechanism strapped to his chest.","他漫不经心地转着绑在他胸前的一个古怪装置上面的曲柄。"]},{"w":"crash","t":"vi. 倒下，坠落；发出撞击声；垮台，破产；vt. 碰撞，砸碎；冲，闯；n. 碰撞；破裂声","p":"kræʃ","e":["We watched the waves crashing against the rocks.","我们看着海浪哗啦哗啦地冲击岩石。"]},{"w":"crawl","t":"n&v. 爬行，蠕动；缓慢行进","p":"krɔːl","e":["The floor was crawling with ants.","地板上爬满了蚂蚁。"]},{"w":"creation","t":"n. 创造，创建；创造的作品，产物；宇宙，天地万物","p":"kri'eɪʃn","e":["a job creation scheme","创造就业机会的计划"]},{"w":"credible","t":"adj. 可信的，可靠的","p":"'kredəbl","e":["a credible alternative to nuclear power","原子能的可靠替代物"]},{"w":"credit","t":"n. 信贷，赊欠；赞扬，荣誉；学分；信任；vt. 相信；把…记入贷方；把…归于","p":"'kredɪt","e":["What’s the credit limit on your Visa card?","你的维萨卡信用额度是多少？"]},{"w":"crew","t":"n. 机组人员","p":"krʊ","c":1,"e":["The plane crashed, killing two of the crew and four passengers.","飞机坠毁，造成两名机组人员和四名乘客死亡。"]},{"w":"crime","t":"n. 罪，罪行，犯罪","p":"kraɪm","e":["Police officers are being given new powers to help combat crime.","警官们被赋予新的权力帮助他们打击犯罪。"]},{"w":"criminal","t":"adj. 犯罪的；n. 罪犯","p":"ˈkrɪmɪnl","c":1,"e":["Police have described the man as a violent and dangerous criminal.","警方形容那名男子是个凶暴而危险的罪犯。"]},{"w":"cripple","t":"n. 残疾，跛子","p":"ˈkrɪpl","c":1,"e":["She has gone from being a healthy, fit, and sporty young woman to being a cripple.","她从一个健康、强壮、爱好体育运动的年轻姑娘变成了一个残疾人。"]},{"w":"crisis","t":"n. 危机，存亡之际；关键阶段","p":"'kraɪsɪs","e":["The Prime Minister was criticized for the way in which he handled the crisis .","首相处理危机的方式遭到了批评。"]},{"w":"crisp","t":"adj. 脆的，鲜脆的；挺括的；清新的，干冷的；简明扼要的，利落的；n. 油炸土豆片","p":"krɪsp","e":["He stepped carefully through the crisp deep snow.","他小心地走在松脆的、厚厚的雪地里。"]},{"w":"criteria","t":"n. 标准","p":"kraɪ'tɪərɪə","c":1,"e":["The most important criterion for entry is that applicants must design and make their own work.","参加的最重要标准就是申请人必须设计并制作自己的作品。"]},{"w":"criterion","t":"n. 标准，准则","p":"kraɪ'tɪəriən","e":["the criteria we use to select candidates","我们挑选候选人的标准"]},{"w":"critic","t":"n. 批评家，爱挑剔的人","p":"'krɪtɪk","e":["Mather was a film critic for many years.","马瑟做过多年的电影评论家。"]},{"w":"critical","t":"adj. 批评的；关键的","p":"ˈkrɪtɪkl","c":1,"e":["It is absolutely critical for us to know the truth.","我们知道真相是极其重要的。"]},{"w":"criticism","t":"n. 批评","p":"ˈkrɪtɪsɪzəm","c":1,"e":["Another criticism levelled at him was that his teaching methods were old-fashioned.","还有一个针对他的批评是，他的教学方法已经过时。"]},{"w":"criticize","t":"vt. 批评，评论，非难","p":"'krɪtɪsaɪz","e":["Ron does nothing but criticize and complain all the time.","罗恩什么也不干，只是一味指责和抱怨。"]},{"w":"crooked","t":"adj. 弯的，歪的；畸形的","p":"'krʊkɪd","e":["narrow crooked streets","狭窄曲折的街道"]},{"w":"cropland","t":"n. 农田","p":"'krɒp,lænd","c":1,"e":["Forests had been cut or burned to provide additional cropland.","为了扩大农田,许多森林遭到砍伐和焚烧。"]},{"w":"cross","t":"adj. 恼怒的","p":"krɒs","e":["She gets cross when he goes out drinking.","他出去喝酒她就不高兴。"]},{"w":"crowd","t":"vi. 聚集，挤，涌；n. 群，一批；vt. 挤；挤满","p":"kraud","e":["Holidaymakers crowded the beaches.","海滩上挤满了度假者。"]},{"w":"crucial","t":"adj. 关键的","p":"'kru:ʃl","c":1,"e":["The conservation of tropical forests is of crucial importance .","保护热带雨林至关重要。"]},{"w":"cruelty","t":"n. 残酷；残酷行为","p":"'krʊəltɪ","e":["The children had suffered cruelty and neglect.","这些孩子遭受虐待，无人照管。"]},{"w":"cruise","t":"v. 巡航，巡航于…","p":"kruːz","e":["She wants to cruise the canals of France in a barge.","她想坐驳船游览法国的运河。"]},{"w":"crumble","t":"vi. 崩溃，瓦解；vt. 弄碎","p":"'krʌmbl","e":["The Empire began to crumble during the 13th century.","这个帝国在13世纪时开始崩溃。"]},{"w":"crush","t":"v. 压碎，压榨","p":"krʌʃ","c":1,"e":["Two people were crushed to death in the rush to escape.","两个人在逃生过程中被踩死。"]},{"w":"crystallize","t":"v. 结晶；变得清晰而明确；使具体化","p":"'krɪstəlaɪz","e":["The liquid will crystallize at 50 degrees centigrade.","这种液体在50摄氏度时结晶。"]},{"w":"cubic","t":"adj. 立方体的；立方的","p":"'kjuːbɪk","e":["75,000 million cubic metres of gas","750亿立方米的煤气"]},{"w":"cuckoo","t":"n. 杜鹃，布谷鸟","p":"'kʊkuː","e":["In England the cuckoo is the herald of spring.","在英国杜鹃鸟是报春的使者。"]},{"w":"cucumber","t":"n. 黄瓜","p":"'kjuːkʌmbə","e":["The \"gurkophone\" is one of their classics, made from a hollowed cucumber , a pepper and a carrot.","黄瓜管“是他们的经典乐器之一，那是用掏空的黄瓜、辣椒和胡萝卜做的。"]},{"w":"culminate","t":"vi. 告终","p":"'kʌlmɪneɪt","e":["They had an argument, which culminated in Tom getting drunk.","他们发生了争论，结果导致汤姆喝醉了酒。"]},{"w":"cultivate","t":"v. 培养","p":"'kʌltɪvet","c":1,"e":["Try to cultivate a more relaxed and positive approach to life.","要努力养成更为放松和积极的生活态度。"]},{"w":"culture","t":"n. 文化，文明；教养；培养；培养菌","p":"'kʌltʃə","e":["We speak Danish at home so that the boys don’t lose touch with their language and culture.","我们在家说丹麦语，这样男孩子们就不会脱离他们的语言和文化。"]},{"w":"cumulative","t":"adj. 积累的","p":"'kjumjəletɪv","c":1,"e":["Learning is a cumulative process.","学习是个逐渐积累的过程。"]},{"w":"curb","t":"v. 限制，控制","p":"kɜ:b","c":1,"e":["measures to curb the spread of the virus","控制病毒扩散的措施"]},{"w":"curly","t":"adj. 卷曲的；有卷毛的","p":"'kɜːlɪ","e":["long dark curly hair","又长又黑的鬈发"]},{"w":"currency","t":"n. 货币","p":"'kʌrənsɪ","c":1,"e":["There are moves towards a single currency in Europe.","欧洲有向单一货币发展的趋势。"]},{"w":"current","t":"adj. 当前的，通用的；流行的，流传的；n. 潮流；电流；趋势，倾向","p":"'kʌrənt","e":["In its current state, the car is worth £1,000.","这辆车按现在的车况来看值1,000英镑。"]},{"w":"currently","t":"adv. 当前","p":"'kʌrəntlɪ","e":["He is currently working on his first novel.","他目前正在创作他的第一本小说。"]},{"w":"curriculum","t":"n. 课程","p":"kəˈrɪkjələm","c":1,"e":["Languages are an essential part of the school curriculum.","语言是学校课程中必不可少的部分。"]},{"w":"curse","t":"v. 诅咒，咒骂，天谴；n. 祸害，祸根；咒骂，诅咒，咒语","p":"kɜːs","e":["Gilbert was cursing under his breath.","吉尔伯特在低声咒骂。"]},{"w":"custom","t":"n. 海关","p":"'kʌstəm","e":["It took ages to clear customs (= be allowed through customs ) but then we were out of the airport quite quickly.","过海关花了很长时间，不过出机场倒是很快。"]},{"w":"customary","t":"adj. 习惯上的，惯常的，合乎习俗的","p":"'kʌstəməri","e":["Barbara answered with her customary enthusiasm.","芭芭拉以惯有的热情作了回答。"]},{"w":"cute","t":"adj. 漂亮的，娇小可爱的；聪明伶俐的，精明的","p":"kjuːt","e":["That’s a really cute outfit.","那套衣服真漂亮。"]},{"w":"cutter","t":"n. 用于切割的器械","p":"'kʌtə","e":["a pastry cutter","油酥饼切刀"]},{"w":"cycle","t":"n&v. 自行车、摩托车；循环","p":"'saɪkl","e":["a woman’s menstrual cycle","女性的月经周期"]},{"w":"cylinder","t":"n. 圆柱体，圆筒；气缸，泵体","p":"'sɪlɪndə","e":["The gases are stored in cylinders.","气体储存在圆筒内。"]},{"w":"cynical","t":"adj. 愤世嫉俗的，怀疑的","p":"'sɪnɪkl","e":["a cynical view of human nature","认为人性本恶的一种观点"]},{"w":"damn","t":"v. 谴责","p":"dæm","e":["...a sensational book in which she damns the ultraright party.","…她谴责极右党派的一本耸人听闻的书。"]},{"w":"dare","t":"v. 勇敢，敢于做","p":"deə(r)","c":1,"e":["He wanted to ask her, but he didn’t dare.","他想问她，但又不敢。"]},{"w":"dart","t":"vi. 猛冲，飞奔；vt. 投射；n. 飞镖，飞镖游戏；急驰，飞奔","p":"dɑːt","e":["Jill darted forward and pulled him away from the fire.","吉尔冲上前把他从火边拉开。"]},{"w":"database","t":"n. 数据库","p":"'deɪtəbeɪs","e":["customer details held on a database","存储在数据库内的客户详细信息"]},{"w":"datum","t":"n. 资料；数据；已知数","p":"ˈdeɪtəm ; ˈdɑːtəm"},{"w":"dazzle","t":"vt. 使眩目，耀；使赞叹不已；使倾倒；n. 耀眼的光；令人赞叹的东西","p":"'dæzl","e":["a deer dazzled by the headlights","被车头灯光照得目眩的鹿"]},{"w":"deadline","t":"n. 最后期限","p":"'dedlaɪn","e":["I’m always working under pressure to meet deadlines (= finish something on time ) .","我总是在赶工期的压力下工作。"]},{"w":"deadly","t":"adv. 非常，极度地；adj. 致死的，致命的；不共戴天的；极度的，十足的","p":"'dedli","e":["Broadcast news was accurate and reliable but deadly dull.","新闻广播准确、可靠，但极其枯燥。"]},{"w":"deafen","t":"v. 使聋","p":"'def(ə)n","e":["He was deafened by the noise from the gun.","枪声把他震聋了。"]},{"w":"deal","t":"v. 买卖毒品","p":"diːl","e":["Many users end up dealing to support their habit.","许多吸毒者最后都是靠做毒品买卖来供自己吸毒。"]},{"w":"dealer","t":"n. 商人；毒品贩；发牌者","p":"'diːlə","e":["They will stay on the job for as long as it takes to clear every dealer from the street.","他们将坚持工作，直到街道上所有的毒品贩子都被清除。"]},{"w":"dean","t":"n. 教长，主任牧师；学院院长，系主任，训导主任","p":"diːn","e":["the admissions dean","招生主任"]},{"w":"debate","t":"n&v. 争论，辩论","p":"dɪ'beɪt","e":["There was much lively debate about whether women should spend more time in the home.","就妇女是否应该花更多时间待在家里这个话题有许多热烈的争论。"]},{"w":"debris","t":"n. 残骸，碎片","p":"ˈdeɪˌbri:","c":1,"e":["She was hit by flying debris from the blast.","她被爆炸产生的飞散碎片击中。"]},{"w":"decade","t":"n. 十年，十年期","p":"'dekeɪd","e":["...the last decade of the nineteenth century.","…19世纪的最后10年。"]},{"w":"decay","t":"vi. 腐烂，衰败；n. 腐烂，衰败状态","p":"dɪ'keɪ","e":["Most archaeological finds are broken, damaged, or decayed.","大部分考古发现物都已破裂、损坏或腐烂。"]},{"w":"deceive","t":"vi. 行骗；vt. 欺骗，蒙蔽","p":"dɪ'siːv","e":["He had been deceived by a young man claiming to be the son of a millionaire.","他被一个自称是百万富翁之子的年轻人骗了。"]},{"w":"decency","t":"n. 得体；宽容，大方；正派，合乎礼仪，体面；","p":"'diːsnsi","e":["If they’re going to charge people a fee, they ought to at least have the decency to tell them in advance.","如果他们要对人们收费，至少也应该事先告诉一声。"]},{"w":"decent","t":"adj. 像样的；正派的，规矩的","p":"ˈdi:snt","c":1,"e":["Paul visited the local bars more frequently than was decent for a senior lecturer.","保罗过于频繁地光顾当地酒吧，不太合乎高级讲师的身份。"]},{"w":"decidedly","t":"adv. 明确地，坚决地","p":"dɪ'saɪdɪdlɪ","e":["‘I’m not going to do it,’ said Margaret decidedly.","“这件事我不做。” 玛格丽特坚决地说。"]},{"w":"decimal","t":"adj. 十进位的；n. 小数","p":"'desɪml","e":["calculations accurate to three decimal places","精确到小数点后三位的计算"]},{"w":"decisive","t":"adj. 决定性的","p":"dɪˈsaɪsɪv","c":1,"e":["Women can play a decisive role in the debate over cloning.","对于克隆问题的辩论，女性能起到决定作用。"]},{"w":"declaration","t":"n. 宣布，宣言","p":"deklə'reɪʃ(ə)n","e":["the Declaration of Independence (= of the United States)","（美国）独立宣言"]},{"w":"decline","t":"v. 拒绝","p":"dɪ'klaɪn","c":1,"e":["Offered the position of chairman, Smith declined, preferring to keep his current job.","对担任主席的邀约，史密斯拒绝了，他宁愿留在现在的职位上。"]},{"w":"decode","t":"v. 解码","p":"ˌdi:ˈkəʊd","c":1,"e":["The software decodes the information embedded in the satellite broadcasts.","这种软件能够解读卫星广播中的信息。"]},{"w":"decompose","t":"v. 腐败；分解","p":"diːkəm'pəʊz","e":["As the waste materials decompose, they produce methane gas.","废物腐烂时会产生沼气。"]},{"w":"decorate","t":"vt. 装饰，装潢，修饰","p":"'dekəreɪt","e":["The bathroom is decorated in green and yellow.","浴室里是用绿色和黄色装潢的。"]},{"w":"decorative","t":"adj. 装饰的；可作装饰的","p":"'dek(ə)rətɪv","e":["a decorative panel above the door","门楣上的饰板"]},{"w":"decrease","t":"v. 减少；n. [dI'kriːs]","p":"'dɪkriːs","e":["The number of people who have the disease has decreased significantly in recent years.","近年来，这种病的患者人数明显下降。"]},{"w":"decree","t":"n. 法令，政令；判决，裁决；vt. 判决，命令","p":"dɪ'kriː","e":["The Emperor issued the decree repealing martial law.","皇帝下诏令取消了军事管制。"]},{"w":"dedicate","t":"vt. 题献词于上；把献给，把用于","p":"'dedɪkeɪt","e":["She dedicated her first album to Woody Allen, who she says understands her obsession.","她把她的第一张唱片献给伍迪·艾伦，她说艾伦理解她的痴迷。"]},{"w":"deduce","t":"vt. 推论，推断，演绎","p":"dɪ'djuːs","e":["Alison cleverly deduced that I was the author of the letter.","艾莉森聪明地推断出我是这封信的作者。"]},{"w":"deduct","t":"v. 减去，扣除","p":"dɪ'dʌkt","e":["The company deducted this payment from his compensation.","公司从他的补偿金中扣除了这笔款项。"]},{"w":"deduction","t":"n. 扣款","p":"dɪˈdʌkʃn","c":1,"e":["After deductions for tax etc, your salary is about £700 a month.","扣除税款等之后，你的月薪大约有700英镑。"]},{"w":"deem","t":"v. 认为","p":"di:m","c":1,"e":["French and German were deemed essential.","法语和德语被认为是必需的。"]},{"w":"deepen","t":"vt. （使色泽等）加浓","e":["deepening shadows","越来越暗的阴影"]},{"w":"default","t":"v. 不履行义务，拖欠；n. 违约，拖欠；弃权；预设，缺省","p":"dɪ'fɔːlt","e":["The credit card business is down, and more borrowers are defaulting on loans.","信用卡生意正在走下坡路，更多的借贷人不履行还贷责任。"]},{"w":"defeat","t":"n&vt. 战胜，挫败","p":"dɪ'fiːt","e":["She was a woman who hated to admit defeat.","她是个不愿认输的女人。"]},{"w":"defect","t":"n. 缺点","p":"'di:fekt","c":1,"e":["All the cars are tested for defects before they leave the factory.","所有汽车在出厂前都经过品质检验。"]},{"w":"defendant","t":"n. 被告","p":"dɪ'fendənt","e":["We find the defendant not guilty.","我们裁定被告无罪。"]},{"w":"defensive","t":"adj. 防守的，防御的","p":"dɪˈfensɪv","c":1,"e":["The rockets are a purely defensive measure against nuclear attack.","火箭弹纯粹是针对核攻击的防御性措施。"]},{"w":"deferential","t":"adj. 恭敬的，恭顺的","p":"ˌdefə'renʃl","e":["They like five-star hotels and deferential treatment.","他们喜欢五星级酒店和谦恭的礼遇。"]},{"w":"defiance","t":"n. 违抗；藐视","p":"dɪ'faɪəns","e":["...his courageous defiance of the government.","…他对政府的大胆蔑视。"]},{"w":"deficiency","t":"n. 缺乏，不足；缺点，缺陷","p":"dɪ'fɪʃnsi","e":["They did blood tests on him for signs of vitamin deficiency.","他们给他做了血检看是否有缺乏维生素的迹象。"]},{"w":"deficient","t":"adj. 不足的，缺乏的","p":"dɪˈfɪʃnt","c":1,"e":["Women who are dieting can become iron deficient.","节食的女性有可能缺铁。"]},{"w":"deficit","t":"n. 赤字","p":"ˈdefɪsɪt","c":1,"e":["the country’s widening budget deficit","这个国家日益严重的预算赤字"]},{"w":"define","t":"vt. 给…下定义，限定","p":"dɪ'faɪn","e":["I’ll now try to define the term ‘popular culture’.","我现在来试试给 “通俗文化” 这个词下定义。"]},{"w":"definite","t":"adj. 一定的，确切的","p":"'defɪnɪt","c":1,"e":["We need to record sufficient data to enable definite conclusions to be reached.","我们需要记录足够的数据，才能得出明确的结论。"]},{"w":"definitely","t":"adv. 一定地，明确地","p":"'defɪnətli","e":["‘Do you reckon Margot will be there?’ ‘ Definitely not .’","“你估计玛戈会在那里吗？” “肯定不会。”"]},{"w":"definition","t":"n. 定义，释义，定界；清晰，鲜明","p":"ˌdefɪ'nɪʃn","e":["a dictionary definition","词典里的释义"]},{"w":"definitive","t":"adj. 最可靠的，权威性的；决定性的","p":"dɪ'fɪnətɪv","e":["a definitive agreement to buy the company","收购这家公司的最终协议"]},{"w":"deflect","t":"v. （使）偏斜","p":"dɪ'flekt","e":["The ball deflected off Reid's body into the goal.","球打在里德身上反弹进球门。"]},{"w":"deflection","t":"n. 偏斜，歪斜；偏差","p":"dɪ'flekʃ(ə)n","e":["the deflection of the missile away from its target","使导弹偏离目标"]},{"w":"deforestation","t":"n. 砍伐森林","p":",di,fɔrɪ'steʃən","c":1,"e":["the deforestation of the tropics","热带森林的毁坏"]},{"w":"deform","t":"v. 损坏…的形状","p":"dɪ'fɔːm","e":["Wearing badly-fitting shoes can deform your feet.","穿不合脚的鞋会使脚变形。"]},{"w":"deformation","t":"n. 损坏；变形；畸形","p":",diːfɔː'meɪʃ(ə)n","e":["a deformation of the spine","脊柱的畸变"]},{"w":"defy","t":"v. 违背，违抗","p":"dɪ'faɪ","c":1,"e":["people who openly defy the law","公然抗拒法律的人"]},{"w":"degenerate","t":"vi. 衰退，堕落，蜕化；adj. 衰退的，堕落的；n. 堕落者","p":"dɪ'dʒenəreɪt","e":["Inactivity can make your joints stiff, and the bones may begin to degenerate.","不活动会使关节僵硬，骨骼因此可能会开始退化。"]},{"w":"degeneration","t":"n. 退化，变质","p":"dɪ,dʒɛnə'reʃən","c":1,"e":["Intensive farming in the area has caused severe degeneration of the land.","这个地区的集约化农业使得土壤严重贫瘠化。"]},{"w":"degradation","t":"n. 降级；退化；衰变","p":",degrə'deɪʃ(ə)n","e":["...air pollution, traffic congestion, and the steady degradation of our quality of life.","…空气污染、交通阻塞以及我们生活质量的持续恶化。"]},{"w":"degrade","t":"vt. 降低…的身份，有辱…的人格；使降解，使退化","p":"dɪ'greɪd","e":["a movie that degrades women","贬损女性的影片"]},{"w":"delegate","t":"n. 代表，委员，特派员","p":"ˈdɛlɪˌɡeɪt; -ɡɪt; (for v.,) ˈdɛlɪˌɡeɪt","e":["Around 350 delegates attended the conference.","大约有350名代表参加了大会。"]},{"w":"deliberate","t":"adj. 故意的","p":"dɪ'lɪbərət","c":1,"e":["The attack on him was quite deliberate.","对他的袭击完全是有预谋的。"]},{"w":"deliberately","t":"adv. 故意地；审慎地","p":"di'libərətli","e":["He shook his head slowly and deliberately.","他缓缓而慎重地摇摇头。"]},{"w":"delicate","t":"adj. 细微的；精细的","p":"'delɪkət","c":1,"e":["There’s something I have to speak to you about – it’s a delicate matter .","我有件事要跟你讲——是一件需要谨慎处理的事。"]},{"w":"deliver","t":"v. 递送；发表演讲","p":"dɪ'lɪvə(r)","c":1,"e":["The king delivered a televised speech to the nation on November 5.","国王在11月5日向全国发表了电视讲话。"]},{"w":"delusion","t":"n. 欺骗；哄骗","p":"dɪ'luːʒn"},{"w":"demand","t":"vt. 要求，需要；询问；n. 要求，需要","p":"dɪ'mɑːnd","e":["Angry demonstrators demanded the resignation of two senior officials.","愤怒的示威者要求两名高级官员辞职。"]},{"w":"democracy","t":"n. 民主","p":"dɪ'mɒkrəsɪ","c":1,"e":["democracy within the trade unions","工会内部的民主"]},{"w":"demonstrate","t":"vt. 说明，论证；表露","p":"'demənstreɪt","e":["The government now has an opportunity to demonstrate its commitment to reform.","政府现在有机会表明改革的决心了。"]},{"w":"demonstration","t":"n. 展示；游行","p":"ˌdemənˈstreɪʃn","c":1,"e":["Supporters staged a demonstration outside the US embassy.","支持者在美国大使馆外举行了示威游行。"]},{"w":"denationalize","t":"v. 使非国有化","p":"ˌdi:'næʃnəlaɪz","c":1,"e":["The government started to denationalize financial institutions.","政府开始将金融机构私有化。"]},{"w":"denial","t":"n. 否认；拒绝，拒绝给予","p":"dɪ'naɪəl","e":["It seems clear that despite official denials, differences of opinion lay behind the ambassador's decision to quit.","很清楚，尽管官方否认，人们对大使决定辞职还是有不同看法。"]},{"w":"denote","t":"vt. 意思是；表示，是…的标志","p":"dɪ'nəut","e":["What does the word ‘curriculum’ denote that ‘course’ does not?","curriculum一词的哪些含义是course没有的？"]},{"w":"denounce","t":"vt. 谴责，指责；告发","p":"dɪ'nauns","e":["The group denounced the failure by the authorities to take action.","该团体谴责当局没有采取行动。"]},{"w":"density","t":"n. 密度","p":"'densɪtɪ","c":1,"e":["areas of high population density","人口密度高的地区"]},{"w":"dentist","t":"n. 牙科医生","p":"'dentɪst","e":["Visit your dentist twice a year for a checkup.","每年看两次牙医做检查。"]},{"w":"deny","t":"v. 否认","p":"dɪ'naɪ","c":1,"e":["The government denied the existence of poverty among 16- and 17-year-olds.","政府否认十六七岁的青少年当中存在贫困问题。"]},{"w":"dependant","t":"n. 受赡养者","p":"dɪ'pend(ə)nt","e":["Companies with 200 or more workers must offer health benefits to employees and their dependants.","员工数为200或更多的公司必须为其员工和员工的受扶养人提供健康福利。"]},{"w":"depict","t":"vt. 描绘，描述","p":"dɪ'pɪkt","e":["a book depicting life in pre-revolutionary Russia","描写革命前俄国人生活的一本书"]},{"w":"deport","t":"vt. 把…驱逐出境","p":"dɪ'pɔːt","e":["...a government decision earlier this month to deport all illegal immigrants.","…本月早些时候政府一项驱逐所有非法移民的决定。"]},{"w":"deposit","t":"v. 存放；n. 存款","p":"dɪˈpɒzɪt","c":1,"e":["I’d like to make a deposit (= pay some money ) into my savings account.","我想存一笔钱到我的储蓄账户里。"]},{"w":"deposition","t":"n. 免职，罢免","p":",depə'zɪʃ(ə)n; diː-","e":["the deposition of the King","废黜国王"]},{"w":"depress","t":"vt. 使沮丧，使不景气；按下","p":"dɪ'pres","e":["Several factors combined to depress the American economy.","几个因素加在一起造成了美国经济的不景气。"]},{"w":"depression","t":"n. 抑郁，沮丧；不景气，萧条；洼地，凹陷","p":"dɪ'preʃn","e":["Mr. Thomas was suffering from depression.","托马斯先生当时正受抑郁症折磨。"]},{"w":"deprivation","t":"n. 剥夺，匮乏","p":"deprɪ'veɪʃ(ə)n","c":1,"e":["Sleep deprivation can result in mental disorders.","缺乏睡眠会引起精神紊乱。"]},{"w":"deprive","t":"v. 剥夺","p":"dɪ'praɪv","c":1,"e":["They've been deprived of the fuel necessary to heat their homes.","他们无法得到住房取暖必需的燃料。"]},{"w":"deputy","t":"n. 代理人；adj. 副的","p":"'depjʊtɪ","e":["the Deputy Secretary of State","助理国务卿"]},{"w":"derail","t":"v. 脱轨","p":"dɪ'reɪl","c":1,"e":["At least six people were killed and about twenty injured when a train was derailed in an isolated mountain region.","火车在一片偏僻的山区脱轨，导致至少六人死亡，约二十人受伤。"]},{"w":"derivation","t":"n. 引出；起源；衍生","p":"derɪ'veɪʃ(ə)n","e":["The derivation of its name is obscure.","它名字的根源起源鲜为人知。"]},{"w":"derive","t":"v. 获得","p":"dɪ'raɪv","c":1,"e":["Mr. Ying is one of those happy people who derive pleasure from helping others.","英先生是那种助人为乐的快活人。"]},{"w":"descend","t":"vi. 下来，下降；vt. 走下，爬下","p":"dɪ'send","e":["I heard his footsteps descending the stairs.","我听到他下楼的脚步声。"]},{"w":"descendant","t":"n. 子孙后代","p":"dɪˈsendənt","c":1,"e":["He was a direct descendant of Napoleon Bonaparte.","他是拿破仑·波拿巴的嫡系后裔。"]},{"w":"descent","t":"n. 血统, 后裔","p":"dɪ'sent","c":1,"e":["The emperor claimed descent from David.","这个皇帝自称是大卫王的后代。"]},{"w":"describe","t":"vt. 形容，描写；画出","p":"dɪ'skraɪb","e":["Another approach to the problem is described in Chapter 3.","这个问题的另一种解决方法在第三章有所阐述。"]},{"w":"descriptive","t":"adj. 描写的，描述的","p":"dɪˈskrɪptɪv","c":1,"e":["the descriptive passages in the novel","小说中的描写性段落"]},{"w":"desert","t":"v. 放弃，抛弃","p":"dɪˈzɜːt","c":1,"e":["Many of the party’s traditional voters deserted it at the last election.","许多长期支持该党的选民在上一次选举中抛弃了它。"]},{"w":"deserve","t":"v. 值得","p":"dɪ'zɜ:v","c":1,"e":["I’m sorry for the kids. They deserve better (= deserve to be treated in a better way ) .","我为这些孩子感到难过，他们应该过得更好。"]},{"w":"design","t":"vt. 设计；预定，指定；n. 设计，构想；图样；企图","p":"dɪ'zaɪn","e":["The tower was designed by Gilbert Scott.","这座塔楼是吉尔伯特·斯科特设计的。"]},{"w":"designate","t":"v. 指定，委派","p":"ˈdezɪgneɪt","c":1,"e":["Some of the rooms were designated as offices.","其中一些房间是被指定用作办公室的。"]},{"w":"desirable","t":"adj. 吸引人的，可取的","p":"dɪ'zaɪərəbl","e":["The ability to speak a foreign language is highly desirable .","能说一门外语是非常理想的。"]},{"w":"desire","t":"vt. 想要，渴望；n. 愿望，欲望","p":"dɪ'zaɪə","e":["The hotel has everything you could possibly desire .","这家酒店里你想要的东西应有尽有。"]},{"w":"desolate","t":"adj. 荒芜的；孤独的","p":"'des(ə)lət","e":["He was desolate without her.","没有她，他感到很凄凉。"]},{"w":"desperate","t":"adj. 绝望的，不顾一切的","p":"ˈdespərət","c":1,"e":["Time was running out and we were getting desperate .","时间越来越少，我们越来越感到绝望。"]},{"w":"despise","t":"vt. 鄙视，看不起","p":"dɪ'spaɪz","e":["She despised her neighbours.","她看不起她的邻居。"]},{"w":"despite","t":"prep. 不管，不顾","p":"dɪ'spaɪt","e":["Liz realized that, despite herself, she cared about Edward.","利兹发现自己不由自主地在乎爱德华。"]},{"w":"dessert","t":"n. 甜点心","p":"dɪ'zɜːt","e":["She had homemade ice cream for dessert.","她吃了些自制冰淇淋当餐后甜点。"]},{"w":"destination","t":"n. 目的地","p":"ˌdestɪˈneɪʃn","c":1,"e":["Ellis Island has become one of America's most popular tourist destinations.","埃利斯岛已经成为美国最受欢迎的游览地之一。"]},{"w":"destine","t":"v. 命定，注定；预定","p":"'destɪn"},{"w":"destined","t":"adj. 命中注定的，预定的；以…为目的地的","p":"'destɪnd","e":["The flight was destined for Cairo.","本次航班飞往开罗。"]},{"w":"destiny","t":"n. 命运；定数，天命","p":"'destəni","e":["She always had a strong sense of destiny .","她向来很相信天意。"]},{"w":"destruction","t":"n. 破坏，毁灭；消灭","p":"dɪ'strʌkʃn","e":["the environmental destruction caused by the road building programme","筑路工程造成的环境破坏"]},{"w":"destructive","t":"adj. 破坏性的，毁灭性的","p":"dɪ'strʌktɪv","c":1,"e":["the destructive power of modern weapons","现代武器的破坏力"]},{"w":"detach","t":"vt. 拆卸；使分开，使分离","p":"dɪ'tætʃ","e":["Please detach and fill out the application form.","请撕下申请表并填好。"]},{"w":"detached","t":"adj. 冷静的，超然的","p":"dɪˈtætʃt","c":1,"e":["Try to take a more detached view .","尽量采取更为客观的态度。"]},{"w":"detail","t":"n. 细节，枝节；零件；vt. 详细说明","p":"'diːteɪl","e":["This issue will be discussed in more detail in Chapter 5.","这个问题将在第五章里作更为详细的论述。"]},{"w":"detain","t":"vt. 拘留，扣留；留住，耽搁","p":"dɪ'teɪn","e":["Two suspects have been detained by the police for questioning .","两名嫌疑人被警方拘留审问。"]},{"w":"detect","t":"v. 发现","p":"dɪ'tekt","c":1,"e":["Many forms of cancer can be cured if detected early.","如果发现得早，许多种癌症都可以治愈。"]},{"w":"detection","t":"n. 察觉，发觉；侦查，探测","p":"dɪ'tekʃn","e":["...the early detection of breast cancer.","…乳腺癌的早期发现。"]},{"w":"detective","t":"n. 侦探","p":"dɪˈtektɪv","c":1,"e":["detectives from the anti-terrorist squad","反恐怖主义小组的侦探"]},{"w":"detector","t":"n. 发觉者，探测器","p":"dɪ'tektə","e":["a smoke detector","烟雾探测器"]},{"w":"deteriorate","t":"v. 恶化","p":"dɪˈtɪəriəreɪt","c":1,"e":["Ethel’s health has deteriorated.","埃塞尔的健康状况恶化了。"]},{"w":"deterioration","t":"n. 恶化，退化","p":"dɪ,tɪərɪə'reɪʃn","c":1,"e":["a serious deterioration in relations between the two countries","两国关系的严重恶化"]},{"w":"determine","t":"v. 决定","p":"dɪˈtɜ:mɪn","c":1,"e":["We determined to leave at once.","我们决定立即离开。"]},{"w":"develop","t":"v. 使（底片）显影","p":"dɪ'veləp","e":["Did you ever get the pictures developed ?","你到底有没有把照片冲洗出来？"]},{"w":"deviate","t":"v. 偏离","p":"ˈdi:vieɪt","c":1,"e":["They stopped you as soon as you deviated from the script.","你一偏离剧本，他们就会叫停。"]},{"w":"deviation","t":"n. 背离，偏离；偏差","p":"diːvɪ'eɪʃ(ə)n","e":["a compass deviation of 5˚ (= from true north)","罗盘偏差5度（相对正北而言）"]},{"w":"device","t":"n. 器械，装置；设计；手段，策略","p":"dɪ'vaɪs","e":["modern labour-saving devices","省力的现代设备"]},{"w":"devise","t":"vt. 设计，发明","p":"dɪ'vaɪz","e":["She devised a method for quicker communications between offices.","她想出一种加快办公室之间通信联络的方法。"]},{"w":"devote","t":"vt. 将…奉献给，把…专用","p":"dɪ'vəut","e":["He decided to devote the rest of his life to scientific investigation.","他决定把余生奉献给科学研究。"]},{"w":"devotion","t":"n. 献身，热诚，专心","p":"dɪ'vəʊʃ(ə)n","e":["Her devotion to the job left her with very little free time.","她全身心投入工作，几乎没有闲暇。"]},{"w":"devour","t":"v. 吞食；吞灭，毁灭","p":"dɪ'vaʊə","e":["Her body had been almost entirely devoured by the disease.","她的身体几乎完全被疾病摧毁。"]},{"w":"diagnose","t":"v. 诊断","p":"ˈdaɪəgnəʊz","c":1,"e":["Joe struggled in school before he was diagnosed as dyslexic.","乔在学校里学习很吃力，后来被诊断出患有诵读困难症。"]},{"w":"dictate","t":"v. ['dIkteIt]；n. 口授；命令，规定，要求","p":"dɪk'teɪt","e":["Federal funds have to be used as dictated by Washington.","联邦款项得按照华盛顿规定的途径使用。"]},{"w":"dictator","t":"n. 独裁者，专政者","p":"dɪk'teɪtə","e":["the downfall of the hated dictator","遭人痛恨的独裁者的垮台"]},{"w":"diesel","t":"n. 柴油发动机，内燃机","p":"'diːz(ə)l","e":["Our new car is a diesel.","我们的新车是柴油车。"]},{"w":"diet","t":"n. 日常饮食，日常食物","p":"'daɪət","e":["Rice is the staple diet (= the main food that a group of people usually eat ) .","大米是主食。"]},{"w":"differentiate","t":"vi. 区分，区别；vt. 区分，区别；使不同，使有差异","p":"ˌdɪfə'renʃieɪt","e":["What differentiates these two periods of history?","这两个历史时期的差别在哪里？"]},{"w":"differentiation","t":"n. 区别","p":"ˌdɪfəˌrenʃi'eɪʃn","e":["Excuse me each other a debate on the web, the virtual space, the interaction between people often with a mask, this month, the mirror with water flowers have what differentiation?","请问对方辩友，在网上这种虚拟空间中，人与人之间的交往往往带着一个假面具，这与水中月、镜中花有什么区别？"]},{"w":"difficult","t":"adj. 难以满足的","p":"'dɪfɪk(ə)lt","e":["Don’t be so difficult!","别这么挑剔！"]},{"w":"diffuse","t":"v. 扩散，弥漫；传播，散布；adj. 冗长的，漫无边际的；四散的，弥漫的","p":"dɪ'fjuːz","e":["Their ideas diffused quickly across Europe.","他们的观点很快在欧洲传播开来。"]},{"w":"digest","t":"vt. 消化，领会；n. 文摘","p":"daɪ'dʒest; dɪ-","e":["Most babies can digest a wide range of food easily.","大多数婴儿能轻易地消化很多种食物。"]},{"w":"dignity","t":"n. 庄严，端庄；尊严，高贵","p":"'dɪgnəti","e":["an appearance of quiet dignity","肃穆的神态"]},{"w":"dilemma","t":"n. 窘境，困境","p":"dɪ'lemə","e":["Many women are faced with the dilemma of choosing between work and family commitments.","许多女性面临着出去工作还是照顾家庭的两难境地。"]},{"w":"diligence","t":"n. 勤奋","p":"ˈdɪlɪdʒəns","c":1,"e":["She shows great diligence in her schoolwork.","她上学非常用功。"]},{"w":"diligent","t":"adj. 勤勉的，勤奋的","p":"'dɪlɪdʒənt","e":["a diligent student","勤勉的学生"]},{"w":"dilute","t":"v. 稀释，冲淡","p":"daɪ'l(j)ut","c":1,"e":["diluted fruit juice","稀释的果汁"]},{"w":"dim","t":"adj. 暗淡的；愚蠢的","p":"dɪm","c":1,"e":["in the dim light of the early dawn","在微弱的晨曦里"]},{"w":"dimension","t":"n. 尺寸；维","p":"daɪˈmenʃn","c":1,"e":["A diagram represents things in only two dimensions.","示意图只能二维地呈现物体。"]},{"w":"diminish","t":"v. 减少","p":"dɪ'mɪnɪʃ","c":1,"e":["The party’s share of the electorate has diminished steadily.","支持这个政党的选民比例持续下降。"]},{"w":"dine","t":"vi. 进餐；vt. 宴请","p":"daɪn","e":["He was dining with friends at the Ritz.","他和朋友在里茨饭店一起进餐。"]},{"w":"dioxide","t":"n. 二氧化物","p":"daɪ'ɒksaɪd","e":["carbon/sulphur dioxide","二氧化碳／硫"]},{"w":"diploma","t":"n. 毕业文凭，毕业证书，资格证书","p":"dɪ'pləumə","e":["I’m hoping to get my teaching diploma this year.","我希望今年能拿到教师证书。"]},{"w":"diplomat","t":"n. 外交官，外交家；有交际手腕的人，圆滑的人","p":"'dɪpləmæt","e":["French diplomats","法国外交官"]},{"w":"diplomatic","t":"adj. 外交的；有策略的","p":"dɪplə'mætɪk","e":["Diplomatic efforts to end the fighting began on October 25.","停战的外交努力于10月25日开始。"]},{"w":"directory","t":"n. 人名地址录；工商行名录；号码簿","p":"də'rektəri","e":["I couldn’t find your number in the telephone directory.","我在电话簿上找不到你的电话号码。"]},{"w":"disable","t":"vt. 丧失能力，伤残","p":"dɪs'eɪbl","e":["She did all this tendon damage and it really disabled her.","她肌腱受了这么多损伤，这真地使她致残了。"]},{"w":"disadvantage","t":"n. 缺点，不利条件","p":"ˌdɪsəd'vɑ:ntɪdʒ","c":1,"e":["Criminal behaviour can be linked to economic disadvantage.","犯罪行为可能会与经济困难有关。"]},{"w":"disagreement","t":"n. 争论；不一致","p":"dɪsə'ɡriːmənt","e":["We’ve had a few disagreements , but we’re still good friends.","虽然有过一些分歧，但我们仍是好朋友。"]},{"w":"disappear","t":"v. 消失","p":"ˌdɪsə'pɪə(r)","c":1,"e":["At this point the path seemed to disappear altogether (= disappear completely ) .","小路到这里好像完全消失了。"]},{"w":"disappearance","t":"n. 消失，消散；失踪","p":"dɪsə'pɪərəns","e":["Police are investigating the woman’s disappearance.","警方正在调查这名女子的失踪。"]},{"w":"disapproval","t":"n. 不赞成","p":"ˌdɪsə'pruːvl","e":["His action had been greeted with almost universal disapproval.","他的行动遭到了几乎一致的反对。"]},{"w":"disarm","t":"v. 解除，消除","p":"dɪs'ɑ:m","c":1,"e":["Getting the rebels to disarm will not be easy.","要让叛乱分子解除武装并非易事。"]},{"w":"disaster","t":"n. 灾难，灾祸，天灾；彻底的失败","p":"dɪ'zɑːstə","e":["Their expedition nearly ended in disaster , when one of the climbers slid off the mountain.","一名登山者从山上滑落，他们的探险活动险些以灾难告终。"]},{"w":"disastrous","t":"adj. 灾难性的，造成灾害的；极坏的，很糟的","p":"dɪ'zɑːstrəs","e":["The move proved disastrous (= was disastrous ) for the company.","这一行动对公司来说是一场灾难。"]},{"w":"discard","t":"vt. 丢弃，抛弃，遗弃","p":"dɪs'kɑːd","e":["Read the manufacturer's guidelines before discarding the box.","先阅读制造商的说明书再把盒子丢掉。"]},{"w":"discern","t":"v. 识别","p":"dɪˈsɜ:n","c":1,"e":["You need a long series of data to be able to discern such a trend.","你需要一大串数据才能认清这一趋势。"]},{"w":"discharge","t":"v. 释放，排出；卸货；n. 释放，放电","p":"dɪs'tʃɑːdʒ","e":["Hospitals now tend to discharge patients earlier than in the past.","与过去相比，现在医院更趋向于让病人早些出院。"]},{"w":"discipline","t":"n. 训练，管教","p":"'dɪsəplɪn","c":1,"e":["The book gives parents advice on discipline.","这本书指导父母如何管教孩子"]},{"w":"disclose","t":"vt. 揭露，泄露，透露","p":"dɪs'kləuz","e":["Some companies have already voluntarily disclosed similar information .","一些公司已经主动透露了类似的信息。"]},{"w":"disconnect","t":"v. 断开","p":"ˌdɪskə'nekt","c":1,"e":["The family agreed to disconnect her life support system.","家人同意切断她的生命维持系统。"]},{"w":"discount","t":"n. 折扣；vt. 把…打折扣；不全信；漠视，低估","p":"'dɪskaʊnt","e":["They are often available at a discount.","它们经常可以以折扣价买到。"]},{"w":"discourage","t":"v. 阻止；使气馁","p":"dɪs'kʌrɪdʒ","c":1,"e":["Aspirin may discourage tumour growth in some types of cancer.","阿司匹林可能遏制某些恶性肿瘤的生长。"]},{"w":"discourse","t":"n. 讲话，演说，讲道","p":"'dɪskɔːs; -'kɔːs","e":["a discourse on art","有关艺术的演讲"]},{"w":"discreet","t":"adj. 谨慎的，慎重的，审慎的","p":"dɪ'skriːt","e":["He assured her that he would be discreet.","他向她保证会谨慎行事。"]},{"w":"discrepancy","t":"n. 不符合，不一致","p":"dɪs'krepənsi","e":["A modification of the common-origin theory accounts for the density discrepancy .","关于共同起源的理论，有一种改进的论点解释了密度的不符。"]},{"w":"discrete","t":"adj. 分离的，不相关联的","p":"dɪ'skriːt","e":["The change happens in a series of discrete steps.","这个变化在一系列分离的步骤中发生。"]},{"w":"discriminate","t":"v. 歧视；区别","p":"dɪ'skrɪmɪneɪt","c":1,"e":["Under federal law, it is illegal to discriminate against minorities and women.","联邦法律规定，歧视少数民族和妇女是违法的。"]},{"w":"discrimination","t":"n. 歧视","p":"dɪˌskrɪmɪˈneɪʃn","c":1,"e":["laws to prevent discrimination","防止歧视的法律"]},{"w":"disease","t":"n. 病，疾病；不健全，弊端","p":"dɪ'ziːz","e":["She contracted the disease while she was abroad on holiday.","她在国外度假时染上了这种疾病。"]},{"w":"disengagement","t":"n. 分离","p":"ˌdɪsɪn'ɡeɪdʒmənt","c":1,"e":["This policy of disengagement from the European war had its critics.","从欧战中逐渐撤军的政策遭到了批评。"]},{"w":"disgrace","t":"n. 失宠，耻辱，丢脸","p":"dɪs'greɪs","e":["Smith faced total public disgrace after the incident.","事情发生之后，史密斯声名狼藉。"]},{"w":"disguise","t":"vt. 假扮，化装，伪装；掩盖，掩饰；n. 用来伪装的东西；伪装，掩饰","p":"dɪs'gaɪz","e":["He escaped across the border disguised as a priest.","他装扮成神父越境逃走了。"]},{"w":"disgust","t":"n&vt. 厌恶，憎恶","p":"dɪs'gʌst","e":["He reached into the bin with a look of disgust on his face.","他把手伸进垃圾箱，脸上带着厌恶的表情。"]},{"w":"dishonest","t":"adj. 不诚实的","p":"dɪsˈɒnɪst","c":1,"e":["People on welfare are wrongly seen as lazy or dishonest.","靠福利救济的人被误以为懒惰或不老实。"]},{"w":"disillusion","t":"v. 觉醒，使觉醒","p":",dɪsɪ'l(j)uːʒ(ə)n","e":["I hate to disillusion you, but I don’t think she’s coming back.","我真不愿意让你失望，但我想她是不会回来了。"]},{"w":"disintegration","t":"n. 破裂，分裂；瓦解","p":"dɪsˌɪntɪ'greɪʃn","e":["The act or an instance of breaking up, as a division, dispersal, or disintegration.","分散，分离分离的行为或实例，如分裂、分散或分解。"]},{"w":"dismantle","t":"vt. 拆开，拆卸","p":"dɪs'mæntl","e":["Chris dismantled the bike in five minutes.","克里斯五分钟内就把自行车拆掉了。"]},{"w":"dismay","t":"n. 失望，气馁；惊恐；vt. 使失望，使气馁；使惊恐","p":"dɪs'meɪ","e":["The thought of leaving filled him with dismay .","想到要离开，他心里充满了忧伤。"]},{"w":"dismiss","t":"v. 解雇","p":"dɪs'mɪs","c":1,"e":["Bryant was unfairly dismissed from his post.","布赖恩特被无理免职了。"]},{"w":"disorder","t":"n. 混乱，杂乱；骚乱","p":"dɪs'ɔːdə","e":["severe eating disorders such as bulimia and anorexia","像贪食症和厌食症这类严重的进食障碍"]},{"w":"dispatch","t":"v. 发送，派遣","p":"dɪˈspætʃ","c":1,"e":["Goods are normally dispatched within 24 hours.","货物一般在24小时内派送。"]},{"w":"dispensable","t":"adj. 可有可无的","p":"dɪˈspensəbl","c":1,"e":["Part-time workers are considered dispensable.","兼职工作人员被认为是可有可无的。"]},{"w":"disperse","t":"vi. 分散，赶散；消散，驱散；vt. 使分散，散开；使消散，消失","p":"dɪ'spɜːs","e":["Police used tear gas to disperse the crowd.","警察用催泪瓦斯驱散人群。"]},{"w":"displace","t":"v. 取代","p":"dɪsˈpleɪs","c":1,"e":["Coal has been displaced by natural gas as a major source of energy.","作为一种主要能源，煤的地位已为天然气所取代。"]},{"w":"displacement","t":"n. 移置；免职；置换","p":"dɪs'pleɪsm(ə)nt","e":["the displacement of traditional agriculture by industrial crops","经济作物对传统农业的替代"]},{"w":"display","t":"n&vt. 陈列，展览；显示","p":"dɪ'spleɪ","e":["a dazzling display (= very good display ) of flowers","令人目眩神迷的花卉展"]},{"w":"disposable","t":"adj. 可任意使用的；n. 一次性物品，不回收物品","p":"dɪ'spəuzəbl","e":["Currently, disposables account for about 80% to 85% of the $3 billion-plus annual diaper market.","目前，一次性尿布占年销售额30多亿美元的尿布市场的80%至85%左右。"]},{"w":"disposal","t":"n. 处理；支配","p":"dɪˈspəʊzl","c":1,"e":["Tanner had a lot of cash at his disposal .","坦纳手头有很多现金可以动用。"]},{"w":"dispose","t":"v. 去掉，销毁；处理，解决；使倾向于","p":"dɪ'spəuz","e":["Chinese vases are disposed around the gallery.","中国花瓶摆放在展馆四周。"]},{"w":"disposition","t":"n. 性情，性格；意向，倾向；排列，部署","p":"ˌdɪspə'zɪʃn","e":["the disposition of assets on death","身后财产的处置"]},{"w":"disproportionately","t":"adv. 比例不均地，不成比例地","p":"ˌdɪsprə'pɔ:ʃənətlɪ","c":1,"e":["The lower-paid spend a disproportionately large amount of their earnings on food.","低工资者将收入花在食物上的比例很大。"]},{"w":"disregard","t":"vt. 不理会，漠视；n. 忽视，漠视","p":"ˌdɪsrɪ'gɑːd","e":["He ordered the jury to disregard the witness’s last statement.","他指示陪审团忽略证人的最后一句话。"]},{"w":"disrupt","t":"vt. 使中断；扰乱","p":"dɪs'rʌpt","e":["Climate change could disrupt the agricultural economy.","气候变化可能给农业经济带来不良影响。"]},{"w":"dissatisfaction","t":"n. 不满，不平","p":"dɪssætɪs'fækʃn","e":["30% of customers expressed dissatisfaction with the service.","30%的顾客对服务表示不满意。"]},{"w":"disservice","t":"n. 危害","p":"dɪsˈsɜ:vɪs","c":1,"e":["He said the protesters were doing a disservice to the nation.","他表示，抗议者们的行为正对国家造成危害。"]},{"w":"dissipate","t":"vi. 消散，消失；vt. 使消散，使消失；浪费，挥霍","p":"'dɪsɪpeɪt","e":["Little by little, the smoke was dissipated by the breeze.","在微风的吹拂下烟雾渐渐地消散了。"]},{"w":"dissolve","t":"v. 解除（婚约等）","p":"dɪ'zɒlv","e":["The monarch had the power to dissolve parliament.","君主有权解散议会。"]},{"w":"distill","t":"vt. 蒸馏，用蒸馏法提取；吸取，提炼","p":"dɪ'stɪl","e":["distilled water","蒸馏水"]},{"w":"distinct","t":"adj. 与其他不同的；清楚的，明确的","p":"dɪ'stɪŋkt","e":["two entirely distinct languages","两种完全不同的语言"]},{"w":"distinction","t":"n. 区分","p":"dɪ'stɪŋkʃən","c":1,"e":["There are obvious distinctions between the two wine-making areas.","这两个酿酒区之间有明显的不同。"]},{"w":"distinctive","t":"adj. 与众不同的","p":"dɪˈstɪŋktɪv","c":1,"e":["a rock band with a distinctive sound","音色独特的摇滚乐队"]},{"w":"distinctly","t":"adv. 显然，清楚地","p":"dɪ'stɪŋ(k)tlɪ","e":["He distinctly remembered the day his father left.","他清晰地记得父亲离开的那一天。"]},{"w":"distinguish","t":"vt. 区别，辨别，识别；使杰出；使著名","p":"dɪ'stɪŋgwɪʃ","e":["The light was too dim for me to distinguish anything clearly.","光线太暗，我什么也看不清。"]},{"w":"distort","t":"v. 歪曲；扭曲","p":"dɪ'stɔ:t","c":1,"e":["an expensive subsidy which distorts the market","扰乱市场秩序的高价补贴"]},{"w":"distortion","t":"n. 歪曲；畸变","p":"dɪ'stɔːʃ(ə)n","e":["modern alloys that are resistant to wear and distortion","耐磨、防变形的新型合金"]},{"w":"distract","t":"v. 分心，分散注意","p":"dɪ'strækt","c":1,"e":["Try not to distract the other students.","尽量不要让其他学生分心。"]},{"w":"distribution","t":"n. 分布，分配","p":"ˌdɪstrɪ'bju:ʃn","c":1,"e":["the distribution of aid supplies","救济物资的分发"]},{"w":"disturbance","t":"n. 扰乱，打扰；骚乱，混乱；心神不安，烦恼","p":"dɪ'stɜːbəns","e":["There were disturbances in the crowd as fans left the stadium.","球迷离开体育场时，人群中发生了骚乱。"]},{"w":"diverge","t":"v. 分岔；分歧","p":"daɪ'vɜːdʒ; dɪ-","e":["Opinions diverge greatly on this issue.","在这个问题上意见分歧很大。"]},{"w":"diverse","t":"adj. 各种各样的","p":"daɪˈvɜ:s","c":1,"e":["subjects as diverse as pop music and archaeology","像流行音乐和考古学这样各不相同的学科"]},{"w":"diversion","t":"n. 转移；娱乐","p":"daɪˈvɜ:ʃn","c":1,"e":["...the illegal diversion of profits from secret arms sales.","…销售秘密武器所得收益的非法转移。"]},{"w":"diversity","t":"n. 多样性","p":"daɪ'vɜ:sətɪ","c":1,"e":["...the cultural diversity of Latin America.","…拉丁美洲文化的多样性。"]},{"w":"divert","t":"v. 使转向；转移注意力","p":"daɪ'vɜ:t","c":1,"e":["The high street is closed and traffic is being diverted .","大街封闭，车辆正改道而行。"]},{"w":"dividend","t":"n. 分红，红利","p":"'dɪvɪdend","c":1,"e":["The first quarter dividend has been increased by nearly 4 percent.","第一季度的股息增加了近4％。"]},{"w":"divine","t":"adj. 神的，神授的，天赐的；极好的，极美的","p":"dɪ'vaɪn","e":["divine power","神的力量"]},{"w":"division","t":"n. 分歧","p":"dɪ'vɪʒ(ə)n","c":1,"e":["The Army was plagued by internal divisions .","军队被内部分歧所困扰。"]},{"w":"divorce","t":"n. 离婚，离异；vt. 离婚；分离，脱离","p":"dɪ'vɔːs","e":["She received the house as part of the divorce settlement (= the amount of money, property etc each person receives in a divorce case ) .","根据离婚协议她获得了这幢房子。"]},{"w":"dizzy","t":"adj. 头晕目眩的，眩晕的；头晕的；vt. 令人发晕","p":"'dɪzi","e":["She started to suffer from dizzy spells (= a short period when you feel dizzy ) .","她开始感到一阵阵的眩晕。"]},{"w":"dock","t":"vi. 靠码头，进港；n. 码头，船埠；被告席；vt. 使靠码头；扣","p":"'dɒk","e":["The crash happened as the ferry attempted to dock on Staten Island.","这次碰撞发生于渡船试图停靠在斯塔滕岛时。"]},{"w":"doctrine","t":"n. 教义，教条；主义","p":"'dɒktrɪn","e":["traditional doctrines of divine power","神力的传统教义"]},{"w":"documentary","t":"n. 纪录片","p":"ˌdɒkjuˈmentri","c":1,"e":["...a TV documentary on homelessness.","…一部关于无家可归现象的电视记录片。"]},{"w":"dodge","t":"vi. 闪身躲开；vt. 回避，逃避；n. 托辞，伎俩；躲闪，躲避","p":"dɒdʒ","e":["He ran across the courtyard, dodging a storm of bullets.","他跑过院子，躲避雨点般的子弹。"]},{"w":"dole","t":"n. 救济，救济金；vt. 发放，发给","p":"dəul","e":["The number claiming dole went up by 3,500.","申请领取救济金者增加了3,500人。"]},{"w":"dolphin","t":"n. 海豚","p":"'dɒlfɪn","c":1,"e":["a school of dolphins","一群海豚"]},{"w":"domain","t":"n. 领域","p":"dəˈmeɪn","c":1,"e":["Looking after the house was viewed as a woman’s domain.","料理家务被认为是女性的份内之事。"]},{"w":"dome","t":"n. 圆屋顶，穹顶","p":"dəum","e":["...the dome of the Capitol.","…国会大厦的穹顶。"]},{"w":"domestic","t":"adj. 国内的","p":"dəˈmestɪk","c":1,"e":["...over 100 domestic flights a day to 30 leading U.S. destinations.","…每天飞往美国30个主要目的地的100多个国内航班。"]},{"w":"dominant","t":"adj. 占优势的，支配的，统治的；居高临下的，高耸的","p":"'dɒmɪnənt","e":["Japan became dominant in the mass market during the 1980s.","20世纪80年代日本在大众市场上开始占据优势。"]},{"w":"dominate","t":"v. 主导，主宰","p":"'dɒmɪneɪt","c":1,"e":["The industry is dominated by five multinational companies.","这个行业受五家跨国公司控制。"]},{"w":"donate","t":"vt. 捐赠，赠送","p":"dəu'neɪt","e":["people who volunteer to donate blood","自愿献血者"]},{"w":"donation","t":"n. 捐款，捐赠物；捐赠，赠送","p":"dəu'neɪʃn","e":["There have been generous donations from EU funds.","欧盟基金给予了慷慨的捐款。"]},{"w":"donor","t":"n. 捐赠者","p":"ˈdəʊnə(r)","c":1,"e":["An anonymous donor (= whose name is unknown ) has given £500 towards the restoration fund.","一位匿名捐赠者向重建基金捐了500英镑。"]},{"w":"doom","t":"vt. 注定，命定；n. 厄运，劫数","p":"duːm","e":["The plan was doomed from the start .","这个计划一开始就注定要失败。"]},{"w":"dorm","t":"n. 宿舍","p":"dɔ:m","c":1,"e":["But I had no food in my dorm, so I had to go to canteen.","但是我在宿舍没有东西可吃，所以我只能去餐厅了。"]},{"w":"doubtless","t":"adv. 无疑地，肯定地","p":"'dautləs","e":["Doubtless there would be lots of rumours.","无疑会谣言四起。"]},{"w":"dove","t":"n. 鸽子，斑鸠","p":"dʌv","e":["A dove cooed softly.","一只鸽子轻柔地咕咕叫。"]},{"w":"draft","t":"n. 草稿；汇票；征兵；通风；vt. 起草；征募","p":"drɑːft","e":["All parties eventually approved the final draft (= finished form ) of the peace treaty.","各方最后都同意了和平条约的终稿。"]},{"w":"drag","t":"v. 拖，拉；迫使，硬拉；拖着脚步走；n. 累赘；一吸，一抽","p":"dræg","e":["He took a drag on his cigarette, and exhaled the smoke.","他咂了口烟，然后吐出烟雾。"]},{"w":"drain","t":"vi. 慢慢减少；vt. 排去，放水；渐渐耗尽；n. 耗竭；排水沟，排水管","p":"dreɪn","e":["Huge imports were draining the country’s currency reserves.","大量的进口正在耗尽该国的货币储备。"]},{"w":"drainage","t":"n. 排水系统，下水道；排水，放水","p":"'dreɪnɪdʒ","e":["A handful of pebbles in the bottom of a flowerpot will help drainage.","在花盆底下放一把鹅卵石能够帮助排水。"]},{"w":"drama","t":"n. 戏剧性事件；戏剧性","e":["accidents, burst pipes, and other domestic dramas","意外事故、水管爆裂及其他家庭生活中的戏剧性事件"]},{"w":"dramatic","t":"adj. 引人注目的，激动人心的；戏剧的","p":"drə'mætɪk","e":["Some of the most dramatic events in American history happened here.","美国历史上一些最震撼人心的事件发生在这里。"]},{"w":"dramatically","t":"adv. 大幅度地；戏剧性地","p":"drə'mætɪklɪ","c":1,"e":["Prices have fallen dramatically.","价格突然暴跌。"]},{"w":"drastic","t":"adj. 严厉的，极端的；激烈的，迅猛的","p":"'dræstɪk","e":["Drastic changesare needed if environmental catastrophe is to be avoided.","要想避免环境灾难就需要重大的变革。"]},{"w":"drastically","t":"adv. 激烈地，猛烈地","p":"'drɑ:stɪklɪ","c":1,"e":["Things have started to go drastically wrong.","情况变得完全失控。"]},{"w":"drawback","t":"n. 缺点，欠缺；不利条件","p":"'drɔːbæk","e":["It’s a great city – the only drawback is the weather.","这是座很不错的城市，唯一的不足就是天气。"]},{"w":"dread","t":"vt. 担忧，忧虑；惧怕；n. 担忧，畏惧","p":"dred","e":["I’ve got an interview tomorrow and I’m dreading it.","明天我要去面试，我正担心呢。"]},{"w":"dreadful","t":"adj. 糟透了的，极不合意的；极端的，极其大的；可怕的","p":"'dredfl","e":["Michelle felt absolutely dreadful (= very ill ) .","米歇尔感觉病得很厉害。"]},{"w":"drift","t":"v. 漂流","p":"drɪft","c":1,"e":["The rubber raft drifted out to sea.","橡皮筏子漂向大海。"]},{"w":"drill","t":"v. 钻，打；训练；n. 钻头；操练，训练","p":"drɪl","e":["Drill a hole in each corner.","在每个角上钻一个孔。"]},{"w":"dropout","t":"n. 辍学学生","p":"ˈdrɒpaʊt","c":1,"e":["a high school dropout","中学退学者"]},{"w":"drought","t":"n. 干旱","p":"draʊt","c":1,"e":["...a country where drought and famines have killed up to two million people during the last eighteen years.","…过去18年来干旱和饥荒致死达两百万人的一个国家。"]},{"w":"drown","t":"v. 溺水","p":"draʊn","c":1,"e":["Many people drowned when the boat overturned.","船翻后许多人淹死了。"]},{"w":"drummer","t":"n. 鼓手","p":"ˈdrʌmə(r)","c":1,"e":["He was a drummer in a rock band.","他是一支摇滚乐队的鼓手。"]},{"w":"dry","t":"adj. 干巴巴的，枯燥的","p":"draɪ","e":["In schools, science is often presented in a dry and uninteresting manner.","在学校里，科学往往用枯燥乏味的方式来讲授。"]},{"w":"dual","t":"adj. 双的，两重的","p":"'djuːəl","e":["a dual system of education","二元[双元]教育体系"]},{"w":"dub","t":"vt. 给…起绰号，把…称为；为配音，译制","p":"dʌb","e":["Today's session has been widely dubbed as a \"make or break\" meeting.","今天的会议被大众称为“不成则散”的会议。"]},{"w":"dubious","t":"adj. 怀疑的，犹豫不决的，无把握的；有问题的；靠不住的","p":"'djuːbjəs","e":["The assumption that growth in one country benefits the whole world is highly dubious .","一国的经济增长会对全世界有益的假设是很值得怀疑的。"]},{"w":"duke","t":"n. 公爵；君主","p":"djuːk","e":["the Duke of Edinburgh","爱丁堡公爵"]},{"w":"duplicate","t":"n. 副本，复制品","p":"ˈdjuːplɪkeɪt","c":1,"e":["She kept both the duplicate and the original.","她把复制本和原本都保留着。"]},{"w":"duplication","t":"n. 复制品","p":"ˌdjuːplɪˈkeɪʃn","c":1,"e":["Is this a duplicate or the original?","这是副本还是正本？"]},{"w":"dust","t":"n. 灰尘","p":"dʌst","e":["All the furniture was covered in dust.","所有的家具都蒙上了灰尘。"]},{"w":"dutiful","t":"adj. 恭敬顺从的；尽职的","p":"'djuːtɪfl","e":["Dutiful applause greeted his speech.","他的讲话被报以礼节性的鼓掌。"]},{"w":"dwarf","t":"adj. 矮小的，发育不全的；n. 矮子，侏儒；vt. 使显得矮小，使相形见绌","p":"dwɔːf","e":["a dwarf conifer","矮生针叶树"]},{"w":"dwell","t":"vi. 居住","p":"dwel","e":["They dwelt in the forest.","他们住在森林里。"]},{"w":"dweller","t":"n. 居住者","p":"ˈdwelə(r)","c":1,"e":["City dwellers suffer higher pollution levels.","城市居民承受的污染程度更严重。"]},{"w":"dynamic","t":"adj. 动力的，动力学的；动态的；有活力的，有生气的","p":"daɪ'næmɪk","e":["dynamic and ambitious people","精力充沛且雄心勃勃的人"]},{"w":"dynamics","t":"n. 动力学","p":"daɪ'næmɪks","c":1,"e":["In its broadest sense, dynamics includes nearly the whole of mechanics.","广义地说来, 动力学几乎包括了整个力学。"]},{"w":"dynamo","t":"n. 发电机","p":"'daɪnəməʊ","e":["bicycle lights powered by a dynamo","以直流发电机供电的自行车车灯"]},{"w":"dysfunction","t":"n. 失常","p":"dɪs'fʌŋkʃn","c":1,"e":["...his severe emotional dysfunction was very clearly apparent.","...他情绪的严重异常是显而易见的。"]},{"w":"eagle","t":"n. 鹰","p":"'iːgl","e":["She looked down at her Viennese fan of eagle feathers.","她的头低着，眼睛看着手中的威尼斯鹰羽扇。"]},{"w":"ear","t":"n. （稻麦等的）穗","p":"ɪə","e":["an ear of corn","玉米穗"]},{"w":"earnings","t":"n. 工资，收入；收益","p":"'ɜːnɪŋz","e":["The company’s earnings have dropped by 5% in the first quarter.","公司第一季度的利润下降了5%。"]},{"w":"earthenware","t":"n. 陶器","p":"'ɜːθ(ə)nweə","e":["...colourful Italian china and earthenware.","...五颜六色的意大利瓷器和陶器。"]},{"w":"Easter","t":"n. 复活节","p":"'iːstə","e":["on Easter Sunday","在复活节星期日"]},{"w":"eastward","t":"adv. 向东","p":"'iːstwəd","e":["A powerful snow storm is moving eastward.","一场强暴风雪正在东移。"]},{"w":"eccentric","t":"adj. 古怪的","p":"ɪkˈsentrɪk","c":1,"e":["His eccentric behaviour lost him his job.","他古怪的行为使他丢了工作。"]},{"w":"echo","t":"v. 随声附和，发出回声","p":"'ekəʊ","c":1,"e":["The sound of an engine echoed back from the thick forest.","从茂密的森林里传来引擎的回声。"]},{"w":"eclipse","t":"n. 食；消失，黯然失色；vt. 食，遮掩光；使暗淡，使失色，使相形见绌","p":"ɪk'lɪps","e":["an eclipse of the sun","日食"]},{"w":"ecological","t":"adj. 生态学的","p":"ˌi:kəˈlɒdʒɪkl","c":1,"e":["an ecological disaster","生态灾难"]},{"w":"ecology","t":"n. 生态；生态学","p":"i'kɒlədʒi","e":["the natural ecology of the Earth","地球的自然生态"]},{"w":"economic","t":"adj. 经济的；经济学的；n. 经济学；经济状况","p":"ˌiːkə'nɒmɪk","e":["In the current economic climate (= conditions ), we must keep costs down.","在当前的经济形势下，我们一定要控制好成本。"]},{"w":"economical","t":"adj. 节约的；经济学的","p":"ˌiːkə'nɒmɪkl","e":["good-quality clothes at economical prices","物美价廉的衣服"]},{"w":"economically","t":"adv. 在经济上；节约地","p":"iːkə'nɒmɪklɪ","e":["In economically advanced countries, women marry later.","在经济发达国家，女性结婚比较晚。"]},{"w":"economics","t":"n. 经济学；经济","p":"iːkə'nɒmɪks; ek-","e":["a Harvard professor of economics","哈佛大学的经济学教授"]},{"w":"economy","t":"n. 经济；节约，节省","p":"i'kɒnəmi","e":["Not insuring your belongings is a false economy (= it is cheaper but could have bad results ).","不给个人财产投保实际上并不划算。"]},{"w":"ecosystem","t":"n. 生态系统","p":"'iːkəʊsɪstəm","c":1,"e":["...the forest ecosystem.","…森林生态系统。"]},{"w":"edible","t":"adj. 可以吃的，可食用的","p":"'edəbl","e":["These berries are edible, but those are poisonous.","这些浆果可以吃，但那些有毒。"]},{"w":"edit","t":"v. 编校；编辑；剪辑","p":"'edɪt","c":1,"e":["I know that this draft text will need to be edited.","我知道这篇草稿需要校订。"]},{"w":"editorial","t":"n. 社论，期刊的社论","p":"edɪ'tɔːrɪəl","e":["In an editorial, The New York Times suggests the victory could turn nasty.","在一篇社论中，《纽约时报》认为该胜利会转成恶梦。"]},{"w":"educational","t":"adj. 教育的，教育性的","p":"ˌedʒu'keɪʃənl","e":["the educational development of children","儿童的教育发展"]},{"w":"effective","t":"adj. 有效的；有影响的","p":"ɪ'fektɪv","e":["The cheaper drugs are just as effective in treating arthritis.","较便宜的药品对治疗关节炎同样有效。"]},{"w":"efficiency","t":"n. 效率；功效，效能","p":"ɪ'fɪʃnsi","e":["considerable advancements in energy efficiency","能源效率的显著提高"]},{"w":"efficient","t":"adj. 效率高的；有能力的","p":"ɪ'fɪʃnt","e":["Lighting is now more energy efficient.","如今的照明设备更加节能。"]},{"w":"ego","t":"n. 自我，自己，自尊","p":"'iːgəu","e":["I need someone to massage my bruised ego (= when you feel less confident than before ).","我需要有人来安抚我受挫的自信心。"]},{"w":"Egyptian","t":"adj. 埃及的；n. 埃及人","p":"ɪ'dʒɪpʃ(ə)n","e":["...the Egyptian pharaoh.","...古埃及法老。"]},{"w":"eject","t":"vt. 驱逐，逐出；喷射，排出；弹出","p":"i'dʒekt","e":["Two engines cut out and the plane started to eject fuel as it lost height.","两个发动机突然熄火，飞机在下降的同时开始喷出燃料。"]},{"w":"elaborate","t":"adj. 复杂的；精心制作的；v. 详述，详细制定","p":"ɪ'læb(ə)rət","e":["A spokesman declined to elaborate on a statement released late yesterday.","发言人拒绝对昨天晚些时候发表的一份声明作出更多说明。"]},{"w":"elaborately","t":"adv. 复杂地，精心设计地","p":"ɪ'læbərətlɪ","c":1,"e":["He elaborately devised a new computer.","他精心设计了一台新电脑。"]},{"w":"elapse","t":"vi. 消逝，过去","p":"ɪ'læps","e":["The assignment must be completed within an overall elapsed time of one week.","这项任务总的时限为一周，必须按时完成。"]},{"w":"elastic","t":"adj. 有弹性的；灵活的；n. 松紧带","p":"ɪ'læstɪk","e":["Make a mask with long ears and attach a piece of elastic to go around the back of the head.","做一个带长耳朵的面具，安上一条松紧带绕过后脑。"]},{"w":"elbow","t":"v. 用肘挤，挤进","p":"'elbəʊ","e":["She pushed through the crowd, elbowing people out of the way.","她用手肘把人们推开，从人群中挤了出来。"]},{"w":"election","t":"n. 选举","p":"ɪ'lekʃn","c":1,"e":["Elections for the state governorship will be on November 25.","州长选举将于11月25日举行。"]},{"w":"electric","t":"adj. 电的，电动的","p":"ɪ'lektrɪk","e":["an electric blanket","电热毯"]},{"w":"electrical","t":"adj. 电的；电气科学的","p":"ɪ'lektrɪkl","e":["The fire was caused by an electrical fault.","大火是电力故障引起的。"]},{"w":"electrician","t":"n. 电工，电气技师","p":"ɪˌlek'trɪʃn","e":["We need an electrician to fix our light switch.","我们需要一个电工来修理电灯开关。"]},{"w":"electricity","t":"n. 电","p":"ɪˌlek'trɪsəti","e":["The farm was very isolated, but it had electricity.","那个农场非常偏远，但有电力供应。"]},{"w":"electrify","t":"vt. 使充电，使电气化；使激动，使兴奋","p":"ɪ'lektrɪfaɪ","e":["She would sit at the piano and sing, electrifying us all.","她会边弹钢琴边唱歌，使我们大家兴奋不已。"]},{"w":"electrode","t":"n. 电极；电焊条","p":"ɪ'lektrəʊd","e":["The monkeys have electrodes implanted into the brain to measure their brain activity.","这些猴子的脑中植入了电极，以监测其大脑活动。"]},{"w":"electron","t":"n. 电子","p":"ɪ'lektrɒn","e":["Most things are balanced - with equal numbers of electrons and protons.","大部分物体都是电荷平衡的——含等量的电子和质子。"]},{"w":"electronic","t":"adj. 电子的；n. 电子学；电子设备","p":"ɪˌlek'trɒnɪk","e":["an electronic organizer (= a small piece of electronic equipment that you can use to record addresses, phone numbers etc )","电子记事本"]},{"w":"electronics","t":"n. 电子学","p":"ɪlek'trɒnɪks; el-","e":["an electronics engineer","电子工程师"]},{"w":"elegant","t":"adj. 高雅的，雅致的","p":"'elɪg(ə)nt","c":1,"e":["You can dine in elegant surroundings.","你可以在雅致的环境中进餐。"]},{"w":"element","t":"n. 成分，要素，元素；基础，纲要；自然力","p":"'elɪmənt","e":["Business and management elements are built into the course.","本课程加入了商务和管理方面的内容。"]},{"w":"elemental","t":"adj. 基本的；自然力的","p":",elɪ'ment(ə)l","e":["Love and fear are two of the most elemental human emotions.","爱和恐惧是人类最基本的两种情感。"]},{"w":"elementary","t":"adj. 基本的，初级的","p":"ˌelɪ'mentri","e":["the elementary principles of justice and democracy","正义和民主的基本信条"]},{"w":"elevate","t":"v. 提升；举起","p":"'elɪveɪt","c":1,"e":["Gradually elevate the patient into an upright position.","把病人慢慢托到直立的位置。"]},{"w":"elevation","t":"n. 高度，海拔","p":",elɪ'veɪʃ(ə)n","e":["The city is at an elevation of 2 000 metres.","这座城市海拔2000米。"]},{"w":"elicit","t":"vt. 诱出，探出","p":"i'lɪsɪt","e":["My letters to her have elicited no response.","我写给她的信没有得到回应。"]},{"w":"eligible","t":"adj. 适合的；胜任的","p":"ˈelɪdʒəbl","c":1,"e":["Students on a part-time course are not eligible for a loan.","非全日制课程的学生没有资格申请贷款。"]},{"w":"eliminate","t":"v. 消除","p":"ɪ'lɪmɪneɪt","c":1,"e":["a ruthless dictator who eliminated all his rivals","铲除所有异己的残酷独裁者"]},{"w":"elimination","t":"n. 消除，淘汰","p":"ɪ,lɪmɪ'neɪʃən","c":1,"e":["the elimination of lead in petrol","除去汽油中的铅"]},{"w":"elite","t":"n. 精英","p":"eɪ'li:t","c":1,"e":["a struggle for power within the ruling elite","统治阶层内部的争权夺利"]},{"w":"elliptical","t":"adj. 椭圆的；省略的","p":"ɪ'lɪptɪk(ə)l","e":["Kepler published his discovery of the elliptical orbits of planets in 1609. 1609","年开普勒公布他的发现，认为行星轨道为椭圆形。"]},{"w":"eloquence","t":"n. 雄辩；口才，修辞","p":"'eləkwəns","e":["a speech of passionate eloquence","激情洋溢的演讲"]},{"w":"eloquent","t":"adj. 口才好的，雄辩的","p":"ˈeləkwənt","c":1,"e":["an eloquent appeal for support","极具说服力的求助呼吁"]},{"w":"embark","t":"vi. 上船；着手，开始工作","p":"ɪm'bɑːk","e":["He's embarking on a new career as a writer.","他正开始一个当作家的新生涯。"]},{"w":"embarrass","t":"vt. 使窘迫，使为难","p":"ɪm'bærəs","e":["He didn’t want to embarrass her by asking questions.","他不想提问让她尴尬。"]},{"w":"embassy","t":"n. 大使馆；大使的职务","p":"'embəsɪ","e":["the American Embassy in Paris","美国驻巴黎大使馆"]},{"w":"embed","t":"vt. 把…嵌入，扎牢；使深留脑中","p":"ɪm'bed","e":["Feelings of guilt are deeply embedded in her personality.","负罪感在她的性格里根深蒂固。"]},{"w":"embody","t":"v. 体现","p":"ɪmˈbɒdi","c":1,"e":["She embodies everything I admire in a teacher.","她具备了我所钦佩的教师该具备的一切素质。"]},{"w":"embrace","t":"v. 采纳，接受","p":"ɪmˈbreɪs","c":1,"e":["Most West European countries have embraced the concept of high-speed rail networks with enthusiasm.","大多数西欧国家都表现出极大的兴趣，欣然接受修建高速铁路网的想法。"]},{"w":"embroidery","t":"n. 绣花，刺绣；绣制品","p":"ɪm'brɒɪd(ə)rɪ; em-","e":["The shorts had blue embroidery over the pockets.","这条短裤口袋上有蓝色的刺绣。"]},{"w":"emerge","t":"v. 出现","p":"ɪ'mɜ:dʒ","c":1,"e":["The flowers emerge in the spring.","花儿在春天开放。"]},{"w":"emergency","t":"n. 紧急情况，突然事件","p":"i'mɜːdʒənsi","e":["The government called an emergency meeting to discuss the crisis.","政府召开了紧急会议，讨论这次危机。"]},{"w":"emigrate","t":"v. 永久移居国外","p":"'emɪgreɪt","e":["He emigrated to Belgium.","他移民去了比利时。"]},{"w":"emission","t":"n. 散发；传播；发出物","p":"ɪ'mɪʃ(ə)n","e":["Britain agreed to cut emissions of nitrogen oxide from power stations.","英国同意减少发电站氮氧化物的排放量。"]},{"w":"emotion","t":"n. 情感，感情；激动","p":"ɪ'məuʃn","e":["Kim received the news without showing any visible sign of emotion.","金接到消息时丝毫不露声色。"]},{"w":"emphasis","t":"n. 强调；重视；重要性","p":"'emfəsɪs","e":["a change of emphasis in government policy","政府政策重心的变化"]},{"w":"emphasize","t":"v. 强调","p":"'emfəsaɪz","c":1,"e":["The report emphasizes the importance of improving safety standards.","报告强调了改进安全标准的重要性。"]},{"w":"empirical","t":"adj. 以经验为依据的，经验主义的，经验的","p":"ɪm'pɪrɪkl","e":["{\"COLLOINEXA\":[\"empirical evidence\"]}","实验证据"]},{"w":"employment","t":"n. 工作；雇用；使用","p":"ɪm'plɔɪmənt","e":["the needs of women who combine paid employment and care for their families","兼顾有薪工作和照料家庭的女性的需要"]},{"w":"enchant","t":"v. 迷住；用魔法迷惑","p":"ɪn'tʃɑːnt; en-","e":["...Celtic stories of cauldrons and enchanted vessels.","…凯尔特人关于神锅和魔法器皿的故事。"]},{"w":"enclosure","t":"n. 四周有篱笆的场地，围场；附件","p":"ɪn'kləuʒə","e":["the bear enclosure at the zoo","动物园中的熊园"]},{"w":"encounter","t":"v. 遭遇","p":"ɪn'kaʊntə(r)","c":1,"e":["The doctor had encountered several similar cases in the past.","那位医生过去曾碰到过好几个类似病例。"]},{"w":"encourage","t":"v. 鼓励","p":"ɪn'kʌrɪdʒ","c":1,"e":["I want to thank everyone who has encouraged and supported me.","我要感谢每一位鼓励和支持过我的人。"]},{"w":"end","t":"n. 目标，目的","p":"end","e":["She’ll do anything to achieve her own ends.","她为了实现自己的目标，什么都会去做。"]},{"w":"endanger","t":"v. 使……危险","p":"ɪnˈdeɪndʒə(r)","c":1,"e":["Smoking during pregnancy endangers your baby’s life.","孕期吸烟会危及胎儿生命。"]},{"w":"endeavor","t":"n&v. 努力，尽力，尝试","p":"ɪn'devə"},{"w":"endless","t":"adj. 无限的，没完没了的","p":"ˈendləs","c":1,"e":["He’s been in a lot of trouble – drugs, guns, blackmail – the list is endless.","他麻烦太多了——毒品、枪支、敲诈——说都说不完。"]},{"w":"endorsement","t":"n. 支持","p":"ɪnˈdɔ:smənt","c":1,"e":["The election victory is a clear endorsement of their policies.","竞选成功显然是对他们政策的支持。"]},{"w":"endow","t":"vt. 资助，捐赠；给予，赋予，认为…具有某种特质","p":"ɪn'dau","e":["You are endowed with wealth, good health and a lively intellect.","你天生赋有财富、健康，和敏锐的智力。"]},{"w":"endurance","t":"n. 忍耐力；持久，耐久","p":"ɪn'djuərəns","e":["She was pushed beyond her powers of endurance.","她被逼得忍无可忍。"]},{"w":"endure","t":"v. 忍受","p":"ɪnˈdjʊə(r)","c":1,"e":["It seemed impossible that anyone could endure such pain.","似乎谁都不可能忍受这样的疼痛。"]},{"w":"energetic","t":"adj. 精力充沛的，充满活力的","p":"ˌenə'dʒetɪk","e":["an energetic drive to get more customers","争取更多客户的十足干劲"]},{"w":"energize","t":"v. 供给…能量","p":"'enədʒaɪz"},{"w":"enforce","t":"v. 强迫，迫使","p":"ɪn'fɔ:s","c":1,"e":["It is unlikely that a record company would enforce its views on an established artist.","唱片公司未必能强迫一位已出名的艺人接受他们的意见。"]},{"w":"engage","t":"v. 忙于，从事；雇佣","p":"ɪn'ɡeɪdʒ","c":1,"e":["Her father engaged a tutor to improve her maths.","她爸爸请了一位家庭教师给她补习数学。"]},{"w":"engagement","t":"n. 订婚，婚约；约会","p":"ɪn'geɪdʒmənt","e":["Tony was stunned when Lisa suddenly broke off their engagement (= finished it ).","托尼对莉萨突然解除他俩的婚约感到震惊。"]},{"w":"engine","t":"n. 引擎，发动机；机车","p":"'endʒɪn","e":["We were stranded with engine trouble on a deserted highway.","我们因发动机故障而被困在空无一人的公路上。"]},{"w":"enhance","t":"vt. 提高，增加，加强","p":"ɪn'hɑːns","e":["The publicity has enhanced his reputation.","这次宣传提高了他的声誉。"]},{"w":"enlighten","t":"vt. 启发，开导","p":"ɪn'laɪtn","e":["A few dedicated doctors have fought for years to enlighten the profession.","少数富有献身精神的医生为启蒙这一行业而奋斗多年。"]},{"w":"enlightenment","t":"n. 启发，开导；开明，文明","p":"ɪn'laɪtnmənt","e":["Isabel looked to Ron for enlightenment.","伊莎贝尔希望得到罗恩的启发。"]},{"w":"enormous","t":"adj. 巨大的","p":"ɪˈnɔ:məs","c":1,"e":["The team made an enormous effort.","该队付出了巨大的努力。"]},{"w":"enrich","t":"v. 丰富，使富裕","p":"ɪn'rɪtʃ","c":1,"e":["Education can greatly enrich your life.","教育可以大大充实生活。"]},{"w":"enroll","t":"vi. 入学，加入；vt. 招收，吸收","p":"ɪn'rəul","e":["And, with the rise of online education, you can even enroll in certified programs that allow you to learn and improve your career during your off-hours.","并且，随着在线教育的崛起，你甚至可以参加认证课程，在下班工夫里学习和改善本人的职业生涯。"]},{"w":"enrollment","t":"n. 入学人数","p":"ɪn'rəʊlmənt","c":1,"e":["Student enrollments have more than doubled.","学生注册人数翻了一倍多。"]},{"w":"ensue","t":"vi. 接着发生，接踵而来，因而产生","p":"ɪn'sjuː","e":["If the Europeans did not reduce subsidies, a trade war would ensue.","如果欧洲不减少补贴，贸易战将随即爆发。"]},{"w":"entail","t":"v. 使需要，使必须","p":"in'teil","c":1,"e":["A new computer system entails a lot of re-training.","使用新的计算机系统需要大量的再培训。"]},{"w":"enterprise","t":"n. 艰巨的事业；事业心","p":"'entəpraɪz","e":["The programme is a joint enterprise with the London Business School.","这一计划是与伦敦商学院的合作项目。"]},{"w":"entertainment","t":"n. 娱乐，文娱节目，表演会；招待，款待，请客","p":"ˌentə'teɪnmənt","e":["There will be live entertainment (= performed then, not recorded ) throughout the day.","现场表演将持续一整天。"]},{"w":"enthusiasm","t":"n. 热情，热心，热忱；巨大兴趣","p":"ɪn'θjuːziæzəm","e":["Gillian and Darren greeted the speakers with great enthusiasm.","吉利恩和达伦非常热情地接待了演讲者。"]},{"w":"enthusiastic","t":"adj. 热情的","p":"ɪnˌθju:ziˈæstɪk","c":1,"e":["an enthusiastic supporter of reform","改革的热心支持者"]},{"w":"entitle","t":"v. 使具有资格","p":"ɪnˈtaɪtl","c":1,"e":["If the warranty is limited, the terms may entitle you to a replacement or refund.","如果保修单有限制，这些条款可让你有权换货或退款。"]},{"w":"entity","t":"n. 实体，独立存在体，实际存在物","p":"'entəti","e":["Good design brings a house and garden together as a single entity.","优秀的设计能把一所房子和花园合为一体。"]},{"w":"entreat","t":"v. 恳求","p":"ɪn'triːt; en-","e":["He entreated them to delay their departure.","他恳求他们晚些再走。"]},{"w":"entrepreneur","t":"n. 企业家","p":"ˌɒntrəprəˈnɜː(r)","c":1,"e":["The entrepreneur takes business risks in the hope of making a profit.","企业家为追求利润而冒险。"]},{"w":"entrepreneurship","t":"n. 企业管理","p":",ɒntrəprə'nɜːʃɪp","c":1},{"w":"entry","t":"n. 入口，通道；条目","p":"ˈɒntreɪ","e":["You can leave your umbrella in the entry.","你可以把伞放在入口处。"]},{"w":"enviable","t":"adj. 值得羡慕的","p":"ˈenviəbl","c":1,"e":["Now he was in the enviable position of not having to work for a living.","现在他已不必为生计而工作，着实令人羡慕。"]},{"w":"environment","t":"n. 环境；外界；围绕","p":"ɪn'vaɪrənmənt","e":["Some of these chemicals are very damaging to the environment.","这些化学品中有些对环境非常有害。"]},{"w":"environmental","t":"adj. 环境的，环境产生的","p":"ɪnvaɪrən'ment(ə)l; en-","e":["the environmental damage caused by the chemical industry","化学工业对环境造成的破坏"]},{"w":"envisage","t":"vt. 想象，设想","p":"ɪn'vɪzɪdʒ","e":["The scheme cost a lot more than we had originally envisaged.","该计划的花费大大超出了我们最初所预想的数额。"]},{"w":"epidemic","t":"n. 流行病","p":"ˌepɪ'demɪk","c":1,"e":["Over 500 people died during last year’s flu epidemic.","去年流感大暴发期间有五百多人死亡。"]},{"w":"episode","t":"n. （人生的）一段经历；（小说的）片段，插曲","p":"'epɪsəʊd","e":["One of the funniest episodes in the book occurs in Chapter 6.","书中最有趣的片段之一在第6章。"]},{"w":"epoch","t":"n. 时期，时代","p":"'iːpɒk","e":["The king’s death marked the end of an epoch.","这位国王的去世标志着一个时代的结束。"]},{"w":"equality","t":"n. 等同；平等；相等","p":"i'kwɒləti","e":["...equality of the sexes.","…性别平等。"]},{"w":"equation","t":"n. 平衡；反应式","p":"ɪ'kweɪʒ(ə)n","e":["When children enter the equation , further tensions may arise within a marriage.","有了孩子以后，婚姻中可能出现新的矛盾。"]},{"w":"equator","t":"n. 赤道","p":"ɪ'kweɪtə","e":["Knows(Those ) from south of the [ equator ] come to the United States during the northern winter .","那些来自赤道以南的学生在北方的冬天来到美国。"]},{"w":"equilibrium","t":"n. 平衡，均衡；均衡论","p":",iːkwɪ'lɪbrɪəm; ,ekwɪ-","e":["The government is anxious not to upset the economic equilibrium.","政府急切希望不要打乱经济平衡。"]},{"w":"equip","t":"vt. 装备，配备；使有准备","p":"ɪ'kwɪp","e":["They try to equip their vehicles with gadgets to deal with every possible contingency.","他们尽量给他们的车辆配备各种小装置以应付任何可能的突发状况。"]},{"w":"equivalent","t":"adj. 相等的，等量的；n. 相等物，等价物","p":"ɪ'kwɪvələnt","e":["I had no dollars, but offered him an equivalent amount of sterling.","我没有美金，但给了他等值的英镑。"]},{"w":"eradicate","t":"v. 根除","p":"ɪ'rædɪkeɪt","c":1,"e":["This problem has now been completely eradicated.","这个问题现已彻底杜绝。"]},{"w":"erect","t":"v. 建立","p":"ɪ'rekt","c":1,"e":["Police have erected barriers across the main roads into the town.","警察在进城的主要道路上设立了路障。"]},{"w":"erosion","t":"n. 腐蚀，侵蚀，磨损；削弱，减少","p":"ɪ'rəuʒn","e":["the erosion of the coastline","海岸线受到的侵蚀"]},{"w":"errand","t":"n. 差使，差事","e":["He quickly set out on his errand of mercy (= journey to help someone in danger ).","他迅速启程参加救援行动。"]},{"w":"erroneous","t":"adj. 错误的","p":"ɪˈrəʊnɪəs","c":1,"e":["His economic predictions are based on some erroneous assumptions.","他的经济预测是基于错误假设之上的。"]},{"w":"erupt","t":"v. 爆发；喷出","p":"ɪ'rʌpt","c":1,"e":["The volcano erupted in 1980, devastating a large area of Washington state.","这座火山1980年喷发，摧毁了华盛顿州的大片地区。"]},{"w":"escort","t":"n. 护卫者，护送者；vt. 护送，护卫","p":"'eskɔːt","e":["a police escort","警察护卫队"]},{"w":"essence","t":"n. 本质，实质，要素；精髓，精华","p":"'esns","e":["In essence his message was very simple.","实质上他想表达的意思很简单。"]},{"w":"essential","t":"adj. 必须的；本质的","p":"ɪ'senʃl","c":1,"e":["The essential difference between Sam and me was the fact that I took life seriously.","我和萨姆的根本区别在于我是认真对待生活的。"]},{"w":"establish","t":"vt. 建立，设立；确立；证实","p":"ɪ'stæblɪʃ","e":["The city of Boerne was established by German settlers in the 1840s.","博恩市是德国移民于19世纪40年代建立的。"]},{"w":"estate","t":"n. 地产，房地产","p":"ɪ'steɪt","e":["His estate was valued at $150,000.","他的遗产价值为15万美元。"]},{"w":"esteem","t":"v. 尊重","p":"ɪ'sti:m","c":1,"e":["Peden was greatly esteemed by the people of Ayrshire.","佩登深受艾尔郡人的尊敬。"]},{"w":"esthetic","t":"adj. 美学的，审美的；悦目的，雅致的","p":"iːs'θetɪk"},{"w":"estimate","t":"vt. 估计；评价；n. 估计；评价；看法","p":"'estɪmeɪt","e":["Try to estimate how many steps it will take to get to a close object.","估计一下需要多少步才能到达一个近距目标。"]},{"w":"eternal","t":"adj. 永久的，永世的；无休止的；永恒的，永不改变的","p":"ɪ'tɜːnl","e":["She’s an eternal optimist (= she always expects that good things will happen ).","她永远是个乐观主义者。"]},{"w":"ethnic","t":"adj. 种族的","p":"ˈeθnɪk","c":1,"e":["The school teaches pupils from different ethnic groups.","该校教授不同种族的小学生。"]},{"w":"evaluate","t":"v. 评价","p":"ɪˈvæljueɪt","c":1,"e":["It can be difficult to evaluate the effectiveness of different treatments.","要对各种治疗方法的效果作出评估会很难。"]},{"w":"evaluation","t":"n. 评价","p":"ɪˌvæljʊ'eɪʃn","c":1,"e":["We need to carry out a proper evaluation of the new system.","我们要对新系统进行合理的评估。"]},{"w":"evaporate","t":"v. 使脱水，发散蒸气","p":"ɪ'væpəreɪt","e":["The sun evaporates moisture on the leaves.","太阳会蒸发叶子上的水分。"]},{"w":"even","t":"adj. 平稳的，均匀的","p":"'iːv(ə)n","e":["The room is kept at an even temperature.","这个房间保持恒温状态。"]},{"w":"evenly","t":"adv. 一致地；平静地","p":"'i:vənlɪ","e":["The profits will be split evenly between the three of us.","利润将由我们三人平分。"]},{"w":"everlasting","t":"adj. 永久的；持久的","p":"evə'lɑːstɪŋ","e":["a symbol of God’s everlasting love","上帝永恒之爱的象征"]},{"w":"evidence","t":"n. 根据，证据；证人","p":"'evɪdəns","e":["Murrow’s evidence was enough to convict Hayes of murder.","默罗的证词足以证明海斯犯了谋杀罪。"]},{"w":"evident","t":"adj. 明显的，明白的","p":"'evɪdənt","e":["Bob ate his lunch with evident enjoyment.","显然鲍勃吃午饭吃得津津有味。"]},{"w":"evil","t":"adj. 坏的；n. 邪恶，祸害","p":"'iːvl","e":["an evil dictator responsible for the deaths of millions","应对数百万人之死负责的邪恶独裁者"]},{"w":"evoke","t":"vt. 唤起，引起，使人想起","p":"ɪ'vəuk","e":["The photographs evoked strong memories of our holidays in France.","那些照片勾起了我们到法国度假的深刻回忆。"]},{"w":"evolution","t":"n. 演变；发展；进化","p":"ˌi:və'lu:ʃn","c":1,"e":["the evolution of the computer","计算机的发展"]},{"w":"evolve","t":"v. 进化","p":"iˈvɒlv","c":1,"e":["Animals have evolved camouflage to protect themselves from predators.","动物进化形成了伪装，以保护自身不被捕食性动物所捕食。"]},{"w":"exaggerate","t":"v. 夸张","p":"ɪgˈzædʒəreɪt","c":1,"e":["I couldn’t sleep for three days – I’m not exaggerating.","我三天没睡觉了——一点不夸张。"]},{"w":"exaggeration","t":"n. 夸张；夸大之词","p":"ɪgˌzædʒə'reɪʃn","e":["It is no exaggeration to say that everyone will be affected by the new policy.","说人人都会受到新政策的影响一点也不夸张。"]},{"w":"exceed","t":"v. 超过","p":"ɪk'si:d","c":1,"e":["Working hours must not exceed 42 hours a week.","工作时间每周不得超过42小时。"]},{"w":"exceedingly","t":"adv. 极端地，非常","p":"ɪk'siːdɪŋli","e":["Thank you. You’ve been exceedingly kind.","谢谢，你真是太好了。"]},{"w":"excel","t":"v. 胜过，杰出","p":"ɪk'sel; ek-","e":["Rick has always excelled at foreign languages.","里克一向擅长外语。"]},{"w":"except","t":"v. 把…除外，除去","p":"ɪk'sept; ek-","e":["High technology equipment would be excepted from any trade agreement.","任何贸易协定都不会把高科技设备包括在内。"]},{"w":"exception","t":"n. 例外，除外","p":"ɪk'sepʃn","e":["We don’t usually accept checks, but for you we’ll make an exception (= not include you in this rule ).","我们一般不接受支票，但对你我们就破个例。"]},{"w":"exceptional","t":"adj. 例外的","p":"ɪkˈsepʃənl","c":1,"e":["A review panel concluded that there were no exceptional circumstances that would warrant a lesser penalty for him.","一个评估小组作出结论：没有什么例外情况可使他获得从轻惩罚。"]},{"w":"excess","t":"n. 过量，过度","p":"'ekses","c":1,"e":["After you apply the oil, wait 20 minutes before wiping off any excess.","涂上油以后，等20分钟再擦掉多余部分。"]},{"w":"excessive","t":"adj. 过度的","p":"ɪkˈsesɪv","c":1,"e":["$15 for two beers seems a little excessive.","两杯啤酒要15美元，似乎有点过分。"]},{"w":"excessively","t":"adv. 过分，极端地","p":"ek'sesɪvlɪ","e":["excessively high prices","过高的价格"]},{"w":"exchange","t":"n&vt. 交换；交流；兑换","p":"ɪks'tʃeɪndʒ","e":["Four of my cassettes for your Madonna CD is a fair exchange.","我用四盒磁带换你的麦当娜激光唱片很公平。"]},{"w":"exclaim","t":"vi. 呼喊，惊叫","p":"ɪk'skleɪm","e":["‘No!’ she exclaimed in shock.","“不！”她惊呼道。"]},{"w":"exclamation","t":"n. 呼喊，惊叫；感叹","p":",eksklə'meɪʃ(ə)n","e":["horrified exclamations of disgust","厌恶的惊叫"]},{"w":"exclude","t":"vt. 把…排除在外","p":"ɪk'skluːd","e":["The judges decided to exclude evidence which had been unfairly attained.","法官裁决不接纳以不正当手段获取的证据。"]},{"w":"exclusive","t":"adj. 奢华的，高级的；独有的；排斥的；不包括…的；n. 独家新闻","p":"ɪk'skluːsɪv","e":["Bel Air is an exclusive suburb of Los Angeles.","贝莱尔是洛杉矶郊外一处高级住宅区。"]},{"w":"excursion","t":"n. 远足，短途旅行","p":"ɪk'skɜːʃn","e":["a shopping excursion","购物游"]},{"w":"excuse","t":"v. 为…辩解；使免除","p":"ɪk'skjuːz; ek-","e":["He excused himself by saying he was 'forced to rob to maintain my wife and cat.'","他辩解说自己是“为了供养妻子和猫儿被迫去抢劫的”。"]},{"w":"execute","t":"vt. 将…处死；实施","p":"'eksɪkjuːt","e":["13 people were summarily executed (= killed without any trial or legal process ) by the guerrillas.","有13人被游击队员就地处决。"]},{"w":"execution","t":"n. 死刑；实行，执行，履行；演奏，表演","p":"ˌeksɪ'kjuːʃn","e":["Torture and summary execution (= execution without a trial or any legal process ) are common.","严刑拷打和不经审判就地处决相当普遍。"]},{"w":"executive","t":"n. 执行官","p":"ɪɡ'zekjətɪv","c":1,"e":["the union’s executive","工会的领导层"]},{"w":"exemplary","t":"adj. 可作楷模的，典范的","p":"ɪg'zempləri","e":["a company with an exemplary record on environmental issues","在处理环境问题方面可作为楷模的公司"]},{"w":"exemplify","t":"vt. 是…的典型；例示，举例证明","p":"ɪg'zemplɪfaɪ","e":["The building exemplifies the style of architecture which was popular at the time.","这栋大楼代表了当时流行的建筑风格。"]},{"w":"exempt","t":"adj. 被免除的，被豁免的；vt. 免除，豁免","p":"ɪg'zempt","e":["Men in college were exempt from military service.","在校男大学生免服兵役。"]},{"w":"exert","t":"v. 施加","p":"ɪɡ'zɜ:t","c":1,"e":["Environmental groups are exerting pressure on the government to tighten pollution laws.","环境保护组织在向政府施加压力，要求从严执行环保法律法规。"]},{"w":"exertion","t":"n. 运用","p":"ɪɡˈzɜːʃn","c":1,"e":["the exertion of authority","行使权力"]},{"w":"exhaust","t":"vt. 使筋疲力尽，用尽；详尽论述；n. 排气装置；废气","p":"ɪg'zɔːst","e":["A full day’s teaching exhausts me.","讲一整天课令我精疲力竭。"]},{"w":"exhibit","t":"vt. 显示；陈列，展览；n. 展览品","p":"ɪg'zɪbɪt","e":["Her paintings have been exhibited all over the world.","她的绘画作品在世界各地展出。"]},{"w":"exile","t":"n. 流放，流亡；被流放者，流亡国外者；vt. 流放，放逐，使流亡","p":"'eksaɪl","e":["He went into exile to escape political imprisonment.","他为了逃避政治监禁而流亡国外。"]},{"w":"existence","t":"n. 存在；生存","p":"ɪɡ'zɪstəns","c":1,"e":["Scientists have many theories about how the universe first came into existence (= started to exist ).","关于宇宙的起源，科学家有多种理论。"]},{"w":"exotic","t":"adj. 异域的，外国的","p":"ɪɡ'zɒtɪk","c":1,"e":["exotic places","有异国风情的地方"]},{"w":"expand","t":"v. 扩大，膨胀","p":"ɪk'spænd","e":["Sydney’s population expanded rapidly in the 1960s.","20世纪60年代，悉尼的人口迅速增加。"]},{"w":"expansion","t":"n. 扩张；扩大","p":"ɪkˈspænʃn","c":1,"e":["The rapid expansion of cities can cause social and economic problems.","城市规模的迅速扩大会带来各种社会和经济问题。"]},{"w":"expect","t":"v. 料想，认为","p":"ɪk'spekt; ek-","e":["I expected her to be taller than me, not shorter.","我曾以为她个子比我高，不会比我矮。"]},{"w":"expectancy","t":"n. 预料；期待；盼望","p":"ɪk'spektənsi","e":["I saw the look of expectancy in the children’s eyes.","我从孩子们的眼神中看到了期盼。"]},{"w":"expectation","t":"n. 期望","p":"ˌekspekˈteɪʃn","c":1,"e":["Some people have totally unrealistic expectations of both medical and nursing staff.","有些人对医护人员的期望完全不切实际。"]},{"w":"expedition","t":"n. 探险，远征","p":"ˌekspəˈdɪʃn","c":1,"e":["an expedition to the North Pole","北极探险"]},{"w":"expel","t":"v. 开除，驱逐","p":"ɪkˈspel","c":1,"e":["More than five-thousand high school students have been expelled for cheating.","五千多名中学生因考试作弊而被开除。"]},{"w":"expend","t":"vt. 花费，消费；消耗","p":"ɪk'spend","e":["Children expend a lot of energy and may need more high-energy food than adults.","孩子们耗能多，可能比成人需要更多高能量的食物。"]},{"w":"expenditure","t":"n. 费用，花销","p":"ɪkˈspendɪtʃə(r)","c":1,"e":["the expenditure of time and money on your house or garden","你在房子或花园上所花费的时间和金钱"]},{"w":"expense","t":"n. 花费，消费，费用；开支，业务费用","p":"ɪk'spens","e":["He borrowed £150,000 and used the money for legal expenses.","他借了15万英镑用于支付律师费。"]},{"w":"experimentally","t":"adv. 实验上，实验性地","p":"iks,peri'mentəli","e":["data obtained experimentally","实验获得的数据"]},{"w":"experimentation","t":"n. 实验；试验","p":"ɪk,sperɪmen'teɪʃən","e":["The issue of animal experimentation is an emotive subject.","动物实验问题是个敏感的话题。"]},{"w":"expert","t":"adj. 熟练的；n. 专家","p":"'ekspɜːt","e":["...a yoga expert.","…一位瑜伽专家。"]},{"w":"expertise","t":"n. 专业知识","p":"ˌekspɜ:ˈti:z","c":1,"e":["She was not an accountant and didn't have the expertise to verify all of the financial details.","她不是会计，不具有核查所有这些财政细目的专业知识。"]},{"w":"expire","t":"vi. 期满，终止；断气，死亡","p":"ɪk'spaɪə","e":["The chairman’s term of office has already expired.","主席任期已满。"]},{"w":"explicit","t":"adj. 详述的，明确的，明晰的；直言的，露骨的","p":"ɪk'splɪsɪt","e":["The kidnappers gave us explicit instructions not to involve the police.","绑匪明确告诉我们不许报警。"]},{"w":"exploit","t":"v. 开发，开采","p":"ɪk'splɔɪt","c":1,"e":["the urgent need to exploit the resources of the Irish Sea","开发爱尔兰海资源的迫切需要"]},{"w":"exploration","t":"n. 考察；勘探；探查","p":"eksplə'reɪʃ(ə)n","e":["You can then use this hut as a base for explorations into the mountains around.","你到时可以把这间小屋当大本营，去周围的山里探险。"]},{"w":"explore","t":"v. 探险，探索；仔细查阅，探究","p":"ɪk'splɔː","e":["Management need to explore ways of improving office security.","管理层需要探讨如何加强办事处的安全措施。"]},{"w":"expose","t":"vt. 使暴露，揭露","p":"ɪk'spəuz","e":["He lifted his T-shirt to expose a jagged scar across his chest.","他撩起T恤衫，露出横贯胸部的锯齿状伤疤。"]},{"w":"exposition","t":"n. 阐述，讲解；展览会，博览会","p":"ˌekspə'zɪʃn","e":["Aristotle was valued because of his clear exposition of rational thought.","亚里士多德因其对理性思维的清晰阐述而被重视。"]},{"w":"expression","t":"n. 词语；表达，表情","p":"ɪk'spreʃn","e":["Student leaders are demanding greater freedom of expression (= the right to say what you think without being punished ).","学生领袖要求得到更多的言论自由。"]},{"w":"exquisite","t":"adj. 精美的，精致的；敏锐的，有高度鉴赏力的；剧烈的，感觉强烈的","p":"ɪk'skwɪzɪt","e":["the most exquisite craftsmanship","最精美的工艺"]},{"w":"extend","t":"v. 延伸；延期","p":"ɪk'stend","c":1,"e":["Management have agreed to extend the deadline.","管理层已同意延长最后期限。"]},{"w":"extensive","t":"adj. 广阔的；广泛的","p":"ɪk'stensɪv","e":["Fire has caused extensive damage to the island’s forests.","大火严重毁坏了岛上的森林。"]},{"w":"extent","t":"n. 程度","p":"ɪkˈstent","c":1,"e":["Considering the extent of his injuries, he’s lucky to be alive.","就他的伤势来说，他能活下来真是够幸运的。"]},{"w":"external","t":"adj. 外部的，外面的","p":"ɪk'stɜːnl","e":["the external appearance of the building","大楼的外观"]},{"w":"extinct","t":"adj. 灭绝的，绝种的；不再活跃的，熄灭了的，已废弃的","p":"ɪk'stɪŋkt","e":["Dinosaurs have been extinct for millions of years.","恐龙已灭绝数千万年了。"]},{"w":"extinction","t":"n. 灭绝","p":"ɪkˈstɪŋkʃn","c":1,"e":["Conservationists are trying to save the whale from extinction.","生态环境保护工作者正努力挽救鲸类以防止其灭绝。"]},{"w":"extinguish","t":"v. 熄灭；使消亡","p":"ɪkˈstɪŋgwɪʃ","c":1,"e":["Firemen were called to extinguish the blaze.","有人打电话叫消防队员来扑灭大火。"]},{"w":"extra","t":"n. 附加物；额外的东西","p":"'ekstrə","e":["I earn extra for working on Sunday.","我星期天工作挣外快。"]},{"w":"extract","t":"vt. 取出，抽出；采掘，提炼，榨取；获得，索取；摘录['3kstrækt]；n. 摘录，选段；提出物，精，汁","p":"ɪk'strækt","e":["You’ll have to have that tooth extracted.","你得把那颗牙拔掉。"]},{"w":"extraction","t":"n. 抽出；提取法","p":"ɪk'strækʃ(ə)n; ek-","e":["the extraction of information from appropriate reference sources","从合适的参考书中摘录资料"]},{"w":"extracurricular","t":"adj. 课外的","p":"ekstrəkə'rɪkjʊlə","c":1,"e":["Each child had participated in extracurricular activities at school.","每个孩子都参加了学校的课外活动。"]},{"w":"extraordinarily","t":"adv. 非常地，特别地","p":"ɪk'strɔːd(ə)n(ə)rəlɪ","e":["We were extraordinarily lucky.","我们极其幸运。"]},{"w":"extraordinary","t":"adj. 非同寻常的，特别的","p":"ɪk'strɔːdnri","e":["It’s extraordinary that he should make exactly the same mistake again.","真想不到他又犯了完全相同的错误。"]},{"w":"extravagant","t":"adj. 奢侈的；过度的，过分的，放肆的","p":"ɪk'strævəgənt","e":["Would it be too extravagant to buy both?","把两个都买下会不会太奢侈了？"]},{"w":"extreme","t":"adj. 极端的","p":"ɪk'stri:m","c":1,"e":["Force is only justified in extreme circumstances.","只有在极端情况下才可以使用武力。"]},{"w":"eyewitness","t":"n. 目击者","p":"ˈaɪwɪtnəs","c":1,"e":["One eyewitness said he saw her talking to a man in a blue car.","一名目击者说他看见她在跟一个坐在蓝色汽车里的男子说话。"]},{"w":"fabric","t":"n. 布料","p":"ˈfæbrɪk","c":1,"e":["our new range of fabrics and wallpapers","我们新的织物和墙纸系列"]},{"w":"fabricate","t":"vt. 捏造，伪造，编造；建造","p":"'fæbrɪkeɪt","e":["The police were accused of fabricating evidence.","警方被控捏造证据。"]},{"w":"fabrication","t":"n. 捏造；制作","p":"fæbrɪ'keɪʃ(ə)n","e":["Her story was a complete fabrication from start to finish.","她的叙述从头到尾都是编造出来的。"]},{"w":"facet","t":"n. 一个方面；面","p":"'fæsɪt","e":["The issues are complex and multi-faceted.","这些问题很复杂，涉及诸多方面。"]},{"w":"facilitate","t":"v. 使便利；促进","p":"fəˈsɪlɪteɪt","c":1,"e":["The new airport will facilitate the development of tourism.","新机场将促进旅游业的发展。"]},{"w":"facility","t":"n. 设施","p":"fəˈsɪləti","c":1,"e":["What recreational facilities are now available?","什么娱乐设施现在是可用的？"]},{"w":"faction","t":"n. 派别，宗派，小集团","p":"'fækʃ(ə)n","e":["struggles between the different factions within the party","党内的派系斗争"]},{"w":"factor","t":"n. 因素，因子；系数","p":"'fæktə","e":["The rise in crime is mainly due to social and economic factors.","犯罪率上升主要由社会和经济因素造成。"]},{"w":"faculty","t":"n. 〔大学的〕全体教员","p":"'fækltɪ","c":1,"e":["Both faculty and students oppose the measures.","教师和学生都反对这些措施。"]},{"w":"fade","t":"v. 褪色","p":"feɪd","c":1,"e":["The sun had faded the curtains.","太阳把窗帘晒得褪了色。"]},{"w":"fair","t":"adj. 美丽的","p":"feə","e":["a fair maiden","美丽的少女"]},{"w":"faith","t":"n. 信任，信心；信仰，信条","p":"feɪθ","e":["People have lost faith in the government.","人们已失去了对政府的信心。"]},{"w":"fake","t":"n. 假货","p":"feɪk","c":1,"e":["Jones can spot a fake from 20 feet away.","琼斯在20英尺开外就能认出假货。"]},{"w":"fall","t":"v. 变成，成为，陷入","p":"fɔːl","e":["He had fallen asleep on the sofa.","他在沙发上睡着了。"]},{"w":"falsehood","t":"n. 谬误，虚假；谎言，说谎","p":"'fɔːlshud","e":["Saunders is deliberately telling a falsehood.","桑德斯在故意说假话。"]},{"w":"famine","t":"n. 饥荒；严重的缺乏","p":"'fæmɪn","e":["A million people are facing famine .","一百万人正面临饥荒。"]},{"w":"fantastic","t":"adj. 极好的，极出色的；了不起的；极大的；难以相信的；异想天开的，不实际的；奇异的，古怪的","p":"fæn'tæstɪk","e":["It’s a fantastic place, really beautiful!","这真是个好地方，漂亮极了！"]},{"w":"fantasy","t":"n. 想象，幻想；想象的产物","p":"'fæntəsi","e":["Young children sometimes can’t distinguish between fantasy and reality.","小孩子有时不能区分幻想与现实。"]},{"w":"fascinate","t":"v. 使着迷","p":"'fæsɪneɪt","c":1,"e":["Politics fascinated Franklin's father.","政治让富兰克林的父亲着迷。"]},{"w":"fastener","t":"n. 扣件，钮扣，揿钮","p":"'fɑːsənə","e":["shoes with velcro fasteners","带维可牢搭链的鞋"]},{"w":"fatal","t":"adj. 致命的","p":"'feɪtl","c":1,"e":["If it is not treated correctly, the condition can prove fatal (= be fatal ) .","如果治疗不当，这种病可能会致命。"]},{"w":"fatigue","t":"n. 疲惫","p":"fə'ti:ɡ","c":1,"e":["Sam’s face was grey with fatigue.","萨姆累得脸色灰白。"]},{"w":"fault","t":"n. 过失","p":"fɔlt","c":1,"e":["I didn’t sleep well that night, but it was my own fault .","那天晚上我没有睡好，但这是我自己的问题。"]},{"w":"faultless","t":"adj. 无过失的；无缺点的","p":"'fɔːltlɪs; 'fɒlt-","e":["a faultless performance","完美的表现"]},{"w":"favor","t":"v. 恩惠；善意的行为","p":"'feɪvə","c":1,"e":["Could you do me a favour and tell Kelly I can’t make it?","你帮个忙告诉凯莉说我来不了好吗？"]},{"w":"fearless","t":"adj. 无畏的，大胆的","p":"'fɪəlɪs","e":["These dogs are absolutely fearless.","这些狗什么都不怕。"]},{"w":"fearlessly","t":"adv. 无畏地，大胆地","p":"'fɪələslɪ","c":1,"e":["He gazed fearlessly at the gunman.","他毫不畏惧地注视着那枪手。"]},{"w":"feasibility","t":"n. 可行","p":",fizə'bɪləti","c":1,"e":["a feasibility study on the proposed new airport","关于建议中新机场的可行性研究"]},{"w":"feasible","t":"adj. 可行的","p":"'fiːzɪb(ə)l","c":1,"e":["a feasible solution","可行的解决方法"]},{"w":"feast","t":"vi. 尽情地吃，宴饮；参加宴会；n. 盛宴，筵席；节日","p":"fiːst","e":["They feasted well into the afternoon on mutton and corn stew.","他们尽情享用玉米炖羊肉，一直吃到下午。"]},{"w":"feature","t":"n. 特征，特色；面貌；特写，专题节目；故事片；vt. 突出；由…主演","p":"'fiːtʃə","e":["The hour-long programme will be updated each week and feature highlights from recent games.","这个一小时的节目将每周更新，重点介绍近期比赛的精彩部分。"]},{"w":"federal","t":"adj. 联邦的，联盟的","p":"'fedərəl","e":["Switzerland is a federal republic.","瑞士是一个联邦共和国。"]},{"w":"federation","t":"n. 联合会；联邦","p":"ˌfedə'reɪʃn","e":["the National Federation of Women’s Institutes","〔英国及英联邦国家〕妇女协会全国联合会"]},{"w":"feeble","t":"adj. 虚弱的，衰弱的，无力的；无效的，无益的","p":"'fiːbl","e":["His voice sounded feeble and far away.","他的声音听上去既无力又遥远。"]},{"w":"feel","t":"v. 摸起来","p":"fiːl","e":["It’s nice fabric - it feels like velvet.","面料不错——摸上去像丝绒。"]},{"w":"fell","t":"v. 砍倒（树等）；砍伐","p":"fel","e":["More than 100 trees were felled in just over an hour.","短短一个多小时100多棵树就被砍倒了。"]},{"w":"fellowship","t":"n. 伙伴关系，交情，友谊；团体，协会，联谊会；奖学金，研究员职位","p":"'feləuʃɪp","e":["Regular outings contribute to a sense of fellowship among co-workers.","经常外出游玩可以增进同事之间的友谊。"]},{"w":"feminine","t":"adj. 女性的，女子的；女子气的","p":"'femənɪn","e":["Dianne loved pretty feminine things.","黛安娜喜爱漂亮有女人味的东西。"]},{"w":"femininity","t":"n. 女性气质","p":"ˌfemə'nɪnəti","e":["You don’t have to lose your femininity to be an independent, successful woman.","成为独立成功的女性并非就会失去女人味。"]},{"w":"fence","t":"n. 击剑（术），击剑","p":"fens"},{"w":"ferrous","t":"adj. 铁的；亚铁的","p":"'ferəs","e":["ferrous metals","含铁[黑色]金属"]},{"w":"ferry","t":"n. 渡船；vt. 渡运","p":"'feri","e":["They had recrossed the River Gambia by ferry.","他们乘船又一次渡过了冈比亚河。"]},{"w":"fertile","t":"adj. （创造力）丰富的","p":"'fɜːtaɪl","e":["the product of a fertile imagination","想象力丰富的产物"]},{"w":"fertility","t":"n. 多产，肥沃","p":"fəˈtɪləti","c":1,"e":["It symbolizes growth, harmony, freshness, and fertility.","它是生长、和谐、新鲜和丰饶的象征。"]},{"w":"fertilizer","t":"n. 肥料","p":"ˈfɜ:təlaɪzə(r)","c":1,"e":["...farming without any purchased chemical, fertilizer or pesticide.","…不使用任何购买的化学品、肥料或杀虫剂的耕作。"]},{"w":"fiction","t":"n. 小说；虚构，杜撰","p":"'fɪkʃn","e":["historical fiction","历史小说"]},{"w":"fierce","t":"adj. 激烈的","p":"fɪəs","c":1,"e":["fierce fighting in the city","城里的激烈战斗"]},{"w":"fighter","t":"n. 战斗机；斗争者","e":["James is a fighter - he never gives up.","詹姆斯是个顽强拼搏的人——他从不放弃。"]},{"w":"figure","t":"n. 数字","p":"ˈfiɡə","c":1,"e":["It’s about 30,000 in round figures (= to the nearest 10, 20, 100 etc ).","凑个整数大约是三万。"]},{"w":"filament","t":"n. 细丝；长丝；灯丝","p":"'fɪləm(ə)nt","e":["an electric filament","灯丝"]},{"w":"fill","t":"v. 担任（职务）；填补","p":"fɪl","e":["Women fill 35% of senior management positions.","女性担任35%的高级管理职位。"]},{"w":"filter","t":"v. 过滤","p":"ˈfɪltə(r)","c":1,"e":["The ozone layer filters harmful UV rays from the sun.","臭氧层过滤掉有害的太阳紫外线。"]},{"w":"filth","t":"n. 污秽，污物；淫猥；淫猥","p":"fɪlθ","e":["I don’t know how you can watch that filth!","我不知道你怎么会看那种淫秽的东西！"]},{"w":"finance","t":"n. 财政，金融；财源，财务情况；vt. 为…提供资金","p":"'faɪnæns","e":["leasing and other forms of business finance","租赁及其他商业金融形式"]},{"w":"financial","t":"adj. 财政的，金融的","p":"faɪ'nænʃl","e":["It was a wonderful film, but not exactly a financial success (= something that makes a profit ) .","这是一部出色的影片，但在票房上不是很成功。"]},{"w":"finely","t":"adv. 精细地；美好地","p":"'faɪnlɪ","e":["high-quality, finely carved statues","工艺上乘、雕工精美的塑像"]},{"w":"finite","t":"adj. 有限的，有限制的；限定的","p":"'faɪnaɪt","e":["the earth’s finite resources","地球有限的资源"]},{"w":"fireplace","t":"n. 壁炉","p":"'faɪəpleɪs","e":["In the evenings, we gathered around the fireplace and talked in hushed whispers.","晚上，我们聚集在壁炉周围轻声交谈。"]},{"w":"firework","t":"n. 爆竹，花炮，烟火","p":"'faɪəwɜːk","e":["Jeff and David were in the back yard setting off fireworks.","杰夫和戴维在后院放烟花。"]},{"w":"firmness","t":"n. 坚固，坚定，稳固","p":"'fɜ:mnɪs"},{"w":"fiscal","t":"adj. 财政的","p":"'fɪskl","c":1,"e":["a fiscal crisis","财政危机"]},{"w":"fission","t":"n. 裂开；分裂生殖","p":"'fɪʃ(ə)n","e":["The fission of the cell could be inhibited with certain chemicals.","细胞裂殖可以靠某些化学制品加以抑制。"]},{"w":"fitness","t":"n. 适当，恰当；健康","p":"'fɪtnəs","e":["Running marathons requires a high level of physical fitness.","跑马拉松需要身体十分强健。"]},{"w":"fitting","t":"adj. 适合的，恰当的；n. 设备，家具，日用器具；配件，附件，零件；试穿，试衣","p":"'fɪtɪŋ","e":["I thought the memorial was a fitting tribute to the President.","我认为这座纪念碑恰如其分地表达了对总统的敬意。"]},{"w":"fixture","t":"n. 固定装置","p":"'fɪkstʃə","c":1,"e":["light fixtures","照明设备"]},{"w":"flake","t":"n. 片，薄片","p":"fleɪk","e":["chocolate flakes","巧克力薄片"]},{"w":"flame","t":"n. 火焰","p":"fleim","c":1,"e":["They rushed past us with buckets of water and tried to douse the flames .","他们提着一桶桶水跑过我们身边去灭火。"]},{"w":"flank","t":"n. 肋，肋腹，侧边；侧翼；vt. 位于…的侧面","p":"flæŋk","e":["We were attacked on our left flank.","我们的左翼受到攻击。"]},{"w":"flannel","t":"n. 法兰绒","p":"'flæn(ə)l","e":["a flannel shirt","法兰绒衬衫"]},{"w":"flap","t":"vi. 飘动，拍动；振翅；n. 片状垂悬物；飘动，摆动，振动；激动，慌忙状态；vt. 使拍动，使飘动","p":"flæp","e":["The flags were flapping in the breeze.","旗帜在微风中飘扬。"]},{"w":"flare","t":"vi. 闪耀，烧旺；突发，突然发怒；n. 闪光信号，照明弹","p":"fleə","e":["The fire flared up again.","火又忽地旺了起来。"]},{"w":"flask","t":"n. 长颈瓶，酒瓶，烧瓶","p":"flɑːsk","e":["He took out a metal flask from a canvas bag.","他从帆布袋里拿出了一个金属水瓶。"]},{"w":"flat","t":"adj. 平的；n. 公寓","p":"flæt","c":1,"e":["The countryside near there is flat as a pancake (= very flat ) .","那儿附近的乡间地势非常平坦。"]},{"w":"flatten","t":"v. 把…弄平；击倒","p":"'flæt(ə)n","e":["Use a rolling pin to flatten the dough.","用擀面杖把面团擀平。"]},{"w":"flatter","t":"vt. 向…谄媚，奉承；使满意，使感到荣幸；使显得好看，使显得突出","p":"'flætə","e":["Perry would always flatter Mrs. Mitchell by praising her cooking.","佩里常常奉承米切尔太太，称赞她的烹调手艺。"]},{"w":"flavor","t":"n. 口味","p":"'fleɪvə","c":1,"e":["Which flavor do you want - chocolate or vanilla?","你要哪种味道的，巧克力还是香草？"]},{"w":"flavour","t":"v. 给…调味","p":"'fleɪvə","e":["Lime preserved in salt is a North African speciality which is used to flavour chicken dishes.","用盐腌的酸橙是用来给鸡肉调味的一种北非特产。"]},{"w":"flaw","t":"n. 缺点，瑕疵","p":"flɔ:","c":1,"e":["A design flaw (= a mistake or weakness in the way something was made ) caused the engine to explode.","一个设计缺陷导致了引擎爆炸。"]},{"w":"flee","t":"v. 离开","p":"fli:","c":1,"e":["Masaari spent six months in prison before fleeing the country .","正有蹲了六个月监狱，然后逃出了该国。"]},{"w":"flexible","t":"adj. 灵活的","p":"ˈfleksəbl","c":1,"e":["The government needs a more flexible approach to education.","政府在处理教育问题上需要更加灵活。"]},{"w":"flight","t":"n. 溃退，逃跑","p":"flaɪt","e":["Donald Wood’s hasty flight from South Africa early in 1978","1978年初唐纳德•伍德匆忙逃离南非"]},{"w":"fling","t":"vt. 扔，掷；使扑，使投身；n. 尽情欢乐的一阵，一时的放纵","p":"flɪŋ","e":["He flung his coat over the back of a chair.","他把外套扔在椅背上。"]},{"w":"flip","t":"adj. 〈口〉无理的，轻率的，轻浮的；vt. 快速翻动，转动；n. 捻掷，轻抛；轻拍","p":"flɪp","e":["I was fed up with his flip comments.","我听够了他那些轻率的评论。"]},{"w":"float","t":"v. 漂浮","p":"fləʊt","c":1,"e":["I looked up at the clouds floating in the sky.","我仰望着天上的浮云。"]},{"w":"flock","t":"v. 群集，聚集","p":"flɒk","e":["People have been flocking to the exhibition.","看展览的人络绎不绝。"]},{"w":"fluctuate","t":"v. 波动","p":"ˈflʌktʃueɪt","c":1,"e":["Insect populations fluctuate wildly from year to year.","昆虫的数量每年变化很大。"]},{"w":"fluctuation","t":"n. 波动","p":",flʌktʃʊ'eɪʃ(ə)n; -tjʊ-","e":["Prices are subject to fluctuation.","价格可能会有波动。"]},{"w":"fluently","t":"adv. 流利地","p":"'flu:əntlɪ","c":1,"e":["We should train our students to speak English fluently and accurately.","我们应培养学生流利而准确地讲英语。"]},{"w":"fluorescent","t":"adj. 荧光的，发荧光的","p":"ˌflɔː'resnt","e":["a fluorescent pink T-shirt","发亮的粉红色 T 恤衫"]},{"w":"flush","t":"vi. 发红；adj. 齐平的，同高的","p":"flʌʃ","e":["Susan flushed deeply and looked away.","苏珊脸涨得通红，目光转向别处。"]},{"w":"flutter","t":"vi. 振翼，拍翅而飞；飘动，飘扬；快速跳动；n. 紧张，激动不安","p":"'flʌtə","e":["A small bird fluttered past the window.","一只小鸟拍打着翅膀飞过窗前。"]},{"w":"flux","t":"n. 流；涨潮；流量","p":"flʌks"},{"w":"fly","t":"v. 飞跑；逃跑，消失","p":"flaɪ","e":["Ellen flew across the room and greeted her uncle with a kiss.","埃伦从房间那头飞奔过来，给了她叔叔一个吻。"]},{"w":"foam","t":"vi. 起泡沫，吐白沫；n. 泡沫；泡沫材料，泡沫状物","p":"fəum","e":["The green water splashed and foamed over the rocks.","碧绿的水花四溅，岩石上满是泡沫。"]},{"w":"focus","t":"v. 聚焦；集中；n. 焦点，中心","p":"'fəukəs","e":["His eyes were focussed straight ahead.","他的双眼盯着正前方。"]},{"w":"foil","t":"n. 箔，金属薄片；陪衬，衬托；vt. 挫败，使受挫折","p":"fɔɪl","e":["chocolates in foil wrappers","箔纸包的巧克力"]},{"w":"fold","t":"vt. 折叠，合拢；n. 褶，折叠的部分","p":"fəuld","e":["Fold the paper along the dotted line.","沿虚线将纸折起来。"]},{"w":"follow","t":"v. 从事（职业），经营","p":"'fɒləʊ"},{"w":"follower","t":"n. 信徒，追随者","p":"'fɒləʊə","e":["Marx and his followers were convinced that capitalism would destroy itself.","马克思及其支持者确信资本主义将自我毁灭。"]},{"w":"footnote","t":"n. 注脚","p":"'fʊtnəʊt","c":1,"e":["There was an interesting footnote to the story.","那则故事有个有趣的注脚。"]},{"w":"footpath","t":"n. 小路，人行道","p":"'fʊtpɑːθ","e":["He said he had just picked up the druken man from the footpath and did not know him from Adam.","他说他只是把这个倒在人行道上的醉汉扶了起来，他根本不认识他。"]},{"w":"force","t":"vt. 强迫；用力推动，用力打开；n. 军队，兵力；暴力，武力；力，力气；影响力，效力","p":"fɔːs","e":["She tried to keep the door shut but the man forced it open .","她不想打开门，但那男人硬是把它推开了。"]},{"w":"fore","t":"adv. 在（或向）船头；在（或向）飞行器头部","p":"fɔː","e":["Our yacht was well equipped with two double cabins fore and aft.","我们的游艇设施完备，首尾有两个双人舱。"]},{"w":"forecast","t":"n. 预报，预测","p":"'fɔ:kɑ:st","c":1,"e":["The weather forecast is good for tomorrow.","天气预报说明天是晴天。"]},{"w":"foreign","t":"adj. 外国的，国外的","p":"'fɒrɪn","e":["Can you speak any foreign languages?","你会讲外语吗？"]},{"w":"foremost","t":"adj. 最好的，最著名的，最重要的","p":"'fɔːməust","e":["Rostropovich was long considered the world’s foremost cellist.","长期以来，罗斯特罗波维奇一直被视为世界上首屈一指的大提琴家。"]},{"w":"foresee","t":"vt. 预见，预知","p":"fɔː'siː","e":["I’ve put your name on the list and I don’t foresee any problems.","我把你的名字写在名单上了，估计不会有什么问题。"]},{"w":"forge","t":"v. 伪造；锻造","p":"fɔːdʒ","c":1,"e":["Someone stole my credit card and forged my signature.","有人偷了我的信用卡，并假冒我的签名。"]},{"w":"formal","t":"adj. 正式的；礼仪上的","p":"'fɔːml","e":["There is no formal structure for negotiating pay increases.","加薪谈判没有正式的框架可循。"]},{"w":"format","t":"n. 形式","p":"'fɔ:mæt","c":1,"e":["The courses were run to a consistent format.","这些课程的编排是有连续性的。"]},{"w":"formerly","t":"adv. 以前，从前","p":"'fɔːməlɪ","e":["Kiribati, formerly known as the Gilbert Islands","基里巴斯，旧称吉尔伯特群岛"]},{"w":"formidable","t":"adj. 可怕的；令人敬畏的，令人惊叹的","p":"ˈfɔ:mɪdəbl","c":1,"e":["The new range of computers have formidable processing power.","该系列的新型计算机处理能力惊人。"]},{"w":"formula","t":"n. 公式","p":"'fɔːmjʊlə","c":1,"e":["Sugar is represented by the simple formula CHO.","糖以简单的分子式CHO表示。"]},{"w":"formulate","t":"v. 制定，规划","p":"'fɔːmjʊleɪt","c":1,"e":["He formulated Labour Party education policy in 1922.","1922年，他制定了工党教育政策。"]},{"w":"formulation","t":"n. 表述方式","p":"fɔːmjʊ'leɪʃn","e":["This is a far weaker formulation than is in the draft resolution which is being proposed.","这是相对于正在被提议的草拟决议要弱得多的一种表述方式。"]},{"w":"forsake","t":"v. 遗弃，抛弃；摒绝，摒弃","p":"fə'seɪk","e":["She will never forsake her vegetarian principles.","她绝不会放弃自己的素食主义原则。"]},{"w":"fort","t":"n. 堡垒，城堡","p":"fɔːt"},{"w":"forthcoming","t":"adj. 即将来临的","p":"ˌfɔ:θˈkʌmɪŋ","c":1,"e":["Keep an eye on the noticeboards for forthcoming events .","请注意布告牌上的活动预告。"]},{"w":"fortress","t":"n. 堡垒，要塞","p":"'fɔːtrɪs","e":["a 13th-century fortress","一座13世纪的城堡"]},{"w":"forum","t":"n. 论坛，讨论会；专题讨论节目","p":"'fɔːrəm","e":["Members of the council agreed that was an important forum for discussion.","理事会成员们一致认为那是一个用于讨论的重要论坛。"]},{"w":"forward","t":"adv. 向前；向将来；v. 转递","p":"'fɔːwəd","e":["Would you make sure that you forward my mail promptly?","请您一定及时转寄我的信，好吗？"]},{"w":"fossil","t":"n. 化石；食古不化的人，老顽固","p":"'fɒsl","e":["Marine sponges have a long fossil record (= their development has been recorded over a long period ) .","海绵动物留下了漫长的化石记录。"]},{"w":"foster","t":"v. 促进；培养","p":"'fɒstə(r)","c":1,"e":["The bishop helped foster the sense of a community embracing all classes.","主教鼓励一种包容各个阶层的社区精神。"]},{"w":"foul","t":"adj. 难闻的，发臭的；令人不愉快的，糟透了的；污浊的，肮脏的；下流的，辱骂性的；恶劣的，有暴风雨的；邪恶的，罪恶的；vt. 对…犯规；弄脏，弄污；n. 犯规","p":"faul","e":["He put down his mug of foul-tasting coffee.","他放下手中一大杯难喝的咖啡。"]},{"w":"foundation","t":"n. 基金会","p":"faʊn'deɪʃ(ə)n","c":1,"e":["the British Heart Foundation","英国心脏病基金会"]},{"w":"fowl","t":"n. 家禽；禽肉","p":"faʊl","e":["Carve the fowl into 8 pieces.","将这只家禽切成8块。"]},{"w":"fraction","t":"n. 小部分，片断；【数】 分数","p":"'frækʃn","e":["The students had a grasp of decimals, percentages and fractions.","学生们掌握了小数、百分数和分数。"]},{"w":"fracture","t":"v. 断裂，折断；n. 裂缝，裂痕；折断","p":"'fræktʃə","e":["The immense pressure causes the rock to fracture.","巨大的压力造成岩石断裂。"]},{"w":"fragile","t":"adj. 易碎的，脆的，易损坏的；虚弱的，脆弱的","p":"'frædʒaɪl","e":["Be careful with that vase – it’s very fragile.","小心那只花瓶——很容易打碎的。"]},{"w":"fragrance","t":"n. 芳香，香味；香水","p":"'freɪgrəns","e":["...a shrubby plant with a strong characteristic fragrance.","…一种有独特浓郁香味的灌木。"]},{"w":"fragrant","t":"adj. 香的，芬芳的","p":"'freɪgr(ə)nt","e":["fragrant flowers","芳香的花朵"]},{"w":"frail","t":"adj. 脆弱的","p":"freɪl","e":["Human nature is frail.","人性脆弱。"]},{"w":"frame","t":"v. 制定，拟定〔计划、体制等〕","p":"frem","c":1,"e":["Newman played a central role in framing the new law.","纽曼在拟定新法的过程中发挥了主要作用。"]},{"w":"framework","t":"n. 体制","p":"'freɪmwɜːk","e":["We need to establish a legal framework for the protection of the environment.","我们需要建立一个法律体制来保护环境。"]},{"w":"frankly","t":"adv. 坦率地","p":"ˈfræŋkli","c":1,"e":["Frankly, I think the Internet is overrated.","坦率地说，我认为因特网被高估了。"]},{"w":"frantic","t":"adj. 疯狂的","p":"'fræntɪk","c":1,"e":["A bird had been locked in and was by now quite frantic.","一只鸟被关了起来，到现在它都非常狂躁。"]},{"w":"fraud","t":"n. 欺诈，诈骗；骗子","p":"frɔːd","e":["{\"COLLOINEXA\":[\"electoral fraud\"]}","选举欺诈"]},{"w":"freight","t":"n. 货运；运费","p":"freɪt","e":["We’ll send your personal belongings by air freight and your furniture by sea freight.","你的个人物品我们将以空运方式运送，家具将以海运方式运送。"]},{"w":"frequency","t":"n. 屡次，次数，频率；经常发生","p":"'friːkwənsi","e":["Side effects from prescribed drugs are being reported with increasing frequency (= more and more often ) .","处方药的副作用正越来越频繁地被报道出来。"]},{"w":"frequent","t":"adj. 时常发生的，常见的","p":"'friːkwənt","e":["Trains rushed past at frequent intervals .","火车频频驶过。"]},{"w":"fresh","t":"adj. 新颖的，新奇的","p":"freʃ","c":1,"e":["Ryan will bring a fresh approach to the job.","瑞安将带来一种新的工作方法。"]},{"w":"freshen","t":"v. 使显得新鲜","p":"'freʃ(ə)n","e":["Using a mouthwash freshens the breath.","使用漱口液可以使口气清新。"]},{"w":"fret","t":"v. （使）烦恼","p":"fret","e":["men of fifty, fretting that they’re no longer young","因不再年轻而烦恼的50岁男人"]},{"w":"friction","t":"n. 不和，抵触；摩擦","p":"'frɪkʃn","e":["Putting oil on both surfaces reduces friction.","两面都上油可减小摩擦力。"]},{"w":"fright","t":"n. 惊吓，恐怖","p":"fraɪt","e":["You gave me such a fright creeping up on me like that!","你这样不声不响地过来，吓了我一跳！"]},{"w":"frighten","t":"v. 使害怕","p":"'fraɪtn","c":1,"e":["Don’t stand so near the edge! You’re frightening me.","别站得那么靠边！你要把我吓坏了。"]},{"w":"frightful","t":"adj. 可怕的；讨厌的","p":"'fraɪtfʊl; -f(ə)l","e":["There’s been a frightful accident.","发生了一起可怕的意外。"]},{"w":"fringe","t":"adj. 附加的；n. 刘海；饰以流苏的边；边缘，外围；vt. 成为…的边缘","p":"frɪndʒ","e":["Remember to use not only the hourly wage, but also include fringe benefits.","切记不要仅仅使用小时工资，还要包括附加福利。"]},{"w":"fro","t":"adv. 往，去，回，向后","p":"frəʊ","e":["She rocked the baby to and fro.","她来回摇动着婴儿。"]},{"w":"frock","t":"n. （女）连衣裙","p":"frɒk","e":["a party frock","宴会礼裙"]},{"w":"frontier","t":"n. 边境","p":"'frʌntɪə(r)","c":1,"e":["Lille is close to the frontier between France and Belgium.","里尔靠近法比边境。"]},{"w":"frustrate","t":"v. 使挫败，使沮丧","p":"frʌ'streɪt","c":1,"e":["The fact that he’s working with amateurs really frustrates him.","与生手共事着实让他沮丧。"]},{"w":"frustration","t":"n. 挫败，挫折，受挫","p":"frʌ'streɪʃn","e":["People often feel a sense of frustration that they are not being promoted quickly enough.","人们经常有一种挫折感，就是觉得自己升职不够快。"]},{"w":"fuel","t":"n. 燃料，燃料剂；vt. 给…加燃料；刺激","p":"fjuːəl","e":["Coal is one of the cheapest fuels.","煤是最廉价的燃料之一。"]},{"w":"fulfill","t":"v. 实现","p":"fʊl'fɪl","c":1,"e":["Being deaf hasn’t stopped Karen fulfilling her ambition to be a hairdresser.","失聪并没有阻止卡伦实现当美发师的抱负。"]},{"w":"function","t":"vi. 工作，运行；起作用；n. 功能，职务；【数】函数；重大聚会","p":"'fʌŋkʃn","e":["You know I can’t function (= cannot perform normal activities ) without a coffee in the morning.","你知道的，我早上不喝杯咖啡就无法工作。"]},{"w":"fund","t":"n. 资金，基金；存款；vt. 为…提供资金","p":"fʌnd","e":["The fund was set up to try to save the cathedral.","设立基金以挽救大教堂。"]},{"w":"fundamental","t":"adj. 基础的，基本的；n. 基本原则","p":"ˌfʌndə'mentl","e":["We have to tackle the fundamental cause of the problem.","我们必须解决问题的根本原因。"]},{"w":"furious","t":"adj. 生气的；激烈的","p":"ˈfjʊəriəs","c":1,"e":["There was a furious row over the proposals.","关于这些提议的争论非常激烈。"]},{"w":"furnish","t":"v. 提供","p":"ˈfɜ:nɪʃ","c":1,"e":["Will these finds furnish more information on prehistoric man?","这些发现是否能提供更多有关史前人类的资料？"]},{"w":"furniture","t":"n. 家具","p":"'fɜːnɪtʃə","e":["I can’t think of a single piece of furniture in my house that I bought new.","我想不出家里有哪件家具是新买的。"]},{"w":"further","t":"v. 增进","p":"'fɜːðə","e":["He dedicated his life to furthering the cause of world peace.","他一生致力于推动世界和平事业。"]},{"w":"furthermore","t":"adv. 而且，此外","p":"ˌfɜːðə'mɔː","e":["He is old and unpopular. Furthermore, he has at best only two years of political life ahead of him.","他年纪已老，又不得人心，而且他最多也只有两年的政治生命了。"]},{"w":"fury","t":"n. 狂怒，暴怒；狂暴，狂烈","p":"'fjuəri","e":["The report was leaked to the press, much to the president’s fury.","报告被泄露给了媒体，令总统大为光火。"]},{"w":"fuse","t":"v. 熔合，合并；因保险丝熔断而中断工作；n. 保险丝，熔丝；导火线","p":"fjuːz","e":["Their music fuses elements as diverse as Cajun, bebop and Cuban waltzes.","他们的音乐融合了卡津音乐、博普爵士乐和古巴华尔兹等不同元素。"]},{"w":"fusion","t":"n. 联合，合并；核聚变","p":"'fjuːʒn","e":["Her work is a fusion of several different styles.","她的作品是几种不同风格的融合。"]},{"w":"fuss","t":"n. 小题大做","p":"fʌs","c":1,"e":["The Steamatic enables you to clean any carpet with the minimum of fuss .","蒸汽清洁器可以让你轻轻松松地清洁地毯。"]},{"w":"galaxy","t":"n. 星系；银河系，银河；一群","p":"'gæləksi","e":["Astronomers have discovered a distant galaxy.","天文学家们发现了一个遥远的星系。"]},{"w":"gallery","t":"n. 美术馆","p":"'ɡælərɪ","c":1,"e":["an exhibition of African art at the Hayward Gallery","海沃德美术馆的非洲艺术展览"]},{"w":"gamble","t":"vi. 赌博，打赌；投机，冒险；vt. 赌，以…为赌注；n. 赌博；投机，冒险","p":"'gæmbl","e":["Yesterday, he named his cabinet and took a big gamble in the process.","昨天他冒了很大的风险任命了他的内阁。"]},{"w":"gangster","t":"n. 匪徒，歹徒，暴徒","p":"'gæŋstə","e":["...a gangster film.","…一部黑帮片。"]},{"w":"gap","t":"n. 差距","p":"ɡæp","c":1,"e":["...the gap between rich and poor.","…贫富差距。"]},{"w":"garage","t":"n. 车库","p":"'ɡærɑ:ʒ","c":1,"e":["I’ll just go and put the car in the garage.","我把车停到车库去。"]},{"w":"garbage","t":"n. 垃圾，废物；废话；无用的资料","p":"'gɑːbɪdʒ","e":["Can you take out the garbage when you go?","你走的时候把垃圾带出去好吗？"]},{"w":"garlic","t":"n. 蒜，大蒜","p":"'gɑːlɪk","e":["Add a crushed clove of garlic (= single section of it ).","加一瓣压碎的大蒜。"]},{"w":"garment","t":"n. 衣服","p":"'gɑːmənt","e":["She pulled the garment on and zipped it up.","她穿上衣服并拉好拉链。"]},{"w":"gasp","t":"vi. 喘气，倒抽气；vt. 喘着气说出；n. 喘气，倒抽气","p":"gɑːsp","e":["‘My leg!’ he gasped. ‘I think it’s broken!’","“我的腿！”他倒抽一口气喊道，“我觉得腿断了！”"]},{"w":"gather","t":"v. 推测，推断","p":"'gæðə","e":["You two know each other, I gather.","我想你们俩认识。"]},{"w":"gathering","t":"n. 集会，聚会，聚集","p":"'gæð(ə)rɪŋ","e":["a select gathering of 20 or 30 people","二三十名特邀人士的聚会"]},{"w":"gauge","t":"n. 测量仪表；厚度，直径；规格、尺寸；vt. 估计，判断；计量，度量","p":"geɪdʒ","e":["a 12-gauge shotgun","12号口径的猎枪"]},{"w":"gaze","t":"n&vi. 凝视，盯，注视","p":"geɪz","e":["Patrick sat gazing into space  (= looking straight in front, not at any particular person or thing ).","帕特里克坐着，茫然地看着前方。"]},{"w":"gear","t":"n. 齿轮，传动装置，挡；用具，设备，衣服；vt. 使适应，使适合","p":"gɪə","e":["Colleges are not always geared to the needs of mature students.","大学并不总是去适应成年学生的需要。"]},{"w":"gender","t":"n. 性别","p":"'dʒendə(r)","c":1,"e":["There may be gender differences in attitudes to paid work.","对待有偿劳动的态度可能存在着性别差异。"]},{"w":"generalization","t":"n. 一般化；概括，综合","p":",dʒenrələ'zeɪʃən","e":["You can’t make generalizations about what men and women are like.","男人什么样，女人什么样，不能一概而论。"]},{"w":"generalize","t":"vt. 概括，归纳，推断；普及","p":"'dʒenrəlaɪz","e":["Critics love to generalize, to formulate trends into which all new work must be fitted, however contradictory.","评论家喜欢概括，归纳出所有新作品都必须符合的趋势，不管它们是如何地不符。"]},{"w":"generate","t":"v. 产生","p":"'dʒenəreɪt","c":1,"e":["The program would generate a lot of new jobs.","这个项目将创造许多新的就业岗位。"]},{"w":"generosity","t":"n. 慷慨，宽宏大量","p":"dʒenə'rɒsətɪ","e":["I shall never forget the generosity shownby the people of Bastaisk.","我永远也不会忘记巴斯泰斯克人的慷慨大方。"]},{"w":"generous","t":"adj. 慷慨的","p":"ˈdʒenərəs","c":1,"e":["Dietler is generous with his time and money.","迪特勒在他的时间和金钱方面慷慨大方。"]},{"w":"genetic","t":"adj. 基因的","p":"dʒəˈnetɪk","c":1,"e":["each person’s genetic make-up","每个人的遗传特征"]},{"w":"genius","t":"n. 天才","p":"'dʒi:nɪəs","c":1,"e":["The film reveals Fellini’s genius.","这部影片展现了费里尼的天赋。"]},{"w":"genuine","t":"adj. 真的；由衷的","p":"ˈdʒenjuɪn","c":1,"e":["‘Did he really?’ Her surprise seemed genuine.","“他真的这样？”她好像是真的惊讶。"]},{"w":"geographical","t":"adj. 地理的；地区（性）的","p":"dʒɪə'græfɪk(ə)l","e":["their geographical proximity to Japan (= nearness to Japan )","它们和日本相邻的地理位置"]},{"w":"geology","t":"n. 地质学","p":"dʒɪ'ɒlədʒɪ","c":1,"e":["He was visiting professor of geology at the University of Georgia.","他曾是佐治亚大学的地质学客座教授。"]},{"w":"geometrical","t":"adj. 几何学的","p":"dʒɪə'metrɪkl","e":["geometrical progression","几何级数"]},{"w":"germ","t":"n. 细菌，病原菌；幼芽","p":"dʒɜːm","e":["Put disinfectant down the toilet to kill any germs.","在抽水马桶里投放消毒剂杀菌。"]},{"w":"gesture","t":"n. 姿势，手势","p":"'dʒestʃə(r)","c":1,"e":["Luke made an obscene gesture with his finger.","卢克用手指做了一个下流的手势。"]},{"w":"gigantic","t":"adj. 巨大的，庞大的","p":"dʒaɪ'gæntɪk","e":["a gigantic skyscraper","摩天大楼"]},{"w":"giggle","t":"n. 咯咯笑，傻笑","p":"'gɪgl","e":["Margaret was seized by a fit of the giggles (= she could not stop giggling ) .","玛格丽特忍不住咯咯笑了起来。"]},{"w":"ginger","t":"n. 姜，生姜","p":"'dʒɪndʒə","e":["a teaspoon of ground ginger","一茶匙姜粉"]},{"w":"given","t":"adj. 规定的，特定的；假设的，已知的；有癖好的，有倾向的；prep. 考虑到","p":"'gɪvn","e":["On any given day in the Houston area, half the hospital beds are empty.","在休斯敦地区，任何一天医院的床位都有一半是空的。"]},{"w":"glamor","t":"n. 魅力，诱惑力","p":"'glæmə","e":["This is the power of glamor of debate!","这就是辩论的力量和魅力！"]},{"w":"glamorous","t":"adj. 有魅力的，迷人的","p":"ˈglæmərəs","c":1,"e":["the most glamorous neighborhood in the city","城里最繁华的街区"]},{"w":"glance","t":"vi. 看一下；n. 一瞥","p":"glɑːns","e":["Wyatt glanced around the restaurant.","怀亚特环视了一下餐馆。"]},{"w":"gland","t":"n. 腺","p":"glænd","e":["the pituitary gland","脑垂体腺"]},{"w":"glare","t":"vi. 怒目而视；发射强光，发出刺眼的光线；n. 强光；怒视，瞪眼；炫耀，张扬","p":"gleə","e":["The sun glared down on us.","刺眼的阳光照在我们身上。"]},{"w":"gleam","t":"n&vi. 闪亮，闪烁；闪现，流露","p":"gliːm","e":["His black hair gleamed in the sun.","他的黑头发在阳光下闪闪发光。"]},{"w":"glide","t":"n. 滑行，滑动；滑翔","p":"glaɪd"},{"w":"glider","t":"n. 滑翔机；滑翔导弹","p":"'glaɪdə"},{"w":"glitter","t":"vi. 闪闪发光，闪耀；n. 闪光，灿烂的光辉；耀眼，辉煌","p":"'glɪtə","e":["The river glittered in the sunlight.","阳光下河面波光粼粼。"]},{"w":"global","t":"adj. 全球的","p":"'gləʊb(ə)l","e":["global climate change","全球气候变化"]},{"w":"gloom","t":"n. 昏暗，阴暗；忧郁，沮丧","p":"gluːm","e":["He peered into the gathering (= increasing ) gloom.","他在渐深的暮色中眺望远方。"]},{"w":"gloomy","t":"adj. 忧郁的，沮丧的；令人沮丧的；昏暗的，阴沉的","p":"'gluːmi","e":["The report paints a gloomy picture of the economy.","这篇报告描绘了一幅惨淡的经济现状。"]},{"w":"glorify","t":"v. 赞美；颂扬（上帝）","p":"'glɔːrɪfaɪ","e":["This magazine in no way glorifies gangs.","本杂志决不美化各种犯罪团伙。"]},{"w":"glory","t":"n. 光荣，荣誉","p":"'ɡlɔ:rɪ","c":1,"e":["He began the season in a blaze of glory , scoring seven goals in as many games.","这个赛季一开始他便光芒四射，七场比赛进了七个球。"]},{"w":"glossary","t":"n. 词汇表；术语汇编","p":"'glɒs(ə)rɪ","e":["A glossary of terms is included for the reader's convenience.","为了方便读者，还收录了术语汇编。"]},{"w":"glow","t":"vi. 发光；燃烧；n. 白热光；脸红；激情","p":"gləu","e":["The fireplace was still glowing with the remains of last night’s fire.","壁炉中，隔夜的余烬依然在微微发光。"]},{"w":"glue","t":"v. 粘牢","p":"gluː","e":["Glue the fabric around the window.","用胶把这布粘在窗户四周。"]},{"w":"gnaw","t":"v. 啃，咬断，啮","p":"nɔː","e":["Dexter gnawed his pen thoughtfully.","德克斯特若有所思地咬着钢笔。"]},{"w":"goddess","t":"n. 女神","p":"ˈgɒdɪs","e":["Aphrodite, goddess of love","爱神阿佛洛狄忒"]},{"w":"goodness","t":"n. 善良，善行，美德","p":"'gʊdnɪs","e":["the desire to see goodness and justice in the world","对善良和正义的向往"]},{"w":"gorgeous","t":"adj. 华丽的，灿烂的，绚丽的；令人十分愉快的，极好的","p":"'gɔːdʒəs","e":["The hotel room had a gorgeous view.","那间客房窗外景色迷人。"]},{"w":"gorilla","t":"n. 大猩猩","p":"gə'rɪlə"},{"w":"gossip","t":"vi. 传播流言蜚语；n. 流言蜚语；爱说长道短的人","p":"'gɒsɪp","e":["You must avoid gossip and focus on what you have to do.","务必避免流言蜚语，关注你必须做的事务。"]},{"w":"govern","t":"v. 管理","p":"'ɡʌvn","c":1,"e":["The party had been governing for seven months.","该党执政已经有七个月了。"]},{"w":"gown","t":"n. 长袍","p":"gaʊn","c":1,"e":["...an old headmaster in a flowing black gown.","…一位身着飘垂黑色礼袍的老校长。"]},{"w":"grab","t":"v. 攫取，抓取","p":"græb","e":["Kay grabbed hold of my arm to stop herself falling.","凯抓住我的手臂，以免自己摔倒。"]},{"w":"gracious","t":"adj. 亲切的，和蔼的；优美的；雅致的，雍容华贵的；int. 天哪!","p":"'greɪʃəs","e":["Sibyl was the most gracious, helpful, and generous person to work with.","西比尔非常和蔼，乐于助人，而且为人慷慨，和她共事最愉快。"]},{"w":"gradient","t":"n. 斜坡","p":"'greɪdɪənt","e":["a steep gradient","陡坡"]},{"w":"graduate","t":"adj. 研究生的；v. 毕业；n. 毕业生；研究生","p":"ˈɡradʒʊeɪt","e":["a graduate student","研究生"]},{"w":"grain","t":"n. 谷物，谷粒，颗粒；少量，微量","p":"greɪn","e":["There were crumbs and grains of sugar on the table.","桌子上有面包屑和糖粒。"]},{"w":"gramophone","t":"n. 留声机","p":"'græməfəʊn","e":["...a wind-up gramophone with a big horn.","...一台带大喇叭的发条式留声机。"]},{"w":"grand","t":"adj. 壮丽的，极好的","p":"ɡrænd","c":1,"e":["New Yorkers build on a grand scale.","纽约人喜欢建高楼大厦。"]},{"w":"granite","t":"adj. 花岗岩，花岗石","p":"'grænɪt"},{"w":"grant","t":"n. 授给物；vt. 授予，给予","p":"grɑːnt","e":["I would love to be able to grant her wish.","我很希望能够满足她的愿望。"]},{"w":"graphic","t":"adj. 生动的，形象的；绘画的，文字的，图表的","p":"'græfɪk","e":["...fine and graphic arts.","…美术与制图艺术。"]},{"w":"graphite","t":"n. 石墨，石墨电极","p":"'græfaɪt"},{"w":"grasp","t":"v. 理解；抓住","p":"ɡrɑ:sp","c":1,"e":["At that time, we did not fully grasp the significance of what had happened.","当时，我们没有完全明白所发生之事的重要性。"]},{"w":"grasshopper","t":"n. 蚱蜢，蝗虫，蚂蚱","p":"'grɑːshɒpə","e":["One day a grasshopper came upon an ant at work in a garden.","一天， 蚱蜢碰到了一只正在花园里干活的蚂蚁。"]},{"w":"grassy","t":"adj. 草多的","p":"'grɑːsɪ","e":["a grassy bank","长满青草的河岸"]},{"w":"grateful","t":"adj. 感激的","p":"ˈgreɪtfl","c":1,"e":["Our grateful thanks go to all who participated.","我们衷心感谢所有参与者。"]},{"w":"gratitude","t":"n. 感激","p":"ˈgrætɪtju:d","c":1,"e":["Tears of gratitude filled her eyes.","她眼里充满感激的泪水。"]},{"w":"grave","t":"adj. 严重的","p":"ɡreɪv","c":1,"e":["The report expressed grave concern over the technicians’ lack of training.","报告中对技术人员缺乏培训深表忧虑。"]},{"w":"gravel","t":"n. 砂跞；砂砾层；结石","p":"'græv(ə)l","e":["a gravel path","石子小道"]},{"w":"graze","t":"vi. 吃青草；vt. 放牧；擦伤；擦过，掠过；n. 擦破","p":"greɪz","e":["fields where they used to graze their sheep","他们过去放羊的田野"]},{"w":"grease","t":"n. 油脂；润滑脂，润滑油；vt. 用油脂涂，给…加润滑油","p":"griːs","e":["...grease-stained hands.","…沾满了油渍的手。"]},{"w":"greed","t":"n. 贪心，贪婪","p":"griːd","e":["people motivated by jealousy and greed","受妒忌和贪婪驱使的人们"]},{"w":"greedy","t":"adj. 贪婪的","p":"ˈɡriːdi","c":1,"e":["Have you eaten them all, you greedy pig?","你把那些全吃了？你这贪吃的猪！"]},{"w":"grief","t":"n. 悲伤，悲痛；悲伤的事，悲痛的缘由","p":"griːf","e":["Every change in our lives brings with it griefs.","我们生活当中的每一个变化都有让人伤心的一面。"]},{"w":"grieve","t":"vi. 感到悲痛，伤心；vt. 使伤心，为…而伤心","p":"griːv","e":["People need time to grieve after the death of a loved one.","人们在所爱之人去世后会有一段悲伤期。"]},{"w":"grim","t":"adj. 讨厌的，糟糕的；严厉的；冷酷的，无情的","p":"grɪm","e":["The child hung on to her arm with grim determination .","那孩子死死抓住她的胳膊。"]},{"w":"grin","t":"n. 咧嘴笑","p":"grɪn","e":["He came into the room with a friendly grin on his face .","他走进房间，脸上带着亲切的微笑。"]},{"w":"grind","t":"v. 磨碎，碾碎，把...磨成粉","p":"graɪnd","e":["Store the peppercorns in an airtight container and grind the pepper as you need it.","将胡椒子储藏在密封容器里，当你需要的时候把它磨成粉。"]},{"w":"grip","t":"n. 抓住","p":"ɡrɪp","c":1,"e":["Hold the microphone in a firm grip and keep it still.","紧紧握住麦克风不要让它动。"]},{"w":"groan","t":"vi. 呻吟，抱怨；发出呻吟般的声音；n. 呻吟，抱怨；呻吟般的声音","p":"grəun","e":["Richard’s jokes make you groan rather than laugh.","理查德的笑话让你哭笑不得。"]},{"w":"grocery","t":"n. 杂货店","p":"'ɡrəʊsərɪ","c":1,"e":["They run a small grocery store.","他们经营一家小食品杂货店。"]},{"w":"groove","t":"n. 沟，槽","p":"gruːv","e":["The bolt slid easily into the groove.","插销顺畅地滑入凹槽。"]},{"w":"grope","t":"vi. 暗中摸索，搜索；探索，搜寻；vt. 摸索","p":"grəup","e":["With his left hand he groped for the knob, turned it, and pulled the door open.","他用左手摸索到门把手，转动把手，把门拉开。"]},{"w":"gross","t":"adj. 总的；严重的；粗俗的；臃肿的","p":"grəus","e":["The company was guilty of gross negligence.","该公司犯了重大的失职罪。"]},{"w":"groundless","t":"adj. 无理由的，无根据的","p":"'graʊn(d)lɪs","c":1,"e":["Mr Kay’s lawyer said the accusations were groundless.","凯先生的律师说这是无端的指控。"]},{"w":"grove","t":"n. 林子，小树林，园林","p":"grəʊv","e":["...an olive grove.","…一片橄榄树丛。"]},{"w":"growl","t":"v. （狗等）嗥叫；咆哮","p":"graʊl","e":["‘Get out of my way,’ he growled.","“滚开。”他低声咆哮道。"]},{"w":"grumble","t":"v. 抱怨，发牢骚","p":"'grʌmb(ə)l","e":["‘This is boring,’ Kathleen grumbled.","“这真无聊。”凯瑟琳抱怨道。"]},{"w":"grunt","t":"v. 作呼噜声；咕哝","p":"grʌnt","e":["Grunting with effort, she lifted me up.","她哼哧着费力地把我抱起来。"]},{"w":"guarantee","t":"v. 保证","p":"ˌɡærən'ti:","c":1,"e":["The law guarantees equal rights for men and women.","法律保障男女平等。"]},{"w":"guard","t":"v. 保护","p":"ɡɑ:d","c":1,"e":["The Sergeant told Swift to guard the entrance.","中士叫斯威夫特守着入口。"]},{"w":"guardian","t":"n. 监护人；守卫者，保护者","p":"'gɑːdiən","e":["Destiny's legal guardian was her grandmother.","德斯蒂妮的法定监护人是她的祖母。"]},{"w":"guesstimate","t":"n. 大概估计，瞎猜估计","p":"ˈgestɪmət","c":1,"e":["Could you give us a guesstimate of the numbers involved?","你能给我们大致估计一下相关数字吗？"]},{"w":"guilt","t":"n. 内疚；有罪，犯罪","p":"gɪlt","e":["He felt an enormous sense of guilt when he thought about how he’d treated her.","他想到自己那样对待她，心里非常歉疚。"]},{"w":"guitar","t":"n. 吉他，六弦琴","e":["an acoustic/an electric/a classical, etc. guitar","原声吉他、电吉他、古典吉他等"]},{"w":"gust","t":"n. 阵风，一阵狂风","p":"gʌst","e":["A gust of wind drove down the valley.","一阵狂风掠过山谷。"]},{"w":"gutter","t":"n. 沟，边沟；檐槽","p":"'gʌtə","e":["The gutters were blocked and overflowing.","排水沟堵住了，水都溢出来了。"]},{"w":"habitual","t":"adj. 习惯的","p":"həˈbɪtʃuəl","c":1,"e":["James took his habitual morning walk around the garden.","詹姆斯又像往常习惯的那样绕花园作晨间散步去了。"]},{"w":"hack","t":"v. 黑客攻击","p":"hæk","c":1,"e":["He managed to hack the code.","他设法窃取了密码。"]},{"w":"hail","t":"v. 向…欢呼，招呼","p":"heɪl","e":["She leaned out of the window and hailed a passerby.","她探出窗户向一个路人大喊。"]},{"w":"halve","t":"v. 对分；平摊","p":"hɑːv","e":["Halve the potatoes lengthwise.","把马铃薯竖着切成两半。"]},{"w":"ham","t":"n. 火腿","p":"hæm","e":["a seven-pound ham","七磅重的火腿"]},{"w":"hamper","t":"vt. 妨碍，束缚，限制；n. 大篮子","p":"'hæmpə","e":["An attempt to rescue the men has been hampered by bad weather.","对那几名男子的营救行动受到恶劣天气的阻碍。"]},{"w":"handbook","t":"n. 手册，便览","p":"'hændbuk","e":["the Fiction Writer’s Handbook","《小说写作手册》"]},{"w":"handgun","t":"n. 手枪","p":"ˈhændgʌn","c":1,"e":["They were yesterday convicted of illegally using a handgun.","他们昨天被判犯有非法使用手枪罪。"]},{"w":"handicap","t":"n. 缺陷；障碍，不利条件；vt. 妨碍，使不利","p":"'hændikæp","e":["Not speaking the language is a real handicap.","不会讲这种语言的确是一个障碍。"]},{"w":"handle","t":"n. 把手","p":"'hændl","c":1,"e":["Then he turned the handle and went in.","然后他转动把手走了进去。"]},{"w":"handout","t":"n. 施舍物，救济品","p":"'hændaʊt","e":["people who have to live on handouts from the state","必须依赖国家发放的救济金生活的人们"]},{"w":"handy","t":"adj. 方便的；便于使用的","p":"'hændɪ","e":["handy hints/tips for removing stains","清除污渍的妙招 / 窍门儿"]},{"w":"harbour","t":"v. 怀着（不好的想法、恐惧或希望）；包含，藏有；窝藏","p":"ˈhɑ:bə(r)","e":["Accusations of harbouring suspects were raised against the former Hungarian leadership.","匈牙利前领导人被指控窝藏疑犯。"]},{"w":"hard","t":"adj. （酒）烈性的","p":"hɑːd","e":["I never touch the hard stuff (= strong alcohol ).","我从来不喝烈酒。"]},{"w":"harden","t":"v. 变硬","p":"'hɑːdn","e":["It will take about 24 hours for the glue to harden.","胶水干透大约需要24小时。"]},{"w":"hardship","t":"n. 艰难","p":"ˈhɑ:dʃɪp","c":1,"e":["an economic policy that caused great hardship for many people","造成许多人贫困的经济政策"]},{"w":"hardy","t":"adj. 能吃苦耐劳的，坚强的；耐寒的","p":"'hɑːdi","e":["hardy mountain goats","能适应恶劣环境的石山羊"]},{"w":"harmonious","t":"adj. 和谐的，协调的","p":"hɑː'məʊnɪəs","e":["The decor is a harmonious blend of traditional and modern.","这种装饰风格是传统与现代的和谐统一。"]},{"w":"harmony","t":"n. 调和；协调；和谐","p":"'hɑːməni","e":["the gorgeous vocal harmonies on ‘Mexicali Rose’","《墨西哥玫瑰》的精彩和声演唱"]},{"w":"harness","t":"v. 利用，控制","p":"'hɑːnɪs","c":1,"e":["We can harness the power of the wind to generate electricity.","我们可以利用风力发电。"]},{"w":"harp","t":"n. 竖琴；天琴座","p":"hɑːp","e":["She swept her fingers over the strings of the harp.","她用手指划过竖琴的琴弦。"]},{"w":"harsh","t":"adj. 严酷的，严峻的","p":"hɑ:ʃ","c":1,"e":["a young girl suddenly exposed to the harsh realities of life","骤然暴露于残酷现实生活中的小女孩"]},{"w":"hasten","t":"v. 加速","p":"ˈheɪsn","c":1,"e":["Their departure was hastened by an abnormally cold winter.","那个冬天异常寒冷，所以他们提前走了。"]},{"w":"hasty","t":"adj. 匆忙的","p":"ˈheɪsti","c":1,"e":["He soon regretted his hasty decision.","他很快就对自己仓促作出的决定感到后悔了。"]},{"w":"hatch","t":"v. 孵化","p":"hætʃ","c":1,"e":["The eggs take three days to hatch.","这些蛋要三天时间才能孵化。"]},{"w":"hatred","t":"n. 憎恶，憎恨，仇恨","p":"'heɪtrɪd","e":["the old hatreds and prejudices that simmered below the surface","长久以来憋在心中的仇恨与偏见"]},{"w":"haughty","t":"adj. 傲慢的，轻蔑的","p":"'hɔːtɪ","e":["a haughty laugh","傲慢的大笑"]},{"w":"haul","t":"vt. 拖，拉；拖运，运送；n. 拖，拉，托运；一次获得的数量","p":"hɔːl","e":["the steam locomotive which hauled the train","拖动火车的蒸汽机车"]},{"w":"haunt","t":"vt. 常出没于；使苦恼，使担忧；萦绕在心头，缠绕；n. 常去的地方","p":"hɔːnt","e":["The pub is said to be haunted by the ghost of a former landlord.","据说这个酒吧里经常有一位前任房主的鬼魂出没。"]},{"w":"hawk","t":"n. 鹰，隼；“鹰派”人物；vt. 叫卖，兜售","p":"hɔːk","e":["Oil thieves sometimes hawk stolen gasoline on the side of highways.","石油大盗们有时在公路边上兜售偷来的石油。"]},{"w":"hazard","t":"n. 危险","p":"'hæzəd","c":1,"e":["That pile of rubbish is a fire hazard (= something that is likely to cause a fire ).","那堆垃圾是火灾隐患。"]},{"w":"hazardous","t":"adj. 危险的","p":"ˈhæzədəs","c":1,"e":["the disposal of hazardous waste","有害废弃物的处理"]},{"w":"head","t":"v. 用头顶（球）；朝...行进","p":"hed","e":["He headed the ball across the face of the goal.","他一个头球，球从球门前横飞而过。"]},{"w":"heading","t":"n. 标题，题词，题名","p":"'hedɪŋ","e":["chapter headings","章节标题"]},{"w":"headlong","t":"adv. 头向前地；adj. 头向前的","p":"'hedlɒŋ","e":["I fell headlong into a pool of icy water.","我一个倒栽葱跌入了冰冷的池水中。"]},{"w":"headquarters","t":"n. 总部","p":"hed'kwɔːtəz","e":["the headquarters of the United Nations","联合国总部"]},{"w":"heap","t":"n. 堆，大量","p":"hiːp","e":["We piled the branches into heaps for burning.","我们把树枝堆起来烧。"]},{"w":"hearth","t":"n. 壁炉地面；炉边","p":"hɑːθ","e":["It was winter and there was a huge fire roaring in the hearth.","时值冬天，壁炉里的炉火在熊熊燃烧。"]},{"w":"hearty","t":"adj. 热情友好的；丰盛的","p":"'hɑːtɪ","e":["The men ate a hearty breakfast.","男士们吃了一顿丰盛的早餐。"]},{"w":"heater","t":"n. 加热器","p":"'hiːtə","e":["Did you turn the heater off?","你关掉加热器了吗？"]},{"w":"heave","t":"v. 举起，提起；扔；发出；起伏，隆起；呕吐，恶心；n. 举起，升降","p":"hiːv","e":["John heaved the metal bar over the fence.","约翰把金属棒扔过了篱笆。"]},{"w":"Heaven","t":"n. 上帝，神","p":"'hev(ə)n"},{"w":"heel","t":"n. 脚后跟，踵；后跟","p":"hiːl","e":["black boots with high heels","有高跟的黑靴子"]},{"w":"heighten","t":"v. 提高，加强","p":"'haɪtn","e":["Increased levels of fat in the diet could heighten the risk of cancer.","饮食中脂肪摄入量的提升会增加患癌症的风险。"]},{"w":"heir","t":"n. 继承人","p":"eə","e":["Jonson was his political heir as leader of the party.","琼森是他的政治接班人，他将担任该党派的领袖。"]},{"w":"helicopter","t":"n. 直升飞机","p":"ˈhelɪkɒptə(r)","c":1,"e":["She swore she saw him putting the helicopter down in a cornfield.","她肯定地说她看到他把那架直升飞机降落到了玉米地里。"]},{"w":"hemisphere","t":"n. 地球的半球；大脑半球","p":"'hemɪsfɪə","e":["the Northern hemisphere","北半球"]},{"w":"henceforth","t":"adv. 从今以后，从此以后","p":"ˌhens'fɔːθ","e":["multiple sclerosis (henceforth referred to as MS)","多发性硬化（以下称为MS）"]},{"w":"herald","t":"n. 传令官；通报者","p":"'her(ə)ld"},{"w":"herb","t":"n. 药草，香草；草本植物","p":"hɜːb","e":["Sprinkle the dish with chopped fresh herbs.","在菜肴上撒些切碎的新鲜香草。"]},{"w":"herd","t":"v. 成群；放牧","p":"hɜːd","e":["The prisoners were herded together.","犯人们被集合起来。"]},{"w":"heritage","t":"n. 遗产；继承物；传统","p":"'herɪtɪdʒ","e":["beautiful old buildings which are part of our heritage","属于我们遗产一部分的漂亮古建筑"]},{"w":"hesitate","t":"v. 犹豫","p":"'hezɪteɪt","c":1,"e":["So if someone asks you out, never hesitate.","如果有人叫你出去玩，千万别犹豫！"]},{"w":"hide","t":"n. 生皮，兽皮，皮革","p":"haɪd","e":["ox hide gloves","牛皮手套"]},{"w":"hierarchy","t":"n. 等级制度；统治集团，领导层","p":"'haɪərɑːki","e":["She worked her way up through the corporate hierarchy to become president.","她在公司一步步升到了总裁的位置。"]},{"w":"highlight","t":"vt. 强调，突出，使显著；n. 最精彩的部分，最重要的事件","p":"'haɪlaɪt","e":["Your résumé should highlight your skills and achievements.","你的简历应该突出自己的技能和成绩。"]},{"w":"hijack","t":"v. 劫持","p":"ˈhaɪˌdʒæk","c":1,"e":["The airliner was hijacked by a group of terrorists.","该航班被一帮恐怖分子劫持。"]},{"w":"hike","t":"vi. 徒步旅行；n. 徒步旅行；增加，上升；vt. 提高","p":"haɪk","e":["You can organize a picnic in the park, a group hike or bike ride, or meet up with friends for one of those free local events.","你可以组织在公园野餐一群徒步旅行或者骑自行车或者和朋友会面为其中的一个免费本地事件。"]},{"w":"hinder","t":"v. 阻碍","p":"'hɪndə(r)","c":1,"e":["policies that will hinder rather than help families","对家庭有害无益的政策"]},{"w":"hindrance","t":"n. 障碍，妨碍","p":"'hɪndr(ə)ns","e":["A degree is more of a hindrance than a help in British industry.","在英国工业界，学位反倒是个累赘。"]},{"w":"hinge","t":"vi. 以…为转移；n. 铰链；vt. 装铰链","p":"hɪndʒ","e":["Each compartment should have a hinged seal door with a concealed or piano-type hinge .","每个隔室应具有一个带暗装或钢琴型铰链的铰接密封门。"]},{"w":"hip","t":"n. 臀部，髋","p":"hɪp","e":["She stood there with her hands on her hips glaring at him.","她站在那里，双手叉腰瞪着他。"]},{"w":"hiss","t":"n. 嘶嘶声；v. 嘶嘶作声","p":"hɪs","e":["The performance was met with boos and hisses.","演出换来一片倒彩声和嘘声。"]},{"w":"historian","t":"n. 历史学家，史学工作者","p":"hɪ'stɔːriən","e":["The field of aesthetics presents an especially difficult problem to the historian.","美学领域向历史学家提出了一个格外困难的问题。"]},{"w":"historic","t":"adj. 历史的；历史性的","p":"hɪ'stɒrɪk","e":["‘It is a historic moment ,’ he told journalists.","“那是历史性的一刻。”他告诉新闻记者。"]},{"w":"hit","t":"n. 轰动一时的人（或事）","p":"hɪt","e":["Which band had a hit with ‘Bohemian Rhapsody’?","《波希米亚狂想曲》是哪支乐队风行一时的歌曲？"]},{"w":"hitherto","t":"adv. 到目前为止，迄今","p":"ˌhɪðə'tuː","e":["a species of fish hitherto unknown in the West","迄今在西方还不为人知的一种鱼"]},{"w":"hoarse","t":"adj. （声音）嘶哑的","p":"hɔːs","e":["He was hoarse from laughing.","他笑得嗓子都沙哑了。"]},{"w":"hoe","t":"v. 锄地","p":"həʊ","e":["to hoe the flower beds","用锄头给花坛除草松土"]},{"w":"hoist","t":"vt. 举起，升起，吊起；n. 起重器械；举起，升起，吊起","p":"hɔɪst","e":["The crew hurried to hoist the flag.","船员们急忙把旗子升起来。"]},{"w":"hollow","t":"v. 凿空，挖空","p":"'hɒləʊ","e":["Hollow out the cake and fill it with cream.","在蛋糕上挖个洞，填入奶油。"]},{"w":"homely","t":"adj. 家常的","p":"'həʊmlɪ","e":["homely cooking","家常烹调"]},{"w":"homogeneous","t":"adj. 同种类的，同性质的，有相同特征的","p":"ˌhɒmə'dʒiːniəs","e":["The unemployed are not a homogeneous group.","失业者并不都是同一类人。"]},{"w":"honorary","t":"adj. 荣誉的","p":"ˈɒnərəri","c":1,"e":["Brown received an honorary doctorate from Seoul University.","布朗获得了首尔大学的荣誉博士学位。"]},{"w":"hook","t":"v. （使）钩住，挂住","p":"hʊk","e":["We hooked the trailer to the back of the car.","我们把拖车挂在汽车尾部。"]},{"w":"hop","t":"vi. 单足跳跃，单足跳行；齐足跳跃，齐足跳行；vt. 跳上；n. 蹦跳；短程航行","p":"hɒp","e":["a little girl hopping and skipping","一个蹦蹦跳跳的小女孩"]},{"w":"horizon","t":"n. 地平线","p":"hə'raɪz(ə)n","e":["We could see a ship on the horizon.","我们能看见地平线上有一艘船。"]},{"w":"horn","t":"n. 角状物；喇叭形物","p":"hɔːn","e":["a wind-up gramophone with a big horn","带有一个大喇叭形扬声器的发条式留声机"]},{"w":"hose","t":"n. 软管，水龙带；vt. 用软管淋浇","p":"həuz","e":["Water in the engine compartment is sucked away by a hose.","发动机舱里的水由一条软管吸走。"]},{"w":"hospitality","t":"n. 友好","p":"ˌhɒspɪ'tælətɪ","c":1,"e":["Thanks for your hospitality over the past few weeks.","感谢你几周来的热情款待。"]},{"w":"host","t":"v. 主持","p":"həʊst","c":1,"e":["Which country is going to host the next World Cup?","哪个国家将主办下一届世界杯？"]},{"w":"hostage","t":"n. 人质","p":"'hɒstɪdʒ","e":["The group are holding two tourists hostage (= keeping them as hostages ) .","这伙人挟持了两名游客作为人质。"]},{"w":"hostess","t":"n. 女主人；旅馆女老板","p":"'həʊstɪs; -es; həʊ'stes","e":["Mary was always the perfect hostess.","玛丽总是最殷勤的女主人。"]},{"w":"hostile","t":"adj. 有敌意的","p":"ˈhɔstail","c":1,"e":["Southampton fans gave their former coach a hostile reception .","南安普敦队的球迷对球队的前任教练很不友善。"]},{"w":"hostility","t":"n. 敌意","p":"hɒ'stɪlɪtɪ","c":1,"e":["The last decade has witnessed a serious rise in the levels of racism and hostility to black and ethnic groups.","过去的10年里，种族主义及对黑人和少数民族的敌意变得更加严重了。"]},{"w":"hound","t":"n. 猎犬；vt. 追逼，烦恼，纠缠","p":"haund","e":["Rainey's chief interest in life is hunting with hounds.","雷尼一生中的主要嗜好是带着猎犬去打猎。"]},{"w":"house","t":"n. 议院，会议厅","p":"haʊs","e":["The president will address both houses of Congress.","总统将向参众两院发表讲话。"]},{"w":"household","t":"n. 家庭，一家人","p":"'haʊshəʊld","c":1,"e":["A growing number of households have at least one computer.","越来越多的家庭拥有至少一台电脑。"]},{"w":"hover","t":"vi. 翱翔；逗留在近旁，徘徊；彷徨，犹豫","p":"'hɒvə","e":["Judith was hovering in the doorway.","朱迪丝在门口徘徊。"]},{"w":"howl","t":"n&vi. 嗥叫；呼啸；吼叫，哀号","p":"haul","e":["wind howling in the trees","在林间呼啸的风"]},{"w":"huddle","t":"vi. 聚集在一起，挤作一团；把身子蜷成一团，蜷缩；vt. 使聚集在一起；n. 挤在一起的人；一堆杂乱的东西","p":"'hʌdl","e":["Off to one side, Sticht, Macomber, Jordan, and Kreps huddled to discuss something.","史蒂希特、麦康伯、乔丹和克雷普斯走到一边，私下商量起事情。"]},{"w":"hug","t":"vi. 紧抱在一起，互相拥抱；vt. 拥抱；紧抱，怀抱；n. 紧抱，热烈拥抱","p":"hʌg","e":["She went to her daughter and hugged her tightly .","她走到女儿身边，紧紧地拥抱她。"]},{"w":"hull","t":"n. 外壳，豆荚；薄膜","p":"hʌl"},{"w":"hum","t":"vi. 哼曲子；发嗡嗡声；vt. 哼；n. 嗡嗡声，营营声，嘈杂声","p":"hʌm","e":["He began to hum a tune.","他开始哼唱一支曲子。"]},{"w":"humanistic","t":"adj. 人文的","p":"ˌhju:mə'nɪstɪk","c":1,"e":["Religious values can often differ greatly from humanistic morals.","宗教价值观常常和人文主义道德观相去甚远。"]},{"w":"humanitarian","t":"adj. 博爱的；n. 慈善家","p":"hjʊ,mænɪ'teərɪən","e":["The well-known humanitarian, Joseph Rowntree, was concerned with the welfare of his employees.","著名的人道主义者约瑟夫.荣特里非常关心其雇员的福利。"]},{"w":"humanity","t":"n. 人类，人；人性；人道，博爱；人文学科","p":"hjuː'mænəti","e":["We want a clean healthy environment for all humanity .","我们希望全人类拥有一个干净健康的生存环境。"]},{"w":"humble","t":"adj. 谦逊的；地位低下的；简陋的；vt. 使谦恭；使卑下","p":"'hʌmbl","e":["a modest and humble man","一个谦卑的男人"]},{"w":"humidity","t":"n. 湿度，潮湿，湿气","p":"hjuː'mɪdəti","e":["The room is kept at 72 degrees and 50% relative humidity.","房间的温度保持在72度，相对湿度50%。"]},{"w":"humorous","t":"adj. 幽默的","p":"ˈhju:mərəs","c":1,"e":["The film has some mildly humorous moments.","那部电影中有些略显幽默的片段。"]},{"w":"hurl","t":"v. 猛投","p":"hɜ:l","c":1,"e":["He hurled a chair across the set, smashing lamps and vases.","他抓起一把椅子扔向片场的那头，把灯和花瓶都砸得粉碎。"]},{"w":"hurrah","t":"int. 好哇，万岁，乌拉","p":"hʊ'rɑː"},{"w":"hurricane","t":"n. 飓风","p":"'hʌrɪkən","e":["Our love is not fierce, not hot, but despite the tsunami hurricane, also vowed.","我们的爱，不剧烈，不炙热，可是任凭海啸飓风，也矢志不渝。"]},{"w":"hurt","t":"n. （对感情造成的）伤害，创伤","p":"hɜːt","e":["all the hurts and wrongs of the past","过去所受的所有伤害和委屈"]},{"w":"hush","t":"n. 沉默；int. 嘘！","p":"hʌʃ","e":["A sudden hush fell over the crowd.","人群突然变得鸦雀无声。"]},{"w":"hustle","t":"v. 催促，赶紧做；猛推，挤，强迫；n. 忙碌，奔忙；挤","p":"'hʌsl","e":["We need to hustle if we’re going to make this flight.","要想搭乘这趟班机，我们得抓紧时间。"]},{"w":"hydraulic","t":"adj. 水力的；水力学的","p":"haɪ'drɔːlɪk; haɪ'drɒlɪk","e":["a hydraulic pump","水压泵，液压泵"]},{"w":"hydrocarbon","t":"n. 烃，碳氢化合物","p":",haɪdrə(ʊ)'kɑːb(ə)n","e":["hydrocarbon emissions","碳氢化合物的排放"]},{"w":"hymn","t":"n. 赞美诗，圣歌；赞歌","p":"hɪm","e":["He liked to sing hymns as he worked.","他工作时喜欢唱赞美诗。"]},{"w":"hypothesis","t":"n. 假设，假说","p":"haɪ'pɒθɪsɪs","c":1,"e":["One hypothesis is that the victim fell asleep while driving.","一种假设是受害人开车时睡着了。"]},{"w":"hysterical","t":"adj. 情绪异常激动的，歇斯底里般的","p":"hɪ'sterɪkl","e":["Everyone in the studio burst into hysterical laughter .","演播室里的每个人都爆发出一阵狂笑。"]},{"w":"ice","t":"v. 使成冰，结冰","p":"aɪs"},{"w":"icy","t":"adj. 冰冷的；冷冰冰的","p":"'aɪsɪ","e":["The bath water was icy cold.","洗澡水冰冷刺骨。"]},{"w":"ideal","t":"adj. 理想的，观念的，空想的；n. 理想，理想的东西","p":"aɪ'diːəl","e":["The scheme offers an ideal opportunity for youngsters to get training.","该计划为年轻人提供了获得培训的极好机会。"]},{"w":"idealism","t":"n. 唯心主义；理想主义","p":"aɪ'dɪəlɪz(ə)m; -'diːə-","e":["the idealism of the younger generation","年轻一代的理想主义"]},{"w":"ideally","t":"adv. 理想地；理论上","p":"aɪ'dɪəl(l)ɪ; aɪ'diːəl(l)ɪ","e":["Fruit and vegetables should ideally be organically grown.","水果和蔬菜最理想的应该是有机种植。"]},{"w":"identical","t":"adj. 相同的","p":"aɪˈdentɪkl","c":1,"e":["four identical houses","四幢一模一样的房子"]},{"w":"identification","t":"n. 身份证明；鉴定，验明，认出；认同","p":"aɪˌdentɪfɪ'keɪʃn","e":["fingerprinting as a means of identification","作为一种身份证明方式的指纹提取"]},{"w":"identify","t":"v. 认出，识别","p":"aɪ'dentɪfaɪ","c":1,"e":["The police took fingerprints and identified the body.","警方采集了指纹，对尸体作了身份确认。"]},{"w":"ideological","t":"adj. 意识形态的","p":"ˌaɪdiəˈlɒdʒɪkl","c":1,"e":["The party is split by ideological differences.","意识形态上的差异造成该政党分裂。"]},{"w":"ideologically","t":"adv. 意识形态上地","p":"ˌaɪdɪə'lɒdʒɪklɪ","c":1,"e":["ideologically correct","意识上正确"]},{"w":"ideology","t":"n. 意识形态","p":"ˌaɪdɪ'ɒlədʒɪ","c":1,"e":["the ideologies of fascism and terrorism","法西斯主义和恐怖主义的意识形态"]},{"w":"idiom","t":"n. 习语，成语；风格，特色","p":"'ɪdiəm","e":["the new musical idiom","新的音乐风格"]},{"w":"idiot","t":"n. 白痴；傻子，笨蛋","p":"'ɪdiət","e":["It was all your fault, you idiot.","全是你的错，你这笨蛋。"]},{"w":"idleness","t":"n. 懒惰；赋闲无事","p":"'aɪdlnəs","e":["After a period of enforced idleness, she found a new job.","她在被迫闲散了一段时间之后，找到了份新工作。"]},{"w":"ignite","t":"vi. 着火；vt. 点燃，引发","p":"ɪg'naɪt","e":["The bombs ignited a fire which destroyed some 60 houses.","炸弹引起了一场火灾，烧毁了大约六十间房屋。"]},{"w":"ignorance","t":"n. 无知，无学，愚昧","p":"'ɪgn(ə)r(ə)ns","e":["Excuse my ignorance, but how does it actually work?","请原谅我的无知，它究竟是如何运作的？"]},{"w":"ignore","t":"v. 忽视","p":"ɪɡ'nɔ:(r)","c":1,"e":["The phone rang, but she ignored it.","电话铃响了，但她只当没听见。"]},{"w":"illegal","t":"adj. 不合法的，非法的","p":"ɪ'liːgl","e":["They were involved in illegal activities.","他们参与了非法活动。"]},{"w":"illiterate","t":"adj. 文盲的；n. 文盲","p":"ɪ'lɪt(ə)rət","e":["A large percentage of the population is illiterate.","文盲人口占有相当高的比例。"]},{"w":"illuminate","t":"v. 阐释，阐明","p":"ɪˈluːmɪneɪt","c":1,"e":["The report illuminated the difficult issues at the heart of science policy.","报告阐明了科学方针核心部分的难点。"]},{"w":"illusion","t":"n. 幻想，错误的观念；错觉，幻觉，假象","p":"ɪ'luːʒn","e":["She had no illusions about her physical attractiveness.","她对自己外表的吸引力不抱幻想。"]},{"w":"illustrate","t":"v. 阐明，说明","p":"'ɪləstreɪt","c":1,"e":["Let me give an example to illustrate the point.","让我举个例子来说明这一点。"]},{"w":"imaginary","t":"adj. 想象中的，假想的","p":"ɪ'mædʒɪnəri","e":["We must protect older people from harm, whether it is real or imaginary.","我们必须保护老人免受伤害，无论这伤害是真实的还是假想的。"]},{"w":"imaginative","t":"adj. 富有想象力的，爱想象的","p":"ɪ'mædʒɪnətɪv","e":["an imaginative solution to the litter problem","解决乱扔垃圾的问题的有创意的方法"]},{"w":"imbalance","t":"n. 不平衡","p":"ɪm'bæləns","c":1,"e":["a hormonal imbalance","内分泌失调"]},{"w":"imitate","t":"v. 模仿","p":"ˈɪmɪteɪt","c":1,"e":["She was a splendid mimic and loved to imitate Winston Churchill.","她是个出色的模仿者，喜欢模仿温斯顿·丘吉尔。"]},{"w":"imitation","t":"n. 模仿；仿制，伪制品；赝品","p":"ˌɪmɪ'teɪʃn","e":["The remake of ‘Casablanca’ was a pale imitation (= something that is much less good than the thing it imitates ) of the original movie.","重拍的《卡萨布兰卡》远不如原版。"]},{"w":"immense","t":"adj. 巨大的","p":"ɪˈmens","c":1,"e":["Regular visits from a social worker can be of immense value to old people living alone.","对于独居老人来说社工的经常探望很重要。"]},{"w":"immensely","t":"adv. 非常，极大地","p":"ɪˈmensli","c":1,"e":["Champagne wines became immensely popular in the 18th century.","香槟酒在18世纪十分流行。"]},{"w":"immerse","t":"vt. 使浸没；使沉浸在，使专心于","p":"ɪ'mɜːs","e":["He left school at 16 and immersed himself in the Labour Party.","他16岁离开学校投身工党。"]},{"w":"immersive","t":"adj. 沉浸的，身临其境的","p":"ɪˈmɜ:sɪv","c":1,"e":["“Right now, we’re just getting to the phase where people appreciate how an “immersive” digital environment can be as complex and rich as sensation, ” he says.","“现在，我们要进入一个阶段，让人们能够领会到‘沉浸式’数字环境可以像感觉一样复杂而丰富，”他说"]},{"w":"immigrant","t":"n. 移民","p":"ˈɪmɪgrənt","c":1,"e":["a new wave of immigrants from the Middle East","来自中东的一股新兴的移民浪潮"]},{"w":"immigrate","t":"v. （使）移居入境","p":"'ɪmɪgreɪt","e":["His father and mother immigrated when he was two.","他的父母在他两岁时移民到这里。"]},{"w":"immigration","t":"n. 移民","p":"ˌɪmɪˈgreɪʃn","c":1,"e":["He called for a common European policy on immigration.","他要求欧洲国家实施共同的移民政策。"]},{"w":"imminent","t":"adj. 即将来临的","p":"'ɪmɪnənt","c":1,"e":["A new trade agreement is imminent.","一项新的贸易协定即将签署。"]},{"w":"immortal","t":"adj. 不朽的；永生的","p":"ɪ'mɔːt(ə)l","e":["Plato believed that the soul is immortal.","柏拉图认为灵魂不灭。"]},{"w":"immune","t":"adj. 免疫的，有免疫力的，不受影响的；免除的，豁免的","p":"ɪ'mjuːn","e":["Once we’ve had the disease, we’re immune for life.","我们一旦得过这种病，就获得了终身免疫力。"]},{"w":"impact","t":"n. 影响","p":"'ɪmpækt","c":1,"e":["They say they expect the meeting to have a marked impact on the future of the country.","他们说期望这次会议对国家的未来产生显著的影响。"]},{"w":"impair","t":"v. 损害","p":"ɪmˈpeə(r)","c":1,"e":["The illness had impaired his ability to think and concentrate.","这种疾病损害了他的思维能力和注意力。"]},{"w":"impart","t":"v. 传授，教授","p":"ɪmˈpɑːt","c":1,"e":["She had information that she couldn’t wait to impart.","她得到了消息，迫不及待地想告诉别人。"]},{"w":"impartial","t":"adj. 公正的，无偏见的","p":"ɪm'pɑːʃ(ə)l","e":["We offer impartial advice on tax and insurance.","我们就税收和保险问题提供公充的建议。"]},{"w":"impatient","t":"adj. 不耐烦的，急躁的；热切的，急切的","p":"ɪm'peɪʃnt","e":["He turned away with an impatient gesture.","他做了个不耐烦的手势转过身去。"]},{"w":"imperative","t":"adj. 必须的,必要的","p":"ɪm'perətɪv","c":1,"e":["It is imperative that politicians should be good communicators.","政治家应该是很好的沟通者，这很重要。"]},{"w":"imperial","t":"adj. 帝国的","p":"ɪm'pɪərɪəl","c":1,"e":["Britain’s imperial expansion in the 19th century","19世纪英帝国的扩张"]},{"w":"impetus","t":"n. 推动，促进，刺激；推动力","p":"'ɪmpɪtəs","e":["The discovery gave fresh impetus to the research.","这个发现为研究带来新动力。"]},{"w":"implement","t":"vt. 使生效，履行，实施；n. 工具，器具，用具","p":"'ɪmplɪm(ə)nt","e":["The government promised to implement a new system to control financial loan institutions.","政府许诺要实施新的制度来控制金融贷款机构。"]},{"w":"implication","t":"n. 含意，暗示，暗指；卷入，牵连","p":"ˌɪmplɪ'keɪʃn","e":["They are called ‘Supertrams’, the implication being that (= which is meant to suggest that ) they are more advanced than earlier models.","它们被称作“超级电车”，这是暗指它们比先前的型号更先进。"]},{"w":"implicit","t":"adj. 不言明的，含蓄的；内含的，固有的；无疑问的","p":"ɪm'plɪsɪt","e":["...an implicit warning to the Moroccans not to continue or repeat the military actions they began a week ago.","…叫摩洛哥人不要继续或重复一周前开始的军事行动的含蓄警告。"]},{"w":"implore","t":"v. 乞求，恳求，哀求","p":"ɪm'plɔː","e":["‘Don’t go,’ I implored her.","“不要走。”我哀求她。"]},{"w":"imply","t":"vt. 暗示，意指","p":"ɪm'plaɪ","e":["an implied threat","隐含的威胁"]},{"w":"impose","t":"v. 强加于","p":"ɪm'pəʊz","c":1,"e":["Parents should beware of imposing their own tastes on their children.","父母应该提防把自己的兴趣强加给孩子。"]},{"w":"impress","t":"v. 盖印，在…打记号","p":"ɪm'pres","e":["patterns impressed in the clay","压印在黏土上的图案"]},{"w":"imprison","t":"v. 监禁","p":"ɪm'prɪzn","c":1,"e":["The government imprisoned all opposition leaders.","政府把反对派领导人全部监禁起来。"]},{"w":"improper","t":"adj. 不适当的；不合理的","p":"ɪm'prɒpə","e":["It would be improper of me to comment before the election outcome is known.","在选举结果未知的情况下我作出评论是不恰当的。"]},{"w":"impulse","t":"n. 冲动，一时的念头；推动，驱使；脉冲","p":"'ɪmpʌls","e":["The eye converts light signals to nerve impulses.","眼睛把光信号转变成神经冲动。"]},{"w":"impulsive","t":"adj. 冲动的","p":"ɪm'pʌlsɪv","e":["Rosa was impulsive and sometimes regretted things she’d done.","罗莎性情鲁莽，有时会为做过的事感到后悔。"]},{"w":"impurity","t":"n. 杂质；不纯","p":"ɪm'pjʊərɪtɪ","e":["All natural minerals contain impurities.","凡天然矿物都含有杂质。"]},{"w":"inaccessible","t":"adj. 达不到的，难接近的","p":"ɪnək'sesɪb(ə)l","e":["In winter, the villages are inaccessible by road.","冬天时，进入这些村子的路很难走。"]},{"w":"inaccurate","t":"adj. 不精密的，不准确的","p":"ɪn'ækjʊrət","e":["A lot of what has been written about him is inaccurate.","关于他的文字描述有大量失实之处。"]},{"w":"inaction","t":"n. 不作为","p":"ɪnˈækʃn","c":1,"e":["He is bitter about the inaction of the other political parties.","他为其他政党的不作为感到愤愤不平。"]},{"w":"inadequate","t":"adj. 不足的","p":"ɪnˈædɪkwət","c":1,"e":["The new air conditioning system proved inadequate.","新的空调系统不够好。"]},{"w":"inanimate","t":"adj. 无生命的","p":"ɪnˈænɪmət","c":1,"e":["an inanimate object","无生命的物体"]},{"w":"inasmuch","t":"adv. 因为，由于","p":"ɪnəz'mʌtʃ","e":["This was a good decision inasmuch as it worked for you.","既然对你起作用，这就是个明智的决定。"]},{"w":"inaugurate","t":"vt. 开始，开展；为…举行就职典礼；为…举行开幕式，为…举行落成仪式","p":"ɪ'nɔːgjəreɪt","e":["The Turner Prize was inaugurated in 1984.","特纳奖于1984年正式设立。"]},{"w":"incalculable","t":"adj. 不可估量的，无法计算的","p":"ɪnˈkælkjələbl","c":1,"e":["Her contribution to our work is incalculable.","她对我们工作的贡献极大。"]},{"w":"incapable","t":"adj. 无能力的；无资格的","p":"ɪn'keɪpəb(ə)l","e":["Seventy-five percent of the electorate believe his party is incapable of government.","75%的选民都认为他领导的政党无能力执政。"]},{"w":"incense","t":"n. 香，熏香；香气","p":"'ɪnsens","e":["a church filled with the smell of incense","充满焚香气味的教堂"]},{"w":"incentive","t":"n. 刺激","p":"ɪnˈsentɪv","c":1,"e":["As an added incentive, there’s a bottle of champagne for the best team.","给最优秀的队发一瓶香槟作为额外的鼓励。"]},{"w":"incidence","t":"n. 发生率","p":"ˈɪnsɪdəns","c":1,"e":["The incidence of breast cancer increases with age.","乳腺癌的发病率随着年龄的增长而上升。"]},{"w":"incident","t":"n. 发生的事，事件","p":"'ɪnsɪdənt","e":["Am I at risk because of some incident in my sexual past?","我过去性生活中的某件事会使我处于危险境地吗？"]},{"w":"incidentally","t":"adv. 顺便地，附带","p":"ɪnsɪ'dent(ə)lɪ","c":1,"e":["\"I didn't ask you to come. Incidentally, why have you come?\"","“我没有叫你来。顺便问一下，你为什么来呢？”"]},{"w":"inclination","t":"n. 倾斜，点头；斜坡","p":"ɪnklɪ'neɪʃ(ə)n","e":["She greeted Maggie with an inclination of the head.","她向玛吉点头打招呼。"]},{"w":"incline","t":"n. 斜坡[In'klaIn]；vt. 使倾斜","p":"'ɪnklaɪn","e":["a steep incline","陡坡"]},{"w":"inclusive","t":"adj. 包括一切的，包括一切费用在内的；所有数目包括在内的","p":"ɪn'kluːsɪv","e":["Not everyone shares his vision of an inclusive America.","不是所有人都同意他的观点，认为美国是个包容性很强的国家。"]},{"w":"incompatibility","t":"n. 不兼容","p":"ˌɪnkəmˌpætə'bɪlətɪ","c":1,"e":["Because of an antibody incompatibility, he is unable to receive a transplant.","由于抗体不相容，他不能接受心脏移植。"]},{"w":"incompatible","t":"adj. 不相容的","p":"ɪnkəm'pætɪb(ə)l","e":["Business interests are incompatible with public office.","商业利益与公职不可兼得。"]},{"w":"incompetence","t":"n. 无能","p":"ɪnˈkɒmpɪtəns","c":1,"e":["The incompetence of government officials is appalling.","政府官员的无能令人吃惊。"]},{"w":"incompetent","t":"adj. 无能力的，不胜任的","p":"ɪn'kɒmpɪt(ə)nt","c":1,"e":["weak incompetent leadership","软弱不称职的领导"]},{"w":"incomplete","t":"adj. 不完全的，未完成的","p":"ɪnkəm'pliːt","e":["Unfortunately, I do not have the information because our records are incomplete.","很遗憾，由于我们的记录不完整，我无法提供有关资料。"]},{"w":"incorporate","t":"v. 合并","p":"ɪn'kɔːpəreɪt","c":1,"e":["The agreement would allow the rebels to be incorporated into a new national police force.","该协议将允许叛军并入一支新的国家警察部队。"]},{"w":"incredible","t":"adj. 不能相信的，不可信的，难以置信的；惊人的","p":"ɪn'kredəbl","e":["I find it almost incredible that no one noticed these errors.","没人发现这些错误，真让我无法相信。"]},{"w":"incur","t":"v. 引起，导致","p":"ɪnˈkɜː(r)","c":1,"e":["She wondered what she’d done to incur his displeasure this time.","她奇怪她这次做了什么引起他的不悦。"]},{"w":"indefinite","t":"adj. 无限期的；模糊的，不确定的","p":"ɪn'defɪnət","e":["The picture has been loaned for an indefinite period to the National Gallery.","那幅画长期出借给国家美术馆。"]},{"w":"independence","t":"n. 独立；自主；自立","p":"ˌɪndɪ'pendəns","e":["The country has made great advances since independence.","该国自独立以来发展迅速。"]},{"w":"index","t":"n. 指数；标志，指标","p":"'ɪndeks","c":1,"e":["The changing size of an infant’s head is considered an index of brain growth","婴儿头围不断变大标志着大脑在发育。"]},{"w":"indicate","t":"v. 表明","p":"'ɪndɪkeɪt","c":1,"e":["The study indicates a connection between poverty and crime.","研究显示贫穷和犯罪有关联。"]},{"w":"indication","t":"n. 指出，指示；迹象，暗示","p":"ˌɪndɪ'keɪʃn","e":["Could you give me some indication as to when I am likely to receive a reply?","你能给我透露一下什么时候我能收到回复吗？"]},{"w":"indicative","t":"adj. 指示的","p":"ɪnˈdɪkətɪv","c":1,"e":["This behaviour is indicative of her whole attitude, I’m afraid.","这一行为恐怕已表明了她的总体态度。"]},{"w":"indifferent","t":"adj. 冷漠的","p":"ɪnˈdɪfrənt","c":1,"e":["People have become indifferent to the suffering of others.","人们已经变得对别人的痛苦漠不关心。"]},{"w":"indignant","t":"adj. 愤怒的，愤慨的，义愤的","p":"ɪn'dɪgnənt","e":["an indignant reply","愤慨的回复"]},{"w":"indignation","t":"n. 愤怒，愤慨，义愤","p":"ˌɪndɪg'neɪʃn","e":["To his indignation, Charles found that his name was not on the list.","查尔斯发现他的名字没有出现在名单上，这让他深感愤慨。"]},{"w":"indiscriminately","t":"adv. 不加选择地，不加区分地","p":"ˌɪndɪ'skrɪmɪnətlɪ","c":1,"e":["The soldiers fired indiscriminately into the crowd.","士兵对着人群胡乱开枪。"]},{"w":"indispensable","t":"adj. 必不可少的","p":"ˌɪndɪˈspensəbl","c":1,"e":["Mobile phones have become an indispensable part of our lives.","移动电话已经成为我们生活中的必需品。"]},{"w":"individual","t":"adj. 个别的；独特的；n. 个人，个体","p":"ˌɪndɪ'vɪdʒuəl","e":["Each individual leaf on the tree is different.","树上每片叶子都不相同。"]},{"w":"indoor","t":"adj. 室内的；室内进行的","p":"'ɪndɔː","e":["Too much central heating can harm indoor plants.","中央供暖系统温度太高对室内植物有害。"]},{"w":"induce","t":"vt. 引导，劝；引起，导致","p":"ɪn'djuːs","e":["She had to be induced because the baby was four weeks late.","她的孩子晚了四星期仍未出生，因此要给她引产。"]},{"w":"induction","t":"n. 就职；归纳推理","p":"ɪn'dʌkʃ(ə)n","e":["Mrs Simpson is responsible for the induction of new library staff.","辛普森太太负责图书馆新职员的入职培训。"]},{"w":"indulge","t":"v. 放纵","p":"ɪn'dʌldʒ","c":1,"e":["His mother spoiled him, indulging his every whim.","他母亲对他纵容娇惯，百依百顺。"]},{"w":"industrial","t":"adj. 工业的，产业的","p":"ɪn'dʌstriəl","e":["By 1900, Britain was a mainly industrial society.","到1900年英国已基本进入工业社会。"]},{"w":"industrious","t":"adj. 勤奋的","p":"ɪnˈdʌstriəs","c":1,"e":["She was an industrious and willing worker.","她是个勤劳肯干的工人。"]},{"w":"ineffective","t":"adj. 无效的","p":"ˌɪnɪˈfektɪv","c":1,"e":["an ineffective marketing campaign","一场毫无成效的营销活动"]},{"w":"inertia","t":"n. 不活动，惰性；惯性","p":"ɪ'nɜːʃə","e":["political inertia","政治上的保守"]},{"w":"inescapable","t":"adj. 不可避免的","p":"ˌɪnɪˈskeɪpəbl","c":1,"e":["She didn’t want to confront the inescapable fact that she would have to sell the house.","她不想面对必须卖掉房子这一无法逃避的事实。"]},{"w":"inevitable","t":"adj. 不可避免的","p":"ɪnˈevɪtəbl","c":1,"e":["A further escalation of the crisis now seems inevitable.","危机的进一步升级现在看来已不可避免。"]},{"w":"inevitably","t":"adv. 不可避免地","p":"ɪ'nevɪtəblɪ; ɪn'evɪtəblɪ","e":["The decision will inevitably lead to political tensions.","该决定必然导致政治局势的紧张。"]},{"w":"inexhaustible","t":"adj. 用不完的，无穷无尽的","p":"ˌɪnɪgˈzɔ:stəbl","c":1,"e":["She has an inexhaustible supply of funny stories.","她有讲不完的有趣故事。"]},{"w":"infant","t":"n. 婴儿","p":"'ɪnfənt","c":1,"e":["An infant’s skin is very sensitive.","幼儿的皮肤非常敏感。"]},{"w":"infect","t":"v. 感染","p":"ɪn'fekt","c":1,"e":["People with the virus may feel perfectly well, but they can still infect others.","带有这种病毒的人可能毫无症状，却仍可能传染他人。"]},{"w":"infectious","t":"adj. 感染的，传染的","p":"ɪnˈfekʃəs","c":1,"e":["Flu is highly infectious.","流感传染性很强。"]},{"w":"infer","t":"v. 推断","p":"ɪn'fɜː","e":["From the evidence, we can infer that the victim knew her killer.","根据证据我们可以推断出受害者认识凶手。"]},{"w":"inference","t":"n. 推论；推断的结果","p":"'ɪnf(ə)r(ə)ns","e":["There were two inferences to be drawn from her letter.","从她的来信可以得到两种推论。"]},{"w":"inferior","t":"adj. 比……差","p":"ɪnˈfɪəriə(r)","c":1,"e":["I felt very inferior among all those academics.","与那些大学教师在一起，我自惭形秽。"]},{"w":"inferiority","t":"n. 自卑；次等","p":"ɪnˌfɪəri'ɒrəti","e":["moral inferiority","道德低下"]},{"w":"infinite","t":"adj. 无限的，无数的","p":"'ɪnfɪnət","e":["The universe is infinite.","宇宙是无限的。"]},{"w":"infinitely","t":"adv. 无限地，无边地","p":"'ɪnfɪnɪtlɪ","e":["Human beings are infinitely adaptable.","人类的适应力是无限的。"]},{"w":"infinity","t":"n. 无穷大","p":"ɪn'fɪnɪtɪ","e":["In the equation below, as E goes to zero, n approaches infinity.","在下面的方程式中，E趋向于零时，n接近无穷大。"]},{"w":"inflation","t":"n. 通货膨胀","p":"ɪn'fleɪʃn","c":1,"e":["Inflation is now at over 16%.","通货膨胀率现已超过16%。"]},{"w":"inflict","t":"vt. 把…强加给；使…遭受，使…承担","p":"ɪn'flɪkt","e":["...the damage being inflicted on industries by the recession.","…经济衰退给工业造成的损失。"]},{"w":"influence","t":"n. 势力，权势","p":"'ɪnflʊəns","e":["He used his influence to get his son into medical school.","他利用权势把儿子弄进了医学院。"]},{"w":"influential","t":"adj. 有影响力的","p":"ˌɪnfluˈenʃl","c":1,"e":["a highly influential art magazine","一本极有影响力的艺术杂志"]},{"w":"ingenious","t":"adj. 设计独特的，别致的，巧妙的；灵巧的，善于创造发明的","p":"ɪn'dʒiːniəs","e":["Many fish have ingenious ways of protecting their eggs from predators.","很多鱼都有绝妙的方法来保护它们产的卵不被捕食者吃掉。"]},{"w":"ingenuity","t":"n. 创造力","p":"ˌɪndʒəˈnju:əti","c":1,"e":["Inspecting the nest can be difficult and may require some ingenuity.","仔细检查鸟巢可能有困难，也许需要一些巧妙的心思。"]},{"w":"ingredient","t":"n. 组成部分，原料；要素","p":"ɪn'griːdiənt","e":["The food is home-cooked using fresh ingredients.","这种食物是用新鲜的食材在家里烹制的。"]},{"w":"inhabit","t":"vt. 居住于，栖居于","p":"ɪn'hæbɪt","e":["The woods are inhabited by many wild animals.","很多野生动物栖居在这片森林里。"]},{"w":"inhabitant","t":"n. 居民，住户","p":"ɪn'hæbɪtənt","e":["a city of six million inhabitants","有600万居民的城市"]},{"w":"inhale","t":"v. 吸入","p":"ɪn'heɪl","c":1,"e":["Myra lit another cigarette and inhaled deeply  (= breathed in a lot of smoke ).","迈拉又点上一支烟，深深地吸了一口。"]},{"w":"inherent","t":"adj. 固有的","p":"ɪnˈhɪərənt","c":1,"e":["Every business has its own inherent risks.","每笔生意本身都有风险。"]},{"w":"inherit","t":"v. 继承","p":"ɪn'herɪt","c":1,"e":["inherited wealth","继承的财富"]},{"w":"inheritance","t":"n. 继承；遗产","p":"ɪnˈherɪtəns","c":1,"e":["Lucinda has to fight for her life and her inheritance in this gripping novel.","在这部扣人心弦的小说里，露辛达不得不为自己的生命与所继承的遗产进行抗争。"]},{"w":"inhibit","t":"vt. 阻止，妨碍，抑制","p":"ɪn'hɪbɪt","e":["An unhappy family life may inhibit children’s learning.","不幸福的家庭生活可能会阻碍儿童的学习。"]},{"w":"initial","t":"adj. 初步的，最初的","p":"ɪ'nɪʃəl","c":1,"e":["The initial response has been encouraging.","最初的反应情况很乐观。"]},{"w":"initially","t":"adv. 最初，开始","p":"ɪ'nɪʃ(ə)lɪ","e":["Initially, I thought I would only stay there a year.","起初，我以为我只会在那儿待一年。"]},{"w":"initiate","t":"vt. 开始，创造，发起；使初步了解；接纳，让…加入；n. 新加入组织的人","p":"ɪ'nɪʃɪeɪt","e":["They have decided to initiate legal proceedings against the newspaper.","他们决定向该报提起法律诉讼。"]},{"w":"initiative","t":"n. 主动性","p":"ɪ'nɪʃətɪv","c":1,"e":["Lt. Carlos was not obeying orders. He acted on his own initiative (= he was not told what to do ).","卡洛斯中尉没有服从命令，而是自作主张。"]},{"w":"inject","t":"vt. 注射，给…注射；注入，引入，投入","p":"ɪn'dʒekt","e":["His son was injected with strong drugs.","他的儿子被注射了强效的药。"]},{"w":"injustice","t":"n. 不公正","p":"ɪnˈdʒʌstɪs","c":1,"e":["The movie deals with injustices suffered by Native Americans.","这部电影讲述印第安人受到的不公正待遇。"]},{"w":"inland","t":"adv. 在内地，向内地；adj. 内陆的，内地的","p":"'ɪnlənd; -lænd","e":["The mountains are five miles inland.","这些山位于内陆五英里处。"]},{"w":"inlet","t":"n. 小湾，水湾；进口，入口","p":"'ɪnlet","e":["There are several sheltered inlets along the coast.","沿着海岸线有几处有天然屏障的水湾。"]},{"w":"innovation","t":"n. 创新，革新；新观念；新方法；新发明","p":"ˌɪnəˈveɪʃn","c":1,"e":["We must encourage innovation if the company is to remain competitive.","公司要想保持竞争力，就必须鼓励革新。"]},{"w":"innumerable","t":"adj. 无数的，数不清的","p":"ɪ'njuːmərəbl","e":["She’s served on innumerable committees.","她在多个委员会担任委员。"]},{"w":"inorganic","t":"adj. 无生物的；无机的","p":"ɪnɔː'gænɪk","e":["inorganic matter","无机物"]},{"w":"input","t":"n. 输入；投入的资金，输入的数据；vt. 把…输入计算机","p":"'ɪnput","e":["If the input data specified it, the file will close and the process terminates.","如果输入数据指定，该文件就会关闭，数据处理终止。"]},{"w":"inquire","t":"v. 询问","p":"ɪn'kwaɪə","c":1,"e":["Toby would have liked to inquire further (= ask more questions ).","托比本想问更多的问题。"]},{"w":"insane","t":"adj. 极蠢的，荒唐的；精神病的，精神失常的，疯狂的","p":"ɪn'seɪn","e":["The whole idea sounds absolutely insane to me.","整个主意在我看来荒谬至极。"]},{"w":"insect","t":"n. 昆虫，虫","p":"'ɪnsekt","e":["Don’t forget to bring insect repellant (= a chemical to keep insects away ).","不要忘记带上驱虫剂。"]},{"w":"insert","t":"vt. 插入，嵌入；登载","p":"ɪn'sɜːt","e":["He took a small key from his pocket and slowly inserted it into the lock.","他从衣袋里掏出一把小钥匙，然后缓缓地将其插入锁孔里。"]},{"w":"insight","t":"n. 洞察力；洞悉，深刻的见解","p":"'ɪnsaɪt","e":["a woman of great insight","一位极有眼光的妇女"]},{"w":"insignificant","t":"adj. 无意义的；低微的","p":"ɪnsɪg'nɪfɪk(ə)nt","e":["You realize that your problems are insignificant in comparison.","要知道，你的问题相对来说微不足道。"]},{"w":"insist","t":"v. 坚持；坚持要求；坚决认为","p":"ɪn'sɪst","e":["Stay for supper – I insist!","留下来吃晚餐——一定的！"]},{"w":"insistent","t":"adj. 坚持的","p":"ɪn'sɪst(ə)nt","e":["She was insistent that they should all meet for dinner.","她坚持要大家聚在一起吃晚餐。"]},{"w":"inspector","t":"n. 检查员；巡官","p":"ɪn'spektə","e":["ticket inspectors","查票员"]},{"w":"inspiration","t":"n. 灵感；鼓舞人心的人","p":"ˌɪnspə'reɪʃn","e":["The Malvern Hills have provided inspiration for many artists and musicians over the decades.","几十年来，莫尔文丘陵为很多艺术家和音乐家提供了灵感。"]},{"w":"inspire","t":"v. 鼓励","p":"ɪn'spaɪə(r)","c":1,"e":["Inspired by the sunny weather, I decided to explore the woods.","阳光明媚的天气令人振奋，我决定到森林里寻幽探胜。"]},{"w":"instability","t":"n. 不稳定性","p":"ɪnstə'bɪlɪtɪ","e":["political instability in the region","该地区的政局不稳"]},{"w":"install","t":"vt. 安装，设置；使就职，任命","p":"ɪn'stɔːl","e":["Security cameras have been installed in the city centre.","在市中心已安装了一些监控摄像机。"]},{"w":"installment","t":"n. 分期付款，分期交付；部分","p":"ɪn'stɔːlmənt","e":["Now she can reduce the installment size that she can afford to pay, by extending the loan period.","现在，她就可通过展延贷款周期来减小自己有能力支付的分期付款的规模。"]},{"w":"instance","t":"n. 例子，实例，事例","p":"'ɪnstəns","e":["We need to rethink the way we consume energy. Take, for instance, our approach to transport.","我们需要重新考虑我们使用能源的方式，例如我们的运输方式。"]},{"w":"instant","t":"adj. 立即的","p":"ˈɪnstənt","c":1,"e":["a system that provides instant access to client information","能立即查到客户信息的系统"]},{"w":"instantaneous","t":"adj. 即时的，瞬间的","p":"ˌɪnstənˈteɪniəs","c":1,"e":["modern methods of instantaneous communication","现代的即时通信方法"]},{"w":"instinct","t":"n. 本能；直觉，生性","p":"'ɪnstɪŋkt","e":["Her instinct told her that something was wrong.","直觉告诉她有些不对劲。"]},{"w":"instinctively","t":"adv. 本能地","p":"ɪn'stɪŋktɪvlɪ","c":1,"e":["He knew instinctively that something was wrong.","他凭直觉知道出事了。"]},{"w":"institute","t":"n. 研究所，学会，学院","p":"'ɪnstɪtjuːt","c":1,"e":["research institutes","研究所"]},{"w":"institution","t":"n. 机构","p":"ˌɪnstɪˈtju:ʃn","c":1,"e":["powerful institutions such as world banks","诸如世界银行之类的强大机构"]},{"w":"instruct","t":"vt. 教，指示；通知；教育","p":"ɪn'strʌkt","e":["Eva went straight to the hotel, as instructed (= as she had been told ).","伊娃按照指示径直去了宾馆。"]},{"w":"instructional","t":"adj. 指导的，教育的","p":"ɪn'strʌkʃənl","e":["...instructional material designed to help you with your lifestyle.","...旨在为你的生活方式提供帮助的指导材料。"]},{"w":"instructor","t":"n. 指导者，教员","p":"ɪn'strʌktə","e":["a driving instructor","驾驶教练"]},{"w":"instrument","t":"n. 仪器，工具；乐器","p":"'ɪnstrəmənt","e":["surgical instruments","外科(手术)器械"]},{"w":"instrumental","t":"adj. 起作用的，有帮助的；用乐器演奏的","p":"ˌɪnstrə'mentl","e":["He was instrumental in developing links with European organizations.","他在建立与欧洲各组织之间的联系中起了重要作用。"]},{"w":"insufficient","t":"adj. 不足的","p":"ˌɪnsə'fɪʃnt","c":1,"e":["Insufficient resources have been devoted to the health service.","用于医疗保健服务的资源不足。"]},{"w":"insulate","t":"vt. 使绝缘，使隔热，使隔音；隔离，使隔绝","p":"'ɪnsjuleɪt","e":["an insulated attic","隔热[隔音]的阁楼"]},{"w":"insulation","t":"n. 绝缘","p":"ˌɪnsju'leɪʃn","e":["Good insulation can save you money on heating bills.","好的隔热效果能节省暖气费。"]},{"w":"insulator","t":"n. 隔离者；绝缘体","p":"'ɪnsjʊleɪtə","e":["Wood is an excellent insulator.","木材是很好的绝缘体。"]},{"w":"insurance","t":"n. 保险；保险费","p":"ɪn'ʃuərəns","e":["Your father took out insurance to cover the mortgage.","你父亲购买了抵押借款保险。"]},{"w":"insurer","t":"n. 保险公司；承保人","p":"ɪn'ʃʊərə","c":1,"e":["The insurer will also have to pay the additional costs of the trial.","保险公司将不得不支付审判的额外费用。"]},{"w":"intact","t":"adj. 完整无缺的；未经触动的；未受损伤的","p":"ɪn'tækt","e":["Only the medieval tower had remained intact.","只有这座中世纪塔楼保存完好。"]},{"w":"intake","t":"n. 吸入；输入能量","p":"'ɪnteɪk","e":["Try to reduce your intake of fat.","尽量减少脂肪的摄入量。"]},{"w":"integral","t":"adj. 必需的，不可缺少的","p":"ˈɪntɪɡrəl","c":1,"e":["Vegetables are an integral part of our diet.","蔬菜是我们膳食中不可缺少的一部分。"]},{"w":"integrate","t":"v. 使结合，使并入","p":"'ɪntɪgreɪt","e":["These programs can be integrated with your existing software.","这些程序能和你的已有的软件整合成一体。"]},{"w":"integrity","t":"n. 正直","p":"ɪnˈtegrəti","c":1,"e":["I have always regarded him as a man of integrity.","我一直把他当作一个正直诚实的人。"]},{"w":"intellect","t":"n. 智力，理解力；才智非凡的人","p":"'ɪntəlekt","e":["Do the emotions develop in parallel with the intellect?","情感与智力同步发展吗？"]},{"w":"intellectual","t":"adj. 智力的；n. 知识分子","p":"ˌɪntə'lektʃuəl","e":["Mark’s very intellectual.","马克很聪明。"]},{"w":"intelligent","t":"adj. 聪明的","p":"ɪnˈtelɪdʒənt","c":1,"e":["Sontag was once famously described as the most intelligent woman in America.","桑塔格曾被称为美国最聪明的女人，这是众人皆知的事。"]},{"w":"intelligible","t":"adj. 可理解的，明白易懂的，清楚的","p":"ɪn'telɪdʒəbl","e":["His reply was barely intelligible.","他的回复几乎让人听不懂。"]},{"w":"intense","t":"adj. 激烈的，强烈的","p":"ɪnˈtens","c":1,"e":["Young people today are under intense pressure to succeed.","如今的年轻人面临要出人头地的巨大压力。"]},{"w":"intensely","t":"adv. 强烈地","p":"ɪn'tenslɪ","c":1,"e":["The fast-food business is intensely competitive.","快餐业竞争非常激烈。"]},{"w":"intensify","t":"v. 增强，加剧","p":"ɪn'tensɪfaɪ","e":["His mother’s death intensified his loneliness.","母亲的过世使他感到更加孤单。"]},{"w":"intensive","t":"adj. 加强的；精耕细作的","p":"ɪn'tensɪv","e":["a one-week intensive course in English","为期一周的英语强化课程"]},{"w":"intent","t":"adj. 专心的，专注的；急切的；n. 意图，意向，目的","p":"ɪn'tent","e":["his intent gaze","他专注的凝视"]},{"w":"interact","t":"v. 互动","p":"ˌɪntər'ækt","c":1,"e":["While the other children interacted and played together, Ted ignored them.","当其他孩子们相互交往、一起玩耍时，泰德却不理他们。"]},{"w":"interaction","t":"n. 相互影响，相互作用；互动","p":"ˌɪntər'ækʃn","c":1,"e":["Price is determined through the interaction of demand and supply.","价格是通过供需消长而定的。"]},{"w":"interactive","t":"adj. 〔人与计算机程序、电视系统等〕交互的，互动的；合作的；相互交流的","p":"ɪntər'æktɪv","c":1,"e":["interactive teaching methods such as role playing","诸如角色扮演等的互动教学法"]},{"w":"interconnect","t":"v. 使互相联系","p":"ɪntəkə'nekt","e":["Our operating system can now interconnect with other networks.","我们的操作系统现在能和其他网络相连。"]},{"w":"intercourse","t":"n. 性交；交流，交往，交际","p":"'ɪntəkɔːs","e":["social intercourse","社交"]},{"w":"interface","t":"n. 分界面","p":"'ɪntəfeɪs","e":["...the development of better user interfaces.","…更好用户界面的开发。"]},{"w":"interfere","t":"adj. 干涉；妨碍","p":"ˌɪntəˈfɪə(r)","c":1,"e":["Anxiety can interfere with children’s performance at school.","焦虑会影响孩子在学校的表现。"]},{"w":"interference","t":"n. 干涉","p":"ˌɪntəˈfɪərəns","c":1,"e":["Industrial relations should be free from state interference.","劳资关系应不受政府干预。"]},{"w":"interim","t":"adj. 暂时的，临时的；n. 间歇，过渡期间","p":"'ɪntərɪm","e":["He received an interim payment of £10,000.","他收到暂时支付的一万英镑。"]},{"w":"interior","t":"n. 内部；adj. 内部的","p":"ɪn'tɪɜːrɪə","e":["The interior walls are all painted white.","室内墙壁都粉刷成了白色。"]},{"w":"intermediate","t":"n. 中间体；调解人","p":",ɪntə'miːdɪət"},{"w":"intermittent","t":"adj. 间歇的，断断续续的","p":"ˌɪntə'mɪtənt","e":["The weather forecast is for sun, with intermittent showers.","天气预报为晴，有阵雨。"]},{"w":"internal","t":"adj. 内的，国内的；内心的","p":"ɪn'tɜːnl","e":["We have no interest in interfering in the internal affairs of other countries.","我们对干涉其他国家内政不感兴趣。"]},{"w":"interpersonal","t":"adj. 人与人之间的，关于人与人之间关系的","p":"ˌɪntə'pɜːsənl","e":["interpersonal communication","人际沟通"]},{"w":"interpret","t":"v. 口译；解释","p":"ɪnˈtɜ:prɪt","c":1,"e":["They spoke good Spanish, and promised to interpret for me.","他们西班牙语说得很好，答应替我翻译。"]},{"w":"interpretation","t":"n. 解释，理解","p":"ɪnˌtɜ:prɪˈteɪʃn","c":1,"e":["It’s difficult to put an accurate interpretation on (= explain ) the survey results.","对调查结果难以作出确切的解释。"]},{"w":"interracial","t":"adj. 种族间的","p":"ˌɪntəˈreɪʃl","c":1,"e":["interracial marriage","种族间的通婚"]},{"w":"interrupt","t":"v. 打断，中止；打扰","p":"ˌɪntə'rʌpt","e":["Sorry to interrupt, but I need to ask you to come downstairs.","很抱歉打扰了，我得请你下楼来。"]},{"w":"intersection","t":"n. 道路交叉口，交点","p":"ˌɪntə'sekʃn","e":["We crossed at a busy intersection.","我们穿过了一个繁忙的道路交叉口。"]},{"w":"intertwine","t":"v. 交织，纠缠","p":"ˌɪntəˈtwaɪn","c":1,"e":["a necklace of rubies intertwined with pearls","缠着珍珠的红宝石项链"]},{"w":"intervene","t":"v. 干涉","p":"ˌɪntə'vi:n","c":1,"e":["The army will have to intervene to prevent further fighting.","军队将不得不干预以阻止进一步的战斗。"]},{"w":"intervention","t":"n. 干涉","p":"ˌɪntə'venʃn","c":1,"e":["government intervention to regulate prices","政府介入控制物价"]},{"w":"interview","t":"v. 接见，会见，会谈","p":"'ɪntəvjuː","e":["a police interview","警方问讯"]},{"w":"intimate","t":"adj. 亲密的","p":"ˈɪntɪmət","c":1,"e":["She’s on intimate terms with people in government.","她与政府官员关系密切。"]},{"w":"intimidate","t":"vt. 恐吓，威胁","p":"ɪn'tɪmɪdeɪt","e":["Attempts to intimidate her failed.","恐吓她的企图失败了。"]},{"w":"intolerant","t":"adj. 无法容忍的","p":"ɪn'tɒl(ə)r(ə)nt","c":1,"e":["people who are intolerant of other people’s political beliefs","不能容忍他人政治信仰的人"]},{"w":"intonation","t":"n. 语调，声调；发声","p":"ɪntə'neɪʃ(ə)n","e":["intonation patterns","语调类型"]},{"w":"intricacy","t":"n. 错综复杂；","p":"'ɪntrɪkəsi","e":["the intricacies of private banking","私人银行业务的错综复杂"]},{"w":"intricate","t":"adj. 错综复杂的，复杂精细的","p":"'ɪntrɪkət","e":["intricate patterns","繁复的图案"]},{"w":"intrigue","t":"vi. 耍阴谋，施诡计；vt. 激起…的好奇心，迷住；n. 阴谋，诡计，密谋","p":"ɪn'triːg","e":["Other people’s houses always intrigued her.","别人的房子总令她好奇。"]},{"w":"intriguing","t":"adj. 有趣的","p":"ɪnˈtri:gɪŋ","c":1,"e":["The magazine carries an intriguing mixture of high fashion, gossip and racing.","这本杂志内容丰富有趣，有关时尚、花边新闻和赛马的内容都有。"]},{"w":"intrinsic","t":"adj. 本质的，固有的","p":"ɪnˈtrɪnsɪk","c":1,"e":["the intrinsic interest of the subject","该话题本身的趣味"]},{"w":"introduce","t":"v. 提出（议案等）","p":"ɪntrə'djuːs","e":["Several senators introduced legislation aimed at sexual harassment.","几位参议员提交了针对性骚扰的立法议案。"]},{"w":"intuition","t":"n. 直觉；由直觉获知的信息","p":"ˌɪntju'ɪʃn","e":["Intuition told her it was unwise to argue.","直觉告诉她争吵是不理智的。"]},{"w":"intuitive","t":"adj. 直觉的","p":"ɪnˈtju:ɪtɪv","c":1,"e":["He seemed to have an intuitive awareness of how I felt.","他好像凭直觉就知道我的感受。"]},{"w":"invalid","t":"adj. 无效的，作废的；无可靠根据的，站不住脚的；n. 病弱者，残疾者","p":"ɪn'vælɪd","e":["Without the right date stamped on it, your ticket will be invalid.","票上若没有加盖正确日期就是废票。"]},{"w":"invaluable","t":"adj. 非常宝贵的，极为贵重的，无价的","p":"ɪn'væljuəbl","e":["The internet is an invaluable source of information.","因特网是十分有价值的信息来源。"]},{"w":"invariably","t":"adv. 不变地，始终如一地，总是","p":"ɪn'veəriəbli","e":["The security guards were invariably ex-servicemen.","保安人员毫无例外地都是退伍军人。"]},{"w":"invasion","t":"n. 入侵","p":"ɪnˈveɪʒn","c":1,"e":["the invasion of Normandy","对诺曼底的入侵"]},{"w":"invasive","t":"adj. 入侵的","p":"ɪnˈveɪsɪv","c":1,"e":["invasive bladder cancers","扩散性膀胱癌"]},{"w":"inventory","t":"n. 详细目录，存货清单","p":"'ɪnvəntri","e":["...one inventory of twelve sails for each yacht.","…为每艘游艇配备12张帆的存货。"]},{"w":"inversely","t":"adv. 相反地","p":"'ɪnvɜːslɪ","e":["We regard health as inversely related to social class.","我们认为健康状况与社会地位成相反关系。"]},{"w":"invert","t":"vt. 使倒转，使倒置，使颠倒","p":"ɪn'vɜːt","e":["Invert the cake onto a serving plate.","把蛋糕倒扣过来放到一个盘子上。"]},{"w":"invest","t":"v. 投资，投入；授予","p":"ɪn'vest","e":["I’ve got a few thousand dollars I’m looking to invest.","我有几千美元想作投资。"]},{"w":"investigate","t":"v. 调查，研究","p":"ɪn'vestɪgeɪt","e":["The study investigates the impact of violent TV programming on children.","该研究调查暴力电视节目对儿童的影响。"]},{"w":"invisible","t":"adj. 看不见的，无形的","p":"ɪn'vɪzəbl","e":["The house was surrounded by trees, and invisible from the road.","这所房子树木环绕，从路上是看不见的。"]},{"w":"invoice","t":"n. 发票，发货清单","p":"'ɪnvɒɪs","e":["We will then send you an invoice for the total course fees.","然后我们将寄给你一张全部课程费用的发票。"]},{"w":"involve","t":"vt. 使卷入，牵涉；包含，含有","p":"ɪn'vɒlv","e":["I didn’t realize putting on a play involved so much work.","我没想到上演一出戏剧需要做这么多的工作。"]},{"w":"involvement","t":"n. 连累；包含","p":"ɪn'vɒlvmənt","e":["School officials say they welcome parental involvement.","校方说他们欢迎学生父母参与。"]},{"w":"ion","t":"n. 离子","p":"'aɪən"},{"w":"irony","t":"n. 讽刺","p":"'aɪrənɪ","c":1,"e":["His tone was tinged with irony.","他的语气中微含讽刺。"]},{"w":"irrational","t":"adj. 不合理的，不理性的","p":"ɪ'ræʃ(ə)n(ə)l","c":1,"e":["He’s becoming increasingly irrational.","他变得越来越不可理喻了。"]},{"w":"irregularity","t":"n. 不规则；不整齐","p":"ɪ,regjʊ'lærɪtɪ","e":["The paint will cover any irregularity in the surface of the walls.","油漆会遮盖住墙壁上任何不平整的地方。"]},{"w":"irrelevant","t":"adj. 无关的","p":"ɪˈreləvənt","c":1,"e":["We’re focussing too much on irrelevant details.","我们过于关注不相干的细节。"]},{"w":"irrespective","t":"adj. 不考虑的，不顾及的","p":"ˌɪrɪ'spektɪv"},{"w":"irreversible","t":"adj. 不可逆的；不可取消的","p":"ˌɪrɪˈvɜ:səbl","c":1,"e":["Fossil fuels have caused irreversible damage to the environment.","矿物燃料已对环境造成了不可挽回的破坏。"]},{"w":"irrigation","t":"n. 灌溉","p":"ˌɪrɪˈɡeʃn","c":1,"e":["In the United States, by contrast, 41% goes for agriculture, almost all of it for irrigation.","与之相比，美国全年41%的水投向了农业，并几乎全都用在了灌溉上。"]},{"w":"irritate","t":"v. 激怒","p":"'ɪrɪteɪt","c":1,"e":["It really irritates me when he doesn’t help around the house.","家里的事情他一点都不帮忙，真让我恼火。"]},{"w":"Islam","t":"n. 伊斯兰教，回教","p":"'izlɑ:m","e":["He converted to Islam at the age of 16.","他在16岁时皈依了伊斯兰教。"]},{"w":"isle","t":"n. 小岛，岛","p":"aɪl","e":["the British Isles","不列颠群岛"]},{"w":"isolate","t":"v. 使隔离","p":"ˈaɪsəleɪt","c":1,"e":["The US has sought to isolate Cuba both economically and politically.","美国一直想在经济和政治上孤立古巴。"]},{"w":"isolation","t":"n. 隔绝，隔离","p":"ˌaɪsəˈleɪʃn","c":1,"e":["Because of its geographical isolation, the area developed its own unique culture.","由于地理上的隔绝，该地区发展了自己独特的文化。"]},{"w":"issue","t":"v. 发行；分发，发出；n. 问题；发行；分发","p":"'ɪʃuː","e":["Silva issued a statement denying all knowledge of the affair.","西尔瓦发表声明，宣称对此事一无所知。"]},{"w":"item","t":"n. 条，条款","p":"'aɪtəm","e":["He opened the cardboard box and took out each item.","他打开纸板箱把里面的物品一一拿出来。"]},{"w":"ivory","t":"n. 象牙；象牙色，乳白色","p":"'aɪvəri","e":["an ivory chess set","一副象牙国际象棋"]},{"w":"jack","t":"n. 起重器；传动装置","p":"dʒæk","e":["a hydraulic jack","液压千斤顶"]},{"w":"jail","t":"n. 监狱","p":"dʒeɪl","c":1,"e":["He’s been in jail for three months already.","他已经入狱三个月。"]},{"w":"jam","t":"n. 堵塞；v. 使…堵塞","p":"dʒæm","e":["Hundreds of departing motorists jammed the roads.","数百名打算驾车离开的司机堵住了道路。"]},{"w":"jealousy","t":"n. 妒忌，嫉妒，猜忌","p":"'dʒeləsɪ","e":["He quickly discovered the petty jealousies and gossip of village life.","他很快就发现，在乡村生活中，人们狭隘善妒，喜欢传播流言蜚语。"]},{"w":"jean","t":"n. 斜纹布；牛仔裤","p":"dʒiːn","e":["a young man in jeans and a worn T-shirt","一个穿着牛仔裤和破旧T恤衫的年轻人"]},{"w":"jelly","t":"n. 冻，果冻；胶状物","p":"'dʒelɪ","e":["frogs’ eggs floating in a protective jelly","包在胶质卵囊里浮在水中的蛙卵"]},{"w":"jeopardize","t":"v. 危害，危及","p":"ˈdʒepədaɪz","c":1,"e":["large-scale military offensives which could jeopardize the UN peace process","可能会破坏联合国和平进程的大规模军事进攻"]},{"w":"jerk","t":"v. 猝然一动，猛拉；n. 急推，急拉，急扭","p":"dʒɜːk","e":["‘Is that the only way out of here?’ he asked, jerking a thumb at the door.","“那是这里唯一的出口吗？”他用拇指指了指门口问道。"]},{"w":"Jesus","t":"n. 耶稣","p":"'dʒiːzəs","e":["As a scientist,he disbelieves in Jesus.","作为一名科学家，他不信耶稣。"]},{"w":"jewellery","t":"n. 珠宝，珠宝饰物","p":"'dʒuːəlrɪ","e":["She wears a lot of gold jewelry.","她戴了许多金首饰。"]},{"w":"jingle","t":"v. （使）丁当响","p":"'dʒɪŋg(ə)l","e":["He jingled his car keys.","他把汽车钥匙弄得叮当响。"]},{"w":"jog","t":"n&v. 慢跑；轻轻碰撞","p":"dʒɒg","e":["I go jogging every morning.","我每天早晨都去慢跑。"]},{"w":"judicial","t":"adj. 司法的","p":"dʒuˈdɪʃl","c":1,"e":["...an independent judicial system.","…一个独立的司法体系。"]},{"w":"jug","t":"n. 带柄水罐，大壶","p":"dʒʌg","e":["a five-gallon jug of beer","五加仑装的啤酒罐"]},{"w":"junction","t":"n. 联结点，交叉点，枢纽","p":"'dʒʌŋkʃn","e":["the junction of Abbot Road and Mill Street","阿伯特路与米尔街的交叉口"]},{"w":"jungle","t":"n. 丛林，密林，莽丛","p":"'dʒʌŋg(ə)l","e":["the Amazon jungle","亚马孙丛林"]},{"w":"junior","t":"n. 年少者；晚辈","p":"'dʒuːnɪə","e":["She now lives with actor Denis Lawson, 10 years her junior.","她现在和比她小10岁的演员丹尼斯·劳森同居。"]},{"w":"junk","t":"n. 废旧物品，破烂；vt. 丢弃，废弃","p":"dʒʌŋk","e":["This cupboard’s full of junk.","这个壁橱里塞满了杂物。"]},{"w":"Jupiter","t":"n. 木星；丘庇特","p":"'dʒuːpɪtə","e":["a space probe on its way to Jupiter","飞向木星的一个太空探测器"]},{"w":"jury","t":"n. 陪审团","p":"'dʒʊərɪ","c":1,"e":["The jury found him not guilty.","陪审团裁定他无罪。"]},{"w":"justice","t":"n. 公平","p":"'dʒʌstɪs","c":1,"e":["His people came to him demanding justice.","他的手下来找他，寻求公正。"]},{"w":"justifiable","t":"adj. 理所应当的","p":"ˈdʒʌstɪfaɪəbl","c":1,"e":["Are these experiments morally justifiable?","这些实验合乎道德准则吗？"]},{"w":"justification","t":"n. 正当的理由，借口","p":"ˌdʒʌstɪfɪ'keɪʃn","e":["Hoggart felt, with some justification, that his colleagues had let him down.","霍加特觉得同事令他失望，这是有理由的。"]},{"w":"justified","t":"adj. 正当的","p":"'dʒʌstɪfaɪd","c":1,"e":["In the Chief Constable’s view, the use of force was fully justified.","在警察局局长看来，使用武力是完全正当的。"]},{"w":"justify","t":"vt. 证明…是正当的","p":"'dʒʌstɪfaɪ","e":["Nothing justifies murdering another human being.","什么都不能成为谋杀他人的正当理由。"]},{"w":"juvenile","t":"adj. 少年的，少年特有的；幼稚的，不成熟的；n. 未成年人，少年","p":"'dʒuːvənaɪl","e":["The number of juveniles in the general population has fallen by a fifth in the past 10 years.","在过去的10年中，青少年在总人口中所占的比重下降了1/5。"]},{"w":"keen","t":"adj. 敏锐的；浓厚的","p":"ki:n","c":1,"e":["He took a keen interest in his grandson's education.","他对孙子的教育很感兴趣。"]},{"w":"kernel","t":"n. （果实的）核；谷粒","p":"'kɜːn(ə)l","e":["The nutshell includes the kernel.","果壳裹着果仁。"]},{"w":"kidnap","t":"v. 绑架","p":"'kɪdnæp","c":1,"e":["Police appealed for witnesses after a woman was kidnapped at gunpoint.","一名妇女遭到持枪绑架，警方呼吁目击者挺身而出。"]},{"w":"kidney","t":"n. 肾，肾脏","p":"'kɪdni","e":["a kidney transplant","肾脏移植"]},{"w":"kilowatt","t":"n. 千瓦（特）","p":"'kɪləwɒt","e":["a prototype system which produces 25 kilowatts of power","一个生产25千瓦电量的样机"]},{"w":"kindle","t":"v. 点燃，着火","p":"'kɪnd(ə)l","e":["We watched as the fire slowly kindled.","我们看着火慢慢地燃烧起来。"]},{"w":"kinetic","t":"adj. 动力（学）的；活动的","p":"kɪ'netɪk; kaɪ-","e":["kinetic energy","动能"]},{"w":"kit","t":"n. 成套工具，成套用品；配套元件；vt. 装备","p":"kɪt","e":["Sally keeps her make-up kit in her bag.","萨莉把化妆包放在手提包里。"]},{"w":"knight","t":"n. 骑士，武士；爵士","p":"naɪt","e":["He hopes to be made a knight for his work at the Bank of England.","他希望因为他在英格兰银行的工作而被封为爵士。"]},{"w":"knit","t":"vi. 编结，编织；愈合；vt. 编结，编织；使紧密地结合，使紧凑；皱紧，皱","p":"nɪt","e":["My grandmother taught me how to knit.","我祖母教过我编织。"]},{"w":"knob","t":"n. 球形把手，球形柄；旋钮；小块","p":"nɒb","e":["He thought the door was locked, but he turned the knob and the door opened.","他本以为门是锁住的，但是转了一下把手门就开了。"]},{"w":"label","t":"n. 标签，标记，符号；vt. 贴标签于；把…称为","p":"'leɪbl","e":["a luggage label","行李标签"]},{"w":"lace","t":"n. 网眼花边，透孔织品；鞋带，系带；vt. 用系带束紧","p":"leɪs","e":["a handkerchief trimmed with lace","饰有蕾丝花边的手绢"]},{"w":"lack","t":"v. 缺少","p":"læk","c":1,"e":["Alex’s real problem is that he lacks confidence.","亚历克斯的真正问题是缺乏信心。"]},{"w":"lag","t":"v. 落后","p":"læɡ","c":1,"e":["Western banks still lag behind financial institutions in most other regions of the country.","西部地区的银行仍然落后于这个国家其他大部分地区的金融机构。"]},{"w":"lame","t":"adj. 跛的，瘸的；站不住脚的，差劲的；蹩脚的","p":"leɪm","e":["a lame attempt to deflect criticism","转移批评的一个无力的尝试"]},{"w":"landmark","t":"n. 地标","p":"'lændmɑrk","c":1,"e":["One of Belfast’s most famous landmarks, the Grosvenor Hall, has been demolished.","贝尔法斯特最著名的地标之一格罗夫纳大厦已被拆毁了。"]},{"w":"landscape","t":"n. 风景，景色，景致","p":"'læn(d)skeɪp","e":["the beauty of the New England landscape","新英格兰风光之美"]},{"w":"lane","t":"n. 小路，跑道；航道，航线","p":"leɪn","e":["a quiet country lane","一条宁静的乡间小路"]},{"w":"largely","t":"adv. 主要地","p":"'lɑːdʒlɪ","e":["It had been a tiring day, largely because of all the tedious waiting.","那一天真累人，主要是因为等得无聊。"]},{"w":"lash","t":"v. 将系牢；鞭打，抽打；猛烈打击；猛烈抨击，严厉斥责；n. 鞭打；假睫毛；鞭梢","p":"læʃ","e":["Giant waves lashed the sea wall.","巨浪拍打着海堤。"]},{"w":"late","t":"adj. 去世不久的","p":"leɪt","e":["Billy Hicks, late of this parish","不久前故去的本教区的比利·希克斯"]},{"w":"latent","t":"adj. 潜在的，隐伏的，不易察觉的","p":"'leɪtnt","e":["latent aggression","潜在的侵略"]},{"w":"lathe","t":"n. 车床；v. 用车床加工","p":"leɪð"},{"w":"latitude","t":"n. 纬度；纬度地区；回旋余地，自由","p":"'lætɪtjuːd","e":["The birds breed in northern latitudes.","这些鸟在北纬地区繁殖。"]},{"w":"lattice","t":"n. 格子结构","p":"'lætɪs","e":["We were crawling along the narrow steel lattice of the bridge.","我们沿着大桥窄窄的钢制格子爬行着。"]},{"w":"launch","t":"v. 发布，推出","p":"lɔ:ntʃ","c":1,"e":["The company hopes to launch the new drug by next October.","公司希望于明年10月前推出这种新药。"]},{"w":"laundry","t":"n. 送洗衣店去洗的东西","p":"'lɔːndrɪ","e":["She did the laundry (= washed the clothes etc ) and hung it out to dry.","她洗了衣服，然后挂出去晾干。"]},{"w":"lawn","t":"n. 草坪","p":"lɔ:n","c":1,"e":["I spent all morning mowing the lawn (= cutting the grass ).","我整个上午都在修剪草坪。"]},{"w":"lawsuit","t":"n. 诉讼","p":"ˈlɔ:su:t","c":1,"e":["The dispute culminated last week in a lawsuit against the government.","这场针对政府诉讼案的争论在上星期达到了高潮。"]},{"w":"layer","t":"n. 层，层次","p":"'leɪə","e":["He pulled off layer upon layer of clothing (= many layers of clothing ).","他把衣服一件件地脱掉。"]},{"w":"layman","t":"n. 门外汉","p":"'leɪmən","c":1,"e":["To the layman (= laymen in general ) all these plants look pretty similar.","对外行的人来说，这些植物看起来都很相似。"]},{"w":"layoff","t":"n. 解雇；裁员；歇工期，停工期","p":"'leɪɒf","e":["It will close more than 200 stores nationwide resulting in the layoffs of an estimated 2,000 employees.","在全国范围内将关闭二百多家商店，造成约两千人失业。"]},{"w":"layout","t":"n. 布局，设计","p":"ˈleɪaʊt","c":1,"e":["All the flats in the building had the same layout.","大楼里所有的公寓布局都是一样的。"]},{"w":"leaflet","t":"v. 散发传单；n. 传单，散页印刷品，小册子","p":"'liːflət","e":["He’s leafleting the neighbourhood.","他在向街区居民散发传单。"]},{"w":"leakage","t":"n. 漏，泄漏；漏出物","p":"'liːkɪdʒ","e":["a leakage of toxic waste into the sea","有毒废物的泄漏入海"]},{"w":"lease","t":"n. 租约，租契；vt. 出租；租得，租有","p":"liːs","e":["Do you understand all the terms of the lease?","租约条款你都理解吗？"]},{"w":"leather","t":"n. 皮革；皮革制品","p":"'leðə","e":["The inside of the bag was lined with soft leather.","这包的里面衬了软皮。"]},{"w":"legal","t":"adj. 法律的；合法的","p":"'liːgl","e":["plans to make the carrying of identity cards a legal requirement","使携带身份证成为法定要求的计划"]},{"w":"legalize","t":"v. 合法化","p":"'liɡəlaɪz","c":1,"e":["Divorce was legalized in 1981.","离婚在1981年被合法化了。"]},{"w":"legend","t":"n. 传奇","p":"'ledʒənd","c":1,"e":["Local legend has it that (= says that ) the island was the original Garden of Eden.","当地传说这个岛就是伊甸园的原型。"]},{"w":"legislation","t":"n. 立法","p":"ˌledʒɪsˈleɪʃn","c":1,"e":["...a letter calling for legislation to protect women's rights.","…呼吁立法保护妇女权利的一封信。"]},{"w":"legislator","t":"n. 立法者","p":"ˈledʒɪsleɪtə(r)","c":1,"e":["...an attempt to get U.S. legislators to change the system.","…让美国立法者改变体制的一次努力。"]},{"w":"legitimate","t":"adj. 合情合理的；合理的，法律认可的；vt. 使合法","p":"lɪ'dʒɪtɪmət","e":["Most scientists believe it is legitimate to use animals in medical research.","大多数科学家认为用动物作医学研究是正当的。"]},{"w":"leisure","t":"n. 空闲时间；悠闲","p":"'leʒə","e":["The hotel offers various leisure facilities such as a swimming pool and sauna.","酒店提供游泳池、桑拿浴室等各种休闲设施。"]},{"w":"length","t":"n. 长度","p":"leŋθ","e":["It is about a metre in length.","它大约有一米长。"]},{"w":"lengthen","t":"v. 使延长，变长","p":"'leŋθ(ə)n; -ŋkθ-","e":["The days lengthened as summer approached.","随着夏天来临，白天变长了。"]},{"w":"lens","t":"n. 透镜，镜片；镜头","p":"lenz","e":["a standard 50mm lens","50毫米标准镜头"]},{"w":"leopard","t":"n. 豹","p":"'lepəd","e":["The young leopard separated from its mother would be eaten by other beast.","与母亲离散的幼豹很可能被其他的野兽吃掉。"]},{"w":"lessen","t":"v. 减少","p":"ˈlesn","c":1,"e":["Gradually her anxiety lessened.","她的焦虑慢慢减轻了。"]},{"w":"lest","t":"conj. 以免","p":"lest","c":1,"e":["She turned away from the window lest anyone see them.","她转身离开窗边，免得有人看见他们。"]},{"w":"lever","t":"n. 杠，杠杆；途径，手段，工具；vt. 撬动，撬起","p":"'liːvə","e":["Pull this lever to open the gate.","拉此横杆开启大门。"]},{"w":"levy","t":"vt. 征收；n. 征税，税款","p":"'levi","e":["They levied religious taxes on Christian commercial transactions.","他们对基督教的商业交易征收宗教税。"]},{"w":"liability","t":"n. 责任；债务","p":"laɪə'bɪlɪtɪ","c":1,"e":["The company had assets of $138 million and liabilities of $120.5 million.","该公司有1.38亿美元资产和1.205亿美元的负债。"]},{"w":"liable","t":"adj. 易于…的，可能的","p":"'laɪəbl","e":["The car is liable to overheat on long trips.","这辆汽车跑长途容易过热。"]},{"w":"liberal","t":"adj. 心胸宽大的，慷慨的；自由的，自由主义的","p":"'lɪbərəl","e":["a more liberal attitude towards sexuality","对两性关系比较开通的态度"]},{"w":"liberation","t":"n. 解放","p":"ˌlɪbə'reɪʃn","c":1,"e":["They consecrated their lives to the liberation of their motherland.","他们把生命献给了祖国的解放事业。"]},{"w":"lieutenant","t":"n. 陆军中尉；海军上尉","p":"lef'tenənt"},{"w":"lighter","t":"n. 打火机，引燃器","p":"'laɪtə","e":["a cigarette lighter","香烟打火机"]},{"w":"likelihood","t":"n. 可能，可能性","p":"'laɪklihud","e":["If I refused, it would in all likelihood mean I’d lose my job.","如果我拒绝，那我十有八九会丢掉工作。"]},{"w":"likeness","t":"n. 同样；类似，相似","p":"'laɪknɪs","e":["I can see the family likeness.","我看出这一家人都长得很像。"]},{"w":"lily","t":"n. 百合，百合花","p":"'lɪlɪ"},{"w":"limb","t":"n. 肢，臂，腿；树枝","p":"lɪm","e":["She would be able to stretch out her cramped limbs and rest for a few hours.","她将可以伸开蜷缩的四肢，休息几个小时。"]},{"w":"limestone","t":"n. 石灰石","p":"'laɪmstəʊn","e":["...high limestone cliffs.","…高耸的石灰岩峭壁。"]},{"w":"limitation","t":"n. 限制，限度；局限","p":"ˌlɪmɪ'teɪʃn","e":["a nuclear limitation treaty","核限制条约"]},{"w":"limp","t":"vi. 一瘸一拐地走，蹒跚；adj. 软弱的，无生气的，无精神的；软的，松沓的；n. 跛行","p":"lɪmp","e":["Moreno limped off the field with a foot injury.","莫雷诺脚上受了伤，一瘸一拐地走出球场。"]},{"w":"line","t":"v. 加衬里于","p":"laɪn","e":["Are those curtains lined?","那些窗帘加衬里了吗？"]},{"w":"linear","t":"adj. 线的，直线的，线状的；长度的；线性的","p":"'lɪniə","e":["a linear diagram","线形图"]},{"w":"linen","t":"n. 日用织品；亚麻织品，亚麻布","p":"'lɪnɪn","e":["table linen","桌布"]},{"w":"liner","t":"n. 衬里；大客轮","p":"'laɪnə","e":["a dustbin liner","垃圾袋"]},{"w":"linger","t":"v. 逗留，徘徊","p":"ˈlɪŋgə(r)","c":1,"e":["I spent a week at Kandersteg and could happily have lingered on.","我在坎德施泰格逗留了一个星期，本来还可以开开心心地多待几天。"]},{"w":"lining","t":"n. （衣服里的）衬里","p":"'laɪnɪŋ","e":["a jacket with a silk lining","有丝绸衬里的夹克"]},{"w":"lipstick","t":"n. 唇膏，口红","p":"'lɪpstɪk","e":["She was wearing red lipstick.","她涂着红色唇膏。"]},{"w":"literacy","t":"n. 识字，有文化","p":"ˈlɪtərəsi","c":1,"e":["a campaign to promote adult literacy","提高成人文化水平的运动"]},{"w":"literal","t":"adj. 字面的","p":"ˈlɪtərəl","c":1,"e":["A trade war is not a war in the literal sense.","贸易战不是字面意义上的战争。"]},{"w":"literally","t":"adv. 照字义，逐字地","p":"'lɪt(ə)rəlɪ","e":["I said I felt like quitting, but I didn’t mean it literally (= I did not mean exactly what I said )!","我是说我不想干了，但并不是真的不干了！"]},{"w":"literary","t":"adj. 文学的；文人的，书卷气的","p":"'lɪtərəri","e":["a literary prize","文学奖"]},{"w":"literature","t":"n. 文学，文学作品；文献，图书资料","p":"'lɪtərətʃə","e":["He has read many of the major works of literature.","他读过许多重要的文学作品。"]},{"w":"litter","t":"vi. 乱扔废弃物；vt. 乱扔东西；n. 废弃物，被胡乱扔掉的东西；一窝；杂乱的东西","p":"'lɪtə","e":["I hate people who litter in the forest.","我讨厌那些在森林里乱扔垃圾的人。"]},{"w":"lobby","t":"n. 游说","p":"'lɒbɪ","c":1,"e":["a mass lobby of Parliament by women’s organizations","妇女团体对议会的集体游说"]},{"w":"lobbyist","t":"n. 游说者","p":"'lɒbɪɪst","c":1,"e":["Lobbyists for the tobacco industry have expressed concerns about the restriction of smoking in public places.","烟草业的游说者们对在公共场所限制吸烟表示关切。"]},{"w":"locality","t":"n. 地区，地点","p":"ləu'kæləti","e":["weather reports from several different localities","来自几个不同地区的天气报告"]},{"w":"location","t":"n. 定位，测位","p":"lə(ʊ)'keɪʃ(ə)n","e":["The main problem for engineers was the location of underground rivers in the area.","工程师们面临的主要难题是要确定该地区地下河的位置。"]},{"w":"locomotive","t":"n. 机车","p":"ˌləukə'məutɪv","e":["A chamber, such as the furnace of a steam locomotive, in which fuel is burned.","火箱，燃烧室一种燃料在里面燃烧的内室，例如蒸汽机车的燃烧室。"]},{"w":"locust","t":"n. 蝗虫","p":"'ləʊkəst","e":["a swarm of locusts","一大群蝗虫"]},{"w":"lodging","t":"n. 寄宿，住宿；住所","p":"'lɒdʒɪŋ","e":["It’s £90 a week for board and lodging (= meals and a room ).","食宿费每周90英镑。"]},{"w":"lofty","t":"adj. 高耸的；崇高的","p":"'lɒftɪ","c":1,"e":["He stayed at the Four Seasons Hotel, from whose lofty heights he could see across New York.","他住在四季酒店，从酒店高处可以看到纽约的全景。"]},{"w":"log","t":"n. 航海日志；飞行日志","p":"lɒg","e":["The captain always keeps a log.","船长坚持记航海日志。"]},{"w":"logical","t":"adj. 逻辑的，合乎常理的","p":"'lɒdʒɪkl","e":["It’s a logical site for a new supermarket, with the housing development nearby.","附近有住宅区，新的超级市场选址在此是合情合理的。"]},{"w":"longevity","t":"n. 长寿，寿命","p":"lɒn'dʒevəti","e":["The ancient Chinese claimed that garlic promoted longevity.","中国古人说蒜能延寿。"]},{"w":"longing","t":"n. 渴望；adj. 显示渴望的","p":"'lɒŋɪŋ","e":["She looked back with longing on the good old days.","她回首往事，怀念着过去的美好时光。"]},{"w":"longitude","t":"n. 经线，经度","p":"'lɒn(d)ʒɪtjuːd; 'lɒŋgɪ-","e":["The town lies at longitude 12˚ east.","这个镇位于东经12度。"]},{"w":"loom","t":"vi. 阴森地逼近，隐现；即将来临；n. 织布机","p":"luːm","e":["An economic crisis is looming on the horizon .","经济危机正在逼近。"]},{"w":"loosely","t":"adv. 松松地，松散地","p":"'lu:slɪ","e":["She fastened the belt loosely around her waist.","她把皮带松松地系在腰上。"]},{"w":"loosen","t":"v. 变松","p":"'luːs(ə)n","e":["You’ll need a spanner to loosen that bolt.","你需要扳手来拧开那个螺栓。"]},{"w":"lounge","t":"n. 休息室","p":"laʊndʒ","c":1,"e":["the television lounge","电视放映室"]},{"w":"loyal","t":"adj. 忠诚的，忠心的","p":"'lɔɪəl","e":["her many years of loyal service to the company","她在公司多年的忠诚服务"]},{"w":"loyalty","t":"n. 忠诚，忠心","p":"'lɔɪəlti","e":["the agony of divided loyalties (= loyalty to two different or opposing people ) for the children in a divorce","父母离婚过程中孩子两面都要依顺的痛苦"]},{"w":"lubricate","t":"vt. 使润滑","p":"'luːbrɪkeɪt","e":["Lubricate all moving parts with grease.","给所有活动部件加润滑油。"]},{"w":"luggage","t":"n. 行李","p":"'lʌgɪdʒ","e":["They searched his luggage for illegal drugs.","他们搜查他的行李看是否藏有毒品。"]},{"w":"luminous","t":"adj. 发光的，发亮的；光明的","p":"'luːmɪnəs","e":["Her large dark eyes were almost luminous.","她那双黑色的大眼睛几乎是亮闪闪的。"]},{"w":"lump","t":"v. （使）成团，结块","p":"lʌmp"},{"w":"lunar","t":"adj. 月的，月球的","p":"'luːnə","e":["studies of the lunar surface","对月球表面的研究"]},{"w":"luncheon","t":"n. 午宴，午餐，便宴","p":"'lʌn(t)ʃ(ə)n","e":["Earlier this month, a luncheon for former U.N. staff was held in Vienna.","本月早些时候在维也纳为前联合国工作人员举行了午宴。"]},{"w":"lure","t":"vt. 吸引，引诱，诱惑；n. 吸引力，诱惑物；诱饵，鱼饵","p":"luə","e":["He lured her to his home and shot her with his father's gun.","他把她诱骗到家里，然后用父亲的枪把她打死。"]},{"w":"luxurious","t":"adj. 奢侈的，豪华的","p":"lʌgˈʒʊəriəs","c":1,"e":["a luxurious 30-room villa","一栋有30个房间的豪华度假别墅"]},{"w":"luxury","t":"n. 奢侈；奢侈品","p":"'lʌkʃəri","e":["He was leading a life of luxury in Australia.","他在澳大利亚过着豪华舒适的生活。"]},{"w":"machinery","t":"n. 机器，机械","p":"mə'ʃiːnəri","e":["...quality tools and machinery.","…优质工具和机械。"]},{"w":"magician","t":"n. 魔法师；变戏法的人","p":"mə'dʒɪʃ(ə)n","e":["There'll be a magician at the kids' Christmas party.","孩子们的圣诞聚会上会有一位魔术师。"]},{"w":"magistrate","t":"n. 地方行政官，地方法官；治安官","p":"'mædʒɪstreɪt","e":["She will face a local magistrate on Tuesday.","她将在星期二面见一位地方治安法官。"]},{"w":"magnet","t":"n. 磁铁，磁体；有吸引力的人和事物","p":"'mægnət","e":["Prospect Park, with its vast lake, is a magnet for all health freaks.","拥有大片湖区的展望公园是所有健身迷的向往之地。"]},{"w":"magnetic","t":"adj. 磁的；有吸引力的","p":"mæg'netɪk","e":["magnetic forces","磁力"]},{"w":"magnetism","t":"n. 磁；魅力","p":"'mægnɪtɪz(ə)m","e":["...his research in electricity and magnetism.","…他在电、磁领域的研究。"]},{"w":"magnificent","t":"adj. 壮丽的，华丽的；极好的","p":"mæg'nɪfɪsnt","e":["The twelve-mile coastline has magnificent sce-nery.","这12英里的海岸线景色壮观。"]},{"w":"magnify","t":"v. 放大","p":"'mæɡnɪfaɪ","c":1,"e":["At the Sheffield arena, the speakers were magnified ten times on a giant screen.","在谢菲尔德体育馆，演讲者在一个巨大的屏幕上被放大了十倍。"]},{"w":"magnitude","t":"n. 重要性，重大；巨大，广大","p":"'mægnɪtjuːd","e":["an increase of this order of magnitude","如此大幅度的增长"]},{"w":"maid","t":"n. 少女；处女","p":"meɪd"},{"w":"maiden","t":"n. 少女，未婚女子","p":"'meɪd(ə)n","e":["...stories of noble princes and their brave deeds on behalf of beautiful maidens.","…高贵的王子以及他们英雄救美的故事。"]},{"w":"main","t":"n. 总管道，干线","p":"meɪn","e":["The report found that many of Yorkshire’s water mains needed replacing.","报告中说约克郡的很多自来水总管道需要更换。"]},{"w":"maintain","t":"vt. 维持；维修，保养；主张；赡养","p":"meɪn'teɪn","e":["A lot depends on building and maintaining a good relationship with your customers.","和顾客建立并保持良好关系很重要，很多事情要取决于此。"]},{"w":"maintenance","t":"n. 维修","p":"'meɪntənəns","c":1,"e":["Engineers are carrying out essential maintenance work on the main line to Cambridge.","机修工正在对通往剑桥的干线进行必要的养护。"]},{"w":"majesty","t":"n. 陛下；雄伟，壮丽；庄严","p":"'mædʒəsti","e":["The Prime Minister is here to see you, Your Majesty.","首相前来拜谒，陛下。"]},{"w":"majority","t":"n. 大多数","p":"mə'dʒɒrətɪ","c":1,"e":["The Labour Party won a huge majority at the last general election.","工党在上次大选中以巨大的票数优势获胜。"]},{"w":"makeup","t":"n. 化妆品；性格；构造；组成","p":"meɪkʌp","e":["The ideological makeup of the unions is now radically different from what it had been.","这些协会的意识形态构成如今与过去大相径庭。"]},{"w":"malice","t":"n. 恶意；蓄意犯罪","p":"'mælɪs","e":["James bore her no malice (= did not feel any malice towards her ) .","詹姆斯对她并无恶意。"]},{"w":"malicious","t":"adj. 恶毒的","p":"mə'lɪʃəs","c":1,"e":["a malicious girl","恶毒的女孩"]},{"w":"mall","t":"n. 商场","p":"mɔ:l","c":1,"e":["If you see something you like at the mall, walk away.","如果在商城里看见某件你喜欢的东西，（别买）走开。"]},{"w":"mammal","t":"n. 哺乳动物","p":"'mæm(ə)l","e":["Humans, dogs, elephants, and dolphins are all mammals, but birds, fish, and crocodiles are not.","人、狗、大象和海豚都是哺乳动物，而鸟、鱼和鳄鱼则不是。"]},{"w":"management","t":"n. 管理；处理；管理部门，管理人员","p":"'mænɪdʒmənt","e":["a lack of management skills","缺乏管理技巧"]},{"w":"maneuver","t":"vi. 设法变动位置；用策略，耍花招；n. 谨慎而熟练的动作；策略，花招；演习；vt. 设法使变动位置；操纵，控制","p":"mə'nuːvə"},{"w":"manifest","t":"v. 表明","p":"'mænɪfest","c":1,"e":["The shareholders have manifested their intention to sell the shares.","股东们表明了要出售股票的意图。"]},{"w":"manipulate","t":"v. 操纵","p":"məˈnɪpjuleɪt","c":1,"e":["You have the constant feeling you are being manipulated.","你总感觉自己是被人控制着的。"]},{"w":"mansion","t":"n. 大厦，宅邸","p":"'mænʃn","e":["a beautiful country mansion","漂亮的乡村宅第"]},{"w":"manual","t":"adj. 手工的；体力的","p":"ˈmænjuəl","c":1,"e":["People in manual occupations have a lower life expectancy.","干体力活的人预期寿命较短。"]},{"w":"manufacture","t":"v. 生产，制造","p":"ˌmænjʊ'fæktʃə(r)","c":1,"e":["the company that manufactured the drug","生产这种药的公司"]},{"w":"manufacturer","t":"n. 制造商，制造厂","p":"ˌmænju'fæktʃərə","e":["Read the manufacturer’s instructions before using your new dishwasher.","使用新洗碗机之前，请先阅读厂家的说明书。"]},{"w":"manuscript","t":"n. 手稿","p":"ˈmænjuskrɪpt","c":1,"e":["Unfortunately, parts of the original manuscript have been lost.","遗憾的是，部分原始手稿丢失了。"]},{"w":"maple","t":"n. 槭树，枫树","p":"'meɪp(ə)l","e":["a maple leaf","枫叶"]},{"w":"marble","t":"n. 大理石；弹子；弹子游戏","p":"'mɑːbl","e":["The columns were of white marble.","柱子是白色的大理石。"]},{"w":"margin","t":"n. 利润","p":"'mɑːdʒɪn","c":1,"e":["Within 10 years they had a gross profit margin of 50%.","10年里他们的毛利率达到了50%。"]},{"w":"marginal","t":"adj. 微小的，少量的；不重要的；仅以微弱多数票获胜的；记在页边的，有旁注的","p":"'mɑːdʒɪnl","e":["a marginal increase in the unemployment figures","失业人数的小幅增加"]},{"w":"marine","t":"adj. 海洋的","p":"mə'ri:n","c":1,"e":["the effects of oil pollution on marine mammals","石油污染对海洋哺乳动物的影响"]},{"w":"markedly","t":"adv. 显著地","p":"'mɑ:kɪdlɪ","c":1,"e":["Her background is markedly different from her husband's.","她的背景和她丈夫的截然不同。"]},{"w":"market","t":"v. 推销","p":"'mɑːkɪt","e":["If you could ever figure out how to market this you’d make a fortune.","如果能想出办法来推销这个东西，你就发财了。"]},{"w":"Mars","t":"n. 火星","p":"mɑːz","e":["the enormous volcanoes known to exist on Mars","已知在火星上存在的大量火山"]},{"w":"marsh","t":"n. 沼泽，湿地","p":"mɑːʃ","e":["Long strips of glazing set vertically into white frames face out into the marsh landscape of the site.","曲线形的立面朝向基地的湿地，其垂直的白色框架间镶嵌着长条的玻璃窗。"]},{"w":"marshal","t":"n. 元帅，最高指挥官；总指挥，司仪；执法官，警察局长，消防队长；vt. 整理，排列，集结","p":"'mɑːʃl","e":["the Marshal of the Royal Air force","皇家空军元帅"]},{"w":"martyr","t":"n. 烈士，殉难者","p":"'mɑːtə","e":["The army has been held back because the government is reluctant to make martyrs of the protesters.","军队后撤了，因为政府不愿意造成抗议者牺牲。"]},{"w":"marvel","t":"n. 奇迹；惊奇；v. 惊奇","p":"'mɑːv(ə)l","e":["Everyone marvelled at his courage.","人人对他的勇气都惊叹不已。"]},{"w":"masculine","t":"adj. 男性的，男子的；男子气的","p":"'mæːskjəlɪn","e":["They’re nice curtains, but I’d prefer something a little more masculine.","这些窗帘很好，但我更喜欢男性化一点的。"]},{"w":"mask","t":"n. 面具；v. 掩饰，掩盖","p":"mɑ:sk","c":1,"e":["Men often mask their true feelings with humour.","男人常常用幽默来掩饰他们真实的情感。"]},{"w":"mass","t":"adj. 大量的，大规模的；v. 聚集，集中；n. 众多，大量；团，块，堆；群众；质量","p":"mæs","e":["the problem of mass unemployment","大批人失业的问题"]},{"w":"massacre","t":"vt. 大规模屠杀，残杀；彻底击败；n. 大屠杀，残杀；惨败","p":"'mæsəkə","e":["Tens of thousands of dolphins and small whales are brutally massacred every year.","每年有数万条海豚和小鲸鱼惨遭杀戮。"]},{"w":"massive","t":"adj. 大的，大而重的；大块的；大量的，大规模的","p":"'mæsɪv","e":["The bell is massive, weighing over 40 tons.","那口钟非常大，有40多吨重。"]},{"w":"mast","t":"n. 桅杆","p":"mɑːst"},{"w":"masterpiece","t":"n. 杰作","p":"'mɑːstəpiːs","e":["Mary Shelley was just 18 when she wrote the horror masterpiece ‘Frankenstein’.","玛丽•雪莱创作《科学怪人》这部恐怖小说名作的时候年仅18岁。"]},{"w":"material","t":"n. 材料","p":"məˈtɪəriəl","c":1,"e":["materials like wood or stone","木材或石头之类的材料"]},{"w":"materialism","t":"n. 唯物主义","p":"mə'tɪəriəlɪzəm","e":["a reaction to a world full of shallow materialism","对充满浅薄的物质主义思想的世界作出的回应"]},{"w":"materialize","t":"v. 实现","p":"mə'tɪərɪəlaɪz","c":1,"e":["The money we had been promised failed to materialize .","答应给我们的钱并没有兑现。"]},{"w":"matter","t":"v. 重要；要紧","p":"'mætə(r)","c":1,"e":["If I have to stay late at work tonight, it won’t matter because we can go out another night.","如果今晚我必须工作到很晚的话，那也没关系，我们可以改天晚上再出去。"]},{"w":"mature","t":"adj. 成熟的，成年人的；深思熟虑的；到期的，应支付的；vt. 使成熟","p":"mə'tʃuə","e":["We’re mature enough to disagree on this issue but still respect each other.","我们都很成熟，尽管我们对此事意见不同，但还是彼此尊重。"]},{"w":"maturity","t":"n. 成熟","p":"mə'tʃʊərətɪ","c":1,"e":["One day you’ll have the maturity to understand.","有一天等你长大后你就明白了。"]},{"w":"maximum","t":"adj. 最大的；最高的；顶点的；n. 最大量；顶点","p":"'mæksɪməm","e":["The award will consist of a lump sum to a maximum value of $5,000.","奖学金最高将是5,000美元，一次性给付。"]},{"w":"meadow","t":"n. 草地","p":"'medəu","e":["He hurried across the stream and reached a meadow. He stopped and looked around, as if hewere looking for something.","忽然来了一个人，他匆匆地穿过溪流，来到草地上，停下来四处看了看，好像在寻找什么。 。"]},{"w":"measure","t":"n. 措施","p":"ˈmeʒə(r)","c":1,"e":["The new bridge was erected as a temporary measure to replace the one which was destroyed by floods.","建这座新桥是为了临时代替被洪水毁坏的那座桥。"]},{"w":"measurement","t":"n. （量得的）尺寸，大小","p":"'meʒəm(ə)nt","e":["Take measurements of the room before you buy any new furniture.","买新家具之前要先量好房间的尺寸。"]},{"w":"mechanical","t":"adj. 机械的，机械制造的，机械学的，力学的；呆板的","p":"mə'kænɪkl","e":["The plane had to make an emergency landing because of mechanical problems.","飞机因机械故障不得不紧急降落。"]},{"w":"mechanics","t":"n. 力学，机械学","p":"mɪ'kænɪks","e":["He has not studied mechanics or engineering.","他没有学习过力学或者工程学。"]},{"w":"mechanism","t":"n. 机制","p":"'mekənɪzəm","c":1,"e":["The Army has set up mechanisms to help jobless ex-soldiers get work.","军队建立了帮助无工作的退伍军人找到工作的机制。"]},{"w":"mediate","t":"vi. 调解，斡旋；vt. 经调解解决；经斡旋促成","p":"'miːdieɪt","e":["The former president has agreed to mediate the peace talks.","前总统同意就和谈进行斡旋。"]},{"w":"medication","t":"n. 药物治疗；药物","p":"ˌmedɪ'keɪʃn","e":["When somebody comes for treatment I always ask them if they are on any medication.","有人来治疗时，我总是会问他们是否在服药。"]},{"w":"medieval","t":"adj. 中世纪的；中古的","p":"ˌmedɪ'iːvl","e":["These spices were first brought to Italy from the East in medieval times.","这些香料最早是在中世纪时从东方被带到了意大利。"]},{"w":"meditate","t":"v. 沉思；冥想","p":"'medɪteɪt","e":["I try to meditate for half an hour every evening.","我每天晚上尽量默想半小时。"]},{"w":"medium","t":"adj. 中等的；n. 媒质，媒介物；传导体","p":"'miːdiəm","e":["Fry the onions over a medium heat until they are golden.","用中火把洋葱炸到金黄色。"]},{"w":"melancholy","t":"n. 忧郁的；adj. 忧郁，悲伤","p":"'melənkəlɪ","e":["The music suited her melancholy mood.","这音乐很适合她的伤感情绪。"]},{"w":"melody","t":"n. 旋律，曲调；悦耳的音乐","p":"'melədi","e":["They played some lovely melodies.","他们演奏了一些动听的曲子。"]},{"w":"melt","t":"v. 融化","p":"melt","c":1,"e":["It was warmer now, and the snow was beginning to melt.","现在天气暖和了，雪开始融化。"]},{"w":"membership","t":"n. 成员资格；会员人数","p":"'membəʃɪp","e":["You should carry your membership card with you at all times.","你应该随身携带会员卡。"]},{"w":"memo","t":"n. 备忘录","p":"'meməʊ","c":1,"e":["I sent him a memo reminding him about the meeting.","我发给他一个通知，提醒他开会的事。"]},{"w":"memorable","t":"adj. 值得纪念的","p":"ˈmemərəbl","c":1,"e":["We want to make this a truly memorable day for the children.","我们想让今天成为孩子们永远难忘的日子。"]},{"w":"memorandum","t":"n. 备忘录","p":"ˌmeməˈrændəm","c":1,"e":["...a memorandum from the Department of Defense on its role.","…一份来自国防部的有关其角色的备忘录。"]},{"w":"memorize","t":"v. 熟记","p":"ˈmeməraɪz","c":1,"e":["He studied his map, trying to memorize the way to Rose's street.","他研究了地图，努力记住去罗丝家那条街的路。"]},{"w":"menace","t":"n. 具有危险性的人；威胁，威吓；vt. 威胁，威吓","p":"'menəs","e":["the growing menace of oil pollution at sea","日益严重的海洋石油污染"]},{"w":"mend","t":"v. 修理；改正","p":"mend","e":["If he doesn’t mend his ways, he’ll be asked to leave.","如果他不好好改改，会让他走人的。"]},{"w":"mental","t":"adj. 心理的，精神的，思想上的；精神病的；智力的","p":"'mentl","e":["The centre provides help for people suffering from mental illness .","该中心对精神病患者提供帮助。"]},{"w":"mention","t":"v. 提及","p":"'menʃn","c":1,"e":["(= it is important enough to mention ) that they only studied a very small number of cases.","必须说明的是他们仅研究了几个个案。"]},{"w":"merchandise","t":"n. 商品，货物","p":"'mɜːtʃ(ə)ndaɪs; -z","e":["A range of official Disney merchandise was on sale.","一系列正版的迪士尼商品在出售。"]},{"w":"merciful","t":"adj. 仁慈的，宽大的","p":"'mɜːsɪfʊl; -f(ə)l","e":["Merciful God, save us.","仁慈的上帝，救救我们吧。"]},{"w":"mercury","t":"n. 水银，汞","p":"'mɜːkjəri","e":["He said that all metals were composed of mercury and sulphur in different proportions .","他说一切金属都是由水银和硫黄按不同比例构成的。"]},{"w":"mere","t":"adj. 仅仅的，纯粹的","p":"mɪə","e":["She lost the election by a mere 20 votes.","她仅仅以20票之差落选。"]},{"w":"merely","t":"adv. 仅仅，只不过","p":"'mɪəli","e":["He’s merely a boy – you can’t expect him to understand.","他只是个孩子——你不要指望他能理解。"]},{"w":"merge","t":"v. 合并","p":"mɜːdʒ","c":1,"e":["The company plans to merge its subsidiaries in the US.","该公司计划合并其在美国的几家子公司。"]},{"w":"merit","t":"v. 值得；n. 优点","p":"'merɪt","c":1,"e":["The merit of the report is its realistic assessment of the changes required.","这份报告的优点就是它对所要求的变动进行了实事求是的评估。"]},{"w":"mesh","t":"n. 网眼，筛孔，网络","p":"meʃ","e":["The windows were covered in wire mesh to keep out flies.","窗户上装了铁丝纱网，防止苍蝇飞入。"]},{"w":"mess","t":"v. 弄脏，弄乱，搞糟","p":"mes","e":["He scratched his head and messed his hair even more.","他挠挠头，把头发弄得更乱了。"]},{"w":"message","t":"n. 启示，要旨，教训","p":"'mesɪdʒ","e":["The result of this legal battle sends an important message to people in similar situations.","这场诉讼战的结果给情况相似的人们传递了一个重要的信息。"]},{"w":"messenger","t":"n. 送信人，信使","p":"'mesɪndʒə","e":["There will be a messenger at the airport to collect the photographs from our courier.","机场会有一名信使从我们的快递员那儿取走照片。"]},{"w":"metabolic","t":"adj. 代谢作用的，新陈代谢的","p":"ˌmetə'bɒlɪk","e":["Exercise can increase your metabolic rate.","运动可以提高新陈代谢率。"]},{"w":"metallic","t":"adj. 金属的，金属制的；有金属特性的，像金属的","p":"mə'tælɪk","e":["The pans made a metallic clatter as they crashed to the floor.","那些锅哐啷一声摔到地上。"]},{"w":"metallurgy","t":"n. 冶金学，冶金术","p":"mɪ'tælədʒɪ; 'met(ə),lɜːdʒɪ","e":["He studied metallurgy as a mature student, having spent ten years working in a foundry.","在一家铸造厂工作了10年以后,他成为成人学生学习冶金专业。"]},{"w":"metropolitan","t":"adj. 大都市的","p":"metrə'pɒlɪt(ə)n","c":1,"e":["a metropolitan area of South Australia","南澳大利亚的一个都市区"]},{"w":"microprocessor","t":"n. 微信息处理机","p":"maɪkrə(ʊ)'prəʊsesə","e":["A microprocessor will check for interrupts at the end of every instruction.","微处理器将在每一个指令末尾检查有无中断."]},{"w":"microscopic","t":"adj. 显微镜的；微观的，极小的","p":"maɪkrə'skɒpɪk","e":["The cells were identified through microscopic analysis.","那些细胞通过显微镜分析被识别出来。"]},{"w":"microwave","t":"n. 微波","p":"'maɪkrə(ʊ)weɪv","e":["Its molecules can be agitated by microwave energy.","微波能量可以使其分子随之运动。"]},{"w":"midst","t":"n. 中部；中间；当中","p":"'mɪdst","e":["We were sitting in the midst of an elegant and well-dressed audience.","我们坐在一群举止优雅、衣着考究的观众中间。"]},{"w":"mighty","t":"adj. 强大的；巨大的","p":"'maɪtɪ","e":["the mighty Mississippi river","浩荡的密西西比河"]},{"w":"migrant","t":"n. 移居者，移民；候鸟，迁移动物","p":"'maɪgrənt","e":["The government divides asylum seekers into economic migrants and genuine refugees.","政府将寻求政治庇护的人划分为经济移民和真正的难民。"]},{"w":"migrate","t":"v. 移民；迁徙","p":"maɪ'ɡreɪt","c":1,"e":["People migrate to cities like Jakarta in search of work.","人们移居到雅加达这样的城市找工作。"]},{"w":"migration","t":"n. 迁徙，移居","p":"maɪ'greɪʃ(ə)n","c":1,"e":["seasonal migration","季节性迁徙"]},{"w":"mild","t":"adj. 温柔的；温暖的；轻微的","p":"maɪld","e":["We had an exceptionally mild winter last year.","去年冬天我们这里异常暖和。"]},{"w":"milestone","t":"n. 里程碑","p":"'maɪlstəʊn","c":1,"e":["He said the launch of the party represented a milestone in Zambian history.","他说该党的成立代表着赞比亚历史上的一个里程碑。"]},{"w":"militant","t":"adj. 激进的；好斗的；n. 激进分子，斗士","p":"'mɪlɪtənt","e":["After the assassination of Martin Luther King, black leaders became more militant.","马丁•路德•金遇刺后，黑人领袖变得更为激进了。"]},{"w":"military","t":"adj. 军事的；军用的；n. 军队，武装力量","p":"'mɪlətri","e":["The government has threatened to take military action if the rebels do not withdraw from the area.","政府警告说，如果叛乱分子不从该地区撤出，就要采取军事行动。"]},{"w":"milky","t":"adj. 牛奶的；乳白色的","p":"'mɪlkɪ","e":["A milky mist filled the valley.","乳白色的薄雾弥漫了山谷。"]},{"w":"millionaire","t":"n. 百万富翁，大富翁","p":"ˌmɪljə'neə","e":["a millionaire businessman","一位富商"]},{"w":"mingle","t":"vi. 混合起来，相混合；相交往，相往来；vt. 使混合，使相混","p":"'mɪŋgl","e":["Add the mint and allow the flavours to mingle.","加入薄荷，把各种味道混合起来。"]},{"w":"miniature","t":"adj. 微型的","p":"ˈmɪnətʃə(r)","c":1,"e":["He looked like a miniature version of his father.","他看上去像是他父亲的微缩版。"]},{"w":"minibus","t":"n. 小型公共汽车","p":"'mɪnibʌs","e":["He was then taken by minibus to the military base.","接着他被小型公共汽车带到了军事基地。"]},{"w":"minimal","t":"adj. 最低的，最小限度的","p":"ˈmɪnɪməl","c":1,"e":["This is a practical course, with only a minimal amount of theory.","这是实践课程，只有少量理论。"]},{"w":"minimize","t":"vt. 使减少到最低限度；极力贬低，对…作最低估计","p":"'mɪnɪmaɪz","e":["Concerned people want to minimize the risk of developing cancer.","忧心忡忡的人们想把患上癌症的风险降到最低。"]},{"w":"minimum","t":"adj. 最低的，最小的；n. 最低限度，最小量","p":"'mɪnɪməm","e":["The minimum number of students we need to run the course is fifteen.","我们开这门课程最少要有15个学生。"]},{"w":"mining","t":"n. 采矿业","p":"ˈmaɪnɪŋ","c":1,"e":["...traditional industries such as coal mining and steel making.","…像采煤和炼钢这样的传统工业。"]},{"w":"minor","t":"adj. 次要的，小的","p":"'maɪnə(r)","c":1,"e":["They played only a minor role in local government.","他们在当地政府里只是扮演次要角色。"]},{"w":"minority","t":"n. 少数，少数民族","p":"maɪ'nɒrətɪ","c":1,"e":["Gaelic is still spoken in Ireland by a tiny minority.","爱尔兰仍有极少数人在说盖尔语。"]},{"w":"mint","t":"n. 造币厂；巨额钱财","p":"mɪnt","e":["coins issued by the Royal Mint","皇家铸币局发行的硬币"]},{"w":"miracle","t":"n. 奇迹","p":"'mɪrəkl","c":1,"e":["By some miracle, we managed to catch the plane.","我们奇迹般地赶上了飞机。"]},{"w":"mirror","t":"n. 反映，借鉴","p":"'mɪrə","e":["We believe the polls are an accurate mirror of public opinion.","我们相信民意测验是准确反映公众意见的一面镜子。"]},{"w":"mischief","t":"n. 调皮，捣蛋，胡闹","p":"'mɪstʃɪf","e":["They’ve got enough toys to keep them out of mischief for a while.","他们有足够的玩具玩，暂时不会捣蛋。"]},{"w":"miser","t":"n. 守财奴，吝啬鬼","p":"'maɪzə","e":["I'm married to a miser.","我嫁了个守财奴。"]},{"w":"misery","t":"n. 痛苦，苦恼，苦难；悲惨的境遇，贫苦","p":"'mɪzəri","e":["What we are witnessing here is human misery on a vast scale.","我们在这里所目睹的情景是许许多多的人都生活困苦。"]},{"w":"misfortune","t":"n. 不幸；灾祸，灾难","p":"ˌmɪsˈfɔ:tʃu:n","c":1,"e":["It seems the banks always profit from farmers’ misfortunes.","银行似乎总是从农民的不幸中获益。"]},{"w":"misinterpret","t":"v. 误解","p":"ˌmɪsɪn'tɜ:prɪt","c":1,"e":["Some parts of the report could be misinterpreted.","报告的某些部分可能会被误解。"]},{"w":"misled","t":"v. (mislead过去式)误导","p":",mɪs'led","c":1,"e":["Don’t be misled into thinking that scientific research is easy.","不要受人误导，以为搞科学研究很容易。"]},{"w":"mismanagement","t":"n. 管理不当","p":"mɪs'mænɪdʒmənt","c":1,"e":["His gross mismanagement left the company desperately in need of restructuring.","他处理事务的严重不当使得公司急需重组。"]},{"w":"mission","t":"n. 使命，任务；使团","p":"'mɪʃn","e":["He was sent on over 200 missions before being killed in action.","在阵亡之前他奉命执行过200多次军事任务。"]},{"w":"missionary","t":"n. 传教士","p":"'mɪʃənri","e":["My mother would still like me to be a missionary in Africa.","我母亲还是想让我在非洲做一名传教士。"]},{"w":"mist","t":"n. 薄雾；v. 下薄雾","p":"mɪst","e":["We could just see the outline of the house through the mist.","薄雾中我们只能看到房子的轮廓。"]},{"w":"mistress","t":"n. 情妇；主妇，女主人","p":"'mɪstrəs","e":["The Prince had shocked society by living openly with his mistress.","王子和他的情妇公开同居，让社会大为震惊。"]},{"w":"mitten","t":"n. 连指手套","p":"'mɪt(ə)n","e":["sheepskin mittens","羊皮连指手套"]},{"w":"mixer","t":"n. 搅拌器","p":"'mɪksə","e":["an electric food mixer","电动食品搅拌器"]},{"w":"moan","t":"vi. 呻吟，呜咽；抱怨，发牢骚；vt. 抱怨；n. 呻吟声，呜咽声；怨声，牢骚","p":"məun","e":["He moaned and groaned all the way there.","他去的一路上抱怨个没完。"]},{"w":"mob","t":"n. 暴民，乌合之众；vt. 成群围住，聚众袭击","p":"mɒb","e":["They were immediately surrounded by the mob.","他们立刻被那帮暴民包围了。"]},{"w":"mobile","t":"adj. 运动的；流动的；多变的；n. 移动电话","p":"'məubaɪl","e":["an upwardly mobile (= moving to a higher social scale ) professional","步步高升的专业人士"]},{"w":"mobility","t":"n. 流动性；活动性","p":"məʊˈbɪləti","c":1,"e":["There is greater mobility of labour (= movement of workers ) between jobs and areas.","工作岗位之间和地区之间的劳动力流动性更大了。"]},{"w":"mobilize","t":"vi. 动员起来；vt. 动员；调动，鼓动起","p":"'məubəlaɪz","e":["a campaign to mobilize support for the strike","动员大家支持罢工的宣传活动"]},{"w":"mock","t":"vi. 嘲笑，嘲弄；adj. 模拟的，演习的；假的，假装的；vt. 嘲笑，嘲弄；模仿","p":"mɒk","e":["It’s easy for you to mock, but we put a lot of work into this play.","你讲风凉话是很轻松，但我们这出戏可是费了很大力气的。"]},{"w":"moderately","t":"adv. 适度地，适中","p":"'mɒd(ə)rətlɪ","e":["He drinks moderately.","他喝酒有节制。"]},{"w":"modernize","t":"v. 现代化","p":"'mɒdənaɪz","c":1,"e":["They need more funds to modernize the country’s telephone system.","他们需要更多的资金将本国的电话系统现代化。"]},{"w":"modest","t":"adj. 谦虚的；适中的；羞怯的","p":"'mɒdɪst","e":["You’re too modest! You’ve been a huge help to us.","你太谦虚了！你帮了我们大忙呢。"]},{"w":"modesty","t":"n. 谦虚","p":"'mɒdəsti","e":["‘Anyone else would have done the same thing,’ he said with typical modesty.","换了谁都会这么做的。”他带着一贯的谦虚说道。"]},{"w":"modification","t":"n. 修改","p":",mɒdɪfɪ'keɪʃ(ə)n","e":["They have used the same process for almost 50 years with only minor modifications.","同样的工序他们用了将近50年，期间只做过很小的改动。"]},{"w":"modify","t":"v. 改变","p":"ˈmɒdɪfaɪ","c":1,"e":["The feedback will be used to modify the course for next year.","这些反馈意见将用于修改明年的课程。"]},{"w":"modulate","t":"v. 调整，调节（声音）","p":"'mɒdjʊleɪt","e":["He carefully modulated his voice.","他仔细地调节了自己的声音。"]},{"w":"module","t":"n. 组件，模块，模件；舱","p":"'mɒdjuːl","e":["A rescue plan could be achieved by sending an unmanned module to the space station.","营救计划可以通过向空间站发送一个无人舱来完成。"]},{"w":"moist","t":"adj. 潮湿的","p":"mɔɪst","c":1,"e":["Make sure the soil is moist before planting the seeds.","播种之前要确保土壤湿润。"]},{"w":"molecular","t":"adj. 分子的；克分子的","p":"mə'lekjʊlə","e":["...the molecular structure of fuel.","…燃料的分子结构。"]},{"w":"molecule","t":"n. 分子","p":"'mɒlɪkjuːl","e":["The molecules of oxygen gas contain just two atoms.","氧分子中只有两个原子。"]},{"w":"momentary","t":"adj. 瞬息间的，片刻的","p":"'məʊm(ə)nt(ə)rɪ","e":["There was a momentary pause.","停顿了片刻。"]},{"w":"momentum","t":"n. 动力，势头","p":"mə'mentəm","c":1,"e":["Governments often lose momentum in their second term of office.","政府往往会在第二届任期中丧失冲劲。"]},{"w":"monarch","t":"n. 君主，最高统治者","p":"'mɒnək","e":["Britain's head of state is a constitutional monarch.","英国的国家元首是君主立宪的国王或女王。"]},{"w":"monetary","t":"adj. 货币的","p":"'mʌnɪt(ə)rɪ","c":1,"e":["the government’s tight monetary policy","政府从紧的货币政策"]},{"w":"monitor","t":"n. 班长；监视器，检测器；显示器；vt. 监听，检测","p":"'mɒnɪtə","e":["a heart monitor","心脏监测仪"]},{"w":"monk","t":"n. 和尚，僧侣，修道士","p":"mʌŋk","e":["...saffron-robed Buddhist monks.","…身穿黄袍的和尚们。"]},{"w":"monopolize","t":"v. 垄断","p":"mə'nɑpə'laɪz","c":1,"e":["The company has monopolized the soft drinks market.","该公司垄断了软饮料市场。"]},{"w":"monopoly","t":"n. 垄断","p":"mə'nɒpəlɪ","c":1,"e":["a monopoly in copper trading","对铜交易的垄断"]},{"w":"monster","t":"adj. 大的，庞大的；n. 怪物；极其残酷的人；巨人，巨兽，巨大的东西","p":"'mɒnstə","e":["The song was a monster hit.","这首歌大受欢迎。"]},{"w":"monstrous","t":"adj. 极大的；可怕的","p":"'mɒnstrəs","e":["a monstrous shadow on the stairs","楼梯上一个可怕的影子"]},{"w":"moor","t":"v. 使停泊；使固定","p":"mɔː; mʊə","e":["Two or three fishing boats were moored alongside the pier.","有两三艘渔船停泊在码头边。"]},{"w":"mop","t":"n. 拖把，墩布；洗碗刷","p":"mɒp","e":["a mop and bucket","拖把和水桶"]},{"w":"moral","t":"adj. 道德的，有道德的；n. 品行，道德规范；寓意","p":"'mɒrəl","e":["If we accept that certain babies should be allowed to die, we place doctors in a moral dilemma .","如果我们同意应该允许某些婴儿死去，那就是让医生在道德上处于两难境地了。"]},{"w":"morality","t":"n. 道德，道德性；德行，品行；道德观，道德规则","p":"mə'ræləti","e":["...standards of morality and justice in society.","…社会中道德和正义的标准。"]},{"w":"moreover","t":"adv. 而且，再者，此外","p":"mɔːr'əuvə","e":["The source of the information is irrelevant. Moreover, the information need not be confidential.","信息来源无关紧要，而且也不一定必须是机密的。"]},{"w":"mortal","t":"adj. 终有一死的；致命的；你死我活的，不共戴天的；n. 凡人，人类","p":"'mɔːtl","e":["Her father’s death reminded her that she was mortal.","父亲的去世让她认识到终有一天她也会死去。"]},{"w":"mortality","t":"n. 死亡率","p":"mɔ:ˈtæləti","c":1,"e":["Mortality from heart disease varies widely across the world.","心脏病死亡率世界各地差异很大。"]},{"w":"mortgage","t":"n. 抵押，抵押借款；vt. 抵押","p":"'mɔːgɪdʒ","e":["They’ve taken out a 30 year mortgage (= they will pay for their house over a period of 30 years ) .","他们办理了一笔30年期的抵押贷款。"]},{"w":"Moslem","t":"n. 穆斯林；adj. 穆斯林的","p":"'mɒzləm"},{"w":"mosque","t":"n. 清真寺","p":"mɒsk","e":["Would you go to church or the synagogue or the mosque?","你会去教堂，犹太教会，或者清真寺吗？"]},{"w":"moss","t":"n. 苔藓，地衣","p":"mɒs","e":["...ground covered over with moss.","…长满青苔的地面。"]},{"w":"motel","t":"n. 汽车旅馆","p":"məʊ'tel","c":1,"e":["I also have to get back to the motel. The manager took my passport last night, and now he and the passport are nowhere to be found.","我也必须回到汽车旅馆去，因为旅馆经理昨天晚上拿走了我的护照，到现在为止他本人和我的护照都不知所踪。"]},{"w":"motivate","t":"vt. 作为…的动机；激励，激发","p":"'məutɪveɪt","e":["Was he motivated solely by a desire for power?","他只是受到权欲的驱使吗？"]},{"w":"motivation","t":"n. 动力，积极性","p":"ˌməʊtɪ'veɪʃn","c":1,"e":["Jack is an intelligent pupil, but he lacks motivation.","杰克是一个很聪明的学生，但学习不够主动。"]},{"w":"motive","t":"n. 动机，目的","p":"'məutɪv","e":["It’s not the kind of thing he’d do unless he had an ulterior motive (= a reason he kept hidden ) .","他不会做这种事的，除非他另有隐情。"]},{"w":"motorway","t":"n. 汽车道，快车路","p":"'məʊtəweɪ","e":["Join the motorway at Junction 19.","在19号路口进入高速公路。"]},{"w":"mount","t":"v. 增加","p":"maʊnt","c":1,"e":["Casualties on both sides of the battle have continued to mount.","交战双方的伤亡人数继续增加。"]},{"w":"mountainous","t":"adj. 多山的；山一般的","p":"'maʊntɪnəs","e":["the mountainous coast of Wales","威尔士多山的海岸"]},{"w":"mourn","t":"v. 哀悼","p":"mɔ:n","c":1,"e":["Hundreds of people gathered to mourn the slain president.","成百上千人聚集在一起悼念遇刺的总统。"]},{"w":"mournful","t":"adj. 悲哀的；令人惋惜的","p":"'mɔrnfl","c":1,"e":["He looked mournful, even near to tears.","他看上去很悲伤，几乎要掉泪了。"]},{"w":"move","t":"n. 行动，步骤","p":"muːv","e":["Taking the position was a good career move (= a decision that will improve the type of jobs you can do).","接受这个职位在事业上是走对了一步。"]},{"w":"muddy","t":"adj. 泥泞的，沾满烂泥的；灰暗的，暗淡的；模糊的，糊涂的；vt. 使沾上烂泥；使显得扑朔迷离","p":"'mʌdi","e":["Take your boots off outside if they’re muddy.","要是靴子上都是泥，你就脱在门外吧。"]},{"w":"multiple","t":"adj. 复合的；多重的，多样的；n. 倍数","p":"'mʌltɪpl","e":["Having multiple partners increases your risk of sexual diseases.","性伴侣多会增加得性病的风险。"]},{"w":"multiplication","t":"n. 乘法；增加","p":",mʌltɪplɪ'keɪʃ(ə)n","e":["There will be simple tests in addition, subtraction, multiplication, and division.","将会有加减乘除的简单测试。"]},{"w":"multiply","t":"v. 增加，繁殖；乘","p":"'mʌltɪplaɪ","e":["Bacteria multiply quickly in warm food.","细菌在温热的食物里繁殖得很快。"]},{"w":"multitude","t":"n. 大量，许多；大众，民众","p":"'mʌltɪtjuːd","e":["Political power has been placed in the hands of the multitude.","政治权力已交到民众手中。"]},{"w":"municipal","t":"adj. 市政府的","p":"mju:ˈnɪsɪpl","c":1,"e":["the municipal waste dump","城市垃圾场"]},{"w":"murmur","t":"n&v. 小声说；小声抱怨，咕哝；发出连续而低沉的声音","p":"'mɜːmə","e":["The girl murmured something polite, and smiled.","那个女孩低声说了些客套话，并且笑了笑。"]},{"w":"muscular","t":"adj. 肌肉发达的，强壮的；肌肉的","p":"'mʌskjələ","e":["She was fast and strong, with a slender, muscular body.","她动作敏捷，身体强壮，身材苗条，肌肉结实。"]},{"w":"muse","t":"v. 沉思，默想，冥想","p":"mjuːz","e":["He mused on how different his life would have been, had he not met Louisa.","他默默地想，如果没有遇到路易莎，他的人生会有多么不同。"]},{"w":"mustard","t":"n. 芥子，芥末","p":"'mʌstəd","e":["a jar of mustard","一罐芥末酱"]},{"w":"mute","t":"adj. 缄默的，无声的；哑的，不会说话的；不发音的；vt. 消除，减轻","p":"mjuːt","e":["Billy continued to stand there, mute and defiant.","比利还是站在那儿一声不吭，一副不服气的样子。"]},{"w":"mutter","t":"n&v. 轻声低语；小声抱怨","p":"'mʌtə","e":["Elsie muttered something I couldn’t catch and walked off.","埃尔茜咕哝了一句什么，我也没有听懂，她就走掉了。"]},{"w":"mutual","t":"adj. 相互的；共同的","p":"'mjuːtʃuəl","e":["The two men were a mutual admiration society , gushing about how much they were learning from each other.","两个男人互相吹捧，盛赞对方让自己受益匪浅。"]},{"w":"mysteriously","t":"adv. 神秘地","p":"mɪ'stɪərɪəslɪ","c":1,"e":["My watch had mysteriously disappeared.","我的手表不知怎么就不见了。"]},{"w":"mystery","t":"n. 神秘小说，侦探小说","p":"ˈmɪstri","e":["an Agatha Christie mystery","一部阿加莎•克里斯蒂的悬疑小说"]},{"w":"myth","t":"n. 杜撰出来的人；神话","p":"mɪθ","e":["the giants of myth and fairytale","神话和童话里的巨人"]},{"w":"naive","t":"adj. 幼稚的；天真的；轻信的","p":"naɪ'iːv","e":["Jim can be so naive sometimes.","吉姆有时候非常幼稚。"]},{"w":"nap","t":"n. 小睡","p":"næp","c":1,"e":["an afternoon nap","午睡"]},{"w":"napkin","t":"n. 餐巾","p":"'næpkɪn","e":["...taking tiny bites of a hot dog and daintily wiping my lips with a napkin.","…小口咬着热狗并用餐巾文雅地擦着我的嘴唇。"]},{"w":"narration","t":"n. 叙述；故事；叙述法","p":"nə'reɪʃ(ə)n"},{"w":"narrative","t":"n. 叙述文，故事；叙述，讲述","p":"'nærətɪv","e":["At several points in the narrative the two stories cross.","叙述中两条故事线多次交织在一起。"]},{"w":"narrow","t":"v. 变窄，缩小","p":"'nærəʊ","c":1,"e":["He narrowed his eyes and gazed at the horizon.","他眯起眼睛凝望着地平线。"]},{"w":"nasty","t":"adj. 令人讨厌的，令人厌恶的；难弄的，困难的；严重的，恶劣的，险恶的；下流的，道德败坏的","p":"'nɑːsti","e":["When you feel you’ve been cheated, it always leaves a nasty taste in the mouth (= makes you feel upset or angry afterwards ).","感觉自己被骗之后，心里总会留下很不好受的滋味。"]},{"w":"navigate","t":"v. 航行，驾驶","p":"ˈnævɪgeɪt","c":1,"e":["The river is too dangerous to navigate.","这河道太危险，不适宜航行。"]},{"w":"navigation","t":"n. 航行，航海，航空；导航，领航","p":"ˌnævɪ'geɪʃn","e":["compasses and other instruments of navigation","罗盘及其他导航仪器"]},{"w":"necessitate","t":"vt. 成为必要，需要","p":"nə'sesɪteɪt","e":["Lack of money necessitated a change of plan.","由于缺乏资金，只能改变计划。"]},{"w":"necessity","t":"n. 必须，必要性","p":"nəˈsesəti","c":1,"e":["I’m afraid it’s become a matter of economic necessity.","恐怕这已成了一个经济需求的问题。"]},{"w":"needle","t":"n. 指针；针","p":"'ni:dl","c":1,"e":["a needle and thread","针和线"]},{"w":"needy","t":"adj. 贫穷的","p":"'ni:dɪ","c":1,"e":["a needy family","贫困家庭"]},{"w":"negative","t":"adj. 否定的，消极的；负的，阴性的；n. 负片，底片；负数","p":"'negətɪv","e":["They have a uniformly negative image of the police.","他们都对警察印象不好。"]},{"w":"neglect","t":"v. 疏忽；忽视","p":"nɪ'ɡlekt","c":1,"e":["She smoked and drank, neglected the children, and left the clothes unmended.","她抽烟喝酒，既不照顾孩子，也不缝补衣服。"]},{"w":"negligible","t":"adj. 可忽略不计的，微不足道的","p":"'neglɪdʒəbl","e":["The damage done to his property was negligible.","对他财产造成的损失微不足道。"]},{"w":"negotiate","t":"v. 洽谈，协商，谈判；顺利通过，成功越过","p":"nɪ'gəuʃieɪt","e":["His first aim is to get the warring parties back to the negotiating table (= discussing something ).","他的首要目标就是把交战各方拉回到谈判桌上。"]},{"w":"negotiation","t":"n. 协商","p":"nɪˌgəʊʃiˈeɪʃn","c":1,"e":["The trader was obstinate in the negotiation.","这个商人在谈判中拗强固执。"]},{"w":"neighborhood","t":"n. 附近","p":"'neɪbəhʊd","c":1,"e":["Is there a good Chinese restaurant in the neighborhood?","这附近有没有好的中餐馆？"]},{"w":"neighbouring","t":"adj. 邻近的，接壤的","p":"'neɪb(ə)rɪŋ","e":["The fair attracted hundreds of people from the neighbouring towns and villages.","集市吸引了邻近城镇及村庄的好几百人前来。"]},{"w":"nest","t":"v. 筑巢，为…筑巢","p":"nest","e":["They say eagles used to nest in those rocks.","他们说以前常有老鹰在那些岩石中筑巢。"]},{"w":"net","t":"v. 用网捕；用网覆盖","p":"net","e":["We netted three fish in under an hour.","不到一小时我们就网住了三条鱼。"]},{"w":"network","t":"n. 网络；广播网","p":"'netwɜːk","e":["You’re listening to the American Armed Forces Network.","您正在收听的是美军广播电台。"]},{"w":"neutral","t":"adj. 中立的，中性的","p":"'njuːtrəl","e":["The British government acted as a neutral observer during the talks.","英国政府在会谈中扮演了中立观察员的角色。"]},{"w":"neutrality","t":"n. 中立","p":"nju:ˈtræləti","c":1,"e":["Some of the nations declared neutrality.","有的国家宣布中立。"]},{"w":"neutron","t":"n. 中子","p":"'njuːtrɒn","e":["Each atomic cluster is made up of neutrons and protons.","每个原子团簇是由中子和质子组成的。"]},{"w":"nice","t":"adj. 细微的，微妙的","p":"naɪs","e":["a nice point of law","法律上的微妙难断之处"]},{"w":"nickel","t":"n. 镍；五分镍币，五分钱","p":"'nɪkl","e":["...a large glass jar filled with pennies, nickels, dimes, and quarters.","…一个装满1分、5分、10分和25分硬币的大玻璃罐。"]},{"w":"nickname","t":"n. 绰号，诨名；vt. 给…起绰号","p":"'nɪkneɪm","e":["When he got older I nicknamed him Little Alf.","他长大些后，我给他起了绰号“小阿尔夫”。"]},{"w":"nightmare","t":"n. 噩梦","p":"ˈnaɪtmeə(r)","c":1,"e":["a recurring nightmare","一再出现的噩梦"]},{"w":"nil","t":"n. 无，零","p":"nɪl","e":["The new machine reduced labour costs to almost nil.","新机器把劳动成本几乎降到零。"]},{"w":"nominal","t":"adj. 名义上的，有名无实的；很少的，象征性的；名词性的","p":"'nɒmɪnl","e":["Their conversion to Christianity was only nominal.","他们只是名义上皈依了基督教。"]},{"w":"nominate","t":"v. 提名","p":"'nɒmɪneɪt","c":1,"e":["This week one of them will be nominated by the Democratic Party for the presidency of the United States.","本周他们中的一人将被民主党提名为美国总统职位的候选人。"]},{"w":"nonetheless","t":"adv. 尽管如此，依然，然而","p":"ˌnʌnðə'les","e":["The region was extremely beautiful. Nonetheless Gerard could not imagine spending the rest of his life there.","那个地区非常漂亮，然而杰拉德却无法想象自己要在那里度过余生。"]},{"w":"norm","t":"n. 标准，规范；准则","p":"nɔːm","e":["Joyce’s style of writing was a striking departure from the literary norm.","乔伊斯的写作风格与传统的文学风格大相径庭。"]},{"w":"normalization","t":"n. 正常化，标准化","p":",nɔːməlaɪ'zeɪʃən","e":["the normalization of relations","关系的正常化"]},{"w":"nose","t":"n. 突出部分（如船头等）","p":"nəʊz","e":["They went over to the aeroplane and stood near its nose.","他们朝飞机走了过去并站在靠近机头的地方。"]},{"w":"notable","t":"adj. 值得注意的，显著的；著名的；n. 名人，要人","p":"'nəutəbl","e":["Every country in the world signed the treaty, with one notable exception - the United States.","全世界每个国家都签署了那份条约，只有一个国家反其道而行之，就是美国。"]},{"w":"notably","t":"adv. 显著地，尤其","p":"'nəʊtəblɪ","c":1,"e":["Notably absent from his statement was any hint of an apology.","他的话里显然没有丝毫道歉的意思。"]},{"w":"notation","t":"n. 记号，标记法","p":"nəu'teɪʃn","e":["Musical notation was conceived for the C major scale and each line and space represents a note in this scale.","乐谱为C大音阶而构思，在这个音阶中的每一个线和间都代表一个音符。"]},{"w":"noted","t":"adj. 著名的","p":"'nəʊtɪd","c":1,"e":["a noted author","著名作家"]},{"w":"notification","t":"n. 通知，告示；通知书","p":"ˌnəutɪfɪ'keɪʃn","e":["Names of the dead and injured are being withheld pending notification of relatives.","伤亡者的姓名在通知亲属前不被公布。"]},{"w":"notify","t":"vt. 通知，告知；报告","p":"'nəutɪfaɪ","e":["The skipper notified the coastguard of the tragedy.","船长通知了海岸警卫队这一灾难。"]},{"w":"notion","t":"n. 想法，观点","p":"ˈnəuʃən","c":1,"e":["She had no notion what he meant.","她根本不明白他是什么意思。"]},{"w":"notorious","t":"adj. 臭名昭著的，声名狼藉的","p":"nəu'tɔːriəs","e":["notorious cases of human rights abuses","臭名昭著的践踏人权案"]},{"w":"notoriously","t":"adv. 臭名昭著地","p":"nəʊ'tɔ:rɪəslɪ","c":1,"e":["He is notoriously indiscreet about his private life.","他在私生活方面的不检点是出了名的。"]},{"w":"notwithstanding","t":"adv. 尽管","p":"ˌnɒtwɪθ'stændɪŋ","e":["His relations with colleagues, differences of opinion notwithstanding, were unfailingly friendly.","他与同事们尽管有意见分歧，但关系一直很融洽。"]},{"w":"nought","t":"n. 无，零","p":"nɔːt","e":["A billion is 1 with 9 noughts after it.","十亿是1后面加9个零。"]},{"w":"nourish","t":"vt. 养育，喂养，滋养；怀有，增强","p":"'nʌrɪʃ","e":["The cream contains vitamin A to nourish the skin.","这种护肤霜含有滋养肌肤的维生素A。"]},{"w":"nourishment","t":"n. 食物；营养（情况）","p":"'nʌrɪʃm(ə)nt","e":["The soil provides nourishment for plant roots.","土壤为植物根部提供养分。"]},{"w":"novel","t":"adj. 新颖的","p":"'nɒv(ə)l","c":1,"e":["Protesters found a novel way of demonstrating against steeply rising oil prices.","抗议者们找到一种新奇的示威方式来反对石油价格的飙升。"]},{"w":"novelty","t":"n. 新奇事物；新奇，新奇感，新奇性；新颖小巧而廉价的物品","p":"'nɒvlti","e":["It was fun for a while, but the novelty wore off (= it became boring ).","开始有一阵很好玩，可是新鲜感随后便消失了。"]},{"w":"nucleus","t":"n. 原子核，细胞核","p":"'njuːklɪəs","e":["Neutrons and protons are bound together in the nucleus of an atom.","在一个原子的核内，中子和质子聚合在一起。"]},{"w":"nuisance","t":"n. 讨厌的人；麻烦事","p":"'njuːsns","e":["He could be a bit of a nuisance when he was drunk.","他喝醉时会是一个有点令人讨厌的人。"]},{"w":"number","t":"v. 共计，达…之数","p":"'nʌmbə","e":["We numbered 20 (= there were 20 of us in the group).","我们总共20人。"]},{"w":"numerical","t":"adj. 数字的；用数字表示的；数值的","p":"njuː'merɪkl","e":["The home team tried to utilize their numerical advantage (= the fact that they had more players than the other team ).","主队试图利用他们在人数上的优势。"]},{"w":"numerous","t":"adj. 无数的","p":"ˈnju:mərəs","c":1,"e":["Numerous attempts have been made to hide the truth.","为掩盖事实作了很多尝试。"]},{"w":"nun","t":"n. 修女，尼姑","p":"nʌn","e":["Mr. Thomas was taught by the Catholic nuns whose school he attended to work and study hard.","托马斯先生受教于天主教修女。在修女开办的学校里他专心工作，刻苦学习。"]},{"w":"nursery","t":"n. 苗圃","p":"'nɜːs(ə)rɪ","e":["The garden, developed over the past 35 years, includes a nursery.","这个有35年历史的园子里有一个苗圃。"]},{"w":"nurture","t":"n&vt. 养育，培育，滋养","p":"'nɜːtʃə","e":["plants nurtured in the greenhouse","在温室里培育的植物"]},{"w":"nut","t":"n. 螺帽，螺母","p":"nʌt","e":["Use a wrench to loosen the nut.","用活动扳手将螺帽拧松。"]},{"w":"nutrition","t":"n. 营养","p":"nju'trɪʃn","e":["Nutrition and exercise are essential to fitness and health.","营养和运动是保持健康所必不可少的。"]},{"w":"nutritious","t":"adj. 有营养的","p":"njuˈtrɪʃəs","c":1,"e":["The cookbook contains many simple yet highly nutritious meals.","那本烹饪书里有许多简单却营养价值很高的食谱。"]},{"w":"oak","t":"n. 栎树，橡树；栎木，橡木","p":"əuk","e":["an oak door","橡木门"]},{"w":"oar","t":"n. 桨","p":"ɔː","e":["He pulled as hard as he could on the oars.","他拼命地划桨。"]},{"w":"oath","t":"n. 誓言，誓约；咒骂，诅咒语","p":"əuθ","e":["The president took the oath of office (= made the official public promises that every president makes when starting their job ) .","总统宣誓就职。"]},{"w":"obedience","t":"n. 服从，顺从","p":"ə'biːdɪəns","e":["obedience classes for dogs and their owners","为狗和主人安排的服从训练课"]},{"w":"obedient","t":"adj. 服从的，顺从的","p":"ə'biːdɪənt","e":["an obedient child","听话的孩子"]},{"w":"obesity","t":"n. 肥胖","p":"əʊ'bi:sətɪ","c":1,"e":["Obesity can increase the risk of heart disease.","肥胖会增加患心脏病的危险。"]},{"w":"object","t":"vi. 反对，不赞成；n. 实物，物体；目的，目标；对象，客体；宾语","p":"'ɒbdʒɪkt; -dʒekt","e":["If no one objects, I would like Mrs Harrison to be present.","如果没人反对的话，我想请哈里森夫人出席。"]},{"w":"objection","t":"n. 反对，异议；反对的理由","p":"əb'dʒekʃn","e":["Her objection was that he was too young.","她反对的理由是他太小。"]},{"w":"objective","t":"n. 目标，目的","p":"əbˈdʒektɪv","c":1,"e":["He vowed to achieve certain objectives before the end of his presidency.","他立誓要在他的总统任期结束之前实现某些目标。"]},{"w":"obligation","t":"n. 义务，责任","p":"ˌɒblɪ'geɪʃn","e":["The government must pay for health care for war veterans – it is an obligation we owe to them.","政府必须为退伍军人支付医疗保健费用——这是我们对他们负有的义务。"]},{"w":"oblige","t":"v. 迫使","p":"ə'blaɪdʒ","c":1,"e":["The storm got worse and worse. Finally, I was obliged to abandon the car and continue on foot.","暴风雨越来越猛烈。最终，我被迫弃车徒步前行。"]},{"w":"obscene","t":"adj. 淫秽的，下流的；可憎的，可恶的","p":"əb'siːn","e":["{\"GLOSS\":[\"calls from an unknown person saying obscene things\"],\"COLLOINEXA\":[\"obscene phone calls\"]}","下流骚扰电话"]},{"w":"obscure","t":"adj. 不著名的，不重要的；费解的，模糊不清的；vt. 使变糊，掩盖","p":"əb'skjuə","e":["Trees obscured his vision; he couldn't see much of the square's southern half.","树木遮住了他的视线，他不怎么看得见广场南半部。"]},{"w":"obscurity","t":"n. 默默无闻","p":"əb'skjʊrəti","c":1,"e":["The group produced two albums before disappearing into obscurity.","这个团体发行两张专辑后就淡出乐坛。"]},{"w":"observation","t":"n. 意见，短评，按语","p":"ɒbzə'veɪʃ(ə)n","e":["Paz makes some observations about the role of the critic.","帕斯论述了评论家的作用。"]},{"w":"observe","t":"v. 说，评述，评论","p":"əb'zɜːv","e":["Keynes observed that humans fall into two classes.","凯恩斯认为人分为两类。"]},{"w":"obstacle","t":"n. 阻碍","p":"ˈɒbstəkl","c":1,"e":["The tax puts obstacles in the way of companies trying to develop trade overseas.","这项税收为想在海外发展贸易的公司设置了障碍。"]},{"w":"obstinate","t":"adj. 固执的；顽强的","p":"'ɒbstɪnət","e":["He was the most obstinate man I’ve ever met.","他是我遇到过的最固执的人。"]},{"w":"obtain","t":"vi. 通用，流行；存在；vt. 获得","p":"əb'teɪn","e":["These conditions no longer obtain.","这些状况已不复存在。"]},{"w":"occasional","t":"adj. 偶尔的，间或发生的","p":"ə'keɪʒənl","e":["They had an occasional coffee together after shopping.","他们偶尔会在购物后一起喝杯咖啡。"]},{"w":"occupation","t":"n. 职业","p":"ɒkjʊ'peɪʃ(ə)n","c":1,"e":["Please state your name, address and occupation.","请写明你的姓名、地址和职业。"]},{"w":"occupy","t":"vt. 占领；占；占有","p":"'ɒkjupaɪ","e":["Football occupies most of my leisure time.","足球占去了我大部分的闲暇时间。"]},{"w":"occur","t":"v. 发生","p":"əˈkɜ:(r)","c":1,"e":["A third of accidental deaths occur in the home.","有三分之一的意外死亡发生在家里。"]},{"w":"occurrence","t":"n. 发生的事","p":"ə'kʌr(ə)ns","e":["Laughter was a rare occurrence in his classroom.","他的课堂上难得有笑声。"]},{"w":"odds","t":"n. 可能性","p":"ɒdz","c":1,"e":["You can narrow the odds of a nasty accident happening in your home by being more safety-conscious.","增强安全意识可以减少家中发生意外危险的可能性。"]},{"w":"odor","t":"n. 气味","p":"'əudə","e":["Note that I was the only one who got sick in that room and I was the only one who could smell the horrible odor.","请注意，我是在那间房子住过的人中唯一一个生病的，同时也是唯一一个能够闻到那股令人作呕气味的人。"]},{"w":"offence","t":"n. 犯罪，犯规；冒犯","p":"ə'fens","e":["Don’t be upset by what he said; he meant no offence (= did not intend to offend anyone ).","不要为他的话而生气，他并没有冒犯谁的意思。"]},{"w":"offense","t":"n. 冒犯","p":"əˈfens","c":1,"e":["The problem was how to say ‘no’ to her without causing offense.","问题是怎样拒绝她而又不得罪她。"]},{"w":"offensive","t":"adj. 冒犯的，无礼的，使人不快的；进攻的，攻击性的；n. 进攻，攻势","p":"ə'fensɪv","e":["I found her remarks deeply offensive.","我觉得她的话令人非常恼火。"]},{"w":"offer","t":"v. 出现","p":"'ɒfə","e":["I’ll raise the subject when a suitable occasion offers itself.","等有合适的机会，我会把这件事提出来的。"]},{"w":"offset","t":"vt. 补偿，抵消","p":"'ɒfset","e":["Cuts in food prices will be offset by direct payments to farmers.","食品降价将通过直接付款给农民的方式进行补偿。"]},{"w":"offspring","t":"n. 子女，子孙，后代；崽","p":"'ɒfsprɪŋ","e":["a young mother trying to control her offspring","一个想管住自己孩子的年轻妈妈"]},{"w":"ohm","t":"n. 欧姆","p":"əʊm"},{"w":"olive","t":"n. 橄榄，橄榄树","p":"'ɒlɪv","e":["an olive grove","一片橄榄树林"]},{"w":"ongoing","t":"adj. 持续的，不间断的","p":"ˈɒnɡəʊɪŋ","c":1,"e":["their ongoing search for a new director","他们仍在寻找一个新主任"]},{"w":"opaque","t":"adj. 不透明的，不透光的；难理解的，晦涩的","p":"əu'peɪk","e":["a shower with an opaque glass door","装有不透明玻璃门的淋浴间"]},{"w":"operation","t":"n. 运算","p":"ɒpə'reɪʃ(ə)n","e":["The whole operation is performed in less than three seconds.","全部运算在三秒内完成。"]},{"w":"opium","t":"n. 鸦片；麻醉剂","p":"'əʊpɪəm","e":["an opium addict","吸鸦片成瘾者"]},{"w":"opponent","t":"n. 反对者","p":"ə'pəʊnənt","c":1,"e":["Rodgers was not an opponent of the new airport.","罗杰斯并不反对建设新机场。"]},{"w":"oppose","t":"v. 反对","p":"ə'pəʊz","c":1,"e":["Congress is continuing to oppose the President’s health care budget.","国会继续反对总统的医疗保健预算。"]},{"w":"opposition","t":"n. 反对","p":"ˌɒpəˈzɪʃn","c":1,"e":["Plans to turn the site into a £600 million leisure complex have met with stiff opposition.","将该处改造成造价六亿英镑的综合性休闲大楼的计划遭到了激烈的反对。"]},{"w":"oppress","t":"vt. 压迫，压制；使沉重，使烦恼","p":"ə'pres","e":["native tribes oppressed by the authorities","受到当局压迫的土著部落"]},{"w":"optical","t":"adj. 眼的，视觉的；光学的","p":"'ɒptɪkl","e":["microscopes and other optical instruments","显微镜和其他光学仪器"]},{"w":"optimism","t":"n. 乐观","p":"ˈɒptɪmɪzəm","c":1,"e":["There are grounds for cautious optimism.","有理由保持谨慎乐观。"]},{"w":"optimistic","t":"adj. 乐观的","p":"ˌɒptɪˈmɪstɪk","c":1,"e":["Andrew took a more optimistic view.","安德鲁抱有更为乐观的想法。"]},{"w":"optimum","t":"adj. 最合适的，最优的，最佳的","p":"'ɒptɪməm","e":["This design makes the optimum use of the available space.","这一设计最大限度地利用了现有的空间。"]},{"w":"option","t":"n. 选择，选择权，选择自由；选择的事物，选课","p":"'ɒpʃn","e":["Teenage mothers often have no option but to (= have no other choice except to ) live with their parents.","少女妈妈往往别无选择，只能与父母同住。"]},{"w":"orbit","t":"n. 轨道","p":"'ɔrbɪt","c":1,"e":["Mars and Earth have orbits which change with time.","火星和地球的轨道随着时间而发生改变。"]},{"w":"orchard","t":"n. 果园","p":"'ɔːtʃəd","e":["a cherry orchard","樱桃园"]},{"w":"orchestra","t":"n. 管弦乐队","p":"'ɔːkɪstrə","e":["the Berlin Symphony Orchestra","柏林交响乐团"]},{"w":"ordinarily","t":"adv. 通常，大概","p":"'ɔːd(ə),n(ə)rɪlɪ; ,ɔːdɪ'nerɪlɪ","e":["This is not the price at which the CD is ordinarily sold.","这不是这张CD平时卖的价格。"]},{"w":"ore","t":"n. 矿，矿石","p":"ɔː","e":["veins of rich ore","富矿脉"]},{"w":"organic","t":"adj. 有机的","p":"ɔ:ˈgænɪk","c":1,"e":["Organic farming is better for the environment.","有机耕作对环境更有利。"]},{"w":"orient","t":"v. 使确定方向；使适应","p":"'ɔ:rɪənt","c":1,"e":["It takes new students a while to orientate themselves to college life.","新生要经过一段时间才能适应大学生活。"]},{"w":"oriental","t":"adj. 东方的；东方人的；东方文化的","p":"ˌɒːri'entl","e":["a beautiful oriental rug","漂亮的东方地毯"]},{"w":"orientation","t":"n. 方向，目标，方位；熟悉情况，适应，情况介绍","p":"ˌɔːriən'teɪʃn","e":["The party has a broadly socialist orientation.","该政党大体上倾向于社会主义。"]},{"w":"origin","t":"n. 起源，起因；出身，血统","p":"'ɒrɪdʒɪn","e":["The tradition has its origins in the Middle Ages.","这一传统源于中世纪。"]},{"w":"original","t":"adj. 最初的；新颖的；原版的；n. 原件，原作","p":"ə'rɪdʒənl","e":["The kitchen still has many original features (= parts that were there when the house was first built ).","这间厨房仍保留着当初的许多特点。"]},{"w":"originate","t":"vi. 起源于，来自，产生；vt. 创造，创始，开创","p":"ə'rɪdʒɪneɪt","e":["All carbohydrates originate from plants.","所有的碳水化合物均来源于植物。"]},{"w":"ornament","t":"n. 装饰品，点缀品；装饰，点缀；vt. 装饰，点缀，美化","p":"'ɔːnəmənt","e":["a cabinet in which she kept her collection of china ornaments","她放置瓷器摆设收藏品的柜子"]},{"w":"ornamental","t":"adj. 装饰的","p":"ɔːnə'ment(ə)l","e":["...an ornamental fountain.","…一个装饰性喷泉。"]},{"w":"orthodox","t":"adj. 传统的；正统的，正宗的","p":"'ɔːθədɒks","e":["He challenged the orthodox views on education.","他对传统的教育观念提出了质疑。"]},{"w":"otherwise","t":"adv. 另外；在其他方面","p":"'ʌðəwaɪz","e":["I could hear the distant noise of traffic. Otherwise all was still.","我能听见远处车流的声音，除此之外，一切都很安静。"]},{"w":"ought","t":"v. 早应该，本应","p":"ɔːt","e":["I realize I ought to have told you about it.","我意识到我本该告诉你这件事的。"]},{"w":"outbreak","t":"n. 爆发，突然发生","p":"'autbreɪk","e":["a cholera outbreak","霍乱的爆发"]},{"w":"outcome","t":"n. 结果","p":"ˈaʊtkʌm","c":1,"e":["People who had heard the evidence at the trial were surprised at the outcome.","在审判过程中听过证词的人都对此结果感到吃惊。"]},{"w":"outcry","t":"n. 大声疾呼，呐喊；强烈抗议","p":"'autkraɪ","e":["The closure of the local hospital has caused a huge public outcry.","当地医院的关闭激起了大规模的公众抗议。"]},{"w":"outdated","t":"adj. 过时的","p":"ˌaʊtˈdeɪtɪd","c":1,"e":["His writing style is now boring and outdated.","他的写作风格如今已显得乏味而过时了。"]},{"w":"outermost","t":"adj. 最外面的，最远的","p":"'aʊtəməʊst","e":["the outermost stars","最远的恒星"]},{"w":"outfit","t":"n. 全套服装；一组人；全套装备，全套工具","p":"'autfɪt","e":["She bought a new outfit for the party.","她为了这次派对买了套新衣服。"]},{"w":"outlaw","t":"n. 逃犯，歹徒","p":"'aʊtlɔː","e":["Jesse was an outlaw, a bandit, a criminal.","杰西曾是个逃犯、土匪、罪犯。"]},{"w":"outlet","t":"n. 发泄（感情等）的方法","p":"'aʊtlet","e":["Is football a good outlet for men’s aggression?","足球是男人宣泄好斗情绪的有效途径吗？"]},{"w":"outline","t":"n. 提纲，要点；外形；略图；vt. 概述；描…的外形","p":"'autlaɪn","e":["a research proposal outline","研究计划梗概"]},{"w":"outlive","t":"v. 比……活的时间长","p":"ˌaʊt'lɪv","c":1,"e":["She outlived her husband by 20 years.","她比她丈夫多活了20年。"]},{"w":"outnumber","t":"v. 超过","p":"ˌaʊt'nʌmbə(r)","c":1,"e":["His troops were hopelessly outnumbered.","他的军队在数量上远远不及对方。"]},{"w":"outperform","t":"v. 胜过","p":"ˌaʊtpəˈfɔ:m","c":1,"e":["Stocks generally outperform other investments.","股票总体上要优于其他投资。"]},{"w":"output","t":"n. 产量；输出，输出功率；vt. 输出","p":"'autput","e":["Output is up 30% on last year.","产量比去年提高了30%。"]},{"w":"outrage","t":"n. 义愤，愤慨；暴行，骇人听闻的事件；vt. 激起…的义愤，激怒","p":"'autreɪdʒ","e":["The response to the jury’s verdict was one of outrage.","陪审团的裁决引发了愤慨。"]},{"w":"outset","t":"n. 开始，开端","p":"'autset","e":["It was clear from the outset that there were going to be problems.","从一开始就很清楚会有问题出现的。"]},{"w":"outside","t":"prep. 在…外，向…外","p":"aʊt'saɪd; 'aʊtsaɪd","e":["You can park your car outside our house.","你可以把汽车停在我们家屋外。"]},{"w":"outsource","t":"v. 外包","p":"ˈaʊtsɔ:s","c":1,"e":["The company began looking for ways to cut costs, which led to the decision to outsource.","该公司开始寻找降低成本的途径，这使他们决定外包。"]},{"w":"outward","t":"adv. 向外地；adj. 外面的，外表的","p":"'autwəd","e":["The top door opened outward.","最上面的门向外开着。"]},{"w":"outweigh","t":"v. 超过","p":"ˌaʊt'weɪ","c":1,"e":["The advantages of this deal largely outweigh the disadvantages.","这笔交易的利远大于弊。"]},{"w":"oval","t":"adj. 卵形的；n. 卵形","p":"'əʊv(ə)l","e":["Using 2 spoons, form the cheese into small balls or ovals.","用两把勺把干酪挤成小圆球状或椭圆球状。"]},{"w":"over","t":"prep. 在（做）…时","p":"'əʊvə","e":["Over a period of ten years he stole a million pounds from the company.","他在10年间从公司偷走了100万英镑。"]},{"w":"overall","t":"adj. 总的","p":"'əʊvərɔːl","e":["...the overall rise in unemployment.","…失业人数的总体上升。"]},{"w":"overcharge","t":"v. 多收钱","p":"ˌəʊvə'tʃɑ:dʒ","c":1,"e":["They were being overcharged for cheap beer.","他们买的是便宜的啤酒，却被收取了高价。"]},{"w":"overcome","t":"vt. 战胜，克服；压倒，使受不了","p":"ˌəuvə'kʌm","e":["Australia overcame the Netherlands 2-1.","澳大利亚队2比1战胜了荷兰队。"]},{"w":"overestimate","t":"v. 高估","p":"əʊvər'estɪmeɪt","c":1,"e":["The importance of training in health and safety cannot be overestimated (= is extremely important ).","对健康和安全方面的培训极为重要。"]},{"w":"overexcited","t":"adj. 过于激烈的","p":"ˌəʊvərɪkˈsaɪtɪd","c":1,"e":["Some of the boys became overexcited.","有些男孩变得兴奋过度了。"]},{"w":"overflow","t":"vi. 满得外溢，外流，泛滥；充满，洋溢；vt. 淹没，从…中溢出，多得无法容纳；n. 容纳不下的物；溢出，满出；溢流口，溢流管","p":"əʊvə'fləʊ","e":["The drains flooded and water overflowed down the main street.","下水道被淹，水溢到了大街上。"]},{"w":"overhang","t":"v. 悬于…之上，悬垂","p":"əʊvə'hæŋ","e":["Part of the rock wall overhung the path at one point.","部分岩壁悬在了小径一处的上方。"]},{"w":"overhead","t":"adv. 在头顶上；adj. 在头顶上的；架空的；n. 经常费用，管理费用","p":"əʊvə'hed","e":["She turned on the overhead light and looked around the little room.","她打开顶灯，环视这间小屋。"]},{"w":"overhear","t":"vt. 无意中听到，偷听到","p":"ˌəuvə'hɪə","e":["I couldn’t help overhearing your argument.","我无意中听到了你们的争吵。"]},{"w":"overlap","t":"v. 重叠","p":"ˌəʊvəˈlæp","c":1,"e":["When the bag is folded, the bottom overlaps one side.","把包折叠起来时，其底部与一边就重合了。"]},{"w":"overload","t":"v. 使超载","p":"əʊvə'ləʊd","e":["The bus was overloaded with tourists and their luggage.","公共汽车载着满满的游客和行李。"]},{"w":"overlook","t":"vt. 忽视；宽恕；俯瞰","p":"ˌəuvə'luk","e":["Nobody could overlook the fact that box office sales were down.","谁也无法忽视票房销售额在下降这个事实。"]},{"w":"overpass","t":"n. 天桥，立交桥","p":"'əuvəpɑːs","e":["Two cargo trains slammed together at a rail intersection southwest of Cape Girardeau, derailing cars that then struck the support columns of a highway overpass.","两辆货运火车在开普吉拉多西南部的铁路交叉口发生碰撞，部分车厢脱轨，并撞毁了高速公路天桥的支撑柱。"]},{"w":"overseas","t":"adv. 在海外，（向）国外","p":"əʊvə'siːz","e":["Most applications came from overseas.","大部分申请来自海外。"]},{"w":"overstate","t":"v. 夸张","p":"əʊvə'steɪt","c":1,"e":["The importance of a child’s early years cannot be overstated (= is very important ).","儿童幼年期的重要性怎么强调也不为过。"]},{"w":"overt","t":"adj. 公开的，不隐蔽的","p":"əu'vɜːt","e":["an overt attempt to silence their political opponents","他们想压制政敌言论的明显企图"]},{"w":"overtake","t":"v. 突然发生；压倒","p":"əʊvə'teɪk","e":["Tragedy was shortly to overtake him, however.","然而，不幸将很快降临到他的头上。"]},{"w":"overthrow","t":"vt. 推翻，打倒；使终止，摒弃；n. 推翻，终止，结束","p":"ˌəuvə'θrəu","e":["Rebels were already making plans to overthrow the government.","反叛者已在密谋颠覆政府。"]},{"w":"overturn","t":"v. 推翻","p":"ˌəʊvəˈtɜːn","c":1,"e":["Leslie jumped to her feet, overturning her chair.","莱斯莉一跃而起，碰倒了椅子。"]},{"w":"overwhelm","t":"v. 压倒，战胜","p":"ˌəʊvə'welm","c":1,"e":["In 1532 the Spaniards finally overwhelmed the armies of Peru.","1532年，西班牙人最终打垮了秘鲁军队。"]},{"w":"overwhelming","t":"adj. 压倒性的","p":"ˌəʊvəˈwelmɪŋ","c":1,"e":["The British Air Force succeeded despite overwhelming odds against them.","英国空军虽然处境极为不利，但还是完成了任务。"]},{"w":"owe","t":"v. 欠钱","p":"əʊ","c":1,"e":["How much do I owe you (= often used to show that you want to pay for something )?","我该付你多少钱？"]},{"w":"owl","t":"n. 猫头鹰","p":"aʊl","c":1,"e":["The owl is sacred for many Californian Indian people.","对于很多加利福尼亚的印第安人而言，猫头鹰是圣物。"]},{"w":"oxide","t":"n. 氧化物","p":"'ɒksaɪd","e":["iron oxide","氧化铁"]},{"w":"oxidize","t":"v. 氧化，使生锈","p":"'ɒksɪdaɪz","e":["If the organic material decays or is oxidized, it will not form petroleum.","如果有机物腐烂或氧化，它不会形成石油。"]},{"w":"oxygen","t":"n. 氧，氧气","p":"'ɒksɪdʒən","e":["The human brain needs to be without oxygen for only four minutes before permanent damage occurs.","人脑缺氧只需4分钟就会造成永久性损伤。"]},{"w":"oyster","t":"n. 牡蛎","p":"'ɒɪstə","e":["He had two dozen oysters and enjoyed every one of them.","他吃了两打牡蛎，每一个都吃得津津有味。"]},{"w":"ozone","t":"n. 臭氧","p":"'əuzəun","e":["Their skin is weathered and tanned, as if they have fossilised themselves in ozone to keep death at bay.","他们的皮肤饱经风霜被晒得黧黑，好像他们在臭氧中变成化石并在海湾边防止死亡。"]},{"w":"pace","t":"v. 踱步","p":"peɪs","e":["I found Mark at the hospital, pacing restlessly up and down.","我看见马克在医院里焦躁不安地踱来踱去。"]},{"w":"pacific","t":"adj. 性情温和的","p":"pə'sɪfɪk","e":["Gorbachev was less pacific than people thought.","戈尔巴乔夫不像人们想得那样温和。"]},{"w":"package","t":"n. 包裹，包装；一揽子交易；vt. 把…打包；包装","p":"'pækɪdʒ","e":["There’s a package here for a Miami Lakes address.","这里有一个寄往迈阿密湖的包裹。"]},{"w":"pact","t":"n. 契约，协定，条约","p":"pækt","e":["the Warsaw pact","华沙条约"]},{"w":"pal","t":"n. 好朋友；同谋","p":"pæl","e":["We’ve been pals since we were at school.","我们上学的时候就是好朋友。"]},{"w":"pamphlet","t":"n. 小册子","p":"'pæmflət","e":["a political pamphlet","政治宣传册"]},{"w":"panel","t":"n. （选定的）专门小组","p":"'pæn(ə)l","e":["There will be at least three senior doctors on the panel.","专家小组中至少有三名资深医生。"]},{"w":"panic","t":"n. 惊慌","p":"'pænɪk","c":1,"e":["They ascribed courage to me for something I did out of sheer panic.","由于我纯粹因惊慌而做的事，他们认为我很有勇气。"]},{"w":"pant","t":"v. 气喘","p":"pænt","e":["He came in panting after running up the steps.","他跑上台阶，气喘吁吁地走了进来。"]},{"w":"panther","t":"n. 豹，黑豹；美洲狮","p":"'pænθə"},{"w":"pantry","t":"n. 食品柜，餐具室","p":"'pæntrɪ"},{"w":"pants","t":"n. 裤子；男用短衬裤","p":"pæn(t)s","e":["She was wearing dark blue pants and a white sweater.","她穿着深蓝色长裤和白色毛衣。"]},{"w":"paper","t":"v. 贴壁纸","p":"'peɪpə","e":["The previous owners had obviously papered over any damp patches.","原先的房主显然是用壁纸把潮斑都盖起来了。"]},{"w":"paperback","t":"n. 平装本，简装本","p":"'peɪpəbæk","e":["a shelf full of paperbacks","放满了平装书的书架"]},{"w":"parachute","t":"n. 降落伞","p":"'pærəʃuːt","e":["a parachute jump","跳伞"]},{"w":"parade","t":"v. 夸耀（才能等）","p":"pə'reɪd","e":["He is not one to parade his achievements.","他不是一个爱炫耀自己成就的人。"]},{"w":"paradise","t":"n. 天堂","p":"'pærədaɪs","c":1,"e":["The Koran describes paradise as a place containing a garden of delight.","《古兰经》把天堂描绘成一个拥有快乐花园的地方。"]},{"w":"paradox","t":"n. 悖论","p":"ˈpærədɒks","c":1,"e":["The paradox is that fishermen would catch more fish if they fished less.","悖论就是: 如果渔夫减少捕鱼，反而会打到更多的鱼。"]},{"w":"paragraph","t":"n. 段，节","p":"'pærəgrɑːf","e":["the opening paragraphs of the novel","小说开篇的几个段落"]},{"w":"parallel","t":"adj. 并列的，平行的；类似的；对应的；并联的；n. 可相比拟的事物，相似处；平行线，平行面；纬线；vt. 与…相似，与… 相当，比得上","p":"'pærəlel","e":["Take the road running parallel to the main road just after the village.","过那个村子后走与主干道平行的路。"]},{"w":"paralyse","t":"v. 使麻痹，使瘫痪","p":"'pærəlaɪz","e":["Her legs were partly paralysed in the crash.","在撞车事故中她的双腿部分瘫痪。"]},{"w":"paralysis","t":"n. 麻痹，瘫痪，中风；无能，无力","p":"pə'ræləsɪs","e":["The snake’s poison causes paralysis.","这种蛇的毒液会引起身体麻痹。"]},{"w":"paralyze","t":"v. 瘫痪，麻痹","p":"'pærəlaɪz","c":1,"e":["A guy with paralysed legs is not supposed to ride horses.","一个双腿瘫痪的人不该骑马。"]},{"w":"parameter","t":"n. 界限，范围；参数","p":"pə'ræmɪtə","e":["The inquiry has to stay within the parameters laid down by Congress.","调查必须局限于国会设定的范围之内。"]},{"w":"parasite","t":"n. 寄生生物；寄生虫","p":"'pærəsaɪt","e":["Kangaroos harbour a vast range of parasites.","袋鼠身上有各种各样的寄生虫。"]},{"w":"partial","t":"adj. 部分的；不公平的；偏爱的，偏袒的","p":"'pɑːʃl","e":["a partial solution to traffic congestion in Oxford","部分解决牛津地区交通拥堵问题的方法"]},{"w":"participant","t":"n. 参加者，参与者","p":"pɑː'tɪsɪpənt","e":["40 of the course participants are offered employment with the company.","参加课程学习的人中有40名得到了在该公司工作的机会。"]},{"w":"participate","t":"v. 参与","p":"pɑː'tɪsɪpeɪt","e":["Some members refused to participate.","有些会员拒绝参加。"]},{"w":"particle","t":"n. 粒子，微粒","p":"ˈpɑ:tɪkl","c":1,"e":["dust particles","尘埃"]},{"w":"particular","t":"adj. 特称的；苛求的","p":"pəˈtɪkjʊlə(r)","e":["Most students choose one particular area for research.","大多数学生选择一个特定领域进行研究。"]},{"w":"partition","t":"n. 分隔物，隔墙；分割，划分；vt. 隔开；分割，瓜分","p":"pɑː'tɪʃn","e":["...new offices divided only by glass partitions.","…仅仅用玻璃隔板隔开的新办公室。"]},{"w":"passion","t":"n. 激情，热情；酷爱","p":"'pæʃn","e":["The issue arouses strong passions .","那件事激起了人们强烈的情绪。"]},{"w":"passive","t":"adj. 被动的，消极的","p":"'pæsɪv","e":["Kathy seems to take a very passive role in the relationship.","凯茜在这一关系中似乎扮演着十分被动的角色。"]},{"w":"passport","t":"n. 达到目的的手段","p":"'pɑːspɔːt","e":["The only passport to success is hard work.","获得成功的唯一途径就是艰苦奋斗。"]},{"w":"pastime","t":"n. 消遣，娱乐","p":"'pɑːstaɪm","e":["Reading was her favourite pastime.","阅读是她最喜爱的消遣方式。"]},{"w":"pastry","t":"n. 油酥面团，酥皮糕点","p":"'peɪstri","e":["a Danish pastry","丹麦油酥糕饼"]},{"w":"pasture","t":"n. 牧场","p":"'pɑ:stʃə(r)","c":1,"e":["the lush pastures of the southern counties","南部各郡茂盛的牧场"]},{"w":"patent","t":"adj. 专利的，受专利保护的；n. 专利，专利权；vt. 得到…的专利权","p":"'pætnt","e":["a patent lock","专利锁"]},{"w":"paternity","t":"n. 父权，父子关系","p":"pə'tɜːnəti","e":["The paternity of the child is in dispute.","这个孩子的生父是谁尚有疑问。"]},{"w":"pathetic","t":"adj. 差劲的，令人生厌的；引起怜悯的，可怜的，可悲的","p":"pə'θetɪk","e":["I know it sounds pathetic now, but at the time I was frightened.","我知道现在听起来挺窝囊，不过当时我很害怕。"]},{"w":"patriot","t":"n. 爱国者，爱国主义者","p":"'peɪtriət","e":["It has been suggested the founders were not true patriots but men out to protect their own interests.","有人指出创建者并非真正的爱国者，而是一些维护自己利益的人。"]},{"w":"patriotic","t":"adj. 爱国的，有爱国心的，显示爱国精神的","p":"ˌpeɪtri'ɒtɪk","e":["I’m not very patriotic.","我不是很爱国。"]},{"w":"patrol","t":"v. 巡逻，巡查；n. 巡逻，巡查；巡逻兵，巡逻队","p":"pə'trəul","e":["an area patrolled by special police units","由特警部队巡逻的地区"]},{"w":"patron","t":"n. 资助人，赞助人；老主顾，顾客","p":"'peɪtrən","e":["a wealthy patron","富有的赞助人"]},{"w":"pattern","t":"n. 模式","p":"'pætn","c":1,"e":["Their descriptions seemed to follow a set pattern (= always develop in the same way ) .","他们的描述似乎依据固定的模式。"]},{"w":"pause","t":"n. 暂停，迟疑","p":"pɔ:z","c":1,"e":["There was a pause while Alice changed the tape.","艾丽斯换磁带的时候出现了短暂的停顿。"]},{"w":"pave","t":"v. 铺路","p":"peɪv","c":1,"e":["a paved courtyard","地面铺砌过的院子"]},{"w":"payroll","t":"n. 工资总额","p":"ˈpeɪrəʊl","c":1,"e":["The annual payroll was $88 million.","年度工资总支出为8,800万美元"]},{"w":"peacock","t":"n. 孔雀","p":"'piːkɒk","e":["...peacocks strutting slowly across the garden.","...孔雀在花园中趾高气扬地走来走去。"]},{"w":"peak","t":"vi. 达到高峰；达到最大值；adj. 最大值的；高峰的；n. 山顶，顶点，顶峰","p":"piːk","e":["Sales peaked in August, then fell sharply.","销售额8月份达到最高点，然后急速下降。"]},{"w":"pearl","t":"n. 珍珠；珠状物；珍品","p":"pɜːl","e":["{\"GLOSS\":[\"a necklace made of pearls\"],\"COLLOINEXA\":[\"a string of pearls\"]}","一串珍珠"]},{"w":"peck","t":"v. 啄，啄起","p":"pek","e":["birds pecking at breadcrumbs on the pavement","在人行道上啄食面包屑的鸟儿"]},{"w":"peculiar","t":"adj. 奇怪的；特有的","p":"pɪ'kju:lɪə(r)","c":1,"e":["It seems very peculiar that no one noticed Kay had gone.","没有人注意到凯已经走了，这好像很奇怪。"]},{"w":"peculiarity","t":"n. 特性，独特性；怪癖","p":"pɪ,kjuːlɪ'ærɪtɪ","e":["The lack of a written constitution is a peculiarity of the British political system.","没有一部成文宪法是英国政治制度的一大特点。"]},{"w":"pedal","t":"vi. 踩踏板，骑车；n. 踏板，踏脚；vt. 脚蹬，踩动…的踏板","p":"'pedl","e":["She was pedalling furiously (= very fast ) .","她飞快地踩着踏板。"]},{"w":"pedestrian","t":"n. 步行者，行人","p":"pə'destriən","e":["Ingrid was a walker, even in Los Angeles, where a pedestrian is a rare sight.","英格丽德是个步行者，即使在行人少见的洛杉矶也是如此。"]},{"w":"pedlar","t":"n. （挨户兜售的）小贩","p":"'pedlə","e":["The pedlar sponged money off us.","那个小商贩骗了我们的钱。"]},{"w":"peel","t":"vi. 剥落，脱皮；vt. 削…的皮，剥…的壳；n. 皮，外衣","p":"piːl","e":["Peel and dice the potatoes.","把马铃薯去皮并切成丁。"]},{"w":"peer","t":"n. 同龄人","p":"pɪə(r)","c":1,"e":["American children did less well in math than their peers in Japan.","美国儿童的数学成绩不如日本的同龄儿童。"]},{"w":"peg","t":"n. 小钉，栓，挂物钉；桩；vt. 用钉子钉，用钉固定；限定；将…看成，将…归入","p":"peg","e":["a pattern made with coloured pegs on a board","木板上彩钉构成的图形"]},{"w":"penalty","t":"n. 惩罚","p":"'penəltɪ","c":1,"e":["If he is convicted, he could receive the death penalty (= be killed as a punishment ) .","一旦定罪，他可能会被判处死刑。"]},{"w":"pendulum","t":"n. 摆，钟摆；摇摆不定的事态","p":"'pendjələm","e":["After several years of Republican government, the pendulum will undoubtedly swing back and voters will elect a Democrat.","由共和党执政数年后，选民无疑会掉过头来，选出一位民主党人。"]},{"w":"penetration","t":"n. 穿入；渗透","p":"penɪ'treɪʃ(ə)n","e":["the company's successful penetration of overseas markets","公司对海外市场的顺利开拓"]},{"w":"penguin","t":"n. 企鹅","p":"'peŋgwɪn","e":["Lovelace: turn to the penguin next to you… and give him a great big hug!","拉雷丝：转向你旁边的企鹅……然后给他一个巨大的拥抱！"]},{"w":"peninsula","t":"n. 半岛","p":"pə'nɪnsjələ","e":["the Korean peninsula","朝鲜半岛"]},{"w":"pension","t":"n. 养老金","p":"'penʃn","c":1,"e":["If you are self-employed, you should think about taking out a private pension .","如果你是自由职业者，应该考虑办理私人养老金事宜。"]},{"w":"perception","t":"n. 看法；意识","p":"pə'sepʃ(ə)n","c":1,"e":["He is interested in how our perceptions of death affect the way we live.","他对我们的死亡观如何影响我们的生活方式感兴趣。"]},{"w":"perch","t":"n. （禽鸟的）栖木","p":"pɜːtʃ","e":["A small, yellow bird in a cage sat on its perch outside the house.","屋外，一只小黄鸟站在鸟笼的栖木上。"]},{"w":"perfect","t":"v. 使熟练，使改善","p":"ˈpəːfɪkt; (for v.) pəˈfekt","e":["Mock trials help students perfect their legal skills.","模拟庭审有助于学生们完善自己的法律技能。"]},{"w":"perfection","t":"n. 完美，完善","p":"pə'fekʃn","e":["My father expected perfection from all of us.","父亲期望我们都尽善尽美。"]},{"w":"performance","t":"n. 演出；履行，执行，完成；工作情况，表现，工作性能","p":"pə'fɔːməns","e":["This evening’s performance will begin at 8.00 pm.","今晚的演出8点开始。"]},{"w":"perfume","t":"n. 香水，香料，香气；vt. 使充满芳香；洒香水于","p":"'pɜːfjuːm","e":["She was wearing the perfume that he’d bought her.","她擦了他买给她的香水。"]},{"w":"peril","t":"n. 危机；危险的事物","p":"'perɪl; -r(ə)l","e":["a voyage that was fraught with peril","历尽艰险的旅程"]},{"w":"perimeter","t":"n. 周（边）；周长","p":"pə'rɪmɪtə","e":["Calculate the perimeter of the rectangle.","计算这个长方形的周长。"]},{"w":"periodic","t":"adj. 周期的，定期的，时而发生的","p":"ˌpɪəri'ɒdɪk","e":["periodic home visits by nurses","护士的定期上门探访"]},{"w":"periodical","t":"adj. 周期的；定期的；时而发生的；n. 期刊","p":"ˌpɪəri'ɒdɪkl","e":["She made periodical visits to her dentist.","她定期去看牙医。"]},{"w":"peripheral","t":"adj. 外围的的；末梢的","p":"pə'rɪf(ə)r(ə)l","e":["the city’s peripheral suburbs","这座城市的市郊"]},{"w":"perish","t":"v. 死亡","p":"'perɪʃ","c":1,"e":["Hundreds perished when the ship went down.","轮船沉没，数百人罹难。"]},{"w":"permanent","t":"adj. 永久的","p":"ˈpɜ:mənənt","c":1,"e":["Miller soon became a permanent fixture (= someone or something that is always there ) on the team.","米勒很快就成为球队的固定队员。"]},{"w":"permeate","t":"v. 渗透","p":"'pɜːmɪeɪt","c":1,"e":["The smell of diesel oil permeated the air.","空气里充斥着柴油的气味。"]},{"w":"permissible","t":"adj. 可允许的，许可的","p":"pə'mɪsəbl","e":["the maximum permissible level of radiation","允许的最大辐射水平"]},{"w":"perpendicular","t":"adj. 垂直的","p":",pɜːp(ə)n'dɪkjʊlə","e":["a perpendicular wall of rock","直立的石壁"]},{"w":"perpetual","t":"adj. 永久的","p":"pəˈpetʃuəl","c":1,"e":["the perpetual snows of the mountaintops","山顶的终年积雪"]},{"w":"perplex","t":"vt. 使困惑，使费解；使复杂化","p":"pə'pleks","e":["Shea’s symptoms perplexed the doctors.","谢伊的症状令医生们困惑。"]},{"w":"persecute","t":"v. 迫害，残害","p":"'pɜːsɪkjuːt","e":["The Puritans left England to escape being persecuted.","清教徒离开了英国以躲避迫害。"]},{"w":"persevere","t":"v. 坚持，不屈不挠","p":"pɜːsɪ'vɪə","e":["It can be tricky at first, but persevere.","一开始会有些棘手，不过要坚持。"]},{"w":"persist","t":"vi. 坚持，持续","p":"pə'sɪst","e":["‘I don’t think it’s right,’ John persisted.","“我认为那不对。”约翰坚持说道。"]},{"w":"persistence","t":"n. 坚持；持续，存留","p":"pə'sɪst(ə)ns","e":["Her persistence paid off when she was offered the job of manager.","她得到了经理的职位，不懈坚持终于有了回报。"]},{"w":"persistent","t":"adj. 持续的；坚持不懈的","p":"pəˈsɪstənt","c":1,"e":["If she hadn’t been so persistent she might not have gotten the job.","假如不是如此执着，她可能得不到这份工作。"]},{"w":"personality","t":"n. 人格，个性；人物","p":"ˌpɜːsə'næləti","e":["Despite their different personalities, they became the best of friends.","尽管个性不同，他们还是成了最好的朋友。"]},{"w":"personnel","t":"n. 人事部门","p":"pɜːsə'nel","e":["A copy should then be sent to Personnel for our files.","然后必须送一份到人事部供我们存档。"]},{"w":"perspective","t":"n. 视角，观点","p":"pə'spektɪv","c":1,"e":["His father’s death gave him a whole new perspective on life.","父亲的死使他对生活有了全新的看法。"]},{"w":"persuasion","t":"n. 说服，劝说；信念，信仰","p":"pə'sweɪʒn","e":["After a little gentle persuasion , Debbie agreed to let us in.","好言劝说了几句后，黛比就同意让我们进去了。"]},{"w":"pertinent","t":"adj. 恰当的；有关的","p":"'pɜːtɪnənt","e":["The last point is particularly pertinent to today’s discussion.","最后一点和今天的讨论关系尤为密切。"]},{"w":"pessimist","t":"n. 悲观主义者","p":"ˈpesɪmɪst","c":1,"e":["Don’t be such a pessimist!","别这么悲观！"]},{"w":"pessimistic","t":"adj. 悲观的","p":",pesɪ'mɪstɪk","c":1,"e":["a pessimistic view of life","对人生的悲观看法"]},{"w":"pest","t":"n. 有害生物，害虫；讨厌的人","p":"pest","e":["a chemical used in pest control","用于防治虫害的一种化学品"]},{"w":"petition","t":"v. 请愿，正式请求；n. 请愿书，申请书；诉状","p":"pə'tɪʃn","e":["...couples petitioning for divorce.","…申请离婚的几对夫妇。"]},{"w":"petty","t":"adj. 小的，琐碎的；不重要的；气量小的，心胸狭窄的","p":"'peti","e":["petty restrictions","小限制"]},{"w":"phase","t":"n. 阶段；方面；相，相位","p":"feɪz","e":["a new drug that is in the experimental phase","处于试验阶段的一种新药"]},{"w":"phenomenon","t":"n. 现象","p":"fə'nɒmɪnən","c":1,"e":["Homelessness is not a new phenomenon .","无家可归已不是什么新现象。"]},{"w":"philosopher","t":"n. 哲学家","p":"fəˈlɒsəfə(r)","c":1,"e":["Plato, Aristotle, and other Greek philosophers","柏拉图、亚里士多德和其他希腊哲学家"]},{"w":"philosophy","t":"n. 哲学","p":"fəˈlɒsəfi","c":1,"e":["Emma studies philosophy at university.","埃玛在大学攻读哲学。"]},{"w":"photoelectric","t":"adj. 光电的","p":",fəʊtəʊɪ'lektrɪk","e":["Advanced imported photoelectric supervision system is used.","采用先进的进口光电眼监控系统。"]},{"w":"photography","t":"n. 摄影术","p":"fə'tɒgrəfɪ","e":["He did fashion photography for ‘Vogue’ magazine.","他为《时尚》杂志拍过时装照片。"]},{"w":"physically","t":"adv. 身体上；体格上","p":"'fɪzɪkəllɪ","e":["children who have been physically abused","身体受到虐待的儿童"]},{"w":"physiological","t":"adj. 生理的，生理学的","p":"ˌfɪziə'lɒdʒɪkl","e":["If so, this would add to a growing list of physiological and biological markers of sexual orientation.","如果是这样，这可能会给生理和生物学上的性取向标记增加一长串名单。"]},{"w":"pickle","t":"n. 腌制食品，泡菜","p":"'pɪk(ə)l","e":["a selection of cold meats and pickles","精选的冷肉和腌菜"]},{"w":"pier","t":"n. 码头；（桥）墩","p":"pɪə","e":["Waves were swashing against the piers.","浪花拍击着桥墩。"]},{"w":"pierce","t":"v. 刺穿","p":"pɪəs","c":1,"e":["Rose underwent emergency surgery after a bullet pierced her lung.","罗丝被子弹射穿肺部，接受了紧急手术。"]},{"w":"pilgrim","t":"n. 朝圣者","p":"'pɪlgrɪm","e":["pilgrims visiting a holy shrine","祭拜圣庙的朝圣者"]},{"w":"pineapple","t":"n. 凤梨，波萝","p":"'paɪnæp(ə)l","e":["pineapple chunks","菠萝块"]},{"w":"pious","t":"adj. 虔诚的；虔奉宗教的","p":"'paɪəs","e":["He was a quiet, pious man.","他是个文静、虔诚的人。"]},{"w":"pipe","t":"n. 管乐器","p":"paɪp"},{"w":"pirate","t":"n. 非法盗印者，侵犯版权者；海盗；vt. 盗用，非法盗印","p":"'paɪrət","e":["Computer game pirates cost the industry twenty million pounds a year.","电脑游戏盗版者每年要给该行业带来两千万英镑的损失。"]},{"w":"pistol","t":"n. 手枪","p":"'pɪstl","e":["He hopped back up the stairs and took his pistol.","他赶紧返回到楼上，拿上了他的手枪。"]},{"w":"piston","t":"n. 活塞","p":"'pɪst(ə)n","e":["The piston moves by steam pressure.","活塞在蒸汽压力下运动。"]},{"w":"pitch","t":"v. 投掷，使猛然倒下；表达，定下特定程度；定调；架设，搭，扎；颠簸；n. 球场；程度，强度；高度，高音；沥青","p":"pɪtʃ","e":["She crumpled up the page and pitched it into the fire.","她把那页纸揉成团，扔进了火里。"]},{"w":"plague","t":"n. 瘟疫，鼠疫；灾难，祸患；vt. 使痛苦，给…造成困难","p":"pleɪg","e":["drops in population levels due to plagues and famines","瘟疫和饥荒造成的人口水平下降"]},{"w":"plain","t":"adj. 坦白的；普通的","p":"pleɪn","e":["You don't need any special skills for this job, just plain common sense.","这项工作不需要任何特殊技能，只要有普通常识就够了。"]},{"w":"planet","t":"n. 行星","p":"'plænɪt","e":["The picture shows six of the nine planets in the solar system.","这张图片展示太阳系9个行星中的6个行星。"]},{"w":"planetary","t":"n. 行星的","p":"'plænətri","e":["OK, this is the Bohr model, Bohr model of the atom is planetary or nuclear.","好的，这就是波尔模型，波尔的原子模型是行星模型或者核心模型。"]},{"w":"plaster","t":"n. 灰浆，灰泥；石膏；橡皮膏，膏药；vt. 在…上抹灰泥，厚厚地涂抹","p":"'plɑːstə","e":["The ceiling he had just plastered fell in and knocked him off his ladder.","他刚抹过灰泥的那块天花板脱落了，把他从梯子上砸了下来。"]},{"w":"plastic","t":"adj. 塑料的；塑性的","p":"'plæstɪk","e":["a plastic spoon","塑料汤匙"]},{"w":"plateau","t":"n. 高原；稳定时期","p":"'plætəu","e":["Inflation rates have reached a plateau.","通货膨胀率已趋平稳。"]},{"w":"platform","t":"n. 政纲，党纲，宣言","p":"'plætfɔːm","e":["a strong women’s rights platform","强硬的妇女权利政纲"]},{"w":"plausible","t":"adj. 似有道理的，似乎正确的，貌似可信的","p":"'plɔːzəbl","e":["His story certainly sounds plausible.","他的叙述听上去当然很合理。"]},{"w":"plea","t":"n. 恳求，请求；抗辩，答辩，辩护；借口，托辞","p":"pliː","e":["Caldwell made a plea for donations.","考德威尔恳求捐款。"]},{"w":"plead","t":"vi. 恳求，请求；申诉，答辩，辩护；vt. 为…辩护，提出…为理由","p":"pliːd","e":["He appeared before the committee to plead his case.","他出现在委员会上为他的案子辩护。"]},{"w":"pledge","t":"n. 保证，誓言；vt. 保证，许诺","p":"pledʒ","e":["The meeting ended with a pledge to step up cooperation between the six states of the region.","会议以加快该地区6个州之间合作的承诺结束。"]},{"w":"plot","t":"n. 情节","p":"plɒt","c":1,"e":["We discover that Jack isn’t as innocent as he seems, as the plot unfolds (= gradually becomes clearer ) .","随着情节的展开，我们发现杰克并不像表面上看起来那么清白。"]},{"w":"plough","t":"n. 犁","p":"plaʊ","c":1,"e":["There are new tractors and new ploughs in the machinery lot.","机器设备场里有新拖拉机和新耕犁。"]},{"w":"pluck","t":"v. 鼓起（勇气），振作","p":"plʌk","e":["He finally plucked up enough courage to ask her out.","他终于鼓起勇气约她出去。"]},{"w":"plump","t":"adj. 丰满的","p":"plʌmp","e":["The nurse was a cheerful plump woman.","那护士是个性格开朗、体形丰满的女人。"]},{"w":"plunder","t":"v. 掠夺，劫掠；n. 掠夺，抢劫","p":"'plʌndə","e":["The rich provinces of Asia Minor were plundered by the invaders.","小亚细亚的富饶地区遭到侵略者的劫掠。"]},{"w":"plunge","t":"n&v. 纵身投入，猛冲，猛跌","p":"plʌndʒ","e":["At least 50 people died when a bus plunged into a river.","一辆公共汽车冲进了河里，至少有50人死亡。"]},{"w":"pneumatic","t":"adj. 空气的；气动的","p":"njuː'mætɪk","e":["pneumatic tyres","充气轮胎"]},{"w":"poetry","t":"n. 诗歌","p":"'pəʊətrɪ","c":1,"e":["He reads a lot of poetry.","他大量阅读诗歌。"]},{"w":"poisonous","t":"adj. 有毒的；恶毒的","p":"'pɔɪzənəs","e":["She was bitten on the ankle by a poisonous snake .","她被毒蛇咬了脚踝。"]},{"w":"poke","t":"vi. 伸出，突出；vt. 戳，捅；用…戳，把…戳向；伸出，突出；n. 戳，捅","p":"pəuk","e":["One of the nurses poked her head around the door.","其中一名护士从门里探出头来。"]},{"w":"polar","t":"adj. 极地的","p":"ˈpəʊlə(r)","c":1,"e":["As our climate warms up, the polar ice caps will begin to melt.","随着地球气候逐渐变暖，极地的冰冠将开始融化。"]},{"w":"polarity","t":"n. （人、意见或观念的）截然相反，截然对立；极性","p":"pə(ʊ)'lærɪtɪ","e":["...the polarities of good and evil.","..善与恶的截然对立。"]},{"w":"pole","t":"n. 杆；极，磁极，电极","p":"pəul","e":["a telephone pole","电话线杆"]},{"w":"polish","t":"vt. 磨光；修改，润色，使优美；n. 擦光剂","p":"'pɒlɪʃ","e":["Your essay is good, you just need to polish it a bit.","你的文章不错，只要稍加润色就可以了。"]},{"w":"politics","t":"n. 政纲，政见，策略","p":"'pɒlɪtɪks","e":["I assume her politics must be fairly conservative.","我猜她的政治观点一定相当保守。"]},{"w":"poll","t":"n. 民意测验","p":"pəʊl","c":1,"e":["The latest public opinion poll showed that 25% of us consider ourselves superstitious.","最新的民意调查显示我们中有25%的人认为自己迷信。"]},{"w":"pollutant","t":"n. 污染物质","p":"pə'luːtənt","e":["a dumping ground for toxic pollutants","有毒污染物堆放场"]},{"w":"polymer","t":"n. 聚合物，多聚物","p":"'pɒlɪmə","e":["Many polymers, such as nylon, are artificial.","许多聚合物是人造的，比如说尼龙。"]},{"w":"ponder","t":"v. 仔细考虑","p":"'pɒndə(r)","c":1,"e":["He continued to ponder the problem as he walked home.","他一边往家走一边继续思考那个问题。"]},{"w":"pop","t":"v. （意外地）出现","p":"pɒp","e":["The window opened and a dog's head popped out.","窗子打开了，冷不防一只狗探出头来。"]},{"w":"pope","t":"n. 教皇，罗马主教","p":"pəup","e":["The highlight of the pope's visit will be his message to the people.","教皇访问的亮点是，他将给人们传达训诫。"]},{"w":"popularity","t":"n. 普及，流行；声望","p":"ˌpɒpju'lærəti","e":["The president’s popularity has declined considerably.","总统的支持率大大下降了。"]},{"w":"porcelain","t":"n. 瓷；adj. 瓷的，瓷制的","p":"'pɔːs(ə)lɪn","e":["a porcelain vase","瓷花瓶"]},{"w":"porch","t":"n. 门廊","p":"pɔːtʃ","e":["He was standing on the porch, waving as we drove away.","我们开车离开的时候，他站在走廊上向我们挥手。"]},{"w":"pore","t":"vi. 仔细阅读，审视；n. 毛孔，细孔","p":"pɔː","e":["We spent hours poring over travel brochures.","我们花了几个小时仔细研究旅游宣传册。"]},{"w":"portable","t":"adj. 可移动的","p":"'pɔːtəb(ə)l","e":["a portable radio","便携式收音机"]},{"w":"portion","t":"n. 部分","p":"'pɔ:ʃn","c":1,"e":["Damage was confined to a small portion of the castle.","城堡仅有一小部分受到了损坏。"]},{"w":"portray","t":"v. 描述","p":"pɔr'trei","c":1,"e":["The President likes to portray himself as a friend of working people.","总统喜欢以工薪阶层的朋友自居。"]},{"w":"pose","t":"v. 形成","p":"pəʊz","c":1,"e":["Rising unemployment is posing serious problems for the administration.","失业率上升正在给政府造成严重的问题。"]},{"w":"position","t":"v. 安放；n. 位置；职位","p":"pəˈzɪʃn","c":1,"e":["Our hotel was in a superb central position near St Mark’s Square.","我们的酒店处于极佳的中心位置，在圣马克广场附近。"]},{"w":"positive","t":"adj. 确实的，明确的；积极的，肯定的","p":"'pɒzətɪv","e":["It’s been a difficult time but, on the positive side , I feel physically fine.","日子过得不容易，不过从好的方面看，我的身体状况还不错。"]},{"w":"positively","t":"adv. 确定的，断然","p":"'pɒzətɪvlɪ","e":["Some holiday destinations are positively dangerous .","有些度假地真的很危险。"]},{"w":"possess","t":"vt. 占用，拥有","p":"pə'zes","e":["He no longer possessed the power to frighten her.","他再也吓不倒她了。"]},{"w":"possession","t":"n. 拥有","p":"pə'zeʃn","c":1,"e":["We didn’t take possession of (= get and start using ) the car until a few days after the auction.","拍卖会过后几天我们才正式拿到那辆车。"]},{"w":"possibility","t":"n. 可能的事","p":",pɒsɪ'bɪlɪtɪ","e":["There were several possibilities open to each manufacturer.","每个制造商都可以有几种不同的选择。"]},{"w":"postal","t":"adj. 邮政的，邮局的","p":"'pəʊst(ə)l","e":["an increase in postal charges","邮资的上涨"]},{"w":"postdoctoral","t":"adj. 博士后的","p":"ˌpəʊstˈdɒktərəl","c":1,"e":["Most postdoctoral work is funded by the research councils.","大部分的博士后的工作都是由研究会资助的。"]},{"w":"postulate","t":"v. 假定，假设","p":"'pɒstjʊleɪt","e":["He dismissed arguments postulating differing standards for human rights in different cultures and regions.","他无法接受的是假定人权标准在不同文化和地区有所不同。"]},{"w":"posture","t":"vi. 摆出姿势，装模作样；n. 姿势，姿态；看法，态度","p":"'pɒstʃə","e":["She says the president may just be posturing.","她说总统也许只是在作态。"]},{"w":"potential","t":"adj. 潜在的；n. 潜力","p":"pəˈtenʃl","c":1,"e":["The company certainly has the potential for growth.","那家公司肯定有发展潜力。"]},{"w":"potentially","t":"adv. 潜在地","p":"pə'tenʃəlɪ","c":1,"e":["a potentially dangerous situation","有潜在危险的局势"]},{"w":"poultry","t":"n. 家禽","p":"'pəʊltrɪ","e":["...a poultry farm.","…一个家禽饲养场。"]},{"w":"poverty","t":"n. 贫穷，贫困","p":"'pɒvəti","e":["continued efforts to alleviate poverty and raise living standards","缓解贫困和提高生活水平的不懈努力"]},{"w":"practicable","t":"adj. 可行的，适用的","p":"'præktɪkəbl","e":["It is their duty to ensure, so far as is reasonably practicable, that the equipment is safe.","在力所能及的情况下确保设备安全是他们的职责。"]},{"w":"practical","t":"adj. 实践的；实用的","p":"ˈpræktɪkl","c":1,"e":["Candidates should have training and practical experience in basic electronics.","应征者应该具备基础电子学方面的培训和实践经验。"]},{"w":"practice","t":"n. 做法","p":"ˈpræktɪs","c":1,"e":["religious beliefs and practices","宗教信仰和习俗"]},{"w":"pragmatic","t":"adj. 务实的，讲求实际的","p":"prægˈmætɪk","c":1,"e":["Williams took a more pragmatic approach to management problems.","威廉斯在管理问题上采用的是一种更务实的做法。"]},{"w":"prairie","t":"n. 大草原，牧场","p":"'preərɪ","e":["Andrew traversed the prairie on horseback.","安德鲁骑马穿越大草原。"]},{"w":"preach","t":"vi. 布道，说教；vt. 宣讲，布道；竭力鼓吹，宣传","p":"priːtʃ","e":["He traveled the southern states, preaching the gospel .","他游历南方各州宣讲福音。"]},{"w":"precede","t":"vt. 在…之前，先于","p":"prɪ'siːd","e":["Lunch will be preceded by a short speech from the chairman.","午餐开始之前主席会发表一段简短的讲话。"]},{"w":"precedent","t":"n. 先例","p":"ˈpresɪdənt","c":1,"e":["a legal precedent","判例"]},{"w":"precious","t":"adj. 珍贵的，宝贵的","p":"'preʃəs","e":["planes delivering precious supplies of medicine and food","运送药品、食品等宝贵物资的飞机"]},{"w":"precipitate","t":"v. 使突然发生；猛然抛下；使沉淀","p":"prɪ'sɪpɪteɪt","e":["The killings in Vilnius have precipitated the worst crisis yet.","维尔纽斯的杀戮事件快速引发了迄今为止最严重的危机。"]},{"w":"precise","t":"adj. 精确的，准确的；严谨的","p":"prɪ'saɪs","e":["‘She’s a lot older than you, isn’t she?’ ‘Fifteen years, to be precise .’","“她比你大很多，是不是？”“准确地说，大了15岁。”"]},{"w":"precision","t":"n. 精确性","p":"prɪˈsɪʒn","c":1,"e":["The choir sang with precision.","合唱团的演唱准确无误。"]},{"w":"preclude","t":"vt. 排除；阻止，妨碍","p":"prɪ'kluːd","e":["rules that preclude experimentation in teaching methods","禁止进行教学方法试验的规定"]},{"w":"predecessor","t":"n. 前任，前辈；原有事物，前身","p":"'priːdɪsesə","e":["Kennedy’s predecessor as President was the war hero Dwight Eisenhower.","肯尼迪总统的前任是战争英雄德怀特·艾森豪威尔。"]},{"w":"predestine","t":"vt. 预先确定；注定","p":"priː'destɪn"},{"w":"predict","t":"v. 预测","p":"prɪ'dɪkt","c":1,"e":["As Liz had predicted , the rumours were soon forgotten.","正如利兹所预料的，流言很快就被淡忘了。"]},{"w":"prediction","t":"n. 预言，预告；预报","p":"prɪ'dɪkʃ(ə)n","e":["The data can be used to make useful economic predictions .","这些数据可用于进行有用的经济预测。"]},{"w":"predominant","t":"adj. 占主导地位的，显著的","p":"prɪ'dɒmɪnənt","e":["In this painting, the predominant colour is black.","这幅画的主色调是黑色。"]},{"w":"predominantly","t":"adv. 占主导地位地","p":"prɪˈdɒmɪnəntli","c":1,"e":["The landscape has remained predominantly rural in appearance.","该风景看上去主要保留了乡村风貌。"]},{"w":"preferable","t":"adj. 更可取的，更好的，更合意的","p":"'prefrəbl","e":["In warm weather, clothes made of natural fabrics are infinitely preferable (= much better ) .","天气暖和的时候，穿天然织物的衣服要舒适得多。"]},{"w":"preference","t":"n. 偏爱","p":"ˈprefrəns","c":1,"e":["Parents may be able to express a preference as to the school their child will attend.","家长也许可以表明愿意让孩子就读哪所学校。"]},{"w":"pregnancy","t":"n. 怀孕","p":"'pregnənsi","e":["This drug should not be taken during pregnancy.","这种药妊娠期间不得服用。"]},{"w":"pregnant","t":"adj. 怀孕的；意义深长的；意义深长的","p":"'pregnənt","e":["He stopped, and there was a pregnant pause.","他停住了，那是个意味深长的停顿。"]},{"w":"preindustrial","t":"adj. 工业化以前的","p":"pri:ɪn'dʌstrɪəl","c":1,"e":["...the transition from preindustrial to industrial society.","从未工业化社会到工业化社会的转变"]},{"w":"prejudice","t":"n. 偏见","p":"'predʒʊdɪs","c":1,"e":["It takes a long time to overcome these kinds of prejudices.","战胜这些偏见需要假以时日。"]},{"w":"preliminary","t":"adj. 预备的，初步的；n. 初步做法，起始行为","p":"prɪ'lɪmɪnəri","e":["the preliminary stages of the competition","竞赛的预赛阶段"]},{"w":"premature","t":"adj. 比预期时间早的；不成熟的，仓促的","p":"'premətʃə","e":["his premature death due to cancer","他因癌症而早逝"]},{"w":"prematurely","t":"adv. 早熟地，过早地","p":"'premətʃəlɪ","c":1,"e":["Her hair became prematurely white.","她的头发过早地苍白了。"]},{"w":"premier","t":"adj. 首要的，首位的，首次的；n. 总理，首相","p":"'premiə","e":["...the country's premier opera company.","…这个国家最好的歌剧团。"]},{"w":"premise","t":"n. 房屋和地基，经营场址；前提，假设","p":"'premɪs","e":["Schools may earn extra money by renting out their premises.","学校通过出租房屋场地可以获取额外收入。"]},{"w":"premium","t":"n. 〔尤指每年缴付的〕保险费","p":"ˈpri:miəm","c":1,"e":["It is too early to say whether insurance premiums will be affected.","保险费会不会受到影响现在判定还为时过早。"]},{"w":"preparatory","t":"adj. 预备的","p":"prɪ'pærətri","e":["preparatory talks to clear the way for a peace settlement","为缔结和平协议扫清道路的预备性会谈"]},{"w":"prescient","t":"adj. 预知的，预见的","p":"'presiənt","e":["...an eerily prescient comedy about a populist multimillionaire political candidate.","...围绕一位身价数百万的民粹主义政治候选人的一部喜剧，其预见性近乎诡异。"]},{"w":"prescribe","t":"v. 开处方","p":"prɪ'skraɪb","c":1,"e":["The physician examines the patient then diagnoses the disease and prescribes medication.","内科医生检查了病人，然后对疾病作出诊断，并开出药方。"]},{"w":"prescription","t":"n. 处方，药方，药；开处方，开药方","p":"prɪ'skrɪpʃn","e":["We are trying to cut the price of prescription drugs .","我们正努力降低处方药的价格。"]},{"w":"present","t":"v. 呈现，给予","p":"'preznt","c":1,"e":["She was presented with an award .","她被授予一个奖项。"]},{"w":"presentation","t":"n. 展示；讲话","p":"ˌpreznˈteɪʃn","c":1,"e":["James Watson, Philip Mayo and I gave a slide and video presentation.","詹姆斯·沃森、菲利普·梅奥和我一起做了一场有幻灯和录像片的讲座。"]},{"w":"preservation","t":"n. 保存，储藏；保持","p":"prezə'veɪʃ(ə)n","e":["the preservation of peace in the region","维护该地区的和平"]},{"w":"preserve","t":"v. 保存，保护","p":"prɪ'zɜːv","c":1,"e":["We must encourage the planting of new trees and preserve our existing woodlands.","我们必须鼓励栽种新树木，同时也要保护现有的林地。"]},{"w":"preset","t":"v. 预先装置","p":"priː'set","e":["...a computerized timer that can be preset.","...一个可以预调的电脑定时器。"]},{"w":"preside","t":"vi. 主持，主管","p":"prɪ'zaɪd","e":["Mr Justice Waller, presiding judge for the northeast","沃勒法官，东北地区的首席法官"]},{"w":"presidency","t":"n. 总统任期","p":"'prezɪdənsɪ","c":1,"e":["Roosevelt was elected four times to the presidency of the US.","罗斯福四次当选美国总统。"]},{"w":"press","t":"n. 出版社；印刷所；印刷机","p":"pres","e":["We were able to watch the books rolling off the presses.","我们可以看到书本从印刷机上源源不断地印出。"]},{"w":"pressure","t":"n. 压，压强；压迫；vt. 对…施加压力，迫使，说服","p":"'preʃə","e":["They are putting pressure on people to vote yes.","他们正在向民众施加压力，要求他们投赞成票。"]},{"w":"prestige","t":"n. 名声，声望","p":"pre'sti:ʒ","c":1,"e":["This little-known British firm has now gained considerable prestige .","这家名不见经传的英国公司如今已经声名鹊起。"]},{"w":"presumably","t":"adv. 大概，可能，据推测","p":"prɪ'zjuːməbli","e":["It’s raining, which presumably means that your football match will be cancelled.","下雨了，这可能意味着你们的足球比赛要取消。"]},{"w":"presume","t":"vi. 擅自行事；vt. 推测，假定，相信；冒昧，擅自；认定，推定","p":"prɪ'zjuːm","e":["They're resentful that outsiders presume to meddle in their affairs.","他们对外人擅自干预他们的事务怨恨不已。"]},{"w":"pretext","t":"n. 借口，托辞","p":"'priːtekst","e":["He’ll phone on some pretext or other.","他会以这样或那样的理由打电话的。"]},{"w":"prevail","t":"v. 流行，普遍","p":"prɪ'veɪl","c":1,"e":["A similar situation prevails in Canada.","同样的情况在加拿大也普遍存在。"]},{"w":"prevailing","t":"adj. 流行的","p":"prɪ'veɪlɪŋ","c":1,"e":["The prevailing mood of public opinion remained hostile.","公众仍普遍持敌对情绪。"]},{"w":"prevalence","t":"n. 流行，普遍","p":"'prɛvələns","c":1,"e":["However, no study on the prevalence of infertility has been conducted in this area.","但是，在这个地区不曾进行过任何关于不孕症流行情况的研究。"]},{"w":"prevalent","t":"adj. 流行的，普遍的","p":"'prevələnt","e":["the prevalent belief in astrology","对占星术的普遍相信"]},{"w":"prevention","t":"n. 预防，阻止，妨碍","p":"prɪ'venʃn","e":["a fire prevention officer","消防官员"]},{"w":"preview","t":"n. 预映，预演；预告","p":"'priːvjuː","e":["the press preview of the show (= when people who write for newspapers, television etc could see it )","该节目的媒体试映"]},{"w":"previous","t":"adj. 之前的","p":"ˈpri:viəs","c":1,"e":["She has a teenage daughter from a previous marriage.","她有个出自前一次婚姻的十几岁的女儿。"]},{"w":"prey","t":"vi. 捕食；折磨，使烦恼；n. 被捕食的动物，捕获物；受害者","p":"preɪ","e":["The effect was to disrupt the food chain, starving many animals and those that preyed on them.","后果是打断食物链，使许多动物和捕食它们的动物饿死。"]},{"w":"priceless","t":"adj. 无价的，难以用价格衡量的","p":"'praɪsləs","c":1,"e":["priceless antiques","极其贵重的古董"]},{"w":"prick","t":"v. 刺（穿）；n. 刺痛","p":"prɪk","e":["Prick the sausages before you grill them.","烤之前把香肠戳孔。"]},{"w":"priest","t":"n. 神父，牧师","p":"priːst","e":["He had trained to be a Catholic priest.","他接受培训成了一名天主教神父。"]},{"w":"primarily","t":"adv. 首先，主要地","p":"praɪ'merəlɪ","e":["The advertisement is aimed primarily at children.","这则广告的对象主要是儿童。"]},{"w":"primary","t":"adj. 首要的，主要的；基本的；最初的，初级的","p":"'praɪməri","e":["Our primary concern is to provide the refugees with food and health care.","我们的头等大事是向难民提供食品和医疗。"]},{"w":"prime","t":"adj. 首要的；最好的；n. 青春；全盛时期；vt. 使准备好","p":"praɪm","e":["Our prime concern is providing jobs for all young school leavers.","我们的头等大事是为所有的年轻毕业生提供工作。"]},{"w":"primitive","t":"adj. 原始的；简单的","p":"ˈprɪmətɪv","c":1,"e":["The first station buildings were quite primitive.","最初的车站建筑很简陋。"]},{"w":"principal","t":"adj. 最重要的，主要的；n. 负责人，校长；资本，本金；主要演员，主角","p":"'prɪnsəpl","e":["His principal reason for making the journey was to visit his family.","他那次旅程的首要目的是探访家人。"]},{"w":"principally","t":"adv. 主要，大抵","p":"'prɪnsɪp(ə)lɪ","e":["The money is principally invested in stocks and shares.","这笔钱主要投资于股票。"]},{"w":"principle","t":"n. 道德原则；原则","p":"ˈprɪnsəpl","c":1,"e":["The general principle is that education should be available to all children up to the age of 16.","总的原则是，16 岁以下儿童都应该能接受教育。"]},{"w":"printer","t":"n. 印刷工；印花工","p":"'prɪntə"},{"w":"prior","t":"adj. 先前的；优先的","p":"'praɪə(r)","c":1,"e":["Changes may not be made without the prior approval of the council.","未经委员会事先同意，不得作出改变。"]},{"w":"prioritize","t":"v. 优先","p":"praɪ'ɔrətaɪz","c":1,"e":["The public wants to see the fight against crime prioritized.","公众希望能把打击犯罪放在第一位。"]},{"w":"priority","t":"n. 优先，重点；优先考虑的事","p":"praɪ'ɒrəti","e":["I want to start work on the garden but the house must take priority .","我想开始整修花园，不过还是先得打扫屋子。"]},{"w":"prism","t":"n. 棱镜；棱柱（体）","p":"'prɪz(ə)m","e":["Light is refracted when passed through a prism.","光通过棱镜时产生折射。"]},{"w":"privacy","t":"n. 个人自由；隐私，私生活，私事","p":"'praɪvəsi","e":["each individual’s right to privacy","每个人的隐私权"]},{"w":"private","t":"adj. 私人的","p":"'praɪvət","c":1,"e":["They objected to any form of private property .","他们反对任何形式的私有财产。"]},{"w":"privilege","t":"n. 特权","p":"ˈprɪvəlɪdʒ","c":1,"e":["He had no special privileges and was treated just like every other prisoner.","他不享受特权，待遇和任何其他犯人一样。"]},{"w":"privileged","t":"adj. 有特权的","p":"'prɪvəlɪdʒd","c":1,"e":["Students from a privileged background have an advantage at university.","出身于特权阶层的学生在大学里具有优势。"]},{"w":"probability","t":"n. 可能性，可能发生的事；概率","p":"ˌprɒbə'bɪləti","e":["You must decide whether, on the balance of probabilities , he committed the crime.","你们一定要权衡正反两方面的可能性，然后再裁定他是否犯罪。"]},{"w":"probe","t":"v. 探索，查究，调查；用探针探查，探测；n. 探针，探测器；探索，调查","p":"prəub","e":["Police probed claims that he had sold drugs.","警方就有人称他贩卖毒品一事进行了调查。"]},{"w":"procedure","t":"n. 程序","p":"prəˈsi:dʒə(r)","c":1,"e":["On board, we were given the usual talk on safety procedures (= what to do if an accident happens, or to prevent an accident ) .","在飞机上，我们听了例行的飞行安全讲解。"]},{"w":"proceeding","t":"n. 诉讼","p":"prə'siːdɪŋ","e":["John is taking legal proceedings against his ex-partner.","约翰在对他的前合伙人提起法律诉讼。"]},{"w":"process","t":"n. 过程；制作方法；程序；vt. 加工，办理","p":"'prəus3s","e":["Repetition can help the learning process.","重复对学习过程会有帮助。"]},{"w":"processing","t":"n. 处理","p":"prəu'sesɪŋ","e":["But its most natural target is in automation of system scripting and text processing tasks.","但是它最自然的目标在于系统脚本的自动化和本文处理任务。"]},{"w":"proclaim","t":"vt. 宣告，宣布，声明；显示","p":"prə'kleɪm","e":["The President proclaimed the republic’s independence.","总统宣布共和国独立。"]},{"w":"producer","t":"n. 生产者；舞台监督","p":"prə'djuːsə","e":["...Saudi Arabia, the world's leading oil producer.","…沙特阿拉伯，世界上最重要的石油生产国。"]},{"w":"productive","t":"adj. 多产的，富饶的；富有成效的","p":"prə'dʌktɪv","e":["Most of us are more productive in the morning.","我们大多数人在早上更有效率。"]},{"w":"productivity","t":"n. 生产力","p":"ˌprɒdʌkˈtɪvəti","c":1,"e":["It cost the country $4 million in lost productivity .","它对该国造成了400万美元的生产力损失。"]},{"w":"profess","t":"vt. 表示，承认；宣称信仰","p":"prə'fes","e":["Why do organizations profess that they care?","为什么一些组织声称他们关心呢？"]},{"w":"profession","t":"n. 职业；公开表示","p":"prə'feʃn","e":["the medical profession","医学界"]},{"w":"professional","t":"adj. 职业的，专业的，专门的；n. 自由职业者，专业人员","p":"prə'feʃənl","e":["This business plan looks very professional.","这个商业计划看上去很有专业水平。"]},{"w":"proficiency","t":"n. 熟练，精通","p":"prə'fɪʃnsi","e":["How do you think of your proficiency in written and spoken English?","你认为你的书面英语和口头英语熟练程度如何？"]},{"w":"proficient","t":"adj. 熟练的，精通的","p":"prə'fɪʃ(ə)nt","e":["a proficient typist","熟练的打字员"]},{"w":"profitable","t":"adj. 有利可图的，有利益的","p":"ˈprɒfɪtəbl","c":1,"e":["The advertising campaign proved very profitable.","事实证明，这次广告宣传活动卓有成效。"]},{"w":"profound","t":"adj. 深刻的；博学的","p":"prə'faʊnd","c":1,"e":["Tolstoy’s experiences of war had a profound effect on his work","托尔斯泰的战争经历深刻影响了他的作品。"]},{"w":"program","t":"v. 计划，安排","p":"'prəʊɡræm","c":1,"e":["Who's behind this program?","谁支持这项计划?"]},{"w":"progressive","t":"adj. 前进的；渐进的；进行式的","p":"prə'gresɪv","e":["progressive and forward-looking policies","有前瞻性的进步政策"]},{"w":"prohibit","t":"vt. 禁止，不准","p":"prə'hɪbɪt","e":["Smoking is strictly prohibited inside the factory.","厂区严禁吸烟。"]},{"w":"prohibition","t":"n. 禁止；禁令，禁律","p":",prəʊhɪ'bɪʃ(ə)n; prəʊɪ-","e":["the prohibition of the sale of firearms","枪支的禁售"]},{"w":"project","t":"v. 伸出；投射；放映；n. 方案，计划；课题，项目；工程","p":"prəˈdʒekt; ˈprɒdʒekt","e":["Bradley projects a natural warmth and sincerity.","布拉德利表现出一种自然的热情和真诚。"]},{"w":"projector","t":"n. 投影仪；探照灯","p":"prə'dʒektə","e":["...a slide projector.","…幻灯机。"]},{"w":"prolong","t":"v. 延长","p":"prə'lɒŋ","c":1,"e":["I was trying to think of some way to prolong the conversation.","我在想方设法拖长这次谈话。"]},{"w":"prolonged","t":"adj. 长时间的","p":"prəˈlɒŋd","c":1,"e":["prolonged exposure to the sun","长时间暴露在阳光下"]},{"w":"prominent","t":"adj. 卓越的；突出的","p":"'prɒmɪnənt","c":1,"e":["a prominent Russian scientist","杰出的俄罗斯科学家"]},{"w":"promising","t":"adj. 有希望的，有前途的","p":"'prɒmɪsɪŋ","e":["a promising career in law","很有前途的法律职业"]},{"w":"promote","t":"v. 促进","p":"prə'məʊt","c":1,"e":["You don't have to sacrifice environmental protection to promote economic growth.","你们没有必要牺牲环保来促进经济增长。"]},{"w":"promotion","t":"n. 促销","p":"prə'məʊʃn","c":1,"e":["a winter sales promotion","冬季促销活动"]},{"w":"prompt","t":"v. 促使","p":"prɒmpt","c":1,"e":["Japan's recession has prompted consumers to cut back on buying cars.","日本的经济衰退已促使消费者们削减购车花销。"]},{"w":"promptly","t":"adv. 敏捷地，迅速地","p":"'prɒm(p)tlɪ","e":["A reply came very promptly.","马上就有了答复。"]},{"w":"prone","t":"adj. 易于…的，很有可能…的；俯卧的","p":"prəun","e":["His eyes shifted to the prone body on the floor.","他的视线移向了趴在地上的尸体。"]},{"w":"pronoun","t":"n. 代词","p":"ˈprəʊnaʊn","c":1,"e":["demonstrative/interrogative/possessive/relative pronouns","指示 / 疑问 / 物主 / 关系代词"]},{"w":"proof","t":"adj. 耐…的，能防…的；n. 证据，证明；校样，样张","p":"pruːf","e":["Their defences are proof against most weapons.","他们的防卫工事可以抵挡大多数武器的攻击。"]},{"w":"propaganda","t":"n. 宣传","p":"ˌprɒpə'gændə","e":["the spreading of political propaganda","政治宣传的开展"]},{"w":"propagate","t":"v. 繁殖，增殖；传播，宣传，普及","p":"'prɒpəgeɪt","e":["The group launched a website to propagate its ideas .","这个团体建了一个网站来宣扬他们的主张。"]},{"w":"propagation","t":"n. 繁殖；传播；蔓延","p":",prɒpə'ɡeɪʃən"},{"w":"propel","t":"vt. 推进，推动；激励，驱使","p":"prə'pel","e":["One of our students was unable to propel her wheelchair up the ramp.","我们有名学生无法把她的轮椅推上坡道。"]},{"w":"propeller","t":"n. 螺旋桨，推进器","p":"prə'pelə","e":["...a fixed three-bladed propeller.","…一个固定的三叶螺旋桨。"]},{"w":"proper","t":"adj. 合乎体统的，正派的","p":"'prɒpə","e":["It is right and proper that parents take responsibility for their children's attendance at school.","父母负责督促子女上学上课，这是天经地义的事。"]},{"w":"property","t":"n. 财产","p":"'prɒpətɪ","c":1,"e":["The hotel is not responsible for any loss or damage to guests’ personal property .","宾馆对住客个人财物的丢失和损坏概不负责。"]},{"w":"prophecy","t":"n. 预言；预言能力","p":"'prɒfɪsɪ","e":["She had the gift of prophecy.","她有预言的天赋。"]},{"w":"prophet","t":"n. 先知；预言者","p":"'prɒfɪt","e":["the prophet Elijah","先知以利亚"]},{"w":"propose","t":"v. 提出","p":"prə'pəʊz","c":1,"e":["the changes currently proposed by the local planning authorities","目前由地方规划局提议的改革"]},{"w":"proposition","t":"n. 提议，主题","p":",prɑpə'zɪʃən","c":1,"e":["He telephoned Stuart with a proposition.","他打电话给斯图尔特提了个建议。"]},{"w":"propulsion","t":"n. 推进，推进力","p":"prə'pʌlʃ(ə)n","e":["research into liquid hydrogen as a means of propulsion","对液态氢作为一种动力方式进行的研究"]},{"w":"prose","t":"n. 散文","p":"prəuz","e":["Shute's prose is stark and chillingly unsentimental.","舒特的散文刻板而冷峻。"]},{"w":"prosecute","t":"vi. 起诉，告发；vt. 对…提起公诉，告发，检举；继续从事","p":"'prɒsɪkjuːt","e":["Shoplifters will be prosecuted.","在商店行窃者将被起诉。"]},{"w":"prospect","t":"n. 前景","p":"'prɒspekt","c":1,"e":["The prospect of marriage terrified Alice.","想到要结婚，艾丽斯害怕极了。"]},{"w":"prospective","t":"adj. 预期的；未来的","p":"prəˈspektɪv","c":1,"e":["They are worried about prospective changes in the law.","他们担心即将修改法律。"]},{"w":"prosperity","t":"n. 繁荣","p":"prɒ'sperətɪ","c":1,"e":["a time of economic prosperity","经济繁荣时期"]},{"w":"prosperous","t":"adj. 繁荣的，兴旺的","p":"'prɒspərəs","e":["a prosperous landowner","富裕的土地拥有者"]},{"w":"protein","t":"n. 蛋白质","p":"'prəutiːn","e":["So, what happens, this is another view of a sodium channel, so this is actually looking a little bit more at the protein structure .","那么，这里发生了什么，这是钠离子通道的另一张图片，在这种蛋白质结构中，它看起来更复杂一点。"]},{"w":"protest","t":"v. ['prəutest]；n. 抗议，反对","p":"prə'test","e":["‘I don’t see why I should take the blame for this!’ she protested.","“我不明白为什么我要对此承担责任！”她抗议道。"]},{"w":"proton","t":"n. 质子，氕核","p":"'prəʊtɒn","e":["When a neutron inside an atom decays, it produces a proton, an electron, and a neutrino.","原子内的一个中子衰变后会产生一个质子、一个电子和一个中微子。"]},{"w":"prototype","t":"n. 原型","p":"'prəutətaɪp","e":["But how do you come up with the architecture for this evolutionary prototype?","但是你将如何为这个进化的原型提出系统的架构呢？"]},{"w":"proverb","t":"n. 谚语，格言，箴言","p":"'prɒvɜːb","e":["An old Arab proverb says, \"The enemy of my enemy is my friend.\"","有一句古老的阿拉伯谚语说：“我敌人的敌人是我的朋友。”"]},{"w":"provided","t":"conj. 假如，若是","p":"prə'vaɪdɪd","e":["He can come with us, provided he pays for his own meals.","只要他付自己的饭钱，就可以跟我们一起来。"]},{"w":"province","t":"n. 领域，范围，职权","p":"'prɒvɪns","e":["Computers were once the exclusive province of scientists and mathematicians.","计算机一度为科学家和数学家专用。"]},{"w":"provision","t":"n. 供应；准备，预备；条款，规定；给养，口粮","p":"prə'vɪʒn","e":["He made provisions for his wife and his children in his will.","在遗嘱里他为妻子和孩子都做好了安排。"]},{"w":"provocative","t":"adj. 挑衅的，煽动的，刺激的；挑逗的","p":"prə'vɒkətɪv","e":["She was accused of being deliberately provocative .","她被指责故意挑衅。"]},{"w":"provoke","t":"v. 激怒","p":"prəˈvəʊk","c":1,"e":["The dog would not have attacked if it hadn’t been provoked.","如果不是被惹恼了，那狗原本不会攻击的。"]},{"w":"proximately","t":"adv. 近似，接近","p":"'prɔksimitli","c":1},{"w":"proximity","t":"n. 接近，邻近","p":"prɒk'sɪməti","e":["Here the rich and the poor live in close proximity (= very near to each other ) .","在这里，富人和穷人比邻而居。"]},{"w":"prudent","t":"adj. 谨慎的；精明的","p":"'pruːd(ə)nt","e":["prudent house buyers","谨慎的购房者"]},{"w":"prune","t":"vt. 修剪，修整；删除，削减","p":"pruːn","e":["The roses need pruning.","玫瑰需要修枝了。"]},{"w":"psychiatrist","t":"n. 精神科医生，精神病专家","p":"saɪ'kaɪətrɪst","e":["A colleague urged him to see a psychiatrist, but Faulkner refused.","一位同事竭力劝福克纳去看精神病医生，但他拒绝了。"]},{"w":"psychological","t":"adj. 心理的","p":"ˌsaɪkə'lɒdʒɪkl","e":["Sleep disorders are a serious psychological problem .","睡眠障碍是严重的心理疾病。"]},{"w":"psychology","t":"n. 心理学；心理","e":["experts in the field of developmental psychology","发展心理学领域的专家"]},{"w":"publicity","t":"n. 宣传","p":"pʌbˈlɪsəti","c":1,"e":["Much advance publicity was given to the talks.","会谈之前做了大量的宣传。"]},{"w":"publicize","t":"v. 宣传","p":"'pʌblɪsaɪz","c":1,"e":["television’s failure to publicize the unemployment issue","电视未能报道失业问题"]},{"w":"pudding","t":"n. 布丁","p":"'pudɪŋ","e":["chocolate pudding","巧克力布丁"]},{"w":"puff","t":"v. 喘气；喷（烟等）","p":"pʌf","e":["George puffed and panted and he tried to keep up.","乔治喘着粗气想跟上。"]},{"w":"pulley","t":"n. 滑轮，滑车，皮带轮","p":"'pʊlɪ","e":["a system of ropes and pulleys","绳索滑轮系统"]},{"w":"pumpkin","t":"n. 南瓜","p":"'pʌmpkɪn","e":["pumpkin pie","南瓜饼"]},{"w":"punch","t":"v. 打孔；n. 冲压机","p":"pʌn(t)ʃ","e":["The guard punched my ticket and I got on.","守卫在我的票上打孔后，我就上去了。"]},{"w":"puppy","t":"n. 小狗；幼小的动物","p":"'pʌpɪ","e":["a six-month-old puppy","一只六个月大的小狗"]},{"w":"purchase","t":"n. 购买","p":"'pɜ:tʃəs","c":1,"e":["I enclose my receipt as proof of purchase .","我附上小票作为购物凭证。"]},{"w":"purify","t":"vt. 使纯净，提纯；使纯洁","p":"'pjuərɪfaɪ","e":["chemicals used to purify the water","用于净化水质的化学品"]},{"w":"purity","t":"n. 纯净，纯洁，纯正","p":"'pjuərəti","e":["{\"COLLOINEXA\":[\"spiritual purity\"]}","心灵的纯洁"]},{"w":"pursue","t":"v. 追求","p":"pə'sju:","c":1,"e":["Students should pursue their own interests , as well as do their school work.","除了完成课业之外，学生也应该追求自己的兴趣。"]},{"w":"pursuit","t":"n. 追求","p":"pəˈsju:t","c":1,"e":["the pursuit of liberty and happiness","对自由和幸福的追求"]},{"w":"puzzle","t":"v. 迷惑","p":"'pʌz(ə)l","c":1,"e":["What puzzles me is why his books are so popular.","令我不解的是，他的书为什么如此受欢迎。"]},{"w":"puzzling","t":"adj. 迷惑的，困扰的","p":"'pʌzlɪŋ","c":1,"e":["Gary found her reaction puzzling.","加里对她的反应感到迷惑。"]},{"w":"pyjamas","t":"n. （宽大的）睡衣裤","p":"pə'dʒɑːməz","e":["striped pyjamas","条纹睡衣裤"]},{"w":"qualification","t":"n. 资格","p":"ˌkwɒlɪfɪ'keɪʃn","c":1,"e":["He left school without any qualifications.","他离校时没有拿到任何文凭。"]},{"w":"qualify","t":"v. 使有资格","p":"'kwɒlɪfaɪ","c":1,"e":["Free school lunches are given to children who qualify.","符合条件的儿童可获得免费的学生午餐。"]},{"w":"qualitative","t":"adj. 性质的，定性的","p":"'kwɒlɪtətɪv","e":["There are qualitative differences in the way children of different ages and adults think.","不同年龄的儿童和成人在思维方式上有着质的差异。"]},{"w":"quantifiable","t":"adj. 可量化的","p":"'kwɒntɪfaɪəbl","c":1,"e":["A clearly quantifiable measure of quality is not necessary.","一种确切的可计量的质量检测是不必要的。"]},{"w":"quantify","t":"vt. 确定…的数量，量化","p":"'kwɒntɪfaɪ","e":["an attempt to quantify the region’s social and economic decline","对该地区社会和经济衰退进行量化的尝试"]},{"w":"quantitative","t":"adj. 量的，定量的","p":"'kwɒntɪtətɪv","e":["...the advantages of quantitative and qualitative research.","…定量和定性研究的优点。"]},{"w":"quantity","t":"n. 数量","p":"ˈkwɒntəti","c":1,"e":["Your work has improved in quantity and quality this term.","这学期你的作业在完成数量和质量上都有提高。"]},{"w":"quart","t":"n. 夸脱","p":"kwɔːt","e":["The quarrelsome general quarreled about a quarter quart of oil in the headquarters.","好争持的将军正在司令部为四分之一夸脱油而争持。"]},{"w":"quarterly","t":"adv. 按季度，一季一次；adj. 季度的，每季一次的；n. 季刊","p":"'kwɔːtəli","e":["It makes no difference whether dividends are paid quarterly or annually.","红利是按季度还是按年度支付没有区别。"]},{"w":"quartz","t":"n. 石英","p":"kwɔːts","e":["quartz crystals","石英晶体"]},{"w":"queer","t":"adj. 奇怪的，异常的；不舒服的，眩晕的","p":"kwɪə","e":["Hank was beginning to feel a little queer.","汉克开始感觉有点不对头。"]},{"w":"quench","t":"vt. 止；扑灭","p":"kwentʃ","e":["a desperate bid to quench the raging flames","为扑灭熊熊大火而不顾一切的努力"]},{"w":"quest","t":"n. 寻找，搜索；追求","p":"kwest","e":["They journeyed to the distant Molucca islands in quest of spices.","他们远赴摩鹿加群岛寻找香料。"]},{"w":"question","t":"v. 问，询问，讯问","p":"'kwestʃ(ə)n","e":["Joseph questioned the doctors closely (= asked them a lot of questions ).","约瑟夫问了医生很多问题。"]},{"w":"questionable","t":"adj. 可疑的，不可靠的","p":"'kwestʃ(ə)nəb(ə)l","e":["The statistics are highly questionable.","这个统计数据大有问题。"]},{"w":"questionnaire","t":"n. 问卷，征求意见表","p":"ˌkwestʃə'neə","e":["Teachers will be asked to fill in a questionnaire.","教师们将被要求填写一份调查问卷。"]},{"w":"quicken","t":"v. 加快","p":"'kwɪkən","c":1,"e":["Companies are finding it hard to cope with the quickening pace of technological change.","各家公司都发现科技的日新月异让他们难以应付。"]},{"w":"quiver","t":"vi. 颤抖，发抖，抖动；n. 颤抖，抖动，颤声","p":"'kwɪvə","e":["I recognized it instantly and felt a quiver of panic.","我立刻认出它了，感到一阵惊恐的颤抖。"]},{"w":"quota","t":"n. 配额","p":"ˈkwəutə","c":1,"e":["The government has decided to scrap quotas on car imports.","政府决定取消汽车进口配额。"]},{"w":"quote","t":"v. 引用","p":"kwəʊt","c":1,"e":["A military spokesman was quoted as saying that the border area is now safe.","报道引述军方一位发言人的话，说边境地区现在很安全。"]},{"w":"racial","t":"adj. 种族的，人种的","p":"'reɪʃl","e":["This part of the community needs to be protected from racial prejudice .","需保护社区里的这一部分人，使其免受种族偏见的伤害。"]},{"w":"racket","t":"n. 喧嚷，吵闹；敲诈，勒索，诈骗；球拍","p":"'rækɪt","e":["The old machine used to make an awful racket .","这台旧机器以前噪音大得吓人。"]},{"w":"radial","t":"adj. 放射状的","p":"'reɪdɪəl","e":["radial roads leading out of the city centre","从市中心向外辐射的道路"]},{"w":"radiant","t":"adj. 容光焕发的，喜形于色的；光芒四射的，光辉灿烂的；辐射的","p":"'reɪdiənt","e":["She looked radiant in a white silk dress.","她身穿白色真丝礼服，看上去光彩照人。"]},{"w":"radiate","t":"v. 发出，辐射；流露，显示","p":"'reɪdieɪt","e":["He radiated calm confidence.","他身上散发着沉稳自信的气质。"]},{"w":"radiator","t":"n. 暖气片；散热器","p":"'reɪdɪeɪtə","e":["My car engine overheated because the water had leaked out of the radiator.","我的汽车引擎过热，原因是散热器漏水。"]},{"w":"radical","t":"adj. 根本的，基本的；激进的，激进派的；n. 激进分子","p":"'rædɪkl","e":["They are proposing radical changes to the way the company is run.","他们建议对公司经营模式进行重大改革。"]},{"w":"radioactive","t":"adj. 放射性的，有辐射能的","p":"ˌreɪdiəu'æktɪv","e":["the problem of how to dispose of radioactive waste","如何处理放射性废物的问题"]},{"w":"radius","t":"n. 半径，半径范围","p":"'reɪdiəs","e":["The shock of the explosion was felt over a radius of forty miles.","爆炸引起的剧烈震动在方圆40英里内都能感觉得到。"]},{"w":"raise","t":"v. 提出，发起，发出","p":"reɪz","e":["Betty raised the important question of who will be in charge.","贝蒂提出了一个重要问题，就是将由谁来负责。"]},{"w":"raisin","t":"n. 葡萄干","p":"'reɪz(ə)n","e":["...homemade oatmeal with brown sugar and raisins.","…自家煮的放有红糖和葡萄干的麦片粥。"]},{"w":"rally","t":"n. 集会","p":"'rælɪ","c":1,"e":["We decided to hold a rally to put pressure on the government.","我们决定举行集会来对政府施压。"]},{"w":"ramble","t":"v. 闲逛，漫步；漫谈，闲聊","p":"'ræmb(ə)l","e":["There’s plenty to discover as you ramble around this little island.","漫步这个小岛，你会有很多新发现。"]},{"w":"ranch","t":"n. （北美洲的）大牧场","p":"rɑːn(t)ʃ","e":["He lives on a cattle ranch in Texas.","他住在德克萨斯州的一个养牛的大牧场里。"]},{"w":"random","t":"adj. 任意的，随机的","p":"'rændəm","e":["The company has introduced random drug testing of its employees.","公司已实行对雇员的随机毒品测试。"]},{"w":"randomly","t":"adv. 随机地","p":"'rændəmlɪ","c":1,"e":["The winning numbers are randomly selected by computer.","中奖号码是由电脑随机选取的。"]},{"w":"range","t":"v. 排列","p":"reɪn(d)ʒ","e":["In the dining room, team photographs were ranged along the wall.","餐厅里，球队的照片排列在墙上。"]},{"w":"rank","t":"v. 排列；分级","p":"ræŋk","c":1,"e":["There were several pairs of riding boots ranked neatly in the hall.","门厅里整齐地摆放着几双马靴。"]},{"w":"rap","t":"vi. 说唱；vt. 敲击，急敲；突然厉声说出；责备，训斥；n. 敲击，急敲","p":"ræp","e":["‘Come on,’ he rapped impatiently.","“得了吧。”他不耐烦地厉声说道。"]},{"w":"rape","t":"n. 强奸","p":"reɪp","c":1,"e":["Police are investigating a series of violent rapes in the town.","警察在调查镇上发生的一连串暴力强奸案。"]},{"w":"rapidity","t":"n. 快，迅速；陡，险峻","p":"rə'pɪdɪtɪ","e":["the rapidity of economic growth","经济增长的高速度"]},{"w":"rapture","t":"n. 狂喜，欢天喜地","p":"'ræptʃə","e":["The boys gazed up at him in rapture.","男孩们欣喜若狂地抬头注视着他。"]},{"w":"rare","t":"adj. 罕见的，稀少的","p":"reə(r)","c":1,"e":["I only saw Helen on the rare occasions when I went into her shop.","我只有偶尔去海伦店里时才会见到她。"]},{"w":"rarely","t":"adv. 不常，难得","p":"'reəli"},{"w":"rascal","t":"n. 流氓，恶棍，无赖","p":"'rɑːsk(ə)l","e":["What's that old rascal been telling you?","那个老家伙对你都一直说些什么？"]},{"w":"rash","t":"adj. 轻率的，鲁莽的；n. 疹，皮疹；爆发的一连串","p":"ræʃ","e":["Don’t go making any rash decisions about your future!","不要对你的未来贸然作决定！"]},{"w":"rate","t":"n. 费用","p":"reɪt","c":1,"e":["$20 an hour is the going rate (= the usual amount paid ) for private tuition.","每小时20美元是私人授课的一般收费。"]},{"w":"rating","t":"n. 等级，品级，评定结果；收视率，收听率","p":"'reɪtɪŋ","e":["By the end of the year the Prime Minister’s approval rating (= how many people agreed with his policies ) had fallen as low as 12 percent.","到年底时，首相的支持率跌到了12%的低点。"]},{"w":"rational","t":"adj. 理性的，理智的；合理的","p":"'ræʃnəl","e":["Parents need to be fully informed so they can make a rational decision.","父母需要充分了解情况，这样才可以作出合理的决定。"]},{"w":"rattle","t":"v. 发出格格声","p":"'ræt(ə)l","e":["Every time a bus went past, the windows rattled.","每逢公共汽车经过这里，窗户都格格作响。"]},{"w":"reaction","t":"n. 反应，反作用","p":"ri'ækʃn","e":["What was Jeff’s reaction when you told him about the job?","你告诉杰夫这个工作时，他是什么反应？"]},{"w":"reactor","t":"n. 反应堆","p":"rɪ'æktə","e":["They shut down the nuclear reactor for safety reasons.","出于安全原因他们关闭了核反应堆。"]},{"w":"readily","t":"adv. 乐意地，欣然地；容易地；很快地，立即","p":"'redɪli","e":["The information is readily accessible on the Internet.","这些信息在因特网上一查就能找到。"]},{"w":"readjust","t":"v. 重新调整，再调整","p":"riːə'dʒʌst","c":1,"e":["He readjusted his glasses.","他重新调了调眼镜。"]},{"w":"ready","t":"adj. 乐意的，愿意的","p":"'redɪ","c":1,"e":["She was ready and willing to work hard.","她工作积极肯干。"]},{"w":"reaffirm","t":"vt. 重申；再确认","p":"ˌriːə'fɜːm","e":["The party reaffirmed its commitment to nuclear disarmament.","该党重申其核裁军承诺。"]},{"w":"realistic","t":"adj. 现实的；实际可行的；现实主义的，逼真的","p":"ˌrɪːə'lɪstɪk","e":["Is this a realistic target?","这个目标能够实现吗？"]},{"w":"realization","t":"n. （理想等的）实现","p":"riːəlaɪ'zeɪʃn","e":["the realization of his dreams","他的梦想成真"]},{"w":"realm","t":"n. 领域，方面","p":"relm","c":1,"e":["the spiritual realm","精神领域"]},{"w":"reap","t":"v. 收割，收获","p":"ri:p","c":1,"e":["The peasants leaned down to reap wheat.","农民们俯身收割小麦。"]},{"w":"rear","t":"v. 饲养，培植；抚养","p":"rɪə","e":["The birds have been successfully reared in captivity.","这些鸟笼养成功。"]},{"w":"reason","t":"v. 论证，推断","p":"'riːz(ə)n","e":["They reasoned that other businesses would soon copy the idea.","他们推断其他企业也会很快仿效这个点子。"]},{"w":"reassess","t":"vt. 再评价","p":"ˌriːə'ses","e":["This has caused us to reassess the way we approach our planning.","这件事让我们重新审视了我们的规划方式。"]},{"w":"reassure","t":"vt. 使放心","p":"ˌriːə'ʃuə","e":["Teachers reassured anxious parents.","老师们安慰焦急的父母。"]},{"w":"rebel","t":"vi. 反叛，造反；反对，不服从；n. 反叛分子，反对者","p":"'rebl","e":["Voters rebelled against high property taxes.","投票者们反对高额财产税。"]},{"w":"rebellion","t":"n. 叛逆","p":"rɪ'beljən","c":1,"e":["an armed rebellion","武装叛乱"]},{"w":"rebuke","t":"v. 指责，非难，斥责","p":"rɪ'bjuːk","e":["The president rebuked the House and Senate for not passing those bills within 100 days.","总统谴责参众两院未在100天内通过那些法案。"]},{"w":"recall","t":"v. 回忆起，想起","p":"rɪ'kɔ:l","c":1,"e":["As I recall, it was you who suggested this idea in the first place.","我记得，是你首先提出这个想法的。"]},{"w":"recede","t":"vi. 退，退去，渐渐远去；向后倾斜，缩进","p":"rɪ'siːd","e":["The pain in his head gradually receded.","他的头痛逐渐缓解。"]},{"w":"receipt","t":"n. 发票","p":"rɪ'si:t","c":1,"e":["Keep your receipt in case you want to bring it back.","保留收据以备退货之需。"]},{"w":"receiver","t":"n. 接待者；收受者","p":"rɪ'siːvə","e":["Molly's more of a giver than a receiver.","莫莉更乐于给予而不是接受。"]},{"w":"reception","t":"n. 接待","p":"rɪˈsepʃn","c":1,"e":["She was unsure of her reception after everything that had happened.","发生了这些事后，她对自己是否还受欢迎没把握。"]},{"w":"receptionist","t":"n. 接待员","p":"rɪˈsepʃənɪst","c":1,"e":["You tell the receptionist that you are expecting a call from this client and to put them through.","你告诉传达员你正在等待一个来自这个客户的电话，并允许将他们接进来。"]},{"w":"recession","t":"n. 衰退，衰退期","p":"rɪ'seʃn","e":["the economic recession of the early 1980s","20世纪80年代初的经济衰退"]},{"w":"recipe","t":"n. 食谱；秘诀","p":"'resəpɪ","c":1,"e":["What's her recipe for success?","她成功的秘诀是什么？"]},{"w":"recipient","t":"n. 接受者，接收者","p":"rɪ'sɪpiənt","e":["...the largest recipient of U.S. foreign aid.","…最大的美国对外援助接受方。"]},{"w":"reciprocal","t":"adj. 相互的；互惠的","p":"rɪ'sɪprəkl","e":["He spoke of the necessity for a reciprocal relationship that would be useful for all sides.","他谈及需要建立对各方都有益的互惠关系。"]},{"w":"recite","t":"v. 背诵，朗诵；列举，一一说出","p":"rɪ'saɪt","e":["She recited a poem that she had learnt at school.","她背诵了一首学校里学的诗。"]},{"w":"reckless","t":"adj. 鲁莽的","p":"'rekləs","c":1,"e":["He ran into the burning house with reckless abandon (= without caring about the danger ) .","他不顾危险冲入着火的房子里。"]},{"w":"reckon","t":"v. 认为，评价","p":"'rekən","c":1,"e":["‘There’s nothing we can do about it.’ ‘You reckon (= used to express doubt or disagreement ) ?’","“这件事我们无能为力。”“是吗？”"]},{"w":"reclaim","t":"vt. 要回；开垦；回收","p":"rɪ'kleɪm","e":["You may be entitled to reclaim some tax.","你也许可以享受一定额度的退税。"]},{"w":"recognition","t":"n. 认出，识别；承认，确认，认可；赏识，表彰，报偿","p":"ˌrekəg'nɪʃn","e":["He has achieved recognition and respect as a scientist.","作为科学家，他得到人们的赞赏和尊敬。"]},{"w":"recognize","t":"vt. 认出，识别；承认，确认，认可；赏识，表彰，报偿","p":"'rekəgnaɪz","e":["It was malaria, but Dr Lee hadn’t recognized the symptoms.","这是疟疾，但李医生没有认出症状。"]},{"w":"recommend","t":"v. 推荐","p":"ˌrekəˈmend","c":1,"e":["I recommend the butter chicken - it’s delicious.","我推荐黄油焗鸡，非常好吃。"]},{"w":"recommendation","t":"n. 推荐，介绍；建议","p":",rekəmen'deɪʃ(ə)n","e":["We chose the hotel on their recommendation (= because they recommended it).","我们根据他们的推荐选了这家酒店。"]},{"w":"reconcile","t":"v. 使一致；使和解，调解","p":"'rekənsaɪl","c":1,"e":["The possibility remains that the two theories may be reconciled.","这两种理论仍是有可能协调的。"]},{"w":"reconciliation","t":"n. 和解，调和","p":"ˌrekənsɪli'eɪʃn","e":["The treaty has brought a new spirit of reconciliation on both sides.","条约使双方产生了新的和解精神。"]},{"w":"recover","t":"v. 重新获得，挽回；恢复","p":"ˌriː'kʌvə","e":["Four paintings stolen from the gallery have been recovered.","美术馆的四幅被盗画作已经失而复得。"]},{"w":"recovery","t":"n. 恢复，痊愈；追回，寻回，收复","p":"rɪ'kʌvəri","e":["Hopes of economic recovery are fading.","经济复苏的希望越来越渺茫。"]},{"w":"recreation","t":"n. 娱乐活动，消遣","p":"ˌrekri'eɪʃn","e":["His only recreations are drinking beer and watching football.","他唯一的消遣就是喝啤酒和看足球比赛。"]},{"w":"recruit","t":"v. 招聘","p":"rɪ'kru:t","c":1,"e":["Many government officials were recruited from private industry.","很多政府官员是从私营企业招募来的。"]},{"w":"recruiter","t":"n. 招聘者","p":"rɪ'kruːtə","c":1,"e":["A recruiter can give you insider pointers and advice.","一个招聘人可以为你提供内行人的观点与建议。"]},{"w":"rectangle","t":"n. 矩形，长方形","p":"'rektæŋg(ə)l","e":["Suppose the width of a rectangle is x metres.","设长方形的宽是 x 米。"]},{"w":"rectangular","t":"adj. 长方形的，矩形的","p":"rek'tæŋgjələ","e":["...a rectangular table.","…一张长方形的桌子。"]},{"w":"rectify","t":"vt. 纠正，修复","p":"'rektɪfaɪ","e":["I did my best to rectify the situation, but the damage was already done.","我竭尽全力去挽回局面，但损害已经造成了。"]},{"w":"recur","t":"vi. 再发生，重现","p":"rɪ'kɜː","e":["There is a danger that the disease may recur.","这种病有复发的危险。"]},{"w":"recurrence","t":"n. 再次发生","p":"rɪˈkʌrəns","c":1,"e":["Police are out in force to prevent a recurrence of the violence.","警察大规模地行动防止暴力的再次发生。"]},{"w":"recyclable","t":"adj. 可回收利用的","p":"riː'saɪkləbl","c":1,"e":["recyclable cardboard packaging","可回收利用的纸板包装材料"]},{"w":"recycle","t":"vt. 回收利用","p":"ˌriː'saɪkl","e":["We take all our bottles to be recycled.","我们把我们所有的瓶子都回收利用。"]},{"w":"redefine","t":"v. 重新定义","p":"riːdɪ'faɪn","c":1,"e":["Feminists have redefined the role of women.","女权主义者们已重新定义了女性角色。"]},{"w":"redundant","t":"adj. 失业的，被解雇的；过剩的","p":"rɪ'dʌnd(ə)nt","c":1,"e":["Seventy factory workers were made redundant in the resulting cuts.","在继而发生的裁员中，70名工厂工人被解雇。"]},{"w":"reed","t":"n. 芦笛，牧笛","p":"riːd"},{"w":"reef","t":"n. 礁，礁石，暗礁","p":"riːf","e":["a proposal to protect several miles of thousand-year-old coral reef","保护绵延数英里的千年古珊瑚礁的提案"]},{"w":"reel","t":"vi. 摇摇晃晃地移动，蹒跚；眩晕，发昏；n. 卷轴，卷筒，卷盘；vt. 卷，绕","p":"riːl","e":["Andy reeled away from the bar and knocked over his stool.","安迪踉跄着离开吧台，把凳子都撞倒了。"]},{"w":"referee","t":"vi. 当裁判；n. 裁判员；证明人，推荐人；仲裁者，调解者","p":"ˌrefə'riː","e":["Vautrot has refereed in two World Cups.","沃特罗特已经在两届世界杯比赛中担任过裁判。"]},{"w":"reference","t":"n. 提到，论及；参考，查阅；引文；参考书目；证明书，推荐信","p":"'refrəns","e":["Keep their price list on file for future reference (= so that it can be looked at in the future ) .","将他们的价目表存档，以供日后参考。"]},{"w":"refine","t":"v. 提炼；改进，完善","p":"rɪˈfaɪn","c":1,"e":["Oil is refined to remove naturally occurring impurities.","油经过提炼去除天然生成的杂质。"]},{"w":"refinery","t":"n. 精炼厂，提炼厂","p":"rɪ'faɪn(ə)rɪ","e":["...an oil refinery.","…一家炼油厂。"]},{"w":"reflect","t":"v. 反映；反射；思考","p":"rɪ'flekt","c":1,"e":["He had time to reflect on his successes and failures.","他有时间反思他的成功和失败。"]},{"w":"reflective","t":"adj. 反映的，反射的；深思熟虑的","p":"rɪ'flektɪv","c":1,"e":["Stick reflective tape on your school bag.","给你的书包贴上反光带。"]},{"w":"reform","t":"n&v. 改革，改良，改造；改正，改过自新","p":"rɪ'fɔːm","e":["plans to radically reform the tax system","彻底改革税收制度的计划"]},{"w":"refrain","t":"v. 抑制，避免","p":"rɪ'freɪn","c":1,"e":["Please refrain from smoking in this area.","请勿在此处吸烟。"]},{"w":"refresh","t":"v. 振作精神，恢复活力","p":"rɪ'freʃ","e":["A shower will refresh you.","洗个淋浴你就凉快了。"]},{"w":"refreshing","t":"adj. 新鲜的","p":"rɪˈfreʃɪŋ","c":1,"e":["It made a refreshing change to talk to someone new.","和刚认识的人谈话感觉很新鲜。"]},{"w":"refreshment","t":"n. 茶点，点心；恢复，精神爽快","p":"rɪ'freʃmənt","e":["Refreshments will be served after the meeting.","会后有茶点招待。"]},{"w":"refuge","t":"n. 庇护所，避难处；庇护","p":"'refjuːdʒ","e":["a wildlife refuge","野生动物保护区"]},{"w":"refugee","t":"n. 难民，流亡者","p":"refjʊ'dʒiː","e":["Refugees were streaming across the border.","难民正涌过边境。"]},{"w":"refund","t":"n. 退款；vt. 退还","p":"ˈriːfʌnd","e":["Return your purchase within 14 days for a full refund .","14 天之内退货可以全额退款。"]},{"w":"refusal","t":"n. 拒绝","p":"rɪ'fjuːzl","e":["Her country suffered through her refusal to accept change.","她的国家因为她拒绝接受变革而受了害。"]},{"w":"refute","t":"vt. 驳斥，驳倒","p":"rɪ'fjuːt","e":["It was the kind of rumour that it is impossible to refute.","这是那种不可能推翻的谣言。"]},{"w":"regain","t":"v. 重新获得","p":"rɪ'ɡeɪn","c":1,"e":["When she regained consciousness (= woke up after being unconscious ) , she was lying on the floor.","她恢复知觉醒来时，正躺在地板上。"]},{"w":"regarding","t":"prep. 关于","p":"rɪ'gɑːdɪŋ","c":1,"e":["Regarding your recent inquiry, I have enclosed a copy of our new brochure.","关于你最近的咨询，我随信附上一本我们最新的手册。"]},{"w":"regardless","t":"adv. 不管，不顾","p":"rɪˈɡɑːdləs","c":1,"e":["The new tax laws were rammed through regardless of the opposition of the majority of the people.","不顾大多数人民的反对，新的税法强行通过了。"]},{"w":"regenerate","t":"vi. 新生，再生，起革新作用；vt. 使新生，重建，改革，革新","p":"rɪ'dʒenər3ɪt","e":["Small nodules form as the liver cells regenerate.","肝细胞再生时会形成一些小结节。"]},{"w":"regenerative","t":"adj. 回授的；再生的","p":"rɪ'dʒen(ə)rətɪv","e":["...the regenerative power of nature.","...大自然的再生力。"]},{"w":"regime","t":"n. 制度，管理体制","p":"reɪˈʒiːm","c":1,"e":["Under the new regime, all sheep and cattle will be regularly tested for disease.","根据新制度，所有牛羊都要定期接受疾病检测。"]},{"w":"regiment","t":"n. 团；大量；vt. 严格地管制，严密地编组","p":"'redʒɪmənt","e":["the regimented routine of boarding school","寄宿学校严格的生活规律"]},{"w":"region","t":"n. 地区，地带，区域；范围，幅度","p":"'riːdʒən","e":["efforts to bring peace to the region","给这个地区带来和平的努力"]},{"w":"register","t":"v. 登记，注册；指示，自动记下；表示，表达；注意到，记住；把挂号；n. 登记，注册；登记表，注册簿","p":"'redʒɪstə","e":["The tanker is registered in Rotterdam.","这艘油轮是在鹿特丹登记的。"]},{"w":"registration","t":"n. 注册，登记","p":"ˌredʒɪˈstreɪʃn","c":1,"e":["Student registration (= for a course of study ) starts the first week in September.","学生注册在9月份的第一个星期开始。"]},{"w":"regularity","t":"n. 规则性；整齐，端正","p":"reɡjʊ'lærətɪ","e":["Climate change is disrupting the regularity of the seasons.","气候的变化正在打乱季节的规律性。"]},{"w":"regulate","t":"v. 调整，调节，校准","p":"'regjʊleɪt","e":["People sweat to regulate their body heat.","人出汗以调节体温。"]},{"w":"regulation","t":"n. 规则；管理","p":"ˌregjuˈleɪʃn","c":1,"e":["There seem to be so many rules and regulations these days.","如今好像条条框框很多。"]},{"w":"rehearsal","t":"n. 排练，排演","p":"rɪ'hɜːsl","e":["a wedding rehearsal","婚礼的预演"]},{"w":"reign","t":"vi. 当政，统治；占主导地位；n. 君主的统治，君主的统治时期","p":"reɪn","e":["Last night confusion reigned about how the debate, which continues today, would end.","昨晚，这场在今天继续进行的辩论将如何结束的问题令人困惑。"]},{"w":"reimbursement","t":"n. 返还费用","p":"ˌri:ɪm'bɜ:smənt","c":1,"e":["She is demanding reimbursement for medical and other expenses.","她在要求医疗和其他费用的报销。"]},{"w":"rein","t":"n. 缰绳；vt. 勒缰使停步；控制，约束","p":"reɪn","e":["Cord held the reins while the stallion tugged and snorted.","当那匹牡马使劲挣扎，打着响鼻的时候，科德勒紧了缰绳。"]},{"w":"reinforce","t":"v. 增强，强化","p":"ˌri:ɪnˈfɔ:s","c":1,"e":["The film reinforces the idea that women should be pretty and dumb.","这部影片强化了这个观点——女人要漂亮，而且要笨一些。"]},{"w":"reject","t":"vt. 拒绝；拒纳，退回，摈弃；n. 被拒货品，不合格产品","p":"rɪ'dʒekt","e":["Dexter flatly rejected (= completely rejected ) calls for his resignation.","德克斯特断然拒绝让他辞职的要求。"]},{"w":"rejection","t":"n. 拒绝","p":"rɪ'dʒekʃn","e":["They sent me a rejection letter.","他们给我发了一封回绝信。"]},{"w":"rejoice","t":"vi. 感到高兴，充满喜悦","p":"rɪ'dʒɔɪs","e":["Garbo plays the queen, rejoicing in the love she has found with Antonio.","嘉宝饰演沉浸在与安东尼奥爱情的欣喜中的王后。"]},{"w":"relative","t":"adj. 有关系的，相对的；n. 亲属，亲戚","p":"'relətɪv","e":["You may think you’re poor, but it’s all relative (= you are not poor compared to some people ) .","你可能认为自己很穷，但一切都是相对的。"]},{"w":"relay","t":"v. 接替，转播","p":"'riːleɪ","c":1,"e":["The broadcasts were relayed by satellite.","这些电视节目通过卫星进行转播。"]},{"w":"release","t":"v. 释放；发布","p":"rɪ'li:s","c":1,"e":["Police arrested several men, who were later released.","警察逮捕了几个人，后来都释放了。"]},{"w":"relegate","t":"vt. 使降位，使降级；把…委托给","p":"'relɪgeɪt","e":["Might it not be better to relegate the king to a purely ceremonial function?","使该国王降级到一种纯粹礼仪性的职能难道不更好吗？"]},{"w":"relevant","t":"adj. 相关的","p":"ˈreləvənt","c":1,"e":["Relevant documents were presented in court.","法庭上出示了相关的文件。"]},{"w":"reliable","t":"adj. 可靠的","p":"rɪˈlaɪəbl","c":1,"e":["Judged by the ordinary standards,he was reliable","用一般的标准衡量，他是可信赖的。"]},{"w":"reliance","t":"n. 依靠，依赖","p":"rɪ'laɪəns","e":["the country’s heavy reliance on trade","该国对贸易的严重依赖"]},{"w":"relief","t":"n. 轻松，宽慰；缓解，减轻，解除；使得到调剂；接替，替下","p":"rɪ'liːf","e":["No one was hurt, and we all breathed a sigh of relief .","没有人受伤，我们都松了一口气。"]},{"w":"relieve","t":"v. 减轻，缓解","p":"rɪ'li:v","c":1,"e":["Drugs helped to relieve the pain.","药物有助于舒缓疼痛。"]},{"w":"relieved","t":"adj. 轻松的，缓解的","p":"rɪˈli:vd","c":1,"e":["A relieved smile spread over his face.","他脸上绽开了宽慰的笑容。"]},{"w":"religion","t":"n. 宗教，宗教信仰","p":"rɪ'lɪdʒən","e":["The U.S. Constitution promises freedom of religion.","美国宪法保证宗教信仰自由。"]},{"w":"religious","t":"adj. 宗教的；笃信宗教的，虔诚的","p":"rɪ'lɪdʒəs","e":["the dates of major religious observances such as Easter or Christmas","复活节和圣诞节等重要宗教节日的日期"]},{"w":"relish","t":"vt. 享受，从…中获得乐趣；n. 享受，滋味，乐趣；调味品","p":"'relɪʃ","e":["a hot dog with mustard and relish","配芥末酱和调味汁的热狗"]},{"w":"reluctance","t":"n. 勉强，不情愿","p":"rɪ'lʌktəns","c":1,"e":["Wells finally agreed, but with reluctance.","韦尔斯最终同意了，但很勉强。"]},{"w":"reluctant","t":"adj. 不情愿的，勉强的","p":"rɪ'lʌktənt","e":["She gave a reluctant smile.","她勉强笑了笑。"]},{"w":"rely","t":"vi. 依靠，依赖；信赖，指望","p":"rɪ'laɪ","e":["They relied heavily on the advice of their professional advisers.","他们非常依赖专业顾问的建议。"]},{"w":"remain","t":"vi. 剩下，余留，保持；仍然是；n. 残余；残骸；遗迹","p":"rɪ'meɪn","e":["They were cleaning up the remains of their picnic.","他们正在打扫野餐的残余物。"]},{"w":"remainder","t":"n. 余下的部分，剩下的人数","p":"rɪ'meɪndə","e":["The remainder must be paid by the end of June.","剩余款项必须在6月底之前支付。"]},{"w":"remarkable","t":"adj. 显著的，杰出的","p":"rɪˈmɑ:kəbl","c":1,"e":["She has made remarkable progress.","她取得了显著的进步。"]},{"w":"remedy","t":"n. 补救办法，纠正办法；药品，治疗法；vt. 补救，纠正；医治，治疗","p":"'remədi","e":["The problems in our schools do not have a simple remedy.","我们学校的问题没有简单的解决办法。"]},{"w":"remnant","t":"n. 残留部分","p":"'remnənt","e":["Beneath the present church were remnants of Roman flooring.","在目前的这座教堂下面还有残余的古罗马地板。"]},{"w":"remote","t":"adj. 遥远的，偏僻的；关系疏远的；脱离的；绝少的；微乎其微的；孤高的，冷淡的","p":"rɪ'məut","e":["a fire in a remote mountain area","偏远山区的火灾"]},{"w":"remove","t":"v. 消除，移除；更新","p":"rɪˈmu:v","c":1,"e":["The college removed rules that prevented women from enrolling.","这所大学取消了禁止女性入学的规定。"]},{"w":"renaissance","t":"n. 文艺复兴，文艺复兴时期；复兴，再生","p":"rɪ'neɪsns","e":["...the Renaissance masterpieces in London's galleries.","…伦敦美术馆里文艺复兴时期的杰作。"]},{"w":"render","t":"v. 给予","p":"'rendə","c":1,"e":["an obligation to render assistance to those in need","为有困难的人提供援助的义务"]},{"w":"renewable","t":"adj. 可再生的","p":"rɪˈnjuːəbl","c":1,"e":["an industry based on renewable resources","基于可再生资源的行业"]},{"w":"repay","t":"vt. 归还；报答","p":"rɪ'peɪ","e":["I’d like to buy them something to repay all their kindness.","我想给他们买点东西来报答他们的好意。"]},{"w":"repeal","t":"v. 撤销","p":"rɪ'piːl","e":["The government has just repealed the law segregating public facilities.","政府刚刚废除了隔离公共设施的法令。"]},{"w":"repel","t":"vt. 使厌恶；击退，逐回，驱除；排斥","p":"rɪ'pel","e":["The smell repelled him.","这气味让他反感。"]},{"w":"repertoire","t":"n. 全部节目","p":"'repətwɑː","e":["the behavioural repertoire of infants","婴幼儿的行为能力"]},{"w":"repetitive","t":"adj. 重复的，反复性的","p":"rɪ'petətɪv","e":["The song was dreary and repetitive.","这首歌又枯燥又重复。"]},{"w":"replace","t":"v. 把...放回原处","p":"rɪ'pleɪs","e":["He replaced the book on the shelf.","他把书放回架子上。"]},{"w":"replacement","t":"n. 代替","p":"rɪ'pleɪsmənt","c":1,"e":["Our old car is badly in need of replacement.","我们的旧车急需更换。"]},{"w":"report","t":"n. 传说，议论","p":"rɪ'pɔːt","e":["Government officials have denied reports of rebel advances.","政府官员否认了有关叛军正在推进的传言。"]},{"w":"represent","t":"vt. 作为…的代表，表示，象征；描绘，表现","p":"ˌreprɪ'zent","e":["Mr Kobayashi was chosen to represent the company at the conference.","小林先生被选中代表公司出席会议。"]},{"w":"representation","t":"n. 描写；陈述；代表","p":",reprɪzen'teɪʃ(ə)n","e":["A group of students made representations to the college about the poor standard of the accommodation.","一群学生就恶劣的住宿条件同校方交涉。"]},{"w":"representative","t":"n. 代表","p":"ˌreprɪˈzentətɪv","c":1,"e":["a union representative","工会代表"]},{"w":"repression","t":"n. 压抑，压制，镇压","p":"rɪ'preʃn","e":["{\"COLLOINEXA\":[\"sexual repression\"]}","性压抑"]},{"w":"reproach","t":"n&vt. 责备，批评","p":"rɪ'prəutʃ","e":["‘You don’t need me,’ she said quietly, without reproach.","“你不需要我。”她语气平静，没有丝毫责备。"]},{"w":"reproduce","t":"v. 仿造","p":"riːprə'djuːs","e":["The effect has proved hard to reproduce.","这种效果经证实很难再造。"]},{"w":"reproduction","t":"n. 繁殖","p":"ˌri:prəˈdʌkʃn","c":1,"e":["Scientists studied the reproduction, diet, and health of the dolphins.","科学家研究了海豚的繁殖情况、进食规律和健康状况。"]},{"w":"reptile","t":"n. 爬行动物","e":["This small reptile, which measures just 10 centimeters long, can swim through the sand dunes at up to 15 centimeters per second.","这种身长只有10厘米小型爬行动物，可以在沙子中以最快每秒15厘米的速度游动。"]},{"w":"reputation","t":"n. 名誉，名气，名声","p":"ˌrepju'teɪʃn","e":["Alice Munro has a reputation for being a very depressing writer.","艾丽斯•门罗有文风抑郁的名声。"]},{"w":"requisite","t":"adj. 需要的，必要的；n. 必需品","p":"'rekwɪzɪt","e":["A university degree has become a requisite for entry into most professions.","大学学位已经成为在大多数行业谋职的必要条件。"]},{"w":"resemblance","t":"n. 相似，形似","p":"rɪ'zembləns","e":["There was a remarkable resemblance between him and Pete.","他和皮特有一个惊人的相似之处。"]},{"w":"resent","t":"vt. 对…表示愤恨，怨恨","p":"rɪ'zent","e":["Paul resented the fact that Carol didn’t trust him.","保罗非常气愤，因为卡萝尔不信任他。"]},{"w":"reservation","t":"n. 预定","p":"ˌrezə'veɪʃn","c":1,"e":["Customers are advised to make seat reservations well in advance.","建议顾客提前订座。"]},{"w":"reserve","t":"vt. 保留，留存；预订；n. 储备；保留；拘谨，矜持；替补队员；后备部队；自然保护区","p":"rɪ'zɜːv","e":["Do you have to reserve tickets in advance?","你必须预先订票吗？"]},{"w":"reserved","t":"adj. 保留意见的；矜持的","p":"rɪˈzɜ:vd","c":1,"e":["He was unemotional, quiet, and reserved.","他不动感情、安静而矜持。"]},{"w":"reside","t":"vi. 居住，定居；存在，在于","p":"rɪ'zaɪd","e":["He spent most of his time in Rutherglen, where his family resided.","他大部分时间都在拉瑟格伦度过，他的家人就在那里居住。"]},{"w":"resident","t":"n. 居民","p":"ˈrezɪdənt","c":1,"e":["The archbishop called on the government to build more low cost homes for local residents.","这位大主教呼吁该政府为当地居民建更多的廉价住宅。"]},{"w":"residential","t":"adj. 居住的，住宅的；寄宿的，住在住所的","p":"ˌrezɪ'denʃl","e":["a quiet residential neighbourhood","安静的住宅区"]},{"w":"residual","t":"adj. 剩余的；残余的","p":"rɪ'zɪdjʊəl","e":["residual income (=the money left from what you earn after you have paid your taxes)","税后收入"]},{"w":"resign","t":"v. 辞职","p":"rɪ'zaɪn","c":1,"e":["A hospital administrator has resigned over claims he lied to get the job.","一位医院主管因为有人声称他的职位是骗来的而辞职了。"]},{"w":"resignation","t":"n. 听从，屈从，顺从","p":"rezɪg'neɪʃ(ə)n","e":["He accepted her decision with resignation.","他无可奈何地接受了她的决定。"]},{"w":"resist","t":"v. 抵制","p":"rɪ'zɪst","c":1,"e":["The bank strongly resisted cutting interest rates.","银行强烈反对降低利率。"]},{"w":"resistant","t":"adj. 抵抗的；抗…的，耐…的","p":"rɪ'zɪstənt","e":["Some people are very resistant to the idea of exercise.","一些人对锻炼的主意非常抵制。"]},{"w":"resolute","t":"adj. 坚定的","p":"'rezəlu:t","c":1,"e":["She remained resolute in her belief that the situation would improve.","她依然坚信情况将会好转。"]},{"w":"resolve","t":"v. 决定；解决；分解；n. 决心","p":"rɪ'zɒlv","e":["Barnet was desperate for money to resolve his financial problems.","巴尼特急需钱来解决他的经济问题。"]},{"w":"resort","t":"n. 度假胜地","p":"rɪ'zɔ:t","c":1,"e":["Lagoon Reef is one of the best resort hotels.","潟湖礁是最好的度假酒店之一。"]},{"w":"respectable","t":"adj. 可敬的；人格高尚的","p":"rɪ'spektəb(ə)l","e":["Put a tie on - it’ll make you look more respectable.","戴上领带，这样显得更体面。"]},{"w":"respective","t":"adj. 各自的","p":"rɪˈspektɪv","c":1,"e":["We all went back to our respective homes to wait for news.","我们都各自回家等待消息。"]},{"w":"respond","t":"vi. 回答，答复；作出反应，响应","p":"rɪ'spɒnd","e":["They are likely to respond positively to the president's request for aid.","他们有可能积极地回应该总统的援助请求。"]},{"w":"response","t":"n. 回答，答复；反应，响应","p":"rɪ'spɒns","e":["Emmett’s new exhibition has met with a favourable response from critics.","埃米特的新展览得到评论家的好评。"]},{"w":"responsibility","t":"n. 责任","p":"rɪˌspɒnsə'bɪlətɪ","c":1,"e":["Kelly’s promotion means more money and more responsibility.","凯利获得提升，这意味着钱多了，责任也更大了。"]},{"w":"responsible","t":"adj. 需负责任的，承担责任的；有责任感的，负责可靠的；责任重大的，重要的","p":"rɪ'spɒnsəbl","e":["We are determined to bring the people responsible to justice.","我们决意要将肇事者绳之以法。"]},{"w":"responsive","t":"adj. 灵敏的，反应的","p":"rɪˈspɒnsɪv","c":1,"e":["a car with highly responsive steering","方向盘操纵灵活的汽车"]},{"w":"restore","t":"vt. 恢复，使恢复；修复，整修；归还，交还","p":"rɪ'stɔː","e":["She was hoping that the Mediterranean climate would restore her to full health.","她希望地中海的气候能使她的身体完全复原。"]},{"w":"restrain","t":"vt. 阻止，控制；抑制，遏制","p":"rɪ'streɪn","e":["Renwick restrained a feeling of annoyance.","伦威克忍住了不悦的情绪。"]},{"w":"restraint","t":"n. 抑制，限制，克制；约束措施，约束条件","p":"rɪ'streɪnt","e":["The police were praised for their restraint in handling the demonstrators.","警方因对待示威者时所表现出的克制而受到赞扬。"]},{"w":"restrict","t":"v. 限制","p":"rɪ'strɪkt","c":1,"e":["You may need to restrict access to certain files (= limit the number of people who can read them ) .","某些档案可能需要限制查阅。"]},{"w":"restructure","t":"v. 调整，重建","p":"riː'strʌktʃə","c":1,"e":["proposals to radically restructure Britain’s electronics industry","彻底整顿英国电子行业的提议"]},{"w":"resultant","t":"adj. 作为结果的，因而发生的","p":"rɪ'zʌltənt","e":["She is still trying to get over the attack and the resultant injuries.","她仍在努力从袭击以及由此造成的伤害中恢复过来。"]},{"w":"resume","t":"n. 简历","p":"ˈrezəmeɪ","c":1,"e":["Update your resume and cover letter.","更新你的简历和求职信。"]},{"w":"retail","t":"n. 零售","p":"'riːteɪl","e":["The retail value would be around $500.","零售价在500美元左右。"]},{"w":"retailer","t":"n. 零售商","p":"ˈri:teɪlə(r)","c":1,"e":["Furniture and carpet retailers are among those reporting the sharpest annual decline in sales.","据称年销售额下滑幅度最大的零售商中包括家具和地毯零售商。"]},{"w":"retain","t":"vt. 保留，保持","p":"rɪ'teɪn","e":["You have the right to retain possession of the goods.","你有权保留这些物品。"]},{"w":"retard","t":"v. 阻碍；减缓；放慢","p":"'rɪtɑːd","e":["Cold weather retards the growth of many plants.","寒冷的天气使许多植物生长滞缓。"]},{"w":"retention","t":"n. 保留，保持","p":"rɪ'tenʃn","e":["The Citizens' Forum supported special powers for Quebec but also argued for the retention of a strong central government.","《市民论坛》支持魁北克的特殊权力，但是也主张保留一个强有力的中央政府。"]},{"w":"retirement","t":"n. 退休，引退；退隐","p":"rɪ'taɪəm(ə)nt","e":["She took early retirement (= retired at an earlier age than usual ) last year.","她去年提前退休了。"]},{"w":"retort","t":"n&v. 反驳，回嘴","p":"rɪ'tɔːt","e":["‘It’s all your fault!’ he retorted.","“那都是你的错！”他反驳道。"]},{"w":"retrieve","t":"vi. 重新得到，取回，收回；挽回，补救；检索","p":"rɪ'triːv","e":["She bent down to retrieve her earring.","她俯身去捡回耳环。"]},{"w":"retrospect","t":"n. 回顾","p":"'retrəspekt","e":["In retrospect, I wonder if we should have done more.","回过头看，我在想我们是否应该做得更多些。"]},{"w":"reunion","t":"n. 团聚","p":"ˌri:'ju:nɪən","c":1,"e":["a high-school reunion","高中同学联谊聚会"]},{"w":"reveal","t":"v. 揭露","p":"rɪ'vi:l","c":1,"e":["He may be prosecuted for revealing secrets about the security agency.","他可能因泄露安全部门的机密而被起诉。"]},{"w":"revelation","t":"n. 被提示的真相，新发现；揭示，透露，显示","p":"ˌrevə'leɪʃn","e":["...the seemingly everlasting revelations about his private life.","…有关他私生活的似乎永无休止的披露。"]},{"w":"revenge","t":"n. 报复，报仇；vt. 为…报仇，报…之仇","p":"rɪ'vendʒ","e":["The attackers were said to be taking revenge on the 14-year-old, claiming he was a school bully.","攻击者被称是在报复一名14岁男孩，称他是学校一霸。"]},{"w":"revenue","t":"n. 收入","p":"'revənju:","c":1,"e":["Strikes have cost £20 million in lost revenues .","罢工造成的收入损失达到2,000万英镑。"]},{"w":"reverse","t":"adj. 相反的","p":"rɪ'vɜ:s","c":1,"e":["The results were read out in reverse order (= with the worst first and the best last ) .","成绩是按逆序宣读的。"]},{"w":"revive","t":"v. 复兴；复苏","p":"rɪ'vaɪv","c":1,"e":["Local people have decided to revive this centuries-old tradition.","当地人决定复兴这一延续了数个世纪的传统。"]},{"w":"revolutionary","t":"adj. 革命的；革新的；n. 革命者","p":"ˌrevə'luːʃənəri","e":["The new cancer drug is a revolutionary breakthrough.","这种抗癌新药是一个革命性突破。"]},{"w":"revolutionize","t":"v. 革命化","p":"ˌrevə'lu:ʃənaɪz","c":1,"e":["New technology is going to revolutionize everything we do.","新科技将彻底改变我们做的每一件事。"]},{"w":"revolve","t":"vi. 旋转","p":"rɪ'vɒlv","e":["The restaurant slowly revolves, giving excellent views of the city.","餐厅缓缓旋转，城市美景尽收眼底。"]},{"w":"reward","t":"n. 报答，奖赏；报酬，酬金；vt. 报答，酬谢，奖励","p":"rɪ'wɔːd","e":["The school has a system of rewards and punishments to encourage good behaviour.","学校有奖惩制度以鼓励良好行为。"]},{"w":"rewarding","t":"adj. 有意义的","p":"rɪˈwɔ:dɪŋ","c":1,"e":["Teaching can be a very rewarding career.","教书可以是一种很有意义的职业。"]},{"w":"rhetorical","t":"adj. 修辞的","p":"rɪˈtɒrɪkl","c":1,"e":["a speech full of rhetorical phrases","充满华丽辞藻的演讲"]},{"w":"rhythm","t":"n. 节奏","p":"ˈrɪðəm","c":1,"e":["Drums are basic to African rhythm.","非洲音乐节奏少不了鼓。"]},{"w":"ridicule","t":"v. 嘲弄，挖苦；n. 嘲弄，挖苦","p":"'rɪdɪkjuːl","e":["He had become an object of ridicule among the other teachers.","他成了其他教师嘲笑的对象。"]},{"w":"ridiculous","t":"adj. 滑稽的，可笑的","p":"rɪˈdɪkjələs","c":1,"e":["I’d look ridiculous in a dress like that.","我穿那样的裙子会显得很可笑。"]},{"w":"rig","t":"vt. 操纵，垄断；给装配帆及索具；用临时替代材料迅速搭起；n. 船桅的装置，成套器械","p":"rɪg","e":["Some international observers have claimed the election was rigged.","一些国际观察员声称选举受到操纵。"]},{"w":"rigid","t":"adj. 严格的","p":"'rɪdʒɪd","c":1,"e":["rigid and authoritarian methods of education","死板、专断的教育方法"]},{"w":"rigor","t":"n. 严格，严谨","p":"'riɡə","c":1,"e":["Their research seems to me to be lacking in rigor.","他们的研究在我看来不够严谨。"]},{"w":"rigorous","t":"adj. 严格的","p":"ˈrɪgərəs","c":1,"e":["the rigorous standards required by the college","大学规定的严格标准"]},{"w":"rim","t":"n. 边，缘；vt. 环绕边缘","p":"rɪm","e":["She looked at him over the rim of her glass.","她沿玻璃杯口看着他。"]},{"w":"rinse","t":"v. 冲洗；嗽（口）","p":"rɪns","e":["After her meal she invariably rinsed out her mouth.","饭后她总漱口。"]},{"w":"riot","t":"n. 骚乱，暴乱；v. 发动骚乱","p":"'raɪət","e":["University students rioted in protest at tuition fees.","大学生闹事，抗议学费过高。"]},{"w":"rip","t":"v. 扯破，撕坏；n. 裂口，裂缝","p":"rɪp","e":["The sail ripped under the force of the wind.","船帆被狂风刮破了。"]},{"w":"ripple","t":"n. 涟漪，细浪，波纹","p":"'rɪp(ə)l","e":["She dived into the pool, making scarcely a ripple.","她跳入池中，几乎没有泛起水波。"]},{"w":"ritual","t":"n. 仪式","p":"'rɪtʃʊəl","c":1,"e":["The lady of the house performs the sacred ritual of lighting two candles.","由女主人来完成点燃两根蜡烛的神圣仪式。"]},{"w":"rival","t":"n. 对手","p":"ˈraɪvl","c":1,"e":["Their sales have now overtaken those of their arch-rival (= main or strongest rival ) .","他们的销售额现已超过了主要竞争对手。"]},{"w":"rivalry","t":"n. 竞争，竞赛；对抗","p":"'raɪvlri","e":["She had never overcome her feelings of sibling rivalry (= rivalry between brothers and sisters ) .","她一直没有克服和兄弟姐妹较劲的那种心理。"]},{"w":"roam","t":"v. 在…漫步，漫游","p":"rəʊm","e":["You shouldn’t let your children roam the streets .","你不应该让孩子在街上游荡。"]},{"w":"robbery","t":"n. 抢劫","p":"'rɒbərɪ","c":1,"e":["He received a 10 year prison sentence for armed robbery (= robbery using a gun ) .","他因持枪抢劫被判十年监禁。"]},{"w":"robust","t":"adj. 强健的","p":"rə(ʊ)'bʌst","c":1,"e":["a robust man of six feet four","一个身高六英尺四英寸的壮汉"]},{"w":"roller","t":"n. 滚筒；滚柱","p":"'rəʊlə","e":["The boats are taken down to the sea on rollers.","船只用滚柱移到海里。"]},{"w":"Roman","t":"n. 古罗马人；罗马人","p":"'rəʊmən","e":["When they conquered Britain, the Romans brought this custom with them.","当古罗马人征服不列颠时，他们把这一习俗也带了过去。"]},{"w":"romance","t":"n. 恋爱，恋爱关系；浪漫气氛，传奇色彩；爱情小说，传奇故事","p":"rəu'mæns","e":["The romance had gone out of their relationship.","他们之间已经没有了爱意。"]},{"w":"romantic","t":"adj. 爱情的","p":"rəʊˈmæntɪk","c":1,"e":["I'm not interested in a romantic relationship.","我对谈情说爱不感兴趣。"]},{"w":"rooster","t":"n. 公鸡","p":"'ruːstə","e":["I heard a rooster crow.","我听见雄鸡啼叫。"]},{"w":"rot","t":"v. 腐烂，腐朽；n. 腐烂，腐朽","p":"rɒt","e":["The trees were cut and left to rot .","树被砍伐后任其腐烂。"]},{"w":"rotary","t":"adj. 旋转的，转动的","p":"'rəutəri","e":["the rotary movement of the helicopter blades","直升机螺旋桨叶的转动"]},{"w":"rotate","t":"v. （使）旋转","p":"rə(ʊ)'teɪt","e":["The Earth rotates on its axis once every 24 hours.","地球每24小时绕地轴自转一周。"]},{"w":"roundabout","t":"adj. 转弯抹角的；迂回的","p":"'raʊndəbaʊt","e":["He left today on a roundabout route for Jordan and is also due soon in Egypt.","他今天绕道前往约旦，也将很快到达埃及。"]},{"w":"routine","t":"adj. 例行的，常规的；n. 例行公事，惯例，惯常的程序","p":"ruː'tiːn","e":["You mustn’t worry. These are just routine enquiries.","你不必担心，这只是例行的询问。"]},{"w":"row","t":"v. 划船","p":"rəʊ","c":1,"e":["Jenny used to row at college (= as a sport ) .","珍妮以前在大学里经常参加划船运动。"]},{"w":"royalty","t":"n. 王族；版税","p":"'rɔɪəlti","e":["the royalties from his latest book","他新书的版税"]},{"w":"ruby","t":"n. 红宝石","p":"'ruːbɪ","e":["...a ruby and diamond ring.","…一枚红宝石钻戒。"]},{"w":"ruin","t":"v. 毁坏","p":"'ru:ɪn","c":1,"e":["All this mud’s going to ruin my shoes.","这泥巴会把我的鞋弄坏。"]},{"w":"rule","t":"v. 裁决，裁定","p":"ruːl","e":["The judge ruled that she should have custody of the children.","法官判定孩子的监护权归她。"]},{"w":"ruling","t":"n. 裁定","p":"ˈru:lɪŋ","c":1,"e":["Goodwin tried to have the court ruling overturned.","古德温试图推翻法院的裁决。"]},{"w":"rupture","t":"v. 破裂；n. 破裂，裂开；决裂，断绝","p":"'rʌptʃə","e":["His liver was ruptured when a brick wall collapsed on him.","一堵砖墙坍塌压住了他，导致他的肝脏破裂。"]},{"w":"rustle","t":"v. 发出沙沙声","p":"'rʌsl","c":1,"e":["She moved nearer, her long silk skirt rustling around her.","她走近了，真丝长裙窸窣作响。"]},{"w":"ruthless","t":"adj. 无情的，冷酷的","p":"'ruːθlɪs","e":["They have shown a ruthless disregard for basic human rights.","他们冷酷地无视基本人权。"]},{"w":"sacred","t":"adj. 神圣的；宗教的；神圣不可侵犯的","p":"'seɪkrɪd","e":["Certain animals were considered sacred.","有些动物被认为是神圣的。"]},{"w":"sacrifice","t":"n&v. 牺牲，舍身；献祭，供奉；祭品","p":"'sækrɪfaɪs","e":["She brought three children up single-handedly, often at great personal sacrifice .","她独自一人把三个孩子带大，常常需要作出巨大的个人牺牲。"]},{"w":"safeguard","t":"vt. 保护，维护；n. 预防措施；保证条款","p":"'seɪfgɑːd","e":["technology that will safeguard the environment","将会保护环境的技术"]},{"w":"sake","t":"n. 缘故，理由","p":"seɪk","e":["I hope he’s told the truth for his own sake (= because it will be good for him ) .","为了他自己好，我希望他已经说出了真相。"]},{"w":"saleable","t":"adj. 适合销售的","p":"'seɪləbl","e":["a saleable commodity","有销路的商品"]},{"w":"salmon","t":"n. 鲑，大马哈鱼","p":"'sæmən","e":["wild and farmed salmon","野生和人工养殖的鲑鱼"]},{"w":"salute","t":"vi. 敬礼，致意；vt. 向…敬礼，向…致意；赞扬，颂扬；n. 敬礼，致意","p":"sə'luːt","e":["The two soldiers saluted Lieutenant Cecil.","那两名士兵向塞西尔中尉行了礼。"]},{"w":"salvation","t":"n. 拯救，解救；解救措施","p":"sæl'veɪʃn","e":["The church's message of salvation has changed the lives of many.","这个教会的灵魂得救的训诫已经改变了很多人的一生。"]},{"w":"sample","t":"n. 样本，样品","p":"'sɑ:mpl","c":1,"e":["They took a blood sample to test for hepatitis.","他们取了血样做肝炎化验。"]},{"w":"sanction","t":"vt. 批准，认可；n. 批准，认可；约束因素，约束力；国际制裁","p":"'sæŋkʃn","e":["The church refused to sanction the king’s second marriage.","教会拒绝批准国王的第二次婚姻。"]},{"w":"sandwich","t":"v. 夹入，挤进","p":"'sæn(d)wɪdʒ; -wɪtʃ","e":["Carefully split the sponge ring, then sandwich the two halves together with whipped cream.","小心地切开海绵蛋糕圈，然后在两半中间夹上生奶油。"]},{"w":"sanitation","t":"n. 卫生环境，卫生设备","p":"sænɪ'teɪʃ(ə)n","c":1,"e":["Overcrowding and poor sanitation are common problems in prisons.","过度拥挤和卫生状况差是监狱里的普遍问题。"]},{"w":"sardine","t":"n. 沙丁鱼","p":"sɑː'diːn","e":["commuters packed like sardines on the evening train","晚班火车上挤得像沙丁鱼一样的通勤乘客"]},{"w":"satellite","t":"n. 附属国","p":"'sætəlaɪt","e":["a satellite country","卫星国"]},{"w":"satisfaction","t":"n. 满足，愉快","p":"sætɪs'fækʃ(ə)n","e":["She got great satisfaction from helping people to learn.","她在帮助人们学习的过程中得到很大的满足。"]},{"w":"satisfactorily","t":"adv. 圆满地","p":",sætɪs'fæktərəlɪ","e":["Her disappearance has never been satisfactorily explained.","她的失踪一直没有得到令人信服的解释。"]},{"w":"saturate","t":"vt. 使湿透，浸透；使充满，使饱和","p":"'sætʃəreɪt","e":["Water poured through the hole, saturating the carpet.","水从洞里流进来，浸湿了地毯。"]},{"w":"saturation","t":"n. 饱和（状态）；浸透","p":"sætʃə'reɪʃ(ə)n","e":["a business beset by price wars and market saturation (= the fact that no new customers can be found)","一家受价格战和市场饱和困扰的企业"]},{"w":"Saturn","t":"n. 土星","e":["Saturn is the second biggest planet in the solar system.","土星是太阳系中的第二大行星。"]},{"w":"savage","t":"adj. 残暴的，凶猛的，粗鲁的；未开化的，野蛮的；n. 野蛮人，粗鲁的人；vt. 乱咬；激烈抨击","p":"'sævɪdʒ","e":["a savage murder","凶残的谋杀"]},{"w":"scaffolding","t":"n. 脚手架","p":"ˈskæfəldɪŋ","c":1,"e":["Workers have erected scaffolding around the base of the tower below the roadway.","工人们已经在车行道下的塔基四周竖起了脚手架。"]},{"w":"scale","t":"n. 大小，规模；等级，级别；天平，磅秤；比例；刻度，标度；鳞；vt. 攀登，爬越","p":"skeɪl","e":["Large firms benefit from economies of scale (= ways of saving money because they are big ) .","大公司从规模经济中得益。"]},{"w":"scan","t":"vt. 细看，审视，浏览；n. 扫描","p":"skæn","e":["She scanned his face, looking for signs of what he was thinking.","她端详着他的脸，想知道他在想些什么。"]},{"w":"scandal","t":"n. 丑闻","p":"'skændl","c":1,"e":["The college has recently been involved in a drugs scandal .","这所大学最近卷入了毒品丑闻。"]},{"w":"scar","t":"v. 留下伤痕；n. 伤疤，伤痕；创伤","p":"skɑː","e":["His hands were badly scarred by the fire.","他的双手被那次大火烧得疤痕累累。"]},{"w":"scarcity","t":"n. 缺乏","p":"'skeəsətɪ","c":1,"e":["...an ever increasing scarcity of water.","…越来越匮乏的水资源。"]},{"w":"scare","t":"n. 恐吓，惊恐","p":"skeə(r)","c":1,"e":["You really gave us a scare !","你真的吓了我们一跳！"]},{"w":"scarlet","t":"n. 猩红色；adj. 猩红的","p":"'skɑːlət","e":["scarlet berries","鲜红的浆果"]},{"w":"scary","t":"adj. 可怕的，骇人的；惊慌的，害怕的；胆小的，易受惊的","p":"'skeəri","e":["The book is both scary and funny.","这本书既恐怖又有趣。"]},{"w":"scatter","t":"vt. 撒，散播；使散开，驱散","p":"'skætə","e":["The sound of gunfire made the crowd scatter in all directions.","枪声使人群四散奔逃。"]},{"w":"scent","t":"n. 香味","p":"sent","c":1,"e":["a yellow rose with a lovely scent","香气怡人的黄玫瑰"]},{"w":"schedule","t":"n. 计划表","p":"'ʃedjuːl","c":1,"e":["How can he fit everything into his busy schedule ?","他是怎么把所有的事情都排进自己忙碌的时间表的？"]},{"w":"scheme","t":"v. 密谋，策划；n. 计划，方案；阴谋","p":"skiːm","e":["She’s nothing but a lying, scheming little monster!","她就是个爱撒谎、爱算计的小巫婆！"]},{"w":"scholarship","t":"n. 奖学金；学问，学识","p":"'skɒləʃɪp","e":["Her latest publication is a fine piece of scholarship.","她最新出版的作品是一部优秀的学术著作。"]},{"w":"scoff","t":"v. 嘲笑，嘲弄","p":"skɒf","e":["‘You, a scientist!’ he scoffed.","“就你，还科学家！”他讥笑道。"]},{"w":"scoop","t":"v. 舀出；抢在之前报道新闻；n. 勺子；抢先报道的新闻","p":"skuːp","e":["Time and again we have scooped our rivals.","我们一再抢在对手之前登出报道。"]},{"w":"scope","t":"n. 范围；余地，机会","p":"skəup","e":["measures to limit the scope of criminals’ activities","限制罪犯活动范围的措施"]},{"w":"scorch","t":"v. 烧焦；枯萎","p":"skɔːtʃ","e":["The leaves will scorch if you water them in the sun.","在太阳底下浇水，叶子会枯。"]},{"w":"score","t":"n. 得分，比数，成绩；二十；vt. 分，给…打分；画线于；获胜","p":"skɔː","e":["Is anybody keeping score (= making a record of the score ) ?","有没有人负责记分？"]},{"w":"scorn","t":"n. 轻蔑，鄙视；vt. 轻蔑，鄙视；拒绝，不屑","p":"skɔːn","e":["Researchers greeted the proposal with scorn.","研究者们对这个提议报以轻蔑的态度。"]},{"w":"scout","t":"v. 搜索，侦察","p":"skaʊt","e":["They scouted the area for somewhere to stay the night.","他们四处查看，想找个过夜的地方。"]},{"w":"scramble","t":"vi. 攀登，爬；争夺，抢夺；vt. 扰乱，搞乱；n. 攀登，爬行；争夺，抢夺","p":"'skræmbl","e":["Tourists were scrambling over the rocks looking for the perfect camera angle.","旅行者们爬上岩石，寻找最完美的拍摄角度。"]},{"w":"scrap","t":"n. 碎片，碎屑；废金属；残羹剩饭；少量，点滴；vt. 废弃，抛弃","p":"skræp","e":["a rug made out of old scraps of material","用旧零碎材料拼做的一块小地毯"]},{"w":"scrape","t":"v. 刮，擦；勉强过日子；n. 刮，擦；刮擦声","p":"skreɪp","e":["The two of them scraped their dishes clean .","他们两个把盘子擦得干干净净。"]},{"w":"scratch","t":"v. 抓，搔，扒；刮擦，刻划；n. 抓痕，划痕；抓，搔，刮","p":"skrætʃ","e":["John yawned and scratched his leg.","约翰打了个呵欠，挠了挠腿。"]},{"w":"screw","t":"n. 螺丝；vt. 用螺钉固定，拧，拧紧","p":"skruː","e":["Fix the frame in position and tighten the screws .","把框子固定在正确位置上，拧紧螺丝。"]},{"w":"script","t":"n. 脚本，剧本","p":"skrɪpt","c":1,"e":["They write all their own scripts.","他们所有的剧本都是自己写的。"]},{"w":"scripture","t":"n. 《圣经》；圣书","p":"'skrɪptʃə","e":["the way God is portrayed in Scripture","《圣经》中对上帝的描写"]},{"w":"scrub","t":"v. 用力擦洗，把…擦净；取消；n. 矮树丛，灌木丛","p":"skrʌb","e":["She was on her hands and knees scrubbing the floor.","她正趴着擦地板。"]},{"w":"scrutiny","t":"n. 详细检查，仔细观察","p":"'skruːtəni","e":["Their activities have come under police scrutiny .","他们的活动受到警方的严密监视。"]},{"w":"sculpture","t":"n. 雕塑","p":"'skʌlptʃə(r)","c":1,"e":["...stone sculptures of figures and animals.","…人物及动物石雕。"]},{"w":"seam","t":"n. 缝，接缝；煤层","p":"siːm","e":["She was repairing Billy’s trousers, where the seam had come undone.","她在补比利裤子的开线处。"]},{"w":"seaport","t":"n. 海港，港口，港市","p":"'siːpɔːt","e":["...the Baltic seaport of Rostock.","...波罗的海沿岸的海港城市罗斯托克。"]},{"w":"seasick","t":"adj. 晕船的","p":"ˈsiːsɪk","c":1,"e":["It was quite rough at times, and she was seasick.","海上有时波涛汹涌，她就晕船。"]},{"w":"seaside","t":"n. 海滨（胜地）；海边","p":"'siːsaɪd","e":["a trip to the seaside","去海滨的旅行"]},{"w":"second","t":"v. 支持","p":"'sek(ə)nd","e":["Any proposal must be seconded by two other members of the committee.","任何提案须有委员会其他两位委员附议。"]},{"w":"section","t":"n. 部分","p":"'sekʃ(ə)n","e":["The plane’s tail section was found in a cornfield.","飞机的尾部在玉米田里找到了。"]},{"w":"sector","t":"n. 部门","p":"'sektə(r)","c":1,"e":["...the nation's manufacturing sector.","…该国的制造部门。"]},{"w":"security","t":"n. 安全，保障；抵押品；证券","p":"sɪ'kjuərəti","e":["This insurance plan offers your family financial security in the event of your death.","这份保险能在你死后给你的家人提供经济保障。"]},{"w":"seemingly","t":"adv. 表面上，看上去","p":"'siːmɪŋli","e":["seemingly unrelated bits of information","似乎互不相关的零星信息"]},{"w":"segment","t":"n. 部分，片段；瓣","p":"'segmənt","e":["Decorate with orange segments.","用几瓣橙子作点缀。"]},{"w":"segregate","t":"vt. 使隔离，使分开","p":"'segrɪgeɪt","e":["A large detachment of police was used to segregate the two rival camps of protesters.","一大队分遣警察被派来隔离两群敌对的抗议者。"]},{"w":"segregation","t":"n. 隔离","p":"ˌseɡrɪˈɡeɪʃn","c":1,"e":["The Supreme Court unanimously ruled that racial segregation in schools was unconstitutional.","最高法院一致裁定学校实施的种族隔离措施违反宪法。"]},{"w":"selection","t":"n. 选择；精选的东西","p":"sɪ'lekʃ(ə)n","e":["These drawings represent a selection from a larger exhibition.","这些画作是从一个规模更大的展会上选出来的。"]},{"w":"semester","t":"n. 学期","p":"sɪ'mestə","e":["the fall semester","秋季学期"]},{"w":"seminar","t":"n. 研究班，研讨会","p":"'semɪnɑː","e":["a Shakespeare seminar","莎士比亚研讨班"]},{"w":"senator","t":"n. 参议员","p":"'senətə","e":["Senator Kennedy","肯尼迪参议员"]},{"w":"sensation","t":"n. 感觉能力；感觉，知觉；轰动，引起轰动的事件","p":"sen'seɪʃn","e":["Jerry realized that he had no sensation in his legs.","杰里意识到自己双腿都没有了知觉。"]},{"w":"sensational","t":"adj. 轰动的，耸人听闻的；使人感动的，非常好的","p":"sen'seɪʃənl","e":["The show was a sensational success.","这次演出取得了轰动性的成功。"]},{"w":"senseless","t":"adj. 愚蠢的，无意义的","p":"'senslɪs","e":["Her death seemed such a senseless waste of life.","她的死真是无谓地浪费生命。"]},{"w":"sensible","t":"adj. 理智的","p":"ˈsensəbl","c":1,"e":["It’s sensible to keep a note of your passport number.","把你的护照号码记下来是明智的。"]},{"w":"sensitive","t":"adj. 敏感的，灵敏的；神经过敏的，容易生气的；易受伤害的","p":"'sensətɪv","e":["a very sensitive child","一个很敏感的小孩"]},{"w":"sensitivity","t":"n. 敏感（性）；灵敏性","e":["The sensitivity of the detector can be increased.","这种探测器的灵敏度还可以提高。"]},{"w":"sensor","t":"n. 传感器，灵敏元件","p":"'sensə","e":["The latest Japanese vacuum cleaners contain sensors that detect the amount of dust and type of floor.","日本最新款吸尘器装有传感器，能测出灰尘量和地板类型。"]},{"w":"sentiment","t":"n. 意见，观点；感情，情绪","p":"'sentɪmənt","e":["‘After all, it’s her decision.’ ‘ My sentiments exactly (= I agree ) .’","“毕竟，这是她自己作的决定。”“我同意。”"]},{"w":"sequence","t":"n. 连续，接续，一连串；次序，顺序","p":"'siːkwəns","e":["Be careful to perform the actions in the correct sequence .","注意要按正确的顺序来完成动作。"]},{"w":"sergeant","t":"n. 中士，警官","p":"'sɑːdʒənt","e":["Right, but how do you know there's a sergeant there?","正确，可是你怎么知道那儿有一个中士？"]},{"w":"serial","t":"adj. 连续的，顺序排列的；n. 连续剧，连载故事","p":"'sɪəriəl","e":["Keep the questions in the same serial order .","让这些问题保持原来的顺序。"]},{"w":"series","t":"n. 一系列，连续；丛书，连续剧","p":"'sɪəriːz","e":["The police are investigating a series of attacks in the area.","警方在调查该地区发生的一连串袭击事件。"]},{"w":"sermon","t":"n. 布道，讲道；说教","p":"'sɜːmən","e":["The vicar gave a sermon on charity.","牧师作了一次关于仁爱的布道。"]},{"w":"serpent","t":"n. 蛇（尤指大蛇或毒蛇）","p":"'sɜːp(ə)nt","e":["...the serpent in the Garden of Eden.","…伊甸园里的那条蛇。"]},{"w":"server","t":"n. 服务器","p":"'sɜ:və(r)","c":1,"e":["All data is stored on a central file server.","所有数据资料都储存在中央文件服务器里。"]},{"w":"session","t":"n. 会议；学年","p":"ˈseʃn","c":1,"e":["Board members met in closed session (= with nobody else present ) .","委员会成员举行了闭门会议。"]},{"w":"set","t":"n. 集（合）","p":"set","e":["The set (x, y) has two members.","（x, y）这个集里有两个项。"]},{"w":"setback","t":"n. 挫折，倒退，失败","p":"'setbæk","e":["The team’s hopes of playing in Europe suffered a setback last night.","球队赴欧洲参加比赛的希望昨晚遇到了阻碍。"]},{"w":"settle","t":"v. 安排，安放；调停；支付，核算；安家；飞落，停留；安定","p":"'setl","e":["She breathed deeply to settle her nerves (= stop herself from feeling worried or frightened ) .","她深深地吸了口气平静自己的情绪。"]},{"w":"settlement","t":"n. 解决；协议；居留地，小社区","p":"'setlmənt","e":["Union leaders and company bosses will meet tomorrow in an attempt to reach a settlement .","工会领导人和公司老板将于明天举行会议以期达成协议。"]},{"w":"severe","t":"adj. 严重的；严厉的，严格的；严峻的，艰难的；朴素的，不加装饰的","p":"sɪ'vɪə","e":["She’s suffering from severe depression.","她患有严重的抑郁症。"]},{"w":"severity","t":"n. 严重性","p":"sɪ'verətɪ","c":1,"e":["The chances of a full recovery will depend on the severity of her injuries.","能否彻底康复取决于她受伤的严重程度。"]},{"w":"sew","t":"v. 缝上，缝纫","p":"səʊ","c":1,"e":["I learned to sew at school.","我在学校学会了缝纫。"]},{"w":"sexism","t":"n. 性别歧视","p":"ˈseksɪzəm","c":1,"e":["sexism in the workplace","工作场所的性别歧视"]},{"w":"shabby","t":"adj. 破旧的，衣衫褴褛的；卑鄙的；不公正的","p":"'ʃæbi","e":["Hugh’s jacket was old and shabby.","休的夹克衫又旧又破。"]},{"w":"shade","t":"v. 为…遮阳[挡光]，遮蔽〔光线〕","p":"ʃeɪd","c":1,"e":["Shading her eyes, Anita scanned the horizon.","安妮塔手搭凉棚，眺望地平线。"]},{"w":"shadowy","t":"adj. 有影的；幽暗的","p":"'ʃædəʊɪ","e":["a shadowy room","幽暗的房间"]},{"w":"shady","t":"adj. 阴凉的","p":"'ʃeɪdɪ","c":1,"e":["It was nice and shady under the trees.","树下好阴凉。"]},{"w":"shaft","t":"n. 柄，杆；束，光线；轴；竖井，升降井","p":"ʃɑːft","e":["a drive shaft","驱动轴"]},{"w":"sham","t":"n. 假冒；膺品；v. 假装","p":"ʃæm","e":["The elections were a complete sham.","这次大选完全是一场骗局。"]},{"w":"shame","t":"v. 使羞愧；玷辱","p":"ʃeɪm","e":["She had shamed her family name (= done something that made her family lose honour ) .","她玷污了家族的名声。"]},{"w":"shameful","t":"adj. 可耻的；不道德的","p":"'ʃeɪmfʊl; -f(ə)l","e":["It’s shameful the way some people treat their pets.","有些人如此对待自己的宠物，真是可耻。"]},{"w":"shareholder","t":"n. 股东","p":"ˈʃeəhəʊldə(r)","c":1,"e":["Shareholders have been told to expect an even lower result next year.","股东们被告知明年的业绩还会更差。"]},{"w":"shark","t":"n. 鲨鱼；勒索者，诈骗者，放高利贷的人","p":"ʃɑːk","e":["Sharks were circling around our boat.","鲨鱼在我们的小船周围游弋。"]},{"w":"sharply","t":"adv. 严厉地，苛刻地","p":"'ʃɑ:plɪ","e":["The report was sharply critical of the police.","报道猛烈地抨击了警方。"]},{"w":"shatter","t":"vi. 碎裂；vt. 使粉碎，砸碎；使破灭；使震惊","p":"'ʃætə","e":["The explosion shattered the building.","这次爆炸把大楼炸成一片废墟。"]},{"w":"shed","t":"v. 洒 (热血)","p":"ʃed","c":1,"e":["...young warriors, eager to shed blood.","…渴望洒热血的年轻武士们。"]},{"w":"sheer","t":"adj. 纯粹的","p":"ʃɪə(r)","c":1,"e":["I’ll never forget the look of sheer joy on her face.","我永远也不会忘记她满脸喜悦的神情。"]},{"w":"shell","t":"n. 炮弹，猎枪子弹","p":"ʃel","e":["We ran for cover as shells dropped all around us.","周围炮弹四处飞落，我们奔跑着寻找地方躲避。"]},{"w":"shelter","t":"v. 掩蔽，躲避，庇护；n. 掩蔽处，躲避处；掩蔽，保护","p":"'ʃeltə","e":["Collins was arrested for sheltering enemy soldiers.","科林斯因收留敌兵而被逮捕。"]},{"w":"shepherd","t":"v. 引导，带领","p":"'ʃepəd","c":1,"e":["The tour guides shepherded the rest of the group onto the bus.","导游把团中的其他人带上了巴士"]},{"w":"sheriff","t":"n. 郡长","p":"'ʃerɪf","e":["...the Sheriff of Oxford.","牛津的郡长"]},{"w":"shield","t":"n. 防护物，护罩；盾；vt. 保护，防护","p":"ʃiːld","e":["He used his left hand as a shield against the reflecting sunlight.","他用左手遮挡反射过来的阳光。"]},{"w":"shift","t":"v. 转移注意力；转变","p":"ʃɪft","c":1,"e":["The White House hopes to shift the media’s attention away from foreign policy issues.","白宫希望把媒体的注意力从外交政策问题上转移开。"]},{"w":"shipbuilding","t":"n. 造船（业），造船学","p":"'ʃip,bildiŋ","e":["a shipbuilding yard","造船厂"]},{"w":"shipment","t":"n. 装运，装船；装载的货物","p":"'ʃɪpmənt","e":["The goods are ready for shipment.","货物已经准备好装运。"]},{"w":"shipwreck","t":"n. 船舶失事","p":"'ʃɪprek","e":["narrowly escaping shipwreck","险些遭遇船只失事"]},{"w":"shortage","t":"n. 短缺，不足额","p":"'ʃɔːtɪdʒ","e":["There is no heating available due to fuel shortages.","因为燃料短缺，所以没有供暖。"]},{"w":"shortcut","t":"n. 近路；捷径","p":"'ʃɔːtkʌt","e":["Fame can be a shortcut to love and money.","名望可以是得到爱情和金钱的捷径。"]},{"w":"shorten","t":"v. 弄短，缩小，减少","p":"'ʃɔːt(ə)n","e":["The days are shortening.","白天变得越来越短了。"]},{"w":"shorthand","t":"n. 速记，速记法","p":"'ʃɔːthænd","e":["a secretary who takes shorthand (= writes in shorthand )","会速记的秘书"]},{"w":"shot","t":"n. 照相，照片","p":"ʃɒt","c":1,"e":["We hired a photographer to take some publicity shots .","我们雇了个摄影师来拍宣传照。"]},{"w":"should","t":"v. 应该；竟然会","p":"ʃəd; strong form ʃʊd","e":["Why should anyone want to marry Tony?","怎么竟然会有人意嫁给托尼？"]},{"w":"shoulder","t":"v. 承担；挑起","p":"'ʃəʊldə","e":["The residents are being asked to shoulder the costs of the repairs.","居民们被要求承担这笔修理费用。"]},{"w":"shove","t":"vi. 用力推，挤；vt. 乱推，挤；乱塞，随意放；n. 猛推","p":"ʃʌv","e":["Everyone was pushing and shoving to see the prince.","大家都推着挤着要看王子。"]},{"w":"shovel","t":"n. 铲，铁铲；v. 铲","p":"'ʃʌv(ə)l","e":["The workmen shovelled gravel onto the road.","工人们把碎石铲到路面上。"]},{"w":"shower","t":"v. 下阵雨，使湿透","p":"'ʃaʊə"},{"w":"shrank","t":"v. 收缩(shrink过去式)","p":"ʃræŋk","c":1,"e":["My sweater shrank in the wash.","我的毛衣缩水了。"]},{"w":"shrewd","t":"adj. 精明的","p":"ʃru:d","c":1,"e":["She was shrewd enough to guess who was responsible.","她很精明，一猜就知道是谁干的。"]},{"w":"shrill","t":"adj. 尖声的；v. 尖声地叫","p":"ʃrɪl","e":["‘That’s not true,’ she protested in a shrill voice.","“不是这样的。”她尖声抗议道。"]},{"w":"shrimp","t":"n. （小）虾，河虾，褐虾","p":"ʃrɪmp","e":["Add the shrimp and cook for 30 seconds.","放入小虾，煮 30 秒。"]},{"w":"shrine","t":"n. 神殿，神龛，圣祠","p":"ʃraɪn","e":["his pilgrimage to the shrine of St John","他去敬奉圣约翰的圣地朝圣"]},{"w":"shrink","t":"v. 缩减，缩小","p":"ʃrɪŋk","c":1,"e":["I’m worried about washing that shirt in case it shrinks.","我不太敢洗那件衬衫，怕它会缩水。"]},{"w":"shrub","t":"n. 灌木","p":"ʃrʌb","e":["...flowering shrubs.","…开花的灌木。"]},{"w":"shrug","t":"v. 耸肩","p":"ʃrʌɡ","c":1,"e":["I just shrugged my shoulders and ignored him.","我只是耸耸肩，没有理睬他。"]},{"w":"shutter","t":"n. 百叶窗；快门","p":"'ʃʌtə","e":["She opened the shutters and gazed out over village roofs.","她打开了百叶窗，朝村里的房顶望去。"]},{"w":"shuttle","t":"n. 航天飞机","p":"'ʃʌtl","c":1,"e":["The space shuttle had been scheduled to blast off at 04:38.","航天飞机已经预定于凌晨4点38分发射升空。"]},{"w":"sideways","t":"adv. 斜向一边地","p":"'saɪdweɪz","e":["A strong gust of wind blew the car sideways into the ditch.","一阵狂风把汽车横着掀进了沟里。"]},{"w":"siege","t":"n. 包围，围困","p":"siːdʒ","e":["a three-day police siege at a remote country cottage","警方对一座偏僻村舍历时三天的包围"]},{"w":"sieve","t":"n. 筛子，漏勺；vt. 筛，滤","p":"sɪv","e":["The next day the team began to sieve the loose, sandy silt around the spot—more hand bones and foot bones turned up.","第二天，考察队开始在现场周围用筛子过滤松散的沙质粉土，他们又陆续发现了更多的手骨和足骨。"]},{"w":"sift","t":"v. 筛，过滤","p":"sɪft","e":["Sift the flour and baking powder into a medium-sized mixing bowl.","把面粉和发酵粉筛到一个中号搅拌碗中。"]},{"w":"sight","t":"n. 景象；名胜，风景","p":"saɪt","e":["In the afternoon, you’ll have a chance to relax or see the sights.","大家下午可以休息，也可以去参观名胜。"]},{"w":"sightseeing","t":"n. 观光，游览","p":"'saɪtˌsiːɪŋ","e":["She swam and sunbathed, went sightseeing and relaxed.","她游泳，晒日光浴，观光，放松。"]},{"w":"sign","t":"n. 征兆，迹象，病症","p":"saɪn","e":["A paw print in the dust was a sign that a tiger was close.","沙土里的一个爪印表明附近有老虎。"]},{"w":"signal","t":"v. 标志","p":"'sɪɡnəl","c":1,"e":["the lengthening days that signal the end of winter","白昼变长标志着冬天的结束"]},{"w":"significant","t":"adj. 重要的","p":"sɪgˈnɪfɪkənt","c":1,"e":["His most significant political achievement was the abolition of the death penalty.","他政治上最重大的成就是废除了死刑。"]},{"w":"signify","t":"v. 表明，象征","p":"'sɪɡnɪfaɪ","c":1,"e":["Some tribes use special facial markings to signify status.","有些部落使用特殊的面部标记来表示地位。"]},{"w":"silicon","t":"n. 硅","p":"'sɪlɪkən","e":["They consist of silicon, sand and metal so there's no any connection to dinosaurs … Besides, we may see corrosion on some of them.","它们是由硅砂和金属构成的，和恐龙蛋没有任何关系……除此之外，我们还能看到它们上面的腐蚀的部分。"]},{"w":"similar","t":"adj. 相似的，类似的","p":"'sɪmələ","e":["A number of his friends had been affected in a similar way .","他的一些朋友也受到了类似的影响。"]},{"w":"similarity","t":"n. 类似，相似；类似点","p":"sɪmə'lærətɪ","e":["a study of the similarities and differences between the two countries","对这两个国家的异同点的研究"]},{"w":"simple","t":"adj. 单纯的；迟钝的","p":"'sɪmp(ə)l","e":["Completing the race is not just a simple matter of physical fitness.","跑完比赛不仅仅是纯粹的体力问题。"]},{"w":"simplicity","t":"n. 单纯，质朴","e":["For the sake of simplicity, the tax form is divided into three sections.","为简明起见，税单分成三个部分。"]},{"w":"simulate","t":"v. 模拟，模仿","p":"'sɪmjʊleɪt","c":1,"e":["Interviews can be simulated in the classroom.","可以在教室里模拟面试。"]},{"w":"simultaneous","t":"adj. 同步的","p":"ˌsɪmlˈteɪniəs","c":1,"e":["Up to twenty users can have simultaneous access to the system.","最多可有20名用户同时登该系统。"]},{"w":"simultaneously","t":"adv. 同步地，同时地","p":"ˌsɪməl'teɪnɪəslɪ","c":1,"e":["The game will be broadcast simultaneously on TV and radio.","比赛将同时在电视和广播中进行转播。"]},{"w":"sincerity","t":"n. 真诚，诚意；真实","p":"sɪn'serətɪ","e":["May I say in all sincerity that we could not have achieved this much without your help and support.","请允许我真心诚意地说: 没有你们的帮助和支持，我们就不可能取得这样的成绩。"]},{"w":"singular","t":"adj. 异常的，奇异的","p":"'sɪŋgjʊlə","e":["I wondered why she was behaving in so singular a fashion.","我真奇怪她为什么会有如此异常的行为。"]},{"w":"sink","t":"n. （厨房内的）洗涤槽","p":"sɪŋk","e":["Dirty plates were piled high in the sink.","脏盘子在洗涤槽里堆得很高。"]},{"w":"sip","t":"v. 小口地喝，抿，呷；n. 小口喝，一小口的量","p":"sɪp","e":["She was sitting at the table sipping her coffee.","她坐在桌边呷着咖啡。"]},{"w":"siren","t":"n. 汽笛，警报器","e":["I heard police sirens in the distance.","我听到了远处的警笛声。"]},{"w":"situated","t":"adj. 位于…的，坐落在…的；处于…境地的","p":"'sɪtʃueɪtɪd","e":["His hotel is situated in one of the loveliest places on the Loire.","他的旅馆坐落在卢瓦尔的一个最优美的地方。"]},{"w":"situation","t":"n. （建筑物等的）位置","p":"sɪtjʊ'eɪʃ(ə)n","e":["The house is in a charming situation, on a wooded hillside.","房子位于林木茂密的小山坡上，环境十分优美。"]},{"w":"skeleton","t":"n. 骨骼；框架，骨干；梗概，提要","p":"'skelɪtn","e":["We agreed on a skeleton outline of the proposal.","我们给提案商定了一个基本框架。"]},{"w":"skeptical","t":"adj. 怀疑的","p":"'skeptɪkəl","c":1,"e":["Environmental groups are skeptical of the government’s claims.","环境保护组织对政府的声明持怀疑态度。"]},{"w":"skip","t":"v. 跳过","p":"skɪp","c":1,"e":["I decided to skip the first chapter.","我决定跳过第一章。"]},{"w":"skull","t":"n. 颅骨，脑壳","p":"skʌl","e":["Her husband was later treated for a fractured skull.","她丈夫后来因颅骨碎裂而接受治疗。"]},{"w":"skyrocket","t":"v. 猛增","p":"'skaɪrɒkɪt","c":1,"e":["The trade deficit has skyrocketed.","贸易逆差已经急剧增长。"]},{"w":"skyscraper","t":"n. 摩天大楼","p":"'skaɪskreɪpə(r)","c":1,"e":["The majesty of the skyscraper awed me .","这幢摩天大厦的雄伟气势令我惊叹。"]},{"w":"slack","t":"adj. 疲软的，萧条的","p":"slæk","c":1,"e":["Business remained slack throughout the day.","一整天生意都很冷清。"]},{"w":"slander","t":"n. 诽谤，诋毁；v. 诽谤，诋毁","p":"'slɑːndə","e":["He angrily accused the investigators of slandering both him and his family.","他气愤地指责调查者诋毁他和他的家人。"]},{"w":"slang","t":"n. 俚语；行话，黑话","p":"slæŋ","e":["schoolboy slang","学生俚语"]},{"w":"slap","t":"vt. 掴，掌击，拍；啪的一声放；n. 掴，掌击，拍","p":"slæp","e":["Sarah slapped Aaron across the face.","萨拉在阿龙的脸上掴了一巴掌。"]},{"w":"slash","t":"v. 猛削，劈，砍；削减","p":"slæʃ","c":1,"e":["The workforce has been slashed by 50%.","劳动力已削减了 50%。"]},{"w":"slaughter","t":"n&vt. 屠杀，杀戮；屠宰","p":"'slɔːtə","e":["Hundreds of innocent civilians had been slaughtered by government troops.","数百名无辜平民遭政府军屠杀。"]},{"w":"slave","t":"v. 作苦工；奴役","p":"sleɪv","e":["When you're busy all day the last thing you want to do is spend hours slaving over a hot stove.","当你忙碌了一整天后，你最不愿意做的事就是花好几个钟头在灼热的火炉边辛苦地劳作。"]},{"w":"slavery","t":"n. 奴隶制度","p":"ˈsleɪvəri","c":1,"e":["attempts to abolish slavery","废除奴隶制的努力"]},{"w":"slice","t":"n. 薄片，切片，部分；vt. 切，削，剁","p":"slaɪs","e":["Cut the tomatoes into slices .","把番茄切成片。"]},{"w":"slick","t":"adj. 圆滑的，口齿伶俐的；精巧的，巧妙的，灵巧的；光滑的，滑溜的","p":"slɪk","e":["He got round the defender using some slick footwork.","他用灵巧的步法突破了后卫的防守。"]},{"w":"slide","t":"v. 滑；悄悄地移动；n. 滑动；滑道，滑面；幻灯片","p":"slaɪd","e":["He slid open the door of the glass cabinet.","他滑开玻璃柜的门。"]},{"w":"slight","t":"adj. 轻微的","p":"slaɪt","c":1,"e":["a slight change of plan","计划的略微变动"]},{"w":"slightly","t":"adv. 轻微地","p":"'slaɪtlɪ","c":1,"e":["His family then moved to a slightly larger house.","他的家后来搬到了一间稍微大一点儿的房子。"]},{"w":"slim","t":"adj. 苗条的","p":"slɪm","c":1,"e":["a slim young woman","身材苗条的年轻女子"]},{"w":"slip","t":"v. 滑跤，滑落，溜；下降，跌落；悄悄放进；n. 疏漏，差错","p":"slɪp","e":["One man managed to slip from the club as police arrived.","警察到来时，一个男子设法溜出了俱乐部。"]},{"w":"slippery","t":"adj. 滑的；狡猾的","p":"'slɪpəri","e":["In places, the path can be wet and slippery.","路上有些地方可能又湿又滑。"]},{"w":"slit","t":"v. 切开；n. 狭长的切口","p":"slɪt","e":["light shining through a slit in the door","透过门缝照进来的光线"]},{"w":"slogan","t":"n. 标语，口号；广告语","p":"'sləugən","e":["demonstrators shouting political slogans","高喊政治口号的示威者"]},{"w":"slope","t":"v. 倾斜；n. 倾斜，斜面","p":"sləup","e":["The bank sloped down sharply to the river.","那座堤岸陡峭地朝着那条河倾斜下去。"]},{"w":"slot","t":"n. 狭缝，狭槽；位置，空位；vt. 把…放入狭长开口中；把…纳入其中，使有位置","p":"slɒt","e":["Alan dropped another quarter into the slot on the pay phone.","艾伦往付费电话的投币口里又塞了一枚 25 分的硬币。"]},{"w":"slum","t":"n. 贫民窟","p":"slʌm","e":["the slums of London","伦敦的贫民区"]},{"w":"slumber","t":"n. 睡眠；沉睡状态","p":"'slʌmbə","e":["He passed into a deep slumber.","他酣然入梦。"]},{"w":"slump","t":"vi. 大幅度下降，暴跌；突然倒下；n. 萧条期，低潮","p":"slʌmp","e":["Sales slumped by 20% last year.","去年销售额骤减 20%。"]},{"w":"smart","t":"v. 刺疼，扎疼，剧痛","p":"smɑːt","e":["My eyes were smarting with the smoke.","我的眼睛被烟熏得发痛。"]},{"w":"smash","t":"vi. 猛撞，猛冲；vt. 使粉碎，使打烂；狠打，猛击；使破灭，使失败；n. 破碎；猛击，猛撞；轰动的演出，巨大的成功","p":"smæʃ","e":["He smashed his fist down on the table.","他把拳头狠狠地砸在桌上。"]},{"w":"smuggle","t":"v. 走私","p":"'smʌɡl","c":1,"e":["My message is \"If you try to smuggle drugs you are stupid.\"","我的讯息是，“你若企图走私毒品，那是犯傻。”"]},{"w":"snack","t":"n. 快餐，小吃，点心","p":"snæk","e":["Drinks and light snacks are served at the bar.","酒吧里供应饮料和小吃。"]},{"w":"snail","t":"n. 蜗牛；行动缓慢的人","p":"sneɪl","e":["Traffic was moving at a snail’s pace.","车辆移动的速度慢得像蜗牛。"]},{"w":"snap","t":"v. 猛咬；突然折断","p":"snæp","e":["The dog started snapping at my heels.","这条狗开始咬我的鞋跟。"]},{"w":"snatch","t":"vi. 一把抓住；vt. 夺，夺走，抢走；一下子拉，一把抓住；抓住机会做，抽空做；n. 片断","p":"snætʃ","e":["I snatched a glance at the mirror.","我乘机瞥了一眼镜子。"]},{"w":"sneak","t":"v. 溜走","p":"sni:k","c":1,"e":["Sometimes he would sneak out of his house late at night to be with me.","有时候他会在深夜偷偷溜出他的家来陪伴我。"]},{"w":"sneer","t":"v. 冷笑；嘲笑；n. 冷笑；嘲笑","p":"snɪə","e":["‘You probably wouldn’t understand,’ he said with a sneer.","“你可能明白不了。”他冷笑了一声说道。"]},{"w":"sneeze","t":"v. 打喷嚏","p":"sniːz","e":["She started coughing and sneezing.","她开始咳嗽、打喷嚏。"]},{"w":"sniff","t":"v. 以鼻吸气，用力吸入；嗅，闻；n. 吸气；嗅，闻","p":"snɪf","e":["Margaret sniffed miserably and nodded.","玛格丽特可怜地抽泣着点了点头。"]},{"w":"snob","t":"n. 势利小人","p":"snɒb","e":["I don’t want to sound like a snob, but I thought she was vulgar.","我不想像个势利小人，但我觉得她就是庸俗。"]},{"w":"snobbish","t":"adj. 势利的，谄上欺下的","p":"'snɒbɪʃ","e":["Her family seems snobbish.","她家里人好像挺势利的。"]},{"w":"snore","t":"v. 打鼾，打呼噜","p":"snɔː","e":["He could hear the old man snoring.","他听到老人在打鼾。"]},{"w":"soar","t":"v. 高飞","p":"sɔ:(r)","c":1,"e":["She watched the dove soar above the chestnut trees.","她看着鸽子在栗子树的上空展翅飞翔。"]},{"w":"sober","t":"adj. 未醉的，有节制的；严肃的，持重的；素淡的，暗淡的；v. 醒酒，清醒","p":"'səubə","e":["He’s a nice guy when he’s sober.","他没喝醉时是个不错的家伙。"]},{"w":"sociology","t":"n. 社会学","p":"ˌsəusi'ɒlədʒi","e":["The mistress hunters are mostly women and are all psychology, sociology or law graduates.","“情妇猎手”大多为女性，且都是心理学、社会学或法学的毕业生。"]},{"w":"sodium","t":"n. 钠","p":"'səʊdɪəm","e":["...one level teaspoon of sodium bicarbonate powder.","一平茶匙碳酸氢钠粉末"]},{"w":"sofa","t":"n. 长沙发，沙发","p":"'səʊfə"},{"w":"soften","t":"v. 使软化，变温和","p":"'sɒf(ə)n","e":["The government has softened its stance on public spending.","政府对公共开支问题的态度软化了。"]},{"w":"softness","t":"n. 温和，柔和；软弱","p":"'sɔftnis","e":["deceitful softness","虚伪的温柔"]},{"w":"software","t":"n. （计算机的）软件","p":"'sɒf(t)weə","e":["She loaded the new software .","她给电脑装上新的软件。"]},{"w":"solar","t":"adj. 利用太阳光的","p":"'səʊlə","e":["solar energy","太阳能"]},{"w":"solemn","t":"adj. 庄严的，隆重的；严肃的","p":"'sɒləm","e":["Their faces suddenly grew solemn.","他们的脸突然变得严肃起来。"]},{"w":"solicitor","t":"n. 初级律师，事务律师","p":"sə'lɪsɪtə","e":["You need to see a solicitor.","你需要找个律师。"]},{"w":"solid","t":"adj. 坚实的；稳固的","p":"'sɒlɪd","c":1,"e":["This provided a solid foundation for their marriage.","这为他们的婚姻提供了坚实的基础。"]},{"w":"solidarity","t":"n. 团结一致","p":"ˌsɒlɪ'dærəti","e":["an appeal for worker solidarity","呼吁工人们团结"]},{"w":"solidify","t":"v. 凝固","p":"sə'lɪdɪfaɪ","e":["The volcanic lava solidifies as it cools.","火山熔岩冷却后变成固体。"]},{"w":"solitary","t":"adj. 单独的，独自的；单个的，唯一的；孤独的，隐居的","p":"'sɒlətri","e":["The benches were empty except for a single solitary figure.","除了一个孤零零的身影，这些长凳上没有其他人了。"]},{"w":"solo","t":"adv. 以独力，单独地；adj. 单独的，单独进行的；n. 独奏，独唱，独舞","p":"'səuləu","e":["Brokaw solos brilliantly on this album.","布罗考在这张专辑中的独唱非常出色。"]},{"w":"soluble","t":"adj. 可溶的；可解决的","p":"'sɒljəbl","e":["soluble aspirin","可溶性阿司匹林"]},{"w":"solution","t":"n. 解决，解决方法；溶液","p":"səˈlu:ʃn","c":1,"e":["The best solution would be for them to separate.","最好的解决方法是他们分开。"]},{"w":"soothe","t":"v. 安慰，减轻","p":"su:ð","c":1,"e":["Lucy soothed the baby by rocking it in her arms.","露西把宝宝抱在怀里摇晃着，让他安静下来。"]},{"w":"sophisticated","t":"adj. 复杂的，精密的；老于世故的","p":"səˈfɪstɪkeɪtɪd","c":1,"e":["British voters have become much more sophisticated.","英国的选民已经变得成熟多了。"]},{"w":"sorrowful","t":"adj. 使人伤心的；悲伤的","p":"'sɒrə(ʊ)fʊl; -f(ə)l","e":["a sorrowful expression","悲伤的表情"]},{"w":"sour","t":"adj. 酸的；馊的，酸味的；脾气坏的；v. 变酸，变馊；变得乖戾","p":"'sauə","e":["Rachel sampled the wine. It was sour.","雷切尔尝了尝葡萄酒，是酸的。"]},{"w":"southwards","t":"adv. 向南方","p":"'saʊθwədz","e":["We followed the coast southwards.","我们沿海岸向南走。"]},{"w":"souvenir","t":"n. 纪念品","p":",suːvə'nɪə","e":["a souvenir shop","纪念品商店"]},{"w":"sovereign","t":"adj. 拥有最高统治权的，至高无上的；具有独立主权的；n. 君主，元首","p":"'sɒvrɪn","e":["Lithuania and Armenia signed a treaty in Vilnius recognizing each other as independent sovereign states.","立陶宛和亚美尼亚在维尔纽斯签订了一份互相承认各自为独立主权国家的协定。"]},{"w":"soy","t":"n. 大豆，黄豆；酱油","p":"sɒɪ","e":["\"I just added a little soy sauce,\" he informs us.","“我就加了一点儿酱油，”他告诉我们。"]},{"w":"spacious","t":"adj. 宽敞的","p":"ˈspeɪʃəs","c":1,"e":["a spacious living area","宽敞的居住空间"]},{"w":"span","t":"n. 跨距，一段时间；vt. 持续，贯穿，包括；横跨，跨越","p":"spæn","e":["It’ll be difficult to hire that many new staff in such a short time span .","在这么短的时间里要想招聘到那么多新员工是很难的。"]},{"w":"spark","t":"n. 火花","p":"spɑrk","c":1,"e":["The scrape of metal on metal sent up a shower of sparks .","金属之间互相摩擦，迸出一串火星。"]},{"w":"sparkle","t":"vi. 发光，闪耀，闪烁；活跃，焕发；n. 闪光，闪耀，闪烁；活力，生气","p":"'spɑːkl","e":["The crystal chandelier sparkled.","那水晶枝形吊灯闪闪发光。"]},{"w":"spatial","t":"adj. 空间的，占据空间的","p":"'speɪʃ(ə)l","e":["...the spatial distribution of black employment and population in South Africa.","…南非黑人就业和人口的空间分布。"]},{"w":"specialist","t":"n. 专家","p":"'speʃəlɪst","c":1,"e":["an attorney who is a specialist in banking law","一名专攻银行法的律师"]},{"w":"specialize","t":"v. 专业从事","p":"ˈspeʃəlaɪz","c":1,"e":["Simmons specialized in contract law.","西蒙斯专攻合同法。"]},{"w":"specialty","t":"n. 特产，名产，特色菜；专业，专长","p":"ˌspeʃəltɪ","e":["Our specialty is clam chowder.","我们的特色菜是蛤肉汤。"]},{"w":"species","t":"n. 物种","p":"'spi:ʃi:z","c":1,"e":["Seven species of birds of prey have been observed.","已有七种猛禽被观察到。"]},{"w":"specific","t":"adj. 具体的","p":"spəˈsɪfɪk","c":1,"e":["a specific example of alcohol’s effect on the body","酒精对身体影响的具体例子"]},{"w":"specification","t":"n. 说明","p":"ˌspesɪfɪˈkeɪʃn","c":1,"e":["The bolts met all the engineering specifications.","这些螺栓符合所有的工程设计规格。"]},{"w":"specimen","t":"n. 抽样，样品","p":"'spesɪmɪn","e":["a blood specimen","血样"]},{"w":"spectacle","t":"n. 景象","p":"ˈspektəkl","c":1,"e":["a multimedia dance and opera spectacle","盛大的多媒体舞蹈戏剧表演"]},{"w":"spectator","t":"n. 观众，旁观者","p":"spek'teɪtə","e":["The match attracted over 40,000 spectators.","这场比赛吸引了四万多名观众。"]},{"w":"spectrum","t":"n. 谱，光谱，频谱；范围，幅度，系列","p":"'spektrəm","e":["The two articles here represent opposite ends of the spectrum .","这里的两篇文章代表了两个极端的观点。"]},{"w":"speculate","t":"v. 推测，推断；投机，做投机买卖","p":"'spekjuleɪt","e":["She refused to speculate.","她拒绝猜测。"]},{"w":"spherical","t":"adj. 球形的，球面的","p":"'sferɪk(ə)l","e":["...purple and gold spherical earrings.","...紫色和金色的球形耳环。"]},{"w":"spice","t":"n. 香料，调味品；趣味，情趣，风味；vt. 使增添趣味；加香料于","p":"spaɪs","e":["herbs and spices","香草和香料"]},{"w":"spill","t":"n. （人）摔下，跌下","p":"spɪl","e":["Tyson broke a rib when he took a spill on his motorcycle.","泰森从摩托车上摔下来，断了一根肋骨。"]},{"w":"spine","t":"n. 脊柱，脊椎；刺，刺毛；书脊","p":"spaɪn","e":["cactus spines","仙人掌的刺"]},{"w":"spiral","t":"vi. 盘旋上升；不断急剧地上升；adj. 螺旋的；n. 螺旋，螺旋式的上升","p":"'spaɪrəl","e":["Crime has spiraled out of control .","犯罪活动激增，已经失控。"]},{"w":"spite","t":"n. 恶意，怨恨；不顾；vt. 刁难，欺侮","p":"spaɪt","e":["Kelly loved her husband in spite of the fact that he drank too much.","虽然丈夫酗酒，凯莉仍然爱着他。"]},{"w":"splash","t":"v. 溅，泼；n. 溅泼声；溅出的水；斑点","p":"splæʃ","e":["The children were splashing about in the pool.","孩子们在水池里戏水。"]},{"w":"split","t":"n. 分裂，分化，派系","p":"splɪt","e":["The argument could lead to a damaging split in the party.","这场争吵可能会导致党内出现分裂，对该党产生不利影响。"]},{"w":"spoil","t":"v. 溺爱","p":"spɔɪl","c":1,"e":["His mother and sisters spoil him rotten (= spoil him very much ) .","他母亲和姐姐把他给宠坏了。"]},{"w":"spokesman","t":"n. 发言人，代言人","p":"'spəʊksmən","e":["a White House spokesman","白宫发言人"]},{"w":"sponge","t":"v. 用湿海绵擦，揩；过寄生生活；n. 海绵","p":"spʌndʒ","e":["She stood on the bath mat and sponged herself down.","她站在浴室踏脚垫上，用海绵擦身子。"]},{"w":"sponsor","t":"v. 赞助；n. 赞助商","p":"'spɒnsə(r)","c":1,"e":["The competition was sponsored by British Airways.","此项比赛由英国航空公司赞助。"]},{"w":"spontaneous","t":"adj. 自发的，无意识的；自然的，天真率直的","p":"spɒn'teɪniəs","e":["My spontaneous reaction was to run away.","我的本能反应就是逃跑。"]},{"w":"spot","t":"n. 点；地点，处所；v. 发现","p":"spɒt","c":1,"e":["I chose a spot well away from the road.","我选了一个远离马路的地点。"]},{"w":"spouse","t":"n. 配偶","p":"spaus","e":["Spouses were invited to the company picnic.","配偶受到邀请参加公司的野餐会。"]},{"w":"spread","t":"v. 传播，扩散","p":"spred","c":1,"e":["The industrial revolution, which started a couple of hundred years ago in Europe, is now spreading across the world.","几百年前始于欧洲的工业革命现在正向全世界扩散。"]},{"w":"sprinkle","t":"v. 撒，洒；n. 少量，少数","p":"'sprɪŋkl","e":["Sprinkle the meat with salt and place in the pan.","给肉撒点盐，然后放进平锅里。"]},{"w":"spy","t":"vi. 当间谍；暗中监视；n. 间谍；vt. 看见，发现","p":"spaɪ","e":["That day he spied on her while pretending to work on the shrubs.","那天他假装修剪灌木，却秘密地监视着她。"]},{"w":"squad","t":"n. 班，小队，小组","p":"skwɒd","e":["a drill squad","操练小队"]},{"w":"squalor","t":"n. 肮脏","p":"ˈskwɒlə(r)","c":1,"e":["We lived in squalor for a year and a half.","我们在肮脏的环境里住了一年半。"]},{"w":"squash","t":"v. 压碎；n. 果汁饮料","p":"skwɒʃ","e":["The cake got a bit squashed on the way here.","蛋糕在送来这里的路上有点压坏了。"]},{"w":"squat","t":"v. （使）蹲下","p":"skwɒt","e":["He squatted down beside the little girl.","他在小女孩身边蹲了下来。"]},{"w":"squeeze","t":"v. 压榨，挤；n. 榨取，勒索","p":"skwiːz","e":["He squeezed the trigger, but nothing happened.","他扣动扳机，但没有反应。"]},{"w":"stab","t":"n&v. 刺，戳","p":"stæb","e":["He was stabbed to death in a fight.","他在一次打斗中被捅死了。"]},{"w":"stability","t":"n. 稳定，稳固","p":"stə'bɪləti","e":["a period of relative stability","相对稳定的一段时期"]},{"w":"stabilize","t":"v. 使稳固，使安定","p":"ˈsteɪbəlaɪz","c":1,"e":["The patient’s condition has now stabilized.","病人的情况现已稳定下来了。"]},{"w":"stable","t":"adj. 稳定的，不变的；沉稳的，持重的；n. 厩，马厩，牛棚","p":"'steɪbl","e":["A wide base will make the structure much more stable.","宽大的底座会使结构牢固许多。"]},{"w":"stack","t":"n. 堆，垛；vt. 堆积，堆放于","p":"stæk","e":["Mrs. Cathiard was stacking the clean bottles in crates.","卡提亚夫人当时正在把干净的瓶子堆放到板条箱里。"]},{"w":"stagger","t":"vi. 摇晃，蹒跚；vt. 使吃惊；使错开，使交错；n. 蹒跚，踉跄","p":"'stægə","e":["The old man staggered drunkenly to his feet.","老汉醉醺醺地踉跄着站了起来。"]},{"w":"stain","t":"n. 污渍，污点","p":"steɪn","c":1,"e":["Remove stains by soaking in a mild solution of bleach.","用温和的漂白溶液浸泡以去除污渍。"]},{"w":"stainless","t":"adj. 不锈的；纯洁的","p":"'steɪnlɪs","e":["stainless steel","不锈钢"]},{"w":"staircase","t":"n. 楼梯","p":"'steəkeɪs","e":["They walked down the staircase together.","他们一起沿楼梯通道往下走。"]},{"w":"stairway","t":"n. 楼梯","p":"'steəweɪ","e":["...the stairway leading to the top floor.","…通往顶层的楼梯。"]},{"w":"stalk","t":"vi. 高视阔步地走；n. 茎，梗，柄；vt. 悄悄地跟踪","p":"stɔːk","e":["celery stalks","芹菜茎"]},{"w":"stall","t":"v. 熄火；拖延，推迟；n. 货摊；","p":"stɔːl","e":["Quit stalling and answer my question!","别拖延时间，快回答我的问题！"]},{"w":"stammer","t":"v. 口吃地说；n. 口吃","p":"'stæmə","e":["Whenever he was angry, he would begin to stammer slightly.","他一生气说话就开始有点结巴。"]},{"w":"standardize","t":"v. 标准化","p":"'stændədaɪz","c":1,"e":["Attempts to standardize English spelling have never been successful.","统一英语拼写的尝试从未成功过。"]},{"w":"standpoint","t":"n. 立场，观点","p":"'stændpɔɪnt","e":["a discussion of marriage from the standpoint of women","从女性角度对婚姻的探讨"]},{"w":"staple","t":"adj. 主要的；经常需要的；n. 订书钉，U形钉；主食；主要产品；vt. 用订书钉订","p":"'steɪpl","e":["Oil is Nigeria’s staple export.","石油是尼日利亚的主要出口产品。"]},{"w":"start","t":"v. 开动，着手；开设","p":"stɑːt","e":["There’s so much to do. I don’t know where to start.","有那么多的事情要做，我都不知道从哪里开始。"]},{"w":"startle","t":"v. 使惊讶","p":"'stɑ:tl","c":1,"e":["Sorry, I didn’t mean to startle you.","抱歉，我不是故意吓你一跳的。"]},{"w":"statement","t":"n. 陈述，声明；结算单，报表","p":"'steɪtmənt","e":["In an official statement, she formally announced her resignation.","在一份官方声明中，她正式宣布辞职。"]},{"w":"statesman","t":"n. 国务活动家，政治家","p":"'steɪtsmən","e":["a respected elder statesman","一位受人尊敬的政界元老"]},{"w":"stationary","t":"adj. 固定的，静止不动的","p":"'steɪʃənri","e":["How did you manage to drive into a stationary vehicle?","你是怎么开车的，竟会撞上一辆停着的车子？"]},{"w":"stationery","t":"n. 信笺，信纸；文具","p":"'steɪʃ(ə)n(ə)rɪ","e":["envelopes and other office stationery","信封及其他办公文具"]},{"w":"statistics","t":"n. 统计学；统计表","p":"stə'tɪstɪks"},{"w":"status","t":"n. 地位，身份；情形，状况","p":"'steɪtəs","e":["What is your marital status (= are you married or not ) ?","你的婚姻状况是什么？"]},{"w":"steady","t":"adj. 稳定的","p":"'stedɪ","c":1,"e":["Paul is making steady progress.","保罗逐渐在进步。"]},{"w":"steak","t":"n. 大块牛肉；牛排","p":"steɪk","e":["...a steak sizzling on the grill.","…一块儿在烤架上滋滋作响的牛排。"]},{"w":"steal","t":"v. 偷偷地做，窃取","p":"stiːl","e":["Boys broke into a shop and stole £45 in cash.","男孩们闯进一家商店，盗走了45英镑现金。"]},{"w":"stem","t":"n. 词干","p":"stem","e":["‘Writ ’ is the stem of the forms ‘writes ’, ‘writing ’ and ‘written ’.","writ是writes、writing和written三个词的词干。"]},{"w":"stereo","t":"adj. 立体的；立体声的；n. 立体声","p":"'steriəu","e":["stereo equipment","立体声音响设备"]},{"w":"stereotype","t":"n. 刻板印象，固有印象","p":"'sterɪətaɪp","c":1,"e":["There's always been a stereotype about successful businessmen.","对成功的商人们总有一种成见。"]},{"w":"stern","t":"adj. 严厉的，严格的，严峻的；n. 船尾","p":"stɜːn","e":["sterner penalties for drug offences","对毒品犯罪的更为严厉的惩罚"]},{"w":"stew","t":"v. 炖；n. 炖菜","p":"stjuː","e":["Stew the apple and blackberries to make a thick pulp.","把苹果和黑莓炖成浓稠的果浆。"]},{"w":"sticky","t":"adj. 黏性的，胶粘的；湿热的","p":"'stɪki","e":["There’s some sticky stuff in your hair.","你的头发上有什么黏糊糊的东西。"]},{"w":"stiff","t":"adj. 生硬的","p":"stɪf","e":["Parsons gave a stiff performance in the main role.","帕森斯把主要角色演得很生硬。"]},{"w":"stiffness","t":"n. 硬度","p":"'stɪfnɪs","e":["If you eat soon after your workout, you can minimize muscle stiffness and soreness.","如果在训练不久之后进食，就可以减缓肌肉僵硬和疼痛。"]},{"w":"stillness","t":"n. 寂静，无声","p":"'stɪlnɪs","e":["The sound of footsteps on the path broke the stillness.","小路上的脚步声打破了宁静。"]},{"w":"stimulate","t":"v. 刺激；激励","p":"'stɪmjʊleɪt","c":1,"e":["the President’s plan to stimulate economic growth","总统刺激经济增长的计划"]},{"w":"stimulus","t":"n. 刺激","p":"'stɪmjʊləs","c":1,"e":["Tax cuts provided the stimulus which the slow economy needed.","减税为不景气的经济带来了其所需的刺激。"]},{"w":"sting","t":"n. 剧痛；刺痛；v. 刺","p":"stɪŋ","e":["She felt the sting of tears in her eyes.","她感觉泪水刺痛了眼睛。"]},{"w":"stitch","t":"v. 缝，绣；n. 一针，线迹；缝法，针法，编结法；突然剧痛","p":"stɪtʃ","e":["Mary is stitching a bedspread.","玛丽在缝床罩。"]},{"w":"stock","t":"v. 储备；adj. 常用的，常备的；n. 原料，库存品；股本，公债；世系，血统；汤汁；家畜，牲畜","p":"stɒk","e":["We stock a wide range of kitchen equipment.","我们备有各种厨房用品。"]},{"w":"stockbroker","t":"n. 股票经理人","p":"'stɒkbrəʊkə(r)","c":1,"e":["Over the next five months, every one of them discouraged me from becoming a stockbroker.","接下来的五个月中，他们每个人都劝阻我不要做股票经纪人。"]},{"w":"stone","t":"n. 果核，（水果的）硬核","p":"stəʊn","e":["...cherry stones.","…樱桃核。"]},{"w":"storage","t":"n. 贮藏；保管","p":"'stɔːrɪdʒ","e":["the storage of highly radioactive material","高放射性材料的存放"]},{"w":"storm","t":"n. 爆发；v. 猛攻","p":"stɔːm","e":["The governor found himself at the center of a political storm .","州长发现自己处于一场政治风暴的中心。"]},{"w":"stout","t":"adj. 肥胖的；厚实牢固的","p":"staʊt","e":["a stout pair of shoes","一双厚实耐穿的鞋子"]},{"w":"stove","t":"n. 炉子","p":"stəuv","c":1,"e":["a wood-burning stove","烧木柴的火炉"]},{"w":"straighten","t":"v. 把…弄直；挺起来","p":"'streɪt(ə)n","e":["The three men straightened and stood waiting.","那3个人挺直了腰站着等。"]},{"w":"straightforward","t":"adj. 直接的","p":"ˌstreɪtˈfɔ:wəd","c":1,"e":["She is very blunt, very straightforward, and very honest.","她直言不讳，非常坦率，也非常诚实。"]},{"w":"strain","t":"n. 压力","p":"streɪn","c":1,"e":["I couldn’t look after him any more; the strain was too much for me.","我不能再照看他了，压力太大。"]},{"w":"strait","t":"n. 海峡","p":"streɪt","e":["the Bering Strait","白令海峡"]},{"w":"strand","t":"n. 股，缕；一个组成部分；vt. 使搁浅","p":"strænd","e":["She tried to blow a grey strand of hair from her eyes.","她试图吹开眼前的一缕白发。"]},{"w":"strange","t":"adj. 陌生的，不熟悉的","p":"streɪn(d)ʒ","e":["As a child, she’d been taught never to speak to strange men.","她从小就受到教育绝对不要和陌生男人说话。"]},{"w":"strap","t":"v. 用带绑住","p":"stræp","c":1,"e":["soldiers with grenades strapped to their belts","腰带上绑着手榴弹的士兵"]},{"w":"strategy","t":"n. 策略","p":"'strætədʒɪ","c":1,"e":["the government’s long-term economic strategy","政府的长期经济策略"]},{"w":"stray","t":"n. 走失[流浪]的动物","p":"streɪ","c":1,"e":["The dog was a stray which had been adopted.","这只狗是被收养的流浪狗。"]},{"w":"streak","t":"vi. 飞跑，疾驶；n. 条纹，条痕；个性特征；一阵子，一连串；vt. 在…上加条纹","p":"striːk","e":["Rain had begun to streak the windowpanes.","雨已开始在窗玻璃上留下条痕。"]},{"w":"stream","t":"v. 流出，涌出；n. 河，溪流；一股，一串","p":"striːm","e":["Tears streamed down their faces.","泪水顺着他们的脸颊流下来。"]},{"w":"streamline","t":"vt. 使成流线型；精简，使效率更高","p":"'striːmlaɪn","e":["efforts to streamline the production process","简化生产过程的努力"]},{"w":"strength","t":"n. 兵力；强度","p":"streŋθ; streŋkθ","e":["The police force is below strength at the moment (= there are fewer police than there should be ).","目前警力不足。"]},{"w":"stress","t":"v. 强调","p":"stres","c":1,"e":["Crawford stressed the need for more housing downtown.","克劳福德强调市中心需要建更多的住宅。"]},{"w":"stride","t":"vi. 大踏步走；n. 大步；步法，步态；进展，进步","p":"straɪd","e":["They were joined by a newcomer who came striding across a field.","他们中又来了个新人，那人穿过一块田地大步走过来。"]},{"w":"strife","t":"n. 冲突，竞争","p":"straɪf","e":["a time of political strife","政治纷争四起的时代"]},{"w":"strike","t":"n. 罢工","p":"straɪk","c":1,"e":["The government has promised that the army will be called in to help if there is a firemen’s strike.","政府承诺，如消防员罢工，就将调军队来协助。"]},{"w":"striking","t":"adj. 显著的，惊人的","p":"'straɪkɪŋ","e":["The most striking feature of those statistics is the high proportion of suicides.","那些统计数据最显著的特征是高自杀率。"]},{"w":"string","t":"n. 线，细绳；一串，一行","p":"strɪŋ","e":["I need a piece of string to tie this package.","我需要一根绳子来捆这个包裹。"]},{"w":"strip","t":"n. 狭长的一块","p":"strɪp","c":1,"e":["a strip of sand between the cliffs and the sea","悬崖和大海之间的一块狭长沙地"]},{"w":"strive","t":"vi. 努力，奋斗，力求","p":"straɪv","e":["He strives hard to keep himself very fit.","他努力使自己保持非常的健康。"]},{"w":"stroke","t":"n. 中风；一举，一次努力；划桨，划水；击，敲；报时的钟声；笔画，一笔；抚摸；vt. 抚摸","p":"strəuk","e":["She died following a massive stroke.","她重度中风后去世了。"]},{"w":"stroll","t":"n&vi. 散步，闲逛","p":"strəul","e":["I used to stroll along the beach on Sundays.","我过去常在星期天沿海滩散步。"]},{"w":"stubborn","t":"adj. 顽固的，执拗的，倔强的；难对付的，难于克服的","p":"'stʌbən","e":["I’ve got a very stubborn streak (= a tendency to be stubborn ) .","我的个性很固执。"]},{"w":"studio","t":"n. 播音室；工作室","p":"'stjuːdɪəʊ","e":["a recording studio in Nashville","在纳什维尔的一间录音室"]},{"w":"stuff","t":"n. 材料，东西","p":"stʌf","c":1,"e":["How do you think you’re going to fit all that stuff into the car?","你说这么多东西你怎么装进车里？"]},{"w":"stuffy","t":"adj. 不透气的，闷热的","p":"'stʌfɪ","e":["It’s getting stuffy in here – do you mind if I open the window?","这里越来越闷了，我开开窗行吗？"]},{"w":"stumble","t":"vi. 绊脚，绊倒；跌跌撞撞地走；结结巴巴","p":"'stʌmbl","e":["In her hurry, she stumbled and spilled the milk all over the floor.","匆忙中她绊了一下，把牛奶洒得满地都是。"]},{"w":"stump","t":"vi. 脚步沉重地走；n. 树桩；残根，残余部分；vt. 把…难住，使为难；在…做巡回演说","p":"stʌmp","e":["an old tree stump","老树墩"]},{"w":"stun","t":"vt. 使震惊，使目瞪口呆；把…打昏，使昏迷","p":"stʌn","e":["Redfern stunned the crowd with a last-minute goal.","雷德芬在最后一分钟进球，使观众很是震惊。"]},{"w":"sturdy","t":"adj. 强壮的，结实的，坚固的；坚定的，坚强的","p":"'stɜːdi","e":["That chair doesn’t look very sturdy.","那把椅子看上去不太结实。"]},{"w":"subconscious","t":"adj. 下意识的，潜意识的","p":"sʌb'kɒnʃəs","c":1,"e":["a subconscious fear of failure","对失败下意识的恐惧"]},{"w":"subculture","t":"n. 亚文化","p":"'sʌbkʌltʃə","e":["the drug subculture of the inner city","旧城区的吸毒亚文化群"]},{"w":"subdivide","t":"v. 把…再分","p":"sʌbdɪ'vaɪd","e":["Over time, developers subdivided the land.","开发商们渐渐地把这块土地进行了再分割。"]},{"w":"subdue","t":"v. 使屈服，征服","p":"səb'djuː","e":["Senior government officials admit they have not been able to subdue the rebels.","高级政府官员们承认他们还没能制服反叛者们。"]},{"w":"subject","t":"v. 使隶属","p":"ˈsʌbdʒɪkt","e":["The Roman Empire subjected most of Europe to its rule.","罗马帝国把欧洲多数地区置于自己的统治之下。"]},{"w":"subjective","t":"adj. 主观的，个人的","p":"səb'dʒektɪv","e":["As a critic, he is far too subjective.","作为评论家，他过于主观。"]},{"w":"submarine","t":"adj. 水底的，海底的；n. 潜水艇","p":"ˌsʌbmə'riːn","e":["submarine plant life","海生植物"]},{"w":"submerge","t":"v. 淹没","p":"səb'mɜ:dʒ","c":1,"e":["The tunnel entrance was submerged by rising sea water.","隧道入口被涨起的海水淹没。"]},{"w":"submit","t":"v. 提交","p":"səb'mɪt","c":1,"e":["They submitted their reports to the chancellor yesterday.","他们昨天向财政大臣提交了他们的报告。"]},{"w":"subordinate","t":"adj. 从属的；次要的","p":"səˈbɔːdɪnət","c":1,"e":["These aims were subordinate to the main aims of the mission.","和这次任务的主要目标相比，这些目标是次要的。"]},{"w":"subscribe","t":"vi. 订阅，订购；同意，赞成；vt. 捐助，赞助","p":"səb'skraɪb","e":["My main reason for subscribing to New Scientist is to keep abreast of advances in science.","我订阅《新科学家》的主要原因是要跟上科学的进步。"]},{"w":"subscript","t":"adj. 写在下方的；n. 下标","p":"'sʌbskrɪpt","e":["The subscript operator must be defined as a class member function.","下标操作符必须定义为类成员函数。"]},{"w":"subscription","t":"n. 订阅（费）；用户费（的缴纳）","p":"səb'skrɪpʃ(ə)n","e":["You may cancel your subscription at any time.","你随时可以取消订阅。"]},{"w":"subsequent","t":"adj. 随后的，后来的","p":"'sʌbsɪkwənt","e":["These skills were passed on to subsequent generations.","这些技能代代相传。"]},{"w":"subsequently","t":"adv. 随后","p":"'sʌbsɪkwəntlɪ","c":1,"e":["The book was subsequently translated into 15 languages.","该书后来被译成 15 种语言。"]},{"w":"subsidiary","t":"adj. 辅助的，次要的，附设的；n. 子公司，附属机构","p":"səb'sɪdiəri","e":["a subsidiary hypothesis","一个附带假设"]},{"w":"subsidy","t":"n. 补助","p":"'sʌbsədɪ","c":1,"e":["European farmers are planning a massive demonstration against farm subsidy cuts.","欧洲的农场主们正在策划一场反对削减农场补贴的大游行。"]},{"w":"substance","t":"n. 物质","p":"'sʌbstəns","c":1,"e":["The leaves were covered with a strange sticky substance.","树叶上覆着一层黏糊糊的怪东西。"]},{"w":"substantial","t":"adj. 可观的，大量的；物质的，坚固的；实质的，真实的","p":"səb'stænʃl","e":["We have the support of a substantial number of parents.","我们有相当多家长的支持。"]},{"w":"substitute","t":"n. 代替人，代用品；vt. 用…代替","p":"'sʌbstɪtjuːt","e":["Germany brought on a substitute at half time.","德国队在比赛半场时换上一名替补队员。"]},{"w":"subtle","t":"adj. 微妙的","p":"'sʌtl","c":1,"e":["The warning signs of the disease are so subtle that they are often ignored.","这种疾病的警示征兆不易察觉，因而往往被忽视。"]},{"w":"subtract","t":"vt. 减，减去；去掉","p":"səb'trækt","e":["Mandy subtracted the date of birth from the date of death.","曼迪从死亡的日期减去了出生的日期。"]},{"w":"suburb","t":"n. 郊区，郊外，近郊","p":"'sʌbɜːb","e":["a kid from the suburbs","来自郊区的小孩子"]},{"w":"suburban","t":"adj. 郊区的","p":"səˈbɜ:bən","c":1,"e":["a quiet, suburban street","一条安静的郊区街道"]},{"w":"succession","t":"n. 继承（权）","p":"sək'seʃ(ə)n","e":["If the prince dies, the succession passes to his son.","王子如果去世，就由他的儿子继承。"]},{"w":"successive","t":"adj. 连续的，接连的","p":"sək'sesɪv","e":["Successive governments have tried to deal with this issue.","历届政府都试图解决这个问题。"]},{"w":"successively","t":"adv. 接连着地，继续地","p":"sək'sesɪvlɪ","c":1,"e":["Our team turned the tables in the last five minutes by scoring two goals successively.","我队在最后五分钟内连进两球，反败为胜。"]},{"w":"successor","t":"n. 接替的人或事物，继任者","p":"sək'sesə","e":["I’m sure she will be a worthy successor (= someone who is very good and deserves to be someone’s successor ) .","我确信她会是个当之无愧的接班人。"]},{"w":"sue","t":"v. 控告，起诉；要求，请求","p":"suː","e":["The railway may sue for damages (= in order to get money ) because of loss of revenue.","铁道部门可能会因收入损失而提出起诉，要求赔偿。"]},{"w":"suffice","t":"vi. 足够","p":"sə'faɪs","e":["A light lunch will suffice .","简单的午餐就够了。"]},{"w":"sufficient","t":"adj. 足够的，充分的","p":"sə'fɪʃnt","e":["Unauthorized absence is sufficient reason for dismissal.","旷工足以成为解雇的理由。"]},{"w":"suicide","t":"n. 自杀","p":"ˈsu:ɪsaɪd","c":1,"e":["He apparently left a suicide note (= letter explaining his reasons for killing himself ) on his desk.","他显然在桌上留了封绝笔信。"]},{"w":"suit","t":"v. 使配合，彼此协调","p":"sju:t; su:t","e":["Whatever your reason for borrowing, we have the loan that suits your needs.","不管您因何贷款，我们都会有满足您需要的贷款。"]},{"w":"suitcase","t":"n. 手提箱，衣箱","p":"'suːtkeɪs","e":["It did not take Andrew long to pack a suitcase.","安德鲁没有用多长时间就整理好了手提箱。"]},{"w":"suite","t":"n. 套间；一套家具；套，组，系列","p":"swiːt","e":["a suite of rooms for palace guests","王室贵宾套房"]},{"w":"sulfur","t":"n. 硫","p":"'sʌlfə","e":["When mixed with sulfur, phosphorus, and the kind of heat you get from, say, friction, it's very unstable.","当与硫磺、磷、你从某处获得的某种热量（比如说摩擦力）混合时，它就变得很不稳定。"]},{"w":"sullen","t":"adj. 绷着脸不高兴的","p":"'sʌlən","e":["Bill sat in sullen silence and refused to eat his lunch.","比尔一声不响，闷闷不乐地坐着，不肯吃午饭。"]},{"w":"summary","t":"adj. 概括的；速决的","p":"'sʌm(ə)rɪ","e":["a summary financial statement","财务汇总报表"]},{"w":"summit","t":"n. 最高点，峰顶；最高级会议","p":"'sʌmɪt","e":["The two presidents agreed to hold a summit in the spring.","两位总统商定在春天举行一次首脑会议。"]},{"w":"summon","t":"vt. 召唤，传唤；鼓起，振作；召集，召开","p":"'sʌmən","e":["Robert summoned the waiter for the bill.","罗伯特召唤服务员结账。"]},{"w":"superb","t":"adj. 壮丽的；超等的","p":"suː'pɜːb; sjuː-","e":["The food was superb.","食物好吃极了。"]},{"w":"superficial","t":"adj. 表面的","p":"ˌsu:pəˈfɪʃl","c":1,"e":["Beneath his refined manners and superficial elegance lay something treacherous.","在他温文尔雅、貌似高贵的举止下隐藏着某种奸诈。"]},{"w":"superintendent","t":"n. 主管人，监管人，负责人；警长","p":"ˌsuːpərɪn'tendənt","e":["a young park superintendent","年轻的公园负责人"]},{"w":"superior","t":"adj. 上级的，较高的；优越的；有优越感的，高傲的；n. 上级，长官","p":"suː'pɪəriə","e":["She had that superior tone of voice.","她带着那种傲慢的语气。"]},{"w":"superiority","t":"n. 优越，优等","p":"suːˌpɪəri'ɒrəti","e":["Janet always spoke with an air of superiority.","珍妮特说话时总显得盛气凌人。"]},{"w":"supersonic","t":"adj. 超声的，超音速的","p":"ˌsuːpə'sɒnɪk","e":["supersonic aircraft","超音速飞机"]},{"w":"superstition","t":"n. 迷信，迷信行为","p":",suːpə'stɪʃ(ə)n; ,sjuː-","e":["the old superstition that walking under a ladder is unlucky","认为从梯子下面穿过不吉利的古老迷信"]},{"w":"supervise","t":"v. 监督，管理，指导","p":"'suːpəvaɪz","e":["Griffiths closely supervised the research.","格里菲思密切指导该项研究。"]},{"w":"supervisor","t":"n. 督导","p":"ˈsu:pəvaɪzə(r)","c":1,"e":["...a full-time job as a supervisor at a factory.","…在一家工厂担任监督员的一项全职工作。"]},{"w":"supplement","t":"n. 增补，补充；增刊，副刊；vt. 增补，补充","p":"'sʌplɪm(ə)nt","e":["vitamins and other dietary supplements","各种维生素和其他膳食补充剂"]},{"w":"supplementary","t":"adj. 增补的，补充的","p":"ˌsʌplɪ'mentri","e":["supplementary information","补充信息"]},{"w":"support","t":"v. 经受，承受","p":"sə'pɔːt","e":["During sleep, our spine no longer needs to support the weight of our body.","睡觉时，我们的脊柱不用再支撑体重。"]},{"w":"suppress","t":"v. 镇压，压制","p":"səˈpres","c":1,"e":["The uprising was ruthlessly suppressed.","起义受到了残酷的镇压。"]},{"w":"supreme","t":"adj. 最高的，最大的；极度的，最重要的","p":"suː'priːm","e":["the Supreme Allied Commander in Europe","欧洲盟军最高指挥官"]},{"w":"surge","t":"vi. 蜂拥而出；洋溢，奔放；汹涌，奔腾；n. 洋溢，奔放；急剧上升，猛增；浪涛般汹涌奔腾","p":"sɜːdʒ","e":["The photographers and cameramen surged forward.","那些摄影和摄像师们涌向前去。"]},{"w":"surgeon","t":"n. 外科医生","p":"'sɜːdʒən","e":["...a heart surgeon.","…一位心脏外科医生。"]},{"w":"surgery","t":"n. 外科，外科手术；手术室","p":"'sɜːdʒəri","e":["Dr. Hanson is in surgery.","汉森医生在手术室。"]},{"w":"surgical","t":"adj. 手术的","p":"ˈsɜ:dʒɪkl","c":1,"e":["surgical techniques","外科技术"]},{"w":"surpass","t":"v. 超过","p":"sə'pɑːs","c":1,"e":["The number of multiple births has surpassed 100,000 for the first time.","多胎产首次突破了 10 万例。"]},{"w":"surplus","t":"adj. 过剩的，多余的；n. 过剩，剩余，盈余","p":"'sɜːpləs","e":["Ethiopia has no surplus food.","埃塞俄比亚没有多余的食物。"]},{"w":"survey","t":"v. 俯瞰，眺望；全面审视，调查；测量，勘定；n. [sə'veɪ]","p":"'sɜːveɪ","e":["Of the 100 companies surveyed, 10% had a turnover of £50 m to £99 m.","被调查的 100 家公司中，10% 的公司营业额在 5,000 万到 9,900 万英镑之间。"]},{"w":"survival","t":"n. 幸存；幸存者；残存物","p":"sə'vaɪvl","e":["A lot of small companies are having to fight for survival (= work hard in order to continue to exist ) .","很多小公司不得不挣扎求生。"]},{"w":"survive","t":"vi. 活下来，继续存在；幸免于；vt. 从中挺过来；从…逃出；比…活得长","p":"sə'vaɪv","e":["Only 12 of the 140 passengers survived.","140 名乘客中只有 12 人生还。"]},{"w":"susceptible","t":"adj. 易受影响的；过敏的；能经受的，容许的","p":"sə'septəbl","e":["A lot of TV advertising is aimed at susceptible young children.","很多电视广告瞄准了易受影响的幼儿。"]},{"w":"suspect","t":"v. 怀疑；n. 嫌疑犯","p":"sə'spekt","c":1,"e":["She’s not going to be very happy about this, I suspect .","我想对于此事她不会太高兴。"]},{"w":"suspend","t":"v. 暂停","p":"səˈspend","c":1,"e":["Sales of the drug will be suspended until more tests are completed.","这种药品在完成进一步检验之前将暂停销售。"]},{"w":"suspension","t":"n. 暂停，中止；暂令停止参加，暂时剥夺；悬架，悬置机构；悬浮液；悬，挂，吊","p":"sə'spenʃn","e":["He received a six-month suspension for unprofessional behaviour.","他因有违职业道德的行为被停职六个月。"]},{"w":"suspicion","t":"n. 怀疑，疑心，猜疑；一点儿，少量","p":"sə'spɪʃn","e":["Police suspicions were confirmed when the stolen property was found in his flat.","失窃物品在他公寓里找到，警方的怀疑得到了证实。"]},{"w":"suspicious","t":"adj. 怀疑的","p":"səˈspɪʃəs","c":1,"e":["His reluctance to answer my questions made me suspicious .","他不愿回答我的问题，这引起我的怀疑。"]},{"w":"sustain","t":"vt. 保持，使持续下去；供养，维持；支持，支撑；经受，遭受","p":"sə'steɪn","e":["He was incapable of sustaining close relationships with women.","他无法和女人维持亲密关系。"]},{"w":"swamp","t":"n. 沼泽；vt. 淹没，浸没；难倒，压倒","p":"swɒmp","e":["I spent one whole night by a swamp behind the road listening to frogs.","我整个晚上都在这条路后面的一个沼泽地旁听蛙鸣。"]},{"w":"swap","t":"n&v. 交换","p":"swɒp","e":["Do you want to swap umbrellas?","你想交换雨伞吗？"]},{"w":"sway","t":"v. 影响","p":"sweɪ","c":1,"e":["Don’t allow yourself to be swayed by his promises.","你可不要听了他的许诺就改变主意呀。"]},{"w":"sweep","t":"v. 扫除，清除","p":"swi:p","c":1,"e":["Bert swept the path in front of the house.","伯特清扫了屋前的小路。"]},{"w":"sweeten","t":"v. 使变甜，变甜","p":"'swiːt(ə)n","e":["Sweeten the mixture with a little honey.","往混合料里加点蜂蜜。"]},{"w":"sweetness","t":"n. 甜蜜，芬芳；愉悦，美好","p":"'swi:tnis","e":["the sweetness of the wild rose","野玫瑰的芬芳"]},{"w":"swell","t":"v. 使膨胀；隆起","p":"swel","e":["Her ankle was already starting to swell.","她的脚踝已经开始肿起来了。"]},{"w":"switch","t":"v. 转换","p":"swɪtʃ","c":1,"e":["The terrorists will switch tactics .","恐怖分子会改变战术。"]},{"w":"symbol","t":"n. 象征；符号，标志","p":"'sɪmbl","e":["The symbol on the packet is a guarantee that the food has been produced organically.","包装盒上的这个标识保证这种食物是有机生产的。"]},{"w":"symbolic","t":"adj. 符号的；象征性的","p":"sɪm'bɒlɪk","e":["Each element of the ceremony has a symbolic meaning .","仪式的每一个元素都具有象征意义。"]},{"w":"symmetrical","t":"adj. 对称的，匀称的","p":"sɪ'metrɪk(ə)l","e":["The pattern was perfectly symmetrical.","该图案完全对称。"]},{"w":"symmetry","t":"n. 对称；匀称，整齐","p":"'sɪmətri","e":["...the incredible beauty and symmetry of a snowflake.","…雪花令人难以置信的美丽和对称。"]},{"w":"sympathetic","t":"adj. 同情的","p":"ˌsɪmpəˈθetɪk","c":1,"e":["We hope always to provide a friendly sympathetic ear (= someone willing to listen to someone else’s problems ) .","我们希望总能做到友善地倾听。"]},{"w":"sympathy","t":"n. 同情；一致；支持，赞同","p":"'sɪmpəθi","e":["Our sympathies are with the families of the victims.","我们向受害者家庭表示慰问。"]},{"w":"symphony","t":"n. 交响乐，交响曲；和谐，协调","p":"'sɪmfəni","e":["Bruckner’s Fifth Symphony","布鲁克纳的《第五交响曲》"]},{"w":"symposium","t":"n. 讨论会，专题报告会；专题论文集","p":"sɪm'pəuziəm","e":["He had been taking part in an international symposium on population.","他那时在参加一个有关人口的国际研讨会。"]},{"w":"symptom","t":"n. 症状","p":"'sɪmptəm","c":1,"e":["One of the most common symptoms of schizophrenia is hearing imaginary voices.","精神分裂症最常见的症状之一是幻听。"]},{"w":"syndrome","t":"n. 综合病症，综合症状；一系列表现","p":"'sɪndrəum","e":["people who suffer from irritable bowel syndrome","患有肠道过敏综合征的人"]},{"w":"synthesis","t":"n. 综合；合成","p":"'sɪnθəsɪs","e":["speech synthesis software","语音合成软件"]},{"w":"systematic","t":"adj. 成体系的","p":"sɪstə'mætɪk","e":["a systematic approach to solving the problem","系统解决问题的办法"]},{"w":"systematically","t":"adv. 系统地，有规则地","p":",sɪstə'mætɪklɪ","e":["The search was carried out systematically.","搜查已按照部署执行。"]},{"w":"tabulate","t":"v. 把…制成表","p":"'tæbjʊleɪt","e":["Results for the test programme haven't been tabulated.","试验项目的结果还没有制成表格。"]},{"w":"tack","t":"n. 平头钉，大头钉；行动方向，方针；vt. 用平头钉钉；附加，增补","p":"tæk","e":["If that doesn’t work, we’ll try a different tack .","如果那样不行，我们将试试别的方法。"]},{"w":"tackle","t":"v. 解决，处理","p":"'tækl","c":1,"e":["There is more than one way to tackle the problem.","解决这个问题不止一个办法。"]},{"w":"tact","t":"n. 机敏，圆滑，得体","p":"tækt","e":["With great tact, Clive persuaded her to apologize.","克莱夫十分巧妙地说服了她去道歉。"]},{"w":"tactics","t":"n. 战术，兵法","p":"'tæktɪks"},{"w":"tame","t":"adj. 驯服的，顺从的；沉闷的，乏味的；vt. 制服，控制并利用；驯化，驯服","p":"teɪm","e":["I decided that teaching was too tame for me.","我最终认为教书对我来说太枯燥。"]},{"w":"tan","t":"vi. 晒成棕褐色；vt. 使晒成棕褐色；硝制；n. 棕褐色，棕黄色；晒成棕褐色，晒黑","p":"tæn","e":["She has a pale skin which doesn’t tan easily.","她的肤色很白，不容易被晒黑。"]},{"w":"tangle","t":"v. 缠结，乱作一团；n. 乱糟糟的一堆，混乱；复杂的问题；困惑","p":"'tæŋgl","e":["His parachute became tangled in the wheels of the plane.","他的降落伞缠在了飞机的轮子上。"]},{"w":"tangled","t":"adj. 纠缠的；复杂的","p":"'tæŋɡld","c":1,"e":["Your bedclothes are all tangled up.","你的床褥乱糟糟的。"]},{"w":"tank","t":"n. 水箱","p":"tæŋk","c":1,"e":["Somehow the chemical got from a storage tank into water supplies.","不知怎么的，这种化学物从储存箱进入了供水系统。"]},{"w":"tanker","t":"n. 油轮","p":"'tæŋkə","e":["A Greek oil tanker has run aground.","一艘希腊油轮已经搁浅了。"]},{"w":"tap","t":"v. 轻敲","p":"tæp","c":1,"e":["He tapped the table nervously with his fingers.","他紧张地用手指轻轻地敲打桌子。"]},{"w":"tape","t":"v. 系，捆","p":"teɪp"},{"w":"taper","t":"n. 细小的蜡烛；微光","p":"'teɪpə","e":["small boys holding lighted tapers","拿着点燃的细蜡烛的小男孩"]},{"w":"tar","t":"n. 柏油；焦油","p":"tɑː","e":["The oil has hardened to tar.","油已经硬化成柏油了。"]},{"w":"target","t":"n. 目标；v. 把…作为目标","p":"'tɑrɡɪt","c":1,"e":["The government may fail to meet (= achieve ) its target of recycling 25% of domestic waste.","政府可能达不到回收利用25%的生活垃圾的目标。"]},{"w":"tariff","t":"n. 关税，税率；价目表，收费表","p":"'tærɪf","e":["America wants to eliminate tariffs on items such as electronics.","美国想要取消电子类产品的关税。"]},{"w":"tasteless","t":"adj. 没有味道的","p":"ˈteɪstləs","c":1,"e":["How can you eat such tasteless food?","你怎么能吃下这么无味的食物呢？"]},{"w":"team","t":"v. 协作，合作","p":"tiːm","e":["You can team up with one other class member if you want.","例句：如果你愿意的话，可以找一个同学组成一组。"]},{"w":"tease","t":"vt. 戏弄，取笑；挑逗，撩拨","p":"tiːz","e":["Don’t get upset. I was only teasing .","别生气，我只是在逗你玩。"]},{"w":"tedious","t":"adj. 冗长的","p":"ˈti:diəs","c":1,"e":["The work was tiring and tedious.","这工作既累人又枯燥。"]},{"w":"telecommunications","t":"n. 通信，电信","p":"'telikəˌmjuːnɪ'keɪʃnz","e":["a new telecommunications system","新的电信系统"]},{"w":"telex","t":"n. 电传，用户电报","p":"'teleks","e":["He sent a telex to the British High Commission in Delhi.","他给德里的英国高级专员公署发了份电传。"]},{"w":"temper","t":"n. 韧度；心情，情绪；vt. 调和，使缓和；回火","p":"'tempə","e":["Pete hit his brother in a fit of temper .","皮特一气之下打了他弟弟。"]},{"w":"temperament","t":"n. 气质，性格","p":"'temprəmənt","e":["His impulsive temperament regularly got him into difficulties.","他容易冲动的性格经常使他陷入困境。"]},{"w":"tempo","t":"n. 速度；节奏，行进速度","p":"'tempəu","e":["the easy tempo of island life","岛上生活的轻松节奏"]},{"w":"tempt","t":"vt. 吸引，引起…的兴趣；引诱，诱惑","p":"tempt","e":["If you leave valuables in your car it will tempt thieves.","如果把贵重物品留在车上，会招来小偷的。"]},{"w":"temptation","t":"n. 诱惑","p":"tempˈteɪʃn","c":1,"e":["Resist the temptation to buy the item until you’re certain you need it.","要抵挡住购买的诱惑，除非你确有需要。"]},{"w":"tempting","t":"adj. 吸引人的","p":"ˈtemptɪŋ","c":1,"e":["That pie looks tempting.","那馅饼看上去很诱人。"]},{"w":"tenant","t":"n. 房客，佃户","p":"'tenənt","e":["The desk was left by the previous tenant.","书桌是上一个房客留下来的。"]},{"w":"tendency","t":"n. 趋向，趋势，倾向","p":"'tendənsi","e":["children with aggressive or anti-social tendencies","具有攻击性倾向或反社会倾向的儿童"]},{"w":"tensile","t":"adj. 张力的；能伸长的","p":"'tensaɪl","e":["tensile rubber","有伸缩性的橡胶"]},{"w":"tension","t":"n. 紧张","p":"ˈtenʃn","c":1,"e":["The tension was becoming unbearable, and I wanted to scream.","这种紧张变得难以忍受，我真想大声尖叫。"]},{"w":"tentative","t":"adj. 试探的，试验的","p":"'tentətɪv","e":["I passed on my tentative conclusions to the police.","我把我的初步结论递交给了警方。"]},{"w":"terminal","t":"n. 计算机终端；线接头","p":"'tɜːmɪn(ə)l","e":["Carl sits at a computer terminal 40 hours a week.","卡尔每周要在电脑前坐40小时。"]},{"w":"terminate","t":"v. 停止，终止","p":"'tɜːmɪneɪt","e":["a woman’s decision on whether or not to terminate the pregnancy","女子关于是否终止妊娠的决定"]},{"w":"terminology","t":"n. 术语学，术语","p":",tɜːmɪ'nɒlədʒɪ","e":["computer terminology","计算机术语"]},{"w":"terrace","t":"n. 排屋；地坪，草坪；","p":"'terəs","e":["Some guests recline in deck chairs on the sea-facing terrace.","有些客人斜躺在朝海露台的躺椅上。"]},{"w":"terrain","t":"n. 地形，地势","p":"tə'reɪn","e":["rocky terrain","多石的地形"]},{"w":"terrific","t":"adj. 极妙的；极大的；令人恐惧的","p":"tə'rɪfɪk","e":["The actress who played the lawyer was terrific.","扮演律师的女演员表演十分出色。"]},{"w":"terrify","t":"vt. 使害怕，使惊吓","p":"'terɪfaɪ","e":["Her husband’s violence terrified her.","丈夫的暴力行为让她感到害怕。"]},{"w":"territory","t":"n. 领域，领土","p":"ˈterətri","c":1,"e":["Hong Kong is a Chinese territory.","香港是中国的领土。"]},{"w":"terrorist","t":"n. 恐怖分子","p":"'terərɪst","e":["a terrorist bomb that left 168 people dead","恐怖分子引爆造成168人死亡的炸弹"]},{"w":"testify","t":"v. 作证；证明，检验","p":"'testɪfaɪ","c":1,"e":["The empty shops in the high street testify to the depth of the recession.","大街上空无一人的商店说明了经济萧条的严重程度。"]},{"w":"testimony","t":"n. 证词","p":"'testɪmənɪ","c":1,"e":["In his testimony, he denied that the company had ignored safety procedures.","他在证词中否认公司忽视了安全程序。"]},{"w":"texture","t":"n. 质地","p":"'tekstʃə(r)","c":1,"e":["This cloth has a silky texture.","这种布具有丝的质地。"]},{"w":"Thanksgiving","t":"n. 感恩节","p":"ˌθæŋks'gɪvɪŋ","e":["He said sometimes they would invite some friends to share the happiness of Thanksgiving Day.","他说有时候他们也会邀请一些朋友来一起分享感恩节快乐。"]},{"w":"theatre","t":"n. 剧场，戏院","p":"'θɪətə","e":["an open-air theatre (= a theatre that is outside )","露天剧场"]},{"w":"theft","t":"n. 偷窃，失窃","p":"θeft","e":["There have been a number of thefts in the area.","该地区发生了几宗偷窃案。"]},{"w":"theme","t":"n. 主题，题目","p":"θiːm","e":["Nature is a recurrent theme (= a theme that appears repeatedly ) in Frost’s poetry.","大自然是弗罗斯特诗作中反复出现的一个主题。"]},{"w":"theorem","t":"n. 定理；原理，原则","p":"'θɪərəm","e":["a mathematical theorem","数学定理"]},{"w":"theory","t":"n. （未证明的）见解，看法，推测","p":"'θɪərɪ","e":["I have this theory that most people prefer being at work to being at home.","依我看，多数人喜欢工作而不愿待在家里。"]},{"w":"therapy","t":"n. 疗法","p":"'θerəpɪ","c":1,"e":["radiation therapy for cancer treatment","治疗癌症的放射疗法"]},{"w":"thereafter","t":"adv. 之后，以后","p":"ˌðeər'ɑːftə","e":["Sophie was born in France, but shortly thereafter her family moved to the United States.","索菲出生在法国，但不久以后她全家就移居到了美国。"]},{"w":"therefore","t":"adv. 因此，所以","p":"'ðeəfɔː","e":["Progress so far has been very good. We are, therefore, confident that the work will be completed on time.","到目前为止进展十分顺利，所以我们有把握按时完成工作。"]},{"w":"therein","t":"adv. 在那里","p":"ðeər'ɪn","e":["See Thompson, 1983, and the references cited therein.","见汤普森（1983）以及书中引用的参考资料。"]},{"w":"thereof","t":"adv. 它的，其；由此","p":"ðeər'ɒv","e":["Money, or the lack thereof , played a major role in their marital problems.","钱，或者说没钱，是他们婚姻出现问题的主要原因。"]},{"w":"thermal","t":"adj. 热的，由热造成的；保暖的","p":"'θɜːml","e":["thermal energy","热能"]},{"w":"thesis","t":"n. 论文，毕业论文；论题，论点","p":"'θiːsɪs","e":["Cynthia’s still working on her thesis.","辛西娅还在写论文。"]},{"w":"thicken","t":"v. 使变厚（或粗、密）","p":"'θɪk(ə)n","e":["Thicken the soup by adding potatoes.","加些马铃薯让汤变稠。"]},{"w":"thigh","t":"n. 大腿","p":"θaɪ","e":["chicken thighs","鸡腿"]},{"w":"thorn","t":"n. 刺，荆棘；带刺小灌木","p":"θɔːn","e":["a long, low hedge of thorns","一长排矮矮的荆棘树篱"]},{"w":"thorough","t":"adj. 精心的；详尽的","p":"'θʌrə","e":["The police investigation was very thorough.","警方的调查十分彻底。"]},{"w":"thoughtless","t":"adj. 欠考虑的；自私的","p":"'θɔːtlɪs","e":["a selfish and thoughtless man","自私而不顾他人的人"]},{"w":"thrash","t":"v. 痛打，鞭打，打","p":"θræʃ","e":["My poor brother used to get thrashed for all kinds of minor offences.","我那可怜的哥哥过去常常因为各种各样的小错而挨打。"]},{"w":"threat","t":"n. 威胁","p":"θret","c":1,"e":["Officials at the school say they received a bomb threat at approximately 11:30 a.m. today.","学校的官员说他们在今天上午11点半左右收到过炸弹恐吓。"]},{"w":"threaten","t":"v. 威胁","p":"'θretn","c":1,"e":["Postal workers are threatening a strike if they don’t receive a pay increase.","邮政工人威胁如果不加薪，他们就要罢工。"]},{"w":"thresh","t":"v. 打谷，脱粒","p":"θreʃ","e":["The grain was still sown, cut and threshed as it was a hundred years ago.","谷物的播种、收割、脱粒方法还和一百年前一样。"]},{"w":"threshold","t":"n. 门槛","p":"'θreʃhəʊld","c":1,"e":["She opened the door and stepped across the threshold.","她打开门，跨过门槛。"]},{"w":"thrifty","t":"adj. 节俭的","p":"'θrɪftɪ","e":["hard-working, thrifty people","勤劳节俭的人们"]},{"w":"thrill","t":"v. 非常兴奋，非常激动；n. 兴奋，激动；引起激动的事物","p":"θrɪl","e":["His music continues to thrill audiences.","他的音乐依然能扣人心弦。"]},{"w":"thrilling","t":"adj. 令人兴奋的","p":"'θrɪlɪŋ","c":1,"e":["a thrilling 3-2 victory","比分为3比2的激动人心的胜利"]},{"w":"thrive","t":"v. 繁荣，兴旺","p":"θraɪv","c":1,"e":["a business which managed to thrive during a recession","在经济萧条时期也能顺利发展的一家企业"]},{"w":"throne","t":"n. 王位","p":"θrəʊn","c":1,"e":["He is next in line to the throne (= will become king when the present ruler dies ) .","他是第一王位继承人。"]},{"w":"through","t":"prep. 因为，由于","p":"θruː","e":["How many working days were lost through sickness last year?","去年因为员工生病损失了多少个工作日？"]},{"w":"tick","t":"vi. 发出滴答声；n. 记号，勾号；滴答声；vt. 给…标记号","p":"tɪk","e":["The old clock ticked noisily.","那只古老的钟大声地嘀嗒着。"]},{"w":"ticket","t":"n. （交通违章）罚款传票","p":"'tɪkɪt","e":["Slow down or you'll get a ticket.","开慢点儿，否则你会接到一张罚款通知单。"]},{"w":"tickle","t":"vi. 发痒；vt. 使发痒；使高兴，逗乐；n. 痒","p":"'tɪkl","e":["Stop tickling me!","别挠我痒痒！"]},{"w":"tighten","t":"v. （使）变紧","p":"'taɪt(ə)n","e":["I’d put the new tyre on, but I hadn’t tightened up the wheel.","我把新轮胎装上了，但没有上紧轮子。"]},{"w":"tightly","t":"adv. 紧地，牢固地","p":"'taɪtlɪ","e":["a tightly packed crowd of tourists","挤得严严实实的旅游人群"]},{"w":"tile","t":"n. 瓦，瓷砖；vt. 铺瓦于，贴瓷砖于","p":"taɪl","e":["bathroom tiles","浴室瓷砖"]},{"w":"tilt","t":"v. 倾斜，倾侧；n. 倾斜，倾侧","p":"tɪlt","e":["Ned’s mouth tilted upwards slightly at the corners.","内德的嘴角微微翘起。"]},{"w":"timely","t":"adj. 及时的，适时的","p":"'taɪmli","e":["The fight ended only with the timely arrival of the police.","幸亏警察及时赶到，打斗总算停止。"]},{"w":"timid","t":"adj. 羞怯的，胆小的","p":"'tɪmɪd","e":["a policy that is both timid and inadequate","一项既无胆识又不完善的政策"]},{"w":"tiresome","t":"adj. 使人厌倦的，讨厌的","p":"'taɪəs(ə)m","e":["the whole tiresome business of filling out the forms","填写表格这套烦人事"]},{"w":"tissue","t":"n. 组织；薄绢，薄纸，手巾纸","p":"'tɪʃuː","e":["a box of tissues","一盒面巾纸"]},{"w":"toad","t":"n. 蟾蜍，癞蛤蟆","p":"təʊd","e":["Toads have drier, lumpier skins than frogs and spend less time in the water.","蟾蜍的皮比青蛙干燥，疙瘩也更多，呆在水中的时间比青蛙少。"]},{"w":"token","t":"adj. 象征性的，装样子的；n. 筹码；信物，标志，纪念品；代金券，礼券","p":"'təukən","e":["The government thinks it can get away with token gestures on environmental issues.","政府以为它在环境问题上做个样子就能敷衍过去。"]},{"w":"tolerant","t":"adj. 宽容的，容忍的","p":"'tɒlərənt","e":["a tolerant society","宽容的社会"]},{"w":"toll","t":"v. 敲；n. 过路费，过桥费；伤亡人数，损失","p":"təul","e":["Church bells tolled and black flags fluttered.","教堂丧钟敲响了，黑旗飘动着。"]},{"w":"tone","t":"n. 色调，光度","p":"təʊn","e":["Perhaps a darker tone would be better.","可能再深一点的色调更好。"]},{"w":"torment","t":"n. 痛苦；v. 折磨","p":"'tɔːment","e":["Seth was tormented by feelings of guilt.","塞思被负罪感折磨着。"]},{"w":"torpedo","t":"n. 鱼雷，水雷","p":"tɔː'piːdəʊ","e":["Sometimes, when you go into small rooms, you can find very interesting things, like this torpedo.","有时候，你走进一些小房间里，你会发现非常有趣的东西，就像这个鱼雷。"]},{"w":"torque","t":"n. 转（力）矩，扭（力）矩","p":"tɔːk","e":["In rotation, force becomes torque, mass becomes moment of inertia, and acceleration becomes angular acceleration.","在旋转时，力变成力矩，质量变成转动惯量，加速度变成角加速度。"]},{"w":"toss","t":"vi. 掷钱币来决定；翻来覆去；vt. 扔，抛，掷；猛抬；拌；掷；使摇动，使颠簸；n. 掷钱币来决定；猛抬头","p":"tɒs","e":["I’ve been tossing and turning all night.","我一晚上辗转反侧。"]},{"w":"tough","t":"adj. 困难的，粗暴的","p":"tʌf","c":1,"e":["(= a difficult decision ) , but we had to cancel the game because of the weather.","尽管是一个艰难的决定，但由于天气不好我们只得取消比赛。"]},{"w":"tow","t":"n&vt. 拖，拉，牵引","p":"təu","e":["The ship had to be towed into the harbor.","那艘轮船不得不被拖进港口。"]},{"w":"towards","t":"prep. 用于，有助于","p":"tə'wɔːdz; twɔːdz; 'tɔːdz","e":["The money collected will be put towards repairing the church roof.","募集到的钱款将用于修缮教堂屋顶。"]},{"w":"tower","t":"v. 高耸，屹立；翱翔","p":"'taʊə","e":["The cliffs towered above them.","悬崖峭壁高耸于他们上方。"]},{"w":"toxic","t":"adj. 有毒的","p":"ˈtɒksɪk","c":1,"e":["fumes from a toxic waste dump","有毒废料堆产生的毒气"]},{"w":"trace","t":"v. 追踪","p":"treɪs","c":1,"e":["The police traced the call (= used special electronic equipment to find out who made the telephone call) to her ex-husband's number.","警方用追踪装置查出是她前夫的电话号码打出的电话。"]},{"w":"track","t":"v. 追踪；n. 轨迹，踪迹","p":"træk","c":1,"e":["Police have been tracking the four criminals all over Central America.","警方一直在中美洲到处追捕这四名罪犯。"]},{"w":"tract","t":"n. 传单，小册子；大片","p":"trækt","e":["vast tracts of woodland","大片大片的林地"]},{"w":"trade","t":"v. 做买卖；交换","p":"treɪd","e":["They had to travel into town to trade the produce from their farm.","他们不得不到镇上去出售他们农场的产品。"]},{"w":"trade-off","t":"n. 权衡，交易","p":"ˈtreɪdˌɒf","c":1,"e":["The newspaper's headline indicates that there was a trade-off at the summit.","报纸的大字标题表明峰会上大家作出了妥协。"]},{"w":"trademark","t":"n. 商标，牌号；特征，标记","p":"'treɪdmɑːk","e":["The striped T-shirt became the comedian’s trademark.","条纹T恤衫成了这位喜剧演员的标记。"]},{"w":"trader","t":"n. 商人","p":"'treɪdə","e":["To the surprise of many Wall Street traders, the dollar rose yesterday.","使很多华尔街经纪人意外的是，昨天美元上涨了。"]},{"w":"tradesman","t":"n. 商人，店主；手艺人","p":"'treɪdzmən","e":["Local tradesmen are objecting to plans for a big new out-of-town shopping centre.","当地的店主们反对在城郊新建大型购物中心的计划。"]},{"w":"tragedy","t":"n. 悲剧","p":"'trædʒədɪ","c":1,"e":["Tragedy struck the family when their two-year-old son was killed in an accident.","悲剧降临到这个家庭，他们两岁的儿子在一次事故中丧生。"]},{"w":"tragic","t":"adj. 悲惨的，可悲的；悲剧的","p":"'trædʒɪk","e":["Lillian Board’s death at 22 was a tragic loss for British athletics.","莉莲•博德22岁早逝，这对英国田径界来说是个惨痛的损失。"]},{"w":"trait","t":"n. 特点","p":"treɪt","c":1,"e":["The study found that some alcoholics had clear personality traits showing up early in childhood.","这项研究发现一些酗酒者早在孩童时就表现出明显的个性特征。"]},{"w":"tramp","t":"v. 以沉重的脚步走（过）；n. 跋涉","p":"træmp","e":["The walk involved tramping through mud.","走这段路要在泥地中跋涉。"]},{"w":"trample","t":"v. 践踏，蹂躏；n. 践踏，蹂躏","p":"'træmp(ə)l","e":["There was a small fence to stop people trampling on the flowers.","有一道小小的围栏，防止人们践踏花草。"]},{"w":"tranquil","t":"adj. 平静的；稳定的","p":"'træŋkwɪl","e":["a small tranquil village","宁静的小村庄"]},{"w":"transaction","t":"n. 交易，业务","p":"træn'zækʃn","e":["The bank charges a fixed rate for each transaction.","银行对每一笔业务收取固定费用。"]},{"w":"transcend","t":"v. 超越","p":"trænˈsend","c":1,"e":["The desire for peace transcended political differences.","对和平的渴望超越了政治分歧。"]},{"w":"transfer","t":"v. 搬，转移；调动，转学；转让，过户；乘车，转乘","p":"træns'fɜː","e":["He was transferred for a fee of £8 million.","他以800万英镑的转会费转到了其他球队。"]},{"w":"transform","t":"v. 转变","p":"trænsˈfɔːm","c":1,"e":["Increased population has transformed the landscape.","人口的增加使景观发生了变化。"]},{"w":"transient","t":"adj. 短暂的，转瞬即逝的；临时的，暂住的","p":"'trænziənt","e":["transient fashions","短暂的时尚"]},{"w":"transistor","t":"n. 晶体管，晶体管收音机","p":"træn'zɪstə"},{"w":"transit","t":"n. 运输，载运","p":"'trænzɪt","e":["baggage that is lost or damaged in transit","在运输过程中丢失或损坏的行李"]},{"w":"transition","t":"n. 过渡","p":"trænˈzɪʃn","c":1,"e":["Making the transition from youth to adulthood can be very painful.","从青少年过渡到成年有时是一个非常痛苦的过程。"]},{"w":"transmission","t":"n. 传播，发射；传送，传递；传染","p":"trænz'mɪʃn","e":["worldwide data transmission","全球数据传输"]},{"w":"transmit","t":"v. 传播，传导","p":"træns'mɪt","c":1,"e":["The system transmits information over digital phone lines.","这一系统通过数字电话线路传输信息。"]},{"w":"transplant","t":"vt. 移栽，移种；移植；使迁移，使移居；n. 移植","p":"træns'plɑːnt","e":["The operation to transplant a kidney is now fairly routine.","移植肾脏的手术如今相当常见。"]},{"w":"transport","t":"vt. 运输；n. 运输，运输工具","p":"træn'spɔːt","e":["trucks used for transporting oil","运输石油的卡车"]},{"w":"transverse","t":"adj. 横的","p":"trænz'vɜːs; trɑːnz-; -ns-","e":["a transverse beam","横梁"]},{"w":"trap","t":"v. 捕捉","p":"træp","c":1,"e":["The locals were encouraged to trap and kill mice to stop the spread of the virus.","当地人被鼓励用捕捉器捕杀老鼠以阻止病毒的传播。"]},{"w":"traverse","t":"vt. 横渡，横越","p":"trə'vɜːs","e":["two minutes to traverse the park","两分钟横穿公园"]},{"w":"tread","t":"v. 踩，踏，践踏","p":"tred","e":["She trod barefoot on the soft grass.","她光脚踩在柔软的草地上。"]},{"w":"treasurer","t":"n. 司库，财务主管","p":"'treʒ(ə)rə"},{"w":"treaty","t":"n. 条约，协议，协定","p":"'triːti","e":["The peace treaty ends nearly four years of violence.","该和平条约结束了将近四年的暴力。"]},{"w":"tremendous","t":"adj. 巨大的","p":"tri'mendəs","c":1,"e":["She praised her husband for the tremendous support he had given her.","她称赞丈夫给了她巨大支持。"]},{"w":"trench","t":"n. 沟，沟渠","p":"trentʃ","e":["Workers dug a trench for gas lines.","工人们挖了一条沟来铺设煤气管道。"]},{"w":"trend","t":"n. 趋势","p":"trend","c":1,"e":["Successive presidents have tried to reverse this trend , but without success.","连续几任总统都试图扭转这一趋势，但均未成功。"]},{"w":"trial","t":"n. 试，试验；审判；讨厌的人","p":"'traɪəl","e":["The trial is due to start next week.","审理定于下周开始。"]},{"w":"triangular","t":"adj. 三角的；三者间的","p":"traɪ'æŋgjʊlə","e":["a triangular sporting competition","一项由三方参加的体育比赛"]},{"w":"tribe","t":"n. 部落；族","p":"traɪb","e":["a tribe of Aborigines known as the Dolphin People","一个叫“海豚族”的澳大利亚土著部落"]},{"w":"tribute","t":"n. 颂词，称赞，礼物；贡品","p":"'trɪbjuːt","e":["I’d like to pay tribute to (= praise and admire publicly ) the party workers for all their hard work.","我谨向党内工作人员致敬，感谢他们的辛苦努力。"]},{"w":"trick","t":"n. 骗局，诡计","p":"trɪk","c":1,"e":["He didn’t really lose his wallet - that’s just a trick.","他并没有真的丢了钱包——这只是一个骗局。"]},{"w":"trifle","t":"vi. 嘲笑；轻视；n. 琐事，小事，无价值的东西","p":"'traɪfl","e":["There’s no point in arguing over trifles.","为琐事争吵毫无意义。"]},{"w":"trigger","t":"v. 引发，引起","p":"'trɪɡə(r)","c":1,"e":["Certain forms of mental illness can be triggered by food allergies.","某些精神疾病可能由食物过敏引发。"]},{"w":"trim","t":"v. 修剪","p":"trɪm","c":1,"e":["Pete was trimming the lawn around the roses.","皮特在修剪玫瑰丛周围的草坪。"]},{"w":"triple","t":"adj. 三部分的，三方的；三倍的，三重的；v. 增至三倍","p":"'trɪpl","e":["a triple bypass heart operation","三重心脏搭桥手术"]},{"w":"triumph","t":"vi. 成功；n. 凯旋，胜利","p":"'traɪʌmf","e":["All her life, Kelly had stuck with difficult tasks and challenges, and triumphed.","凯利在一生中遭遇了种种艰巨任务与挑战，但成功了。"]},{"w":"triumphant","t":"adj. 得胜的；得意洋洋的","p":"traɪ'ʌmf(ə)nt","e":["I feel exhausted, but also triumphant.","我感到很疲倦，但也很得意。"]},{"w":"trivial","t":"adj. 琐碎的，不重要的","p":"'trɪviəl","e":["a trivial sum","一笔极小的金额"]},{"w":"trolley","t":"n. 手推车；有轨电车","p":"'trɒlɪ","e":["He took a northbound trolley on State Street.","他在州大街坐上了一辆北行的有轨电车。"]},{"w":"troop","t":"n. 一群，一队，大量","p":"truːp","e":["a troop of monkeys","一群猴子"]},{"w":"tropic","t":"n. 回归线；热带地区","p":"'trɒpɪk","e":["the Tropic of Capricorn/the Tropic of Cancer","南/北回归线"]},{"w":"tropical","t":"adj. 热带的","p":"ˈtrɒpɪkl","c":1,"e":["the tropical rain forests","热带雨林"]},{"w":"trot","t":"v. （马）小跑；n. （马）小跑；慢跑","p":"trɒt","e":["She broke into a trot (= started running slowly ) and hurried on ahead of us.","她突然小跑起来，赶到我们前头。"]},{"w":"troublesome","t":"adj. 困难的","p":"'trʌb(ə)ls(ə)m","e":["The economy has become a troublesome issue for the Conservative Party.","经济状况已成为保守党的一大难题。"]},{"w":"tub","t":"n. 桶，塑料杯，纸杯；盆，洗澡盆，浴缸","p":"tʌb","e":["I had a long soak in the tub.","我在浴缸里泡了很久。"]},{"w":"tuberculosis","t":"n. 结核病，肺结核","p":"tjʊ,bɜːkjʊ'ləʊsɪs","e":["She was infected with tuberculosis.","她被传染上了肺结核。"]},{"w":"tuck","t":"vt. 把边塞到下面；把…夹入，把…藏入；n. 褶，裥","p":"tʌk","e":["He tried to tuck his flapping shirt inside his trousers.","他试图把飘动的衬衫塞进他的裤子里。"]},{"w":"tug","t":"v. 用力拖；n. 拖船；猛拉，牵引","p":"tʌg","e":["She removed the bandage with a sharp tug.","她猛地一拉，扯下绷带。"]},{"w":"tuition","t":"n. 学费","p":"tjuˈɪʃn","c":1,"e":["When I started college, tuition was 350 a quarter.","我开始念大学的时候，学费是每学季350美元。"]},{"w":"tulip","t":"n. 郁金香","p":"'tjuːlɪp","e":["In a vase on the table stood a tulip.","桌上的花瓶里插着一束郁金香。"]},{"w":"tumble","t":"vi. 跌倒，摔下，滚下；翻滚；暴跌；不由自主地卷入；n. 跌倒，摔倒","p":"'tʌmbl","e":["Oil prices have tumbled.","石油价格猛跌。"]},{"w":"tuna","t":"n. 金枪鱼","p":"'tjuːnə","e":["...a shoal of tuna.","…一群金枪鱼。"]},{"w":"tunnel","t":"v. 挖，开；n. 隧道，坑道，地道","p":"'tʌnl","e":["The thieves tunnelled under all the security devices.","小偷们在所有的那些安全装置下面都挖了地道。"]},{"w":"turbulence","t":"n. 气流；骚乱","p":"'tɜ:bjələns","c":1,"e":["The plane encountered severe turbulence and winds of nearly two-hundred miles an hour.","那架飞机遇到了强湍流和时速近二百英里的强风。"]},{"w":"turbulent","t":"adj. 动荡的，骚乱的","p":"'tɜːbjʊl(ə)nt","c":1,"e":["the turbulent times of the French Revolution","法国大革命的动荡时期"]},{"w":"turnover","t":"n. 营业额，成交量；人员调整，人员更替率","p":"'tɜːnəuvə","e":["The company had a turnover of $3.8 million.","那个公司拥有380万美元的营业额。"]},{"w":"turtle","t":"n. 海龟","p":"'tɜ:tl","c":1,"e":["...a pet turtle.","…一只宠物龟。"]},{"w":"tutor","t":"v. 辅导","p":"'tju:tə(r)","c":1,"e":["He was privately tutored.","他是由家庭教师教的。"]},{"w":"twilight","t":"n. 黄昏","p":"'twaɪlaɪt","e":["romantic walks along the beach at twilight","黄昏时分浪漫的海边漫步"]},{"w":"twist","t":"v. 扭曲","p":"twɪst","c":1,"e":["She twisted her handkerchief into a knot.","她把手帕绕成一个结。"]},{"w":"typical","t":"adj. 典型的","p":"ˈtɪpɪkl","c":1,"e":["This advertisement is a typical example of their marketing strategy.","这则广告是他们营销策略的一个典型例子。"]},{"w":"tyranny","t":"n. 暴政，专制；残暴","p":"'tɪr(ə)nɪ","e":["organizations which have criticized the tyrannies of the government","批判政府暴政的组织"]},{"w":"tyrant","t":"n. 暴君；专制君主","p":"'taɪr(ə)nt","e":["The country had long been ruled by tyrants.","这个国家长期受暴君统治。"]},{"w":"ultimate","t":"adj. 最终的","p":"ˈʌltɪmət","c":1,"e":["The ultimate outcome of the experiment cannot be predicted.","试验的最后结果无法预测。"]},{"w":"ultrasonic","t":"adj. 超声的；n. 超声波","p":"ʌltrə'sɒnɪk","e":["ultrasonic waves","超声波"]},{"w":"ultraviolet","t":"adj. 紫外的","p":"ˌʌltrə'vaɪələt","e":["This is the energy of an ultraviolet photon, a \"large\" energy on the atomic scale .","这是一个紫外光子的能量，在原子尺度上，它是一个“大”能量。"]},{"w":"unanimous","t":"adj. 全体一致的，一致同意的","p":"ju'nænɪməs","e":["It was decided by a unanimous vote that the school should close.","关闭学校是大家一致通过的决定。"]},{"w":"unbiased","t":"adj. 公正的","p":"ʌnˈbaɪəst","c":1,"e":["We aim to provide a service that is balanced and unbiased.","我们的目标是提供一种公平公正的服务。"]},{"w":"uncertain","t":"adj. 不确定的","p":"ʌnˈsɜ:tn","c":1,"e":["My whole future now seemed uncertain.","现在我的前途似乎是个未知数。"]},{"w":"undecided","t":"adj. 不确定的","p":"ˌʌndɪˈsaɪdɪd","c":1,"e":["After college she was still undecided as to what career she wanted to pursue.","大学毕业后她仍无法决定自己要追求什么事业。"]},{"w":"underestimate","t":"v. 低估","p":"ˌʌndər'estɪmeɪt","c":1,"e":["None of us should ever underestimate the degree of difficulty women face in career advancement.","我们谁都不应低估妇女在职业发展中所面临的困难程度。"]},{"w":"underfunded","t":"adj. 资金不足的","p":"ˌʌndəˈfʌndɪd","c":1,"e":["For years we have argued that the FDA is underfunded.","数年来我们一直在讲食品及药物管理局经费不足。"]},{"w":"undergo","t":"vt. 经历；经受，忍受","p":"ˌʌndə'gəu","e":["He has been released from prison to undergo medical treatment in the United States.","他获释出狱去美国接受治疗。"]},{"w":"underline","t":"v. 着重；强调；n. 预告","p":"ʌndə'laɪn","e":["This tragic incident underlines the need for immediate action.","这一悲剧事件突显了立即采取行动的必要性。"]},{"w":"underlying","t":"adj. 潜在的，基础的","p":"ˌʌndəˈlaɪɪŋ","c":1,"e":["There is an underlying assumption that younger workers are easier to train.","有一种潜在的假设，认为年轻一些的雇员容易培训。"]},{"w":"undermine","t":"v. 削弱","p":"ˌʌndəˈmaɪn","c":1,"e":["economic policies that threaten to undermine the health care system","可能会损害医疗保健制度的经济政策"]},{"w":"underrepresented","t":"adj. 未被充分代表的","p":"ˌʌndəreprɪ'zentɪd","c":1,"e":["“While that percentage has increased from 9.5 percent in 1986, it is clear that women are still underrepresented in this realm of academia,” AAUW said in a press release.","美国高校妇女联合会在一份新闻简报中表示：\"尽管这一比例高于1986年时的9.5%，但女性在学术界的这一领域显然没有得到充分的代表。"]},{"w":"underscore","t":"v. 强调","p":"ˌʌndəˈskɔː(r)","c":1,"e":["The Labour Department figures underscore the shaky state of the economic recovery.","劳工部的数字突出显示了经济复苏的不稳定。"]},{"w":"undertake","t":"v. 承担；着手，开始","p":"ˌʌndə'teɪk","c":1,"e":["Dr Johnson undertook the task of writing a comprehensive English dictionary.","约翰逊博士担负起编写一本综合性英语词典的工作。"]},{"w":"undertaking","t":"n. 任务，事情","p":"ˌʌndəˈteɪkɪŋ","c":1,"e":["Starting a new business can be a risky undertaking.","创办新企业有时是一件有风险的事情。"]},{"w":"underwear","t":"n. 衫衣，内衣，贴身衣","p":"'ʌndəweə","e":["You just need to take a change of underwear.","你只需带一套换洗的内衣。"]},{"w":"undesirable","t":"adj. 不合需要的；讨厌的","p":"ʌndɪ'zaɪərəb(ə)l","e":["It would be highly undesirable to increase class sizes further.","再增加班级人数，是大家都极不愿意的。"]},{"w":"undocumented","t":"adj. 无证明的","p":"ˌʌn'dɒkjʊmentɪd","c":1,"e":["The place is rife with smugglers, dealers, undocumented immigrants, and slaves.","这里到处都是走私者、交易商、无证移民甚至奴隶。"]},{"w":"uneasy","t":"adj. 不安的；拘束的","p":"ʌn'iːzɪ","e":["She eventually fell into an uneasy sleep.","她终于睡着了，但睡得并不踏实。"]},{"w":"unemployment","t":"n. 失业，失业人数","p":"ˌʌnɪm'plɔɪmənt","e":["a town where there is high unemployment","高失业率城镇"]},{"w":"unethical","t":"adj. 不道德的","p":"ʌnˈeθɪkl","c":1,"e":["unethical medical practices","不道德的医疗行为"]},{"w":"uneven","t":"adj. 不均衡的","p":"ʌnˈi:vn","c":1,"e":["His breathing had become uneven.","他的呼吸变得不均匀"]},{"w":"unexpected","t":"adj. 意想不到的","p":"ˌʌnɪkˈspektɪd","c":1,"e":["Hague’s announcement was not entirely unexpected.","黑格的声明并非完全出乎意料。"]},{"w":"unfit","t":"adj. 不合适的；无能力的","p":"ʌn'fɪt","e":["Jenkins is unfit for public office.","詹金斯不适合担任公职。"]},{"w":"unfold","t":"v. 展开","p":"ʌnˈfəʊld","c":1,"e":["As the story unfolds, we learn more about Max’s childhood.","随着故事的展开，我们对马克斯的童年有了更多的了解。"]},{"w":"unified","t":"adj. 统一的","p":"'ju:nɪfaɪd","c":1,"e":["a unified approach","统一的方法"]},{"w":"uniformly","t":"adv. 相同地；一贯","p":"'ju:nɪfɔ:mlɪ","e":["The principles were applied uniformly across all the departments.","这些原则统一适用于所有部门。"]},{"w":"unify","t":"vt. 使联合，统一；使相同，使一致","p":"'juːnɪfaɪ","e":["Strong support for the war has unified the nation.","对战争的坚决支持使这个国家团结了起来。"]},{"w":"uninformed","t":"adj. 无知的，未受过教育的","p":"ˌʌnɪnˈfɔːmd","c":1,"e":["Parents were left anxious, uninformed, and isolated.","家长们忧心忡忡，不知道情况到底如何，感到孤立无援。"]},{"w":"unintentionally","t":"adv. 无意地","p":"ˌʌnɪnˈtenʃənəli","c":1,"e":["They had unintentionally provided wrong information.","他们无意中提供了错误的信息。"]},{"w":"unique","t":"adj. 唯一的，独一无二的；极不寻常的，极好的","p":"ju'niːk","e":["a unique opportunity to study these rare creatures","研究这些珍稀动物的难得机会"]},{"w":"unity","t":"n. 单一，统一，团结；和睦，协调","p":"'juːnəti","e":["economic unity","经济统一"]},{"w":"universally","t":"adv. 普遍地，一般地","p":"juːnɪ'vɜːsəlɪ","e":["...a universally accepted point of view.","…一个被普遍接受的观点。"]},{"w":"universe","t":"n. 宇宙，世界；领域，范围","p":"'juːnɪvɜːs","e":["Einstein's equations showed the universe to be expanding.","爱因斯坦的方程式表明宇宙正在扩大。"]},{"w":"unlimited","t":"adj. 无限的；不定的","p":"ʌn'lɪmɪtɪd","e":["The ticket offers unlimited travel on the London underground for seven days.","凭本票可在七日内无限次乘坐伦敦地铁。"]},{"w":"unlock","t":"v. 开…的锁；开启","p":"ʌn'lɒk","e":["to unlock the door","打开门锁"]},{"w":"unpaid","t":"adj. 未付的；无偿的","p":"ʌn'peɪd","e":["unpaid bills","未付的账单"]},{"w":"unprecedented","t":"adj. 史无前例的","p":"ʌnˈpresɪdentɪd","c":1,"e":["Such a move is rare, but not unprecedented.","这样的举动少见，但并非从来没有过。"]},{"w":"unqualified","t":"adj. 不合格的，不胜任的","p":"ʌn'kwɒlɪfaɪd","c":1,"e":["unqualified staff","不合格的员工"]},{"w":"unrealistic","t":"adj. 不现实的","p":"ˌʌnrɪəˈlɪstɪk","c":1,"e":["Some parents have totally unrealistic expectations of teachers.","有些家长对老师抱着完全不切实际的期望。"]},{"w":"unreasonable","t":"adj. 不讲道理的；过高的","p":"ʌn'riːz(ə)nəb(ə)l","e":["I think he’s being unreasonable.","我认为他是在无理取闹。"]},{"w":"unstable","t":"adj. 不稳定的","p":"ʌnˈsteɪbl","c":1,"e":["The political situation is still very unstable.","政局依然非常动荡。"]},{"w":"untie","t":"v. 解开，松开；解放","p":"ʌn'taɪ","e":["Peter untied his shoelaces.","彼得解开鞋带。"]},{"w":"untiring","t":"adj. 不知疲倦的","p":"ʌnˈtaɪərɪŋ","c":1,"e":["untiring efforts to help the homeless","帮助无家可归者的不懈努力"]},{"w":"untreated","t":"adj. 未经处理的","p":",ʌn'tritɪd","c":1,"e":["untreated sewage","未经处理过的污水"]},{"w":"untrustworthy","t":"adj. 不值得信任的，怀疑的","p":"ʌnˈtrʌstwɜ:ði","c":1,"e":["I think he is shallow, vain and untrustworthy.","我觉得他肤浅、虚荣，并不值得信赖。"]},{"w":"update","t":"vt. 更新；使现代化；n. 最新信息","p":"ˌʌp'deɪt","e":["The files need updating.","这些档案需要更新。"]},{"w":"upgrade","t":"v. 升级","p":"ˈʌpɡreɪd","c":1,"e":["Helicopters have been upgraded and modernized.","直升机已经升级并且装上现代化设备。"]},{"w":"uphold","t":"vt. 支持，维护","p":"ˌʌp'həuld","e":["a committee that aims to uphold educational standards","旨在保持教育水准的委员会"]},{"w":"upright","t":"adv. 挺直着，竖立着；adj. 垂直的；正直的，诚实的","p":"'ʌpraɪt","e":["You imagine being on a bicycle or motorbike; you go around the corner, you lean into the corner, which remains perfectly upright in physics.","想象一下骑着自行车和摩托车走在拐弯处时，你朝着拐角处倾斜，这在物理上仍然保持了完全笔直。"]},{"w":"uproar","t":"n. 骚动，扰乱；喧嚣","p":"'ʌprɔː","e":["The announcement caused uproar in the crowd.","公告在人群中引起了一阵骚动。"]},{"w":"uranium","t":"n. 铀","p":"jʊ'reɪnɪəm","e":["The fuel was enriched with uranium 235 for the nuclear reactor.","核反应堆的燃料被铀235浓缩。"]},{"w":"urban","t":"adj. 城市的，都市的","p":"'ɜ:bən","c":1,"e":["the deprived sections of the urban population","城市人口中的贫困群体"]},{"w":"urbanization","t":"n. 城市化","p":"ˌɜ:bənaɪ'zeɪʃn","c":1,"e":["The urbanization level increased from 19.39 percent in 1980 to 28.85 percent in 1995.","城市化水平由1980年的19.39%提高到1995年的28.85%。"]},{"w":"urge","t":"v. 催促","p":"ɜ:dʒ","c":1,"e":["The charity urged quick action.","慈善机构敦促迅速采取行动。"]},{"w":"urgent","t":"adj. 急迫的","p":"ˈɜ:dʒənt","c":1,"e":["The report called for urgent action to reduce lead in petrol.","报告呼吁迅速采取行动，减少汽油中的铅含量。"]},{"w":"usage","t":"n. 习惯用法","p":"'juːsɪdʒ","e":["a book on modern English usage","关于现代英语用法的书"]},{"w":"utensil","t":"n. 器皿，用具","p":"juː'tens(ə)l","e":["kitchen utensils","厨房用具"]},{"w":"utility","t":"n. 效用，有用","p":"juː'tɪləti","e":["It’s a simple shareware utility that allows you to print signs and banners.","这是个简单的共享应用软件，你可以用它来打印标牌和横幅。"]},{"w":"utilization","t":"n. 利用","p":"ˌju:təlaɪ'zeɪʃn","c":1,"e":["Computer has found an increasingly wide utilization in all fields.","电子计算机已越来越广泛地在各个领域得到应用。"]},{"w":"utilize","t":"vt. 利用","p":"'juːtəlaɪz","e":["We must consider how best to utilize what resources we have.","我们必须考虑怎样充分利用现有的资源。"]},{"w":"utmost","t":"adj. 最远的；n. 极限","p":"'ʌtməust","e":["It is a matter of the utmost urgency to find out what has happened to these people.","当务之急是弄清楚这些人出了什么事。"]},{"w":"utopian","t":"adj. 乌托邦的；理想的","p":"juː'təupiən","e":["His was a utopian vision of nature in its purest form.","他对大自然的看法是一种最纯粹的乌托邦式看法。"]},{"w":"utterly","t":"adv. 完全地，彻底地","p":"'ʌtəli:","c":1,"e":["You look utterly miserable.","你看起来很痛苦。"]},{"w":"vacant","t":"adj. 空的，未被占用的；空缺的；茫然的，空虚的","p":"'veɪkənt","e":["There was only a vacant lot (= empty unused area of land in a city ) where her house used to be.","她以前房子所在的地方只剩下一块空地了。"]},{"w":"vaccinate","t":"v. 给…接种疫苗","p":"'væksɪneɪt","e":["All children should be vaccinated against measles.","所有儿童都应该接种麻疹疫苗。"]},{"w":"vacuum","t":"v. 收集；用真空吸尘器打扫；n. 真空；真空吸尘器","p":"'vækjuəm","e":["I vacuumed the carpets today.","我今天用吸尘器清洁地毯了。"]},{"w":"vague","t":"adj. 不明确的；含糊的；暧昧的","p":"veɪg","e":["The governor gave only a vague outline of his tax plan.","州长只是含糊地大致说了一下他的税务计划。"]},{"w":"vain","t":"adj. 徒劳的；自负的","p":"veɪn","e":["Men can be just as vain as women.","男人有时会和女人一样虚荣。"]},{"w":"valid","t":"adj. 有效的，正当的；有根据的，有理的","p":"'vælɪd","e":["Your return ticket is valid for three months.","你的往返票有效期为三个月。"]},{"w":"validation","t":"n. 证实","p":"ˌvælɪ'deɪʃn","c":1,"e":["In the next tip in this series, we'll examine the other side of validation: exception handling.","在本系列的下一篇技巧文章中，我们将研究验证的另一方面：异常处理。"]},{"w":"validity","t":"n. 有效性；真实性","p":"vəˈlɪdəti","c":1,"e":["Shocked by the results of the elections, they now want to challenge the validity of the vote.","震惊于这些选举的结果，他们现在想质疑投票的可信性。"]},{"w":"valuable","t":"n. 贵重物品，财宝","p":"'væljʊəb(ə)l"},{"w":"value","t":"v. 尊重，重视；估价","p":"'væljuː","e":["We decided to get the house valued.","我们决定给房子估一估价。"]},{"w":"valve","t":"n. 阀，活门；瓣膜，活瓣","p":"vælv","e":["heart valves","心脏瓣膜"]},{"w":"van","t":"n. 大篷车，运货车","p":"væn","e":["a delivery van","运货车"]},{"w":"variance","t":"n. 不同","p":"ˈveəriəns","c":1,"e":["a price variance of 5%","5%的价格差异"]},{"w":"variation","t":"n. 变化","p":"ˌveəriˈeɪʃn","c":1,"e":["White bread is really just a variation of French bread.","白面包其实只是法式长条面包的一种变化形式。"]},{"w":"various","t":"adj. 各种各样的，不同的","p":"'veəriəs","e":["There are various ways to answer your question.","有多种方法可以回答你的问题。"]},{"w":"vary","t":"v. 变化","p":"'veərɪ","c":1,"e":["Quentin’s mood seems to vary according to the weather.","昆廷的情绪似乎随天气而变化。"]},{"w":"vast","t":"adj. 巨大的，大量的；浩瀚的","p":"vɑːst","e":["In the past five years, there has been a vast improvement in graduation rates.","过去的五年内，毕业率大幅度提高。"]},{"w":"vault","t":"n. 拱顶；（教堂的）地下墓室","p":"vɔːlt","e":["He ordered that Matilda's body should be buried in the family vault.","他下命令说玛蒂尔达的尸体要埋葬在家族墓穴中。"]},{"w":"vector","t":"n. 矢量；飞机航线","p":"'vektə","e":["Acceleration and velocity are both vectors.","加速度和速度都是矢量。"]},{"w":"vegetarian","t":"n. 素食主义者","p":"ˌvedʒə'teərɪən","c":1,"e":["I’m thinking about becoming a vegetarian.","我在考虑戒除荤食。"]},{"w":"vegetation","t":"n. 植物，草木","p":"ˌvedʒə'teɪʃn","e":["Lefkas has an abundance of lush green vegetation.","莱夫卡斯有葱郁茂盛的植被。"]},{"w":"vehicle","t":"n. 车辆","p":"ˈvi:əkl","c":1,"e":["a description of the stolen vehicle","对被盗车辆的描述"]},{"w":"veil","t":"n. 面纱，面罩；遮盖物，掩饰物；vt. 掩盖，掩饰","p":"veɪl","e":["She lifted her veil with both hands.","她用双手揭开面纱。"]},{"w":"vein","t":"n. 静脉，血管；叶脉；纹理，纹路；方式，风格","p":"veɪn","e":["She felt the blood racing through her veins as they kissed.","他们接吻时她觉得热血沸腾。"]},{"w":"velocity","t":"n. 速度，速率","p":"və'lɒsəti","e":["The speedboat reached a velocity of 120 mph.","快艇的时速达到了120英里。"]},{"w":"velvet","t":"n. 天鹅绒，丝绒","p":"'velvɪt","e":["green velvet drapes","绿色丝绒帷帘"]},{"w":"vengeance","t":"n. 报复，报仇，复仇","p":"'ven(d)ʒ(ə)ns","e":["a desire for vengeance","复仇的愿望"]},{"w":"vent","t":"n. 通风口，排放口；开衩；vt. 表达，发泄","p":"vent","e":["a blocked air vent","堵塞的通风口"]},{"w":"ventilate","t":"v. 使通风","p":"ˈventɪleɪt","c":1,"e":["Ventilate the room properly when stripping paint.","在刮漆的时候要适当地使房间通风。"]},{"w":"venture","t":"vi. 冒险；大胆行事；n. 风险投资，风险项目；vt. 拿…冒险；敢于","p":"'ventʃə","e":["children who lack the confidence to venture into libraries","缺乏自信、不敢进图书馆的儿童"]},{"w":"Venus","t":"n. 维纳斯；美人","p":"'viːnəs"},{"w":"verbal","t":"adj. 口头的；用言辞的，用文字的；动词的","p":"'vɜːbl","e":["verbal skills","语言技能"]},{"w":"verdict","t":"n. 裁定；定论，判断性意见","p":"'vɜːdɪkt","e":["The verdict was ‘not guilty’.","裁决为“无罪”。"]},{"w":"verge","t":"vi. 接近，濒临；n. 边，边缘","p":"vɜːdʒ"},{"w":"verify","t":"vt. 证实，查证，证明","p":"'verɪfaɪ","e":["His statement was verified by several witnesses.","他的说法得到了几位证人的证实。"]},{"w":"versatile","t":"adj. 多才多艺的，有多种技能的；有多种用途的，多功能的，万用的","p":"'vɜːsətaɪl","e":["a very versatile performer","多才多艺的表演者"]},{"w":"verse","t":"n. 诗，诗句","p":"vɜːs","e":["a book of comic verse","一本滑稽诗集"]},{"w":"version","t":"n. 译文，说法，改写本","p":"'vɜːʃn","e":["Could Donna’s version of what happened that night be correct?","唐娜对那晚发生的事情的描述是否正确呢？"]},{"w":"versus","t":"prep. 以…为对手，对；与…相对，与…相比之下","p":"'vɜːsəs","e":["the Supreme Court decision in Roe vs. Wade","最高法院关于罗诉韦德案的判决"]},{"w":"vertical","t":"adj. 垂直的，竖式的","p":"'vɜːtɪkl","e":["the vertical axis of a graph","图的纵轴"]},{"w":"vessel","t":"n. 血管","p":"ˈvesl","c":1,"e":["a burst blood vessel","破裂的血管"]},{"w":"veteran","t":"adj. 经验丰富的；n. 老手；老兵","p":"'vetərən","e":["He is a veteran of the last revolution in medical technology, gene therapy, which, after some hyped expectations in the 1990s, fell into disfavor after some unsuccessful trials.","他是基因治疗这项最新医学技术的老手，经过了1990年代的兴奋期和之后几次失败的实验后，基因治疗技术已经失宠了。"]},{"w":"veto","t":"n&vt. 否决","p":"'viːtəu","e":["The Senate had a sufficient majority to override the presidential veto (= not accept his refusal ).","参议院有足够的多数票可以推翻总统的否决。"]},{"w":"vice","t":"n. 恶习","p":"vaɪs","c":1,"e":["Smoking is my only vice.","吸烟是我唯一的恶习。"]},{"w":"vicinity","t":"n. 周围地区，邻近地区","p":"və'sɪnəti","e":["There were a hundred or so hotels in the vicinity of the station.","在车站附近有大约一百家左右的旅馆。"]},{"w":"vicious","t":"adj. 恶毒的，凶残的；剧烈的，严重的","p":"'vɪʃəs","e":["Keep away from that dog, he can be vicious.","离那只狗远点，它有时很凶猛。"]},{"w":"victim","t":"n. 受害者","p":"ˈvɪktɪm","c":1,"e":["a credit card fraud ring that stole millions of dollars from unsuspecting victims","从毫无戒心的受害者手中盗取数百万美元的信用卡诈骗团伙"]},{"w":"video","t":"adj. 录像的","p":"'vɪdɪəʊ","e":["video materials for language teaching","语言教学的影像素材"]},{"w":"view","t":"v. 看待","p":"vju:","c":1,"e":["The law should be viewed as a way of meeting certain social goals.","这项法规应被视为实现某些社会目标的一种途径。"]},{"w":"viewpoint","t":"n. 观点","p":"ˈvju:pɔɪnt","c":1,"e":["Different viewpoints produce different images.","角度不同，产生的画面也不同。"]},{"w":"vigorous","t":"adj. 积极的；精力充沛的","p":"ˈvɪgərəs","c":1,"e":["Environmentalists have begun a vigorous campaign to oppose nuclear dumping in the area.","环保人士已经发动了一场积极的运动，反对在该地区倾倒核废物。"]},{"w":"vigour","t":"n. 活力，精力；元气","p":"'vɪgə","e":["He began working with renewed vigour.","他以更加旺盛的精力开始工作。"]},{"w":"villa","t":"n. 别墅","p":"'vɪlə","e":["We rented a holiday villa in Spain.","我们在西班牙租了一座假日别墅。"]},{"w":"vine","t":"n. 蔓，藤，藤本植物","p":"vaɪn","e":["Ivy is a type of vine.","常青藤是一种藤本植物。"]},{"w":"violate","t":"vt. 违反，违背；亵渎；侵犯，妨碍","p":"'vaɪəleɪt","e":["34 protesters were arrested for violating criminal law.","34名抗议者因违反刑法而被逮捕。"]},{"w":"violation","t":"n. 违反","p":"ˌvaɪə'leɪʃn","c":1,"e":["human rights violations","违反人权"]},{"w":"violent","t":"adj. 暴力的","p":"ˈvaɪələnt","c":1,"e":["31 people have been injured in violent incidents throughout the day.","今天一天有31人在暴力事件中受伤。"]},{"w":"virgin","t":"adj. 未经开发的，未经使用的，未经触动的；处女的；n. 处女，未婚女子","p":"'vɜːdʒɪn","e":["Within 40 years there will be no virgin forest left.","过不了40年原始森林将所剩无几。"]},{"w":"virtual","t":"adj. 虚拟的；事实上的","p":"ˈvɜ:tʃuəl","c":1,"e":["Argentina came to a virtual standstill while the game was being played.","阿根廷在比赛进行期间全国上下事实上进入了停顿状态。"]},{"w":"virtually","t":"adv. 几乎","p":"ˈvɜ:tʃuəli","c":1,"e":["He was virtually unknown before running for office.","他在参加竞选之前几乎不为人知。"]},{"w":"virtue","t":"n. 善，美德；优点，长处","p":"'vɜːtjuː","e":["Women have often been used as symbols of virtue.","女性常被用作美德的象征。"]},{"w":"virus","t":"n. 病毒","p":"'vaɪrəs","c":1,"e":["children infected with the Aids virus","感染艾滋病病毒的儿童"]},{"w":"visa","t":"n. 签证","p":"'viːzə","e":["I was still in New York, trying to get a visa to visit Russia.","我仍在纽约，正在办理去俄罗斯的签证。"]},{"w":"visceral","t":"adj. 内脏的，腑脏的；出自内心的，发自肺腑的","p":"'vɪsərəl","e":["his visceral hatred of the ruling class","他对统治阶级发自肺腑的仇恨"]},{"w":"viscous","t":"adj. 粘滞的，粘性的","p":"'vɪskəs","e":["As the liquid cools, it becomes viscous.","这液体冷却后会变黏稠。"]},{"w":"vision","t":"n. 想象力，梦幻；视力，视觉","p":"'vɪʒn","e":["She suffered temporary loss of vision after being struck on the head.","她头部受撞击以后出现暂时性失明。"]},{"w":"visit","t":"v. 拜访","p":"'vɪzɪt","e":["Eric went to Seattle to visit his cousins.","埃里克到西雅图去看望他的表兄弟。"]},{"w":"visual","t":"adj. 看的，视觉的","p":"'vɪʒuəl","e":["The tall tower adds to the visual impact of the building.","高高的塔楼增强了这幢大楼的视觉效果。"]},{"w":"visualize","t":"v. 想象","p":"ˈvɪʒuəlaɪz","c":1,"e":["I tried to visualize the house while he was describing it.","我一边听他描述，一边想象那房子的样子。"]},{"w":"vital","t":"adj. 重要的","p":"'vaitəl","c":1,"e":["The samples could give scientists vital information about long-term changes in the earth’s atmosphere.","这些样本可以给科学家提供关于地球大气长期变化的极其重要的资料。"]},{"w":"vitality","t":"n. 活力；生机，元气","p":"vaɪ'tæləti","e":["Despite her eighty years, Elsie was full of vitality.","尽管已80岁了，埃尔茜依然充满活力。"]},{"w":"vitamin","t":"n. 维他命","p":"'vɪtəmɪn","c":1,"e":["Try to eat foods that are rich in vitamins and minerals.","尽量吃富含维生素和矿物质的食物。"]},{"w":"vivid","t":"adj. 生动的","p":"ˈvɪvɪd","c":1,"e":["He had a vivid picture of her in his mind.","他的脑海中清晰地留着她的形象。"]},{"w":"vocabulary","t":"n. 词汇表，词汇汇编","p":"və(ʊ)'kæbjʊlərɪ"},{"w":"vocal","t":"adj. 喜欢畅所欲言的，直言不讳的；嗓音的，发声的；n. 声乐节目","p":"'vəukl","e":["Allison’s vocal style is influenced by country and blues music.","艾利森的演唱风格受到乡村音乐和布鲁斯音乐的影响。"]},{"w":"vocation","t":"n. 职业，行业","p":"və(ʊ)'keɪʃ(ə)n","e":["At 17 she found her true vocation as a writer.","17岁时她找到了自己真正的使命——当一名作家。"]},{"w":"vocational","t":"adj. 职业的","p":"vəʊˈkeɪʃənl","c":1,"e":["vocational qualifications","职业资格"]},{"w":"void","t":"adj. 无效的；没有的，缺乏的；n. 空虚感，寂寞感；真空，空白；vt. 使无效","p":"vɔɪd","e":["Her eyes were void of all expression.","她的眼神一片茫然。"]},{"w":"volume","t":"n. 卷，册，书卷；容积，体积；音量，响度","p":"'vɒljuːm","e":["the volume of trade","贸易量"]},{"w":"voluntary","t":"adj. 自愿的，志愿的","p":"'vɒləntri","e":["Workers are being encouraged to take voluntary redundancy.","工人被鼓励主动离职。"]},{"w":"volunteer","t":"v. 自愿；自愿提供；志愿；n. 志愿者；志愿兵","p":"vɒlən'tɪə","e":["I volunteered my services as a driver.","我主动提出来当司机。"]},{"w":"vow","t":"n. 誓言，誓约，许愿","p":"vaʊ","e":["Jim made a vow that he would find his wife’s killer.","吉姆发誓要找到杀害他妻子的凶手。"]},{"w":"vowel","t":"n. 元音；元音字母","p":"'vaʊəl","e":["Each language has a different vowel system.","每种语言都有不同的元音系统。"]},{"w":"vulgar","t":"adj. 粗野的，下流的；庸俗的，粗俗的","p":"'vʌlgə","e":["vulgar behaviour","粗俗的行为"]},{"w":"vulnerable","t":"adj. 脆弱的, 易受影响的","p":"ˈvʌlnərəbl","c":1,"e":["We work mainly with the elderly and other vulnerable groups.","我们主要和老年人以及其他弱势群体打交道。"]},{"w":"wade","t":"v. 趟（河），跋涉","p":"weɪd","e":["Sometimes they had to wade waist-deep through mud.","有时他们得通过齐腰深的泥浆。"]},{"w":"wag","t":"v. （狗） 摇摆 （尾巴）；摇晃 （手指）","p":"wæg","e":["‘You naughty girl!’ Mom said, wagging her finger at me.","“你这个调皮的丫头！”妈妈对我摇了摇手指说道。"]},{"w":"waggon","t":"n. 敞蓬车厢","p":"'wæɡən"},{"w":"waitress","t":"n. 女侍者，女服务员","p":"ˈweɪtrəs"},{"w":"wallet","t":"n. 皮夹子","p":"'wɒlɪt","e":["He took a credit card out of his wallet.","他从钱包里拿出一张信用卡。"]},{"w":"walnut","t":"n. 核桃；胡桃树","p":"'wɔːlnʌt","e":["Below in the valley lie miles of walnut trees.","在下面的山谷里绵延着几英里的核桃树。"]},{"w":"ward","t":"n. 病房；区；受监护人","p":"wɔːd","e":["the other patients in the ward","病房里的其他病人"]},{"w":"wardrobe","t":"n. 衣柜；全部衣物","p":"'wɔːdrəub","e":["Can you hang these in the wardrobe, please?","请你把这些衣服挂到衣橱里去好吗？"]},{"w":"ware","t":"n. 物品；商品，货物","p":"weə(r)","e":["He travelled from town to town selling his wares.","他走乡串镇出售自己的货品。"]},{"w":"warehouse","t":"n. 仓库，货栈","p":"'weəhaus","e":["Each warehouse reports back to the retailer which portion (if any) of the customer order it was able to fulfil.","每个仓库把它能完成客户定单的哪个部分（如果有）的报告返回给零售商。"]},{"w":"warfare","t":"n. 战争；斗争，冲突","p":"'wɔːfeə","e":["the realities of modern warfare","现代战争的真实面貌"]},{"w":"warning","t":"n. 警告，告诫，鉴诫","p":"'wɔːnɪŋ","e":["a warning that grey squirrels are threatening the existence of red squirrels","关于灰松鼠正威胁到红松鼠生存的警告"]},{"w":"warrant","t":"n. 授权令；理由，根据；vt. 证明…是正当的","p":"'wɒrənt","e":["There is no warrant for copying other people’s work.","剽窃他人作品毫无道理。"]},{"w":"wasp","t":"n. 黄蜂","p":"wɒsp","e":["a wasps' nest","黄蜂窝"]},{"w":"wasteful","t":"adj. 浪费的","p":"'weɪstfʊl; -f(ə)l","e":["The software is very wasteful of memory.","这个软件很占内存。"]},{"w":"watchful","t":"adj. 注意的，警惕的","e":["The entrances are guarded by watchful security staff.","入口处由警惕的保安人员把守。"]},{"w":"watertight","t":"adj. 不透水的，防水的；严密的，无懈可击的","p":"'wɔːtətaɪt","e":["Lucky for him, his alibi is watertight.","算他走运，不在犯罪现场的证据无懈可击。"]},{"w":"watery","t":"adj. 充满水的；与水有关的；湿的；（食物、饮料等）味淡的","p":"'wɔːt(ə)rɪ","e":["Her eyes were red and watery from crying.","她的眼睛哭得红红的，眼里含满泪水。"]},{"w":"watt","t":"n. 瓦","p":"wɒt","e":["a 100-watt bulb","100瓦的灯泡"]},{"w":"waver","t":"v. 犹豫不决；摇摆","p":"'weɪvə","e":["The candle flame wavered, throwing shadows on the wall.","烛光摇曳，在墙上投下影子。"]},{"w":"wax","t":"n. 蜡，蜂蜡；vt. 给…上蜡","p":"wæks","e":["wax crayons","蜡笔"]},{"w":"way","t":"n. （特定的）状态，状况","p":"weɪ","e":["It’s worth thinking how you can improve the way things are.","你应该想想如何让现状变得更好。"]},{"w":"wealth","t":"n. 财富；财产；丰富","p":"welθ","e":["The purpose of industry is to create wealth.","工业的目的就是创造财富。"]},{"w":"wealthy","t":"adj. 富的，富裕的","p":"'welθi","e":["the wealthy nations of the world","世界上的富国"]},{"w":"weary","t":"vi. 厌烦，不耐烦；adj. 疲劳的，疲倦的；使人疲劳的，令人厌倦的","p":"'wɪəri","e":["She found Rachel in the kitchen, looking old and weary.","她发现雷切尔在厨房里，看上去苍老而疲惫。"]},{"w":"weave","t":"v. 织布，编织","p":"wiːv","c":1,"e":["Only a few of the women still weave.","只有数量很少的妇女还在编织。"]},{"w":"weaver","t":"n. 织布工，编织者","p":"'wiːvə","e":["basket weavers","编篮子的人"]},{"w":"web","t":"n. 网；网络；错综复杂的事物","p":"web","e":["a tangled web of relationships","复杂的关系"]},{"w":"wedge","t":"n. 楔；vt. 楔入，塞入","p":"wedʒ","e":["Wedge the plug into the hole.","把塞子塞进洞里。"]},{"w":"weird","t":"adj. 古怪的，离奇的；怪诞的，神秘而可怕的","p":"wɪəd","e":["They sell all sorts of weird and wonderful (= very strange ) products.","他们出售各种稀奇古怪的产品。"]},{"w":"welfare","t":"n. 幸福；福利","p":"'welfeə(r)","c":1,"e":["the provision of education and welfare services","提供教育和福利服务"]},{"w":"whale","t":"n. 鲸","p":"weɪl"},{"w":"wharf","t":"n. 码头，停泊所","p":"wɔːf","e":["The ship lies alongside the wharf.","那艘船停靠在码头边。"]},{"w":"what","t":"adj. 所…的","p":"wɒt","e":["What he did was morally wrong.","他的行为很缺德。"]},{"w":"whereas","t":"conj. 然而，但是，尽管","p":"ˌweər'æz","e":["The old system was fairly complicated whereas the new system is really very simple.","旧系统相当复杂，而新系统却很简单。"]},{"w":"whereby","t":"adv. 凭此；借以；由于","p":"weə'baɪ","e":["a proposal whereby EU citizens would be allowed to reside anywhere in the EU","允许欧盟公民在欧盟任何地方居住的一项提议"]},{"w":"whilst","t":"conj. 同时；然而","p":"waɪlst"},{"w":"whirl","t":"vi. 旋转，急转；发晕，变混乱；n. 旋转，回旋；混乱；一连串的事","p":"wɜːl","e":["We watched the seagulls whirling and shrieking over the harbour.","我们看海鸥在港口上空盘旋鸣叫。"]},{"w":"whisker","t":"n. 髯，连鬓胡子","p":"'wɪskə","e":["...wild, savage-looking fellows, with large whiskers and dirty faces.","…一些狂野、面相凶恶的家伙，留着满脸的络腮胡子，蓬头垢面。"]},{"w":"whisper","t":"v. 低声地讲；私下说","p":"'wɪspə","e":["Staff were whispering that the company was about to go out of business.","员工私下在传，说公司要倒闭了。"]},{"w":"white","t":"adj. 白种（人）的","p":"wʌɪt","e":["young white males","年轻的白种男性"]},{"w":"whitewash","t":"n. 石灰水；v. 粉饰","p":"'waɪtwɒʃ","e":["Investigators are accused of whitewashing the governor’s record.","调查者被指责粉饰州长的政绩。"]},{"w":"whoever","t":"pron. 究竟是谁","p":"huːˈɛvə","e":["Whoever would do a thing like that to an old woman?","究竟是谁会对一位老太太做出那样的事？"]},{"w":"wholesome","t":"adj. 对健康有益的","p":"'həʊls(ə)m","e":["well-balanced wholesome meals","营养均衡的健康餐"]},{"w":"widely","t":"adv. 大大地","p":"'waɪdlɪ","e":["The quality of the applicants varies widely.","申请人的素质差异很大。"]},{"w":"widen","t":"v. 拓宽，变宽","p":"'waɪdn","c":1,"e":["The river widens and splits.","这条河有变宽的河段，也有分流的河段。"]},{"w":"widespread","t":"adj. 广泛传播的","p":"ˈwaɪdspred","c":1,"e":["the widespread use of chemicals in agriculture","化学品在农业中的广泛使用"]},{"w":"wield","t":"v. 挥（剑）；行使","p":"wiːld","e":["She wields enormous power within the party.","她操纵着党内大权。"]},{"w":"wildfire","t":"n. 野火","p":"ˈwaɪldfaɪə(r)","c":1,"e":["...a wildfire in Montana that's already burned thousands of acres of rich grassland.","...已经烧毁几千英亩肥沃草地的蒙大拿州野火。"]},{"w":"wildlife","t":"n. 野生动物","p":"ˈwaɪldlaɪf","c":1,"e":["measures to protect the area’s wildlife","保护该地区野生生物的措施"]},{"w":"willful","t":"adj. 故意的，特意的","p":"'wɪlfl"},{"w":"willow","t":"n. 柳树，柳木","p":"'wɪləʊ","e":["The baskets are woven from strips of willow.","这些篮子是用柳条编的。"]},{"w":"wind","t":"n. 风","p":"wɪnd; (for v.) waɪnd","e":["The wind blew from the northeast.","风从东北方向吹来。"]},{"w":"winding","t":"n. 蜿蜒曲折的路径；adj. 蜿蜒曲折的","p":"'waɪndɪŋ","e":["a long and winding road","漫长而曲折的道路"]},{"w":"windmill","t":"n. 风车","p":"'wɪn(d)mɪl","e":["The sails of the windmill are now at rest.","风车的帆叶现在静止不动了。"]},{"w":"windy","t":"adj. 多风的，刮风的","p":"'wɪndɪ","e":["It’s too windy for a picnic.","风太大，不适合野餐。"]},{"w":"wink","t":"v. 眨眼；使眼色","p":"wɪŋk","e":["He winked an eye at his companion.","他朝同伴眨眨眼。"]},{"w":"wisdom","t":"n. 智慧","p":"'wɪzdəm","e":["You can always expect a few words of wisdom from Dave.","戴夫总能冒出几句至理名言。"]},{"w":"wishful","t":"adj. 一厢情愿的","p":"'wɪʃfəl","c":1,"e":["Stop your wishful thinking and be glad for what you do have instead of always wanting more.","别再一厢情愿的妄想了，高高兴兴的接受你已经有的，别再奢求更多了。"]},{"w":"withdraw","t":"v. 撤销，撤退","p":"wɪð'drɔ","c":1,"e":["calls for Britain to withdraw from the European Union","要求英国退出欧盟的呼声"]},{"w":"wither","t":"v. 枯萎；使衰弱","p":"'wɪðə","e":["Industries unable to modernize have been left to wither.","无法实现现代化的行业已经自行衰落。"]},{"w":"withhold","t":"vt. 拒绝，不给；抑制，制止","p":"wɪð'həuld","e":["Ian was accused of withholding vital information from the police.","伊恩被控向警方隐瞒重要信息。"]},{"w":"witness","t":"n. 证据；目击者，证人；vt. 目击；为…作证，证明","p":"'wɪtnəs","e":["an eye witness (= someone who sees an event ) to the robbery","抢劫案的一名目击者"]},{"w":"witty","t":"adj. 机智的；风趣的","p":"'wɪtɪ","e":["Laura’s very witty.","劳拉谈吐很风趣。"]},{"w":"woe","t":"n. 悲哀，悲痛，苦恼","p":"wəʊ","e":["He listened to my tale of woe.","他听了我悲伤的故事。"]},{"w":"wonder","t":"v. 想知道，好奇","p":"'wʌndə(r)","c":1,"e":["He’s been leaving work early a lot – it makes you wonder , doesn’t it?","他最近经常提早下班——让人觉得奇怪，是不是？"]},{"w":"woodpecker","t":"n. 啄木鸟","p":"'wʊdpekə","e":["Savour the silence, if that's what nature serves up, or thrill to the tap-tap of the woodpecker.","如果这是大自然奉上的一份佳肴，给这份宁静加点作料吧，或是因为啄木鸟的叩击声而兴奋起来吧。"]},{"w":"workload","t":"n. 工作量","p":"ˈwɜ:kˌləʊd","c":1,"e":["She’s struggling to cope with the heavy workload .","她在努力应付繁重的工作量。"]},{"w":"workpiece","t":"n. 工（作）件","p":"'wə:kpi:s","e":["The workpiece is already on the lathe.","工件已经上了车床。"]},{"w":"workshop","t":"n. 车间，工场；专题讨论会","p":"'wɜːkʃɒp","e":["Trumpeter Marcus Belgrave ran a jazz workshop for young artists.","鼓手马库斯马贝尔格瑞夫为年轻艺术家们举办了一场爵士乐研讨会。"]},{"w":"worldly","t":"adj. 世间的，尘世的","p":"ˈwɜ:ldli","c":1,"e":["He seemed very calm and far removed from worldly concerns.","他显得非常淡定，完全没有俗世的忧虑。"]},{"w":"worldwide","t":"adv. 世界范围地，全世界","p":"'wɜːl(d)waɪd","c":1,"e":["His books have sold more than 20 million copies worldwide.","他的书在全世界卖出了两千多万本。"]},{"w":"worship","t":"v. 崇拜，喜爱","p":"ˈwɜːʃɪp","c":1,"e":["He absolutely worships her.","他太崇拜她了。"]},{"w":"worthwhile","t":"adj. 值得花时间做的","p":"ˌwɜːθ'waɪl","e":["We decided to give the money to a worthwhile cause (= one that helps people ) .","我们决定把这笔钱投入到慈善事业中。"]},{"w":"worthy","t":"adj. 有价值的，值得的","p":"'wɜːði","e":["Leeds United were worthy winners of the competition.","利兹联队是比赛当之无愧的获胜者。"]},{"w":"wrath","t":"n. 暴怒，狂怒，愤慨","p":"rɒθ; rɔːθ","e":["He was scared of incurring his father’s wrath .","他害怕惹他父亲大发脾气。"]},{"w":"wreck","t":"n. 失事，残骸；精神或身体已垮的人；vt. 破坏","p":"rek","e":["He was still alive when they pulled him from the wreck.","他们把他从失事的车辆中拖出来时，他还活着。"]},{"w":"wrench","t":"vt. 猛拧，猛扭；挣脱；使扭伤；n. 痛苦，难受；猛扭，猛拉；扳手","p":"rentʃ","e":["I wrenched the packet from his grasp.","我用力夺过他攥在手里的纸袋。"]},{"w":"wrestle","t":"n. 摔跤；斗争，搏斗","p":"'resl"},{"w":"wretched","t":"adj. 极不愉快的，难受的，可怜的；令人苦恼的，讨厌的；拙劣的","p":"'retʃɪd","e":["the poor, wretched girl","极其不幸的可怜姑娘"]},{"w":"wring","t":"v. 拧，挤，扭，榨","p":"rɪŋ","e":["This jacket’s wringing wet!","这件上衣湿得都能拧出水来！"]},{"w":"wrinkle","t":"v. 起皱纹；n. 皱纹","p":"'rɪŋkl","e":["Carter wrinkled his forehead in concentration.","卡特全神贯注，眉头紧锁。"]},{"w":"xerox","t":"v. 用静电复印","p":"'ziərɔks","e":["Could you xerox this letter, please?","请复印一下这封信好吗？"]},{"w":"yacht","t":"n. 快艇，帆船，游艇","p":"jɒt","e":["His 36 ft yacht sank suddenly last summer.","他的36英尺游艇去年夏天突然沉没了。"]},{"w":"yearn","t":"v. 渴望，向往","p":"jɜːn","e":["Hannah yearned for a child.","汉娜渴望有个孩子。"]},{"w":"yeast","t":"n. 酵母","p":"jiːst","e":["dried/fresh yeast","干／新鲜酵母"]},{"w":"yell","t":"n&vi. 号叫，叫喊","p":"jel","e":["He could hear Pete yelling at the top of his voice (= very loudly ).","他听到皮特声嘶力竭地在喊叫。"]},{"w":"yield","t":"v. 产生","p":"ji:ld","c":1,"e":["Our research has only recently begun to yield important results.","直到最近我们的研究才开始取得重要成果。"]},{"w":"yoke","t":"n. 牛轭；束缚，枷锁；vt. 结合，联结","p":"jəuk","e":["the yoke of tradition","传统的枷锁"]},{"w":"yolk","t":"n. 蛋黄，卵黄","p":"jəʊk","e":["Only the yolk contains cholesterol.","只有蛋黄含胆固醇。"]},{"w":"youngster","t":"n. 儿童，少年，年轻人","p":"'jʌŋstə","e":["Other youngsters are not so lucky.","其他的年轻人没有这么幸运。"]},{"w":"zinc","t":"n. 锌","p":"zɪŋk","e":["One medium oyster provides nearly all of the zinc you need for a day.","一个中等大小的牡蛎几乎可以提供给你一天所需的所有锌。"]}];
